NSPoint g_new_window_from = NSZeroPoint;
// Issue #486: `--boot-report <path>` writes the boot timeline (core/boot_timeline.h)
// as JSON once the launch is ready, then quits: a measuring run, repeated by
// tools/perf/boot.sh. Like the Windows switch it leaves the recent folders alone;
// like the other measuring runs it shows the window without taking the keyboard.
std::string g_boot_report;
// A launch with a file is ready at its full-resolution present; one that never
// gets there (a document, a clip, an unreadable file) reports after this.
constexpr double kBootReportGiveUpMs = 15000.0;

// Add-ons -- the AI pack and its indexer, Import's volume watch, Final Cut
// search -- run in one window's process only, the first to take this lock: two
// indexers would write one index. The lock is the process's until it exits,
// crash or not, and the next window to start takes it over.
bool MvClaimAddonHost() {
  auto dir = mv::io::addons_dir();
  if (!dir) return true;
  (void)::mkdir(dir->c_str(), 0700);
  const std::string path = mv::io::join_path(*dir, ".host.lock");
  const int fd = ::open(path.c_str(), O_RDWR | O_CREAT | O_CLOEXEC, 0600);
  if (fd < 0) return true;  // cannot tell: as before, this process hosts them
  if (::flock(fd, LOCK_EX | LOCK_NB) == 0) return true;  // fd kept open until exit
  ::close(fd);
  return false;
}

#if MV_WITH_SPARKLE
// #532: Sparkle's installer quits every running copy with an Apple quit event
// from its progress agent (org.sparkle-project.Sparkle.Updater) and no quit
// reason: the Dock's Quit has the same shape, and the background (#452) answers
// that by hiding, so the install waited for ever. The sender tells them apart.
bool MvQuitFromSparkle(NSAppleEventDescriptor* event) {
  if (event.eventClass != kCoreEventClass || event.eventID != kAEQuitApplication) return false;
  NSAppleEventDescriptor* pid = [event attributeDescriptorForKeyword:keySenderPIDAttr];
  if (pid == nil) return false;
  NSRunningApplication* sender = [NSRunningApplication runningApplicationWithProcessIdentifier:pid.int32Value];
  return [sender.bundleIdentifier hasPrefix:@"org.sparkle-project."];
}
#endif

