// --browse-soak (the Windows lab's harness, main.cpp browse_run): open a
// folder, dwell on the first photo, jump to photos past its prefetched
// neighbours (cold), then arrow forward with a dwell before each (warm).
// Every step is timed from just before the selection to the present that
// shows the new item. Writes the same JSON as Windows (tools/perf reads it).
struct mac_browse_row {
  std::string name;
  int index = 0;
  int cold = 0;
  int cached = 0;
  int timed_out = 0;
  double ready_ms = -1.0;
  double present_ms = -1.0;
  double refresh_ms = 0.0;
};
enum class mac_browse_phase { wait_media, dwell, cold, wait_away, go_home, wait_home, warm, wait_warm, finish };
struct mac_browse_run {
  bool enabled = false;
  std::string json_path;
  mac_browse_phase step = mac_browse_phase::wait_media;
  mac_browse_phase after_dwell = mac_browse_phase::cold;
  double t0 = 0.0;
  double phase_t = 0.0;
  std::size_t count = 0;
  int cold_targets[6]{};
  int cold_n = 0;
  int cold_i = 0;
  int warm_left = 0;
  std::uint64_t seq = 0;
  bool record = false;
  int pending_index = 0;
  int pending_cold = 0;
  std::string pending_name;
  std::vector<mac_browse_row> rows;
  // Seconds the window spent covered or minimised. The display link stops for
  // a hidden window, so its steps time out: the run is void, and says so.
  double hidden_s = 0.0;
  double last_tick = 0.0;
} g_mac_browse;
constexpr double kMacBrowseDwell = 3.0;
constexpr double kMacBrowseStepTimeout = 20.0;
constexpr double kMacBrowseOpenTimeout = 60.0;

// --page-soak PATH (issue #429): open a PDF, DOCX or PPTX, then (1) fling the
// page sidebar from the first page to the last in 1.5 s, as a hard flick of
// the strip does: the SwiftUI strip scrolls, its cells ask for thumbnails and
// the pool renders them while the canvas presents (run it under --soak to have
// the pacing measured); (2) go to pages as a thumbnail click does, each timed
// to its first image, the present showing it and the full-size page. Writes
// its own JSON; under --soak the soak report is the lab's as usual.
struct mac_page_row {
  int page = 0;
  int timed_out = 0;
  int placeholder = 0;  // the first image was not the full page
  double ready_ms = -1.0;
  double present_ms = -1.0;
  double full_ms = -1.0;
};
enum class mac_page_phase { wait_doc, settle, fling, drain, jump, wait_jump, finish };
struct mac_page_run {
  bool enabled = false;
  std::string json_path;
  mac_page_phase step = mac_page_phase::wait_doc;
  double t0 = 0.0, phase_t = 0.0;
  std::uint32_t pages = 0;
  double sidebar_s = -1.0;  // open -> the strip listing the document
  double fling_s = 0.0;
  double drain_s = -1.0;    // fling end -> the last screenful of thumbnails in
  std::uint32_t landed = 0; // pages with a thumbnail once drained
  std::vector<std::uint32_t> targets;
  std::size_t next = 0;
  std::uint64_t seq = 0;
  std::vector<mac_page_row> rows;
} g_mac_pages;
constexpr double kMacPageFlingSeconds = 1.5;
constexpr std::uint32_t kMacPageWindow = 6;  // cells a 900 pt strip shows

double browse_now() {
  return std::chrono::duration<double>(std::chrono::steady_clock::now().time_since_epoch()).count();
}

void browse_json_string(FILE* f, const std::string& s) {
  std::fputc('"', f);
  for (const unsigned char c : s) {
    if (c == '"' || c == '\\') std::fprintf(f, "\\%c", c);
    else if (c < 0x20) std::fprintf(f, "\\u%04x", c);
    else std::fputc(c, f);
  }
  std::fputc('"', f);
}

// --pane-drag-soak (docs/plans/edit-refresh.md §7 S1; the Windows lab's twin):
// open the still, open the Edit workspace (the docked column), then drag the
// column's edge 280 <-> 720 and back every 4 s (one way in 2 s) for 20 s
// through the same code the mouse drag runs, while the lab pans the still at
// 100 % for 10 s and then refits it live (present_lab_mac pane_drag_soak).
// Reports the render thread's present intervals during the drag (none over 2x
// the refresh), the main thread's layout time per step, the layer's drawable
// size assignments during the drag (must be 0), and the presents in 2 s after
// a 1.5 s settle (must be 0). The p99 against a base --pan-soak run is the
// reader's. The width is never saved.
enum class mac_pane_drag_phase { wait_media, dwell, drag, settle, measure, finish };
struct mac_pane_drag_run {
  bool enabled = false;
  std::string json_path;
  mac_pane_drag_phase step = mac_pane_drag_phase::wait_media;
  double t0 = 0.0;
  double phase_t = 0.0;
  std::vector<float> layout_ms;
  std::uint32_t drawable_sets_before = 0;
  std::uint32_t drawable_sets_during = 0;
  std::uint64_t presents_before = 0;
  std::uint64_t presents_after_settle = 0;
  double hidden_s = 0.0;
  double last_tick = 0.0;
} g_pane_drag;
constexpr double kPaneDragSweepSeconds = 20.0;
constexpr double kPaneDragLegSeconds = 2.0;
constexpr double kPaneDragDwellSeconds = 2.0;
constexpr double kPaneDragSettleSeconds = 1.5;
constexpr double kPaneDragMeasureSeconds = 2.0;

