// ---- PR 9 bridge: metadata pane, folder tree, sort -------------------------------
namespace {

// Tabs and newlines are the table's separators, so they cannot appear in values.
std::string MvFlat(const std::string& s) {
  std::string out = s;
  for (char& c : out) {
    if (c == '\t' || c == '\n' || c == '\r') c = ' ';
  }
  return out;
}

int32_t MvCopyOut(const std::string& out, char* buf, int32_t size) {
  if (buf && size > 0) {
    const std::size_t n = std::min<std::size_t>(out.size(), static_cast<std::size_t>(size) - 1);
    std::memcpy(buf, out.data(), n);
    buf[n] = '\0';
  }
  return static_cast<int32_t>(out.size());
}

// #612 (docs/design/04 "Thumbnail cache upkeep"): Settings -> Storage's cap
// for the thumbnail cache in bytes, 0 (the default) none; kept in the user's
// defaults, read at launch, applied by the next sweep. And the host's folder
// model, for Clear from Swift's background task (it lives as long as the app).
std::atomic<std::uint64_t> g_thumb_cache_cap{0};
std::atomic<mv::shell::folder_model*> g_storage_folder{nullptr};
NSString* const kThumbCacheCapDefault = @"mv.thumbCacheCap";

// What a path handed to the app names: the folder to open and, for a file, the
// file to select there. One stat (containing_dir() would take a second); false
// when nothing exists. A worker's call, but for the launch open.
bool MvResolveEntry(const std::string& path, std::string* dir, std::string* select_path) {
  auto is_dir = mv::io::is_directory(path);
  if (!is_dir) return false;
  select_path->clear();
  if (is_dir.value()) {
    *dir = path;
    return true;
  }
  const std::size_t slash = path.find_last_of('/');
  if (slash == std::string::npos) return false;
  *dir = slash == 0 ? std::string("/") : path.substr(0, slash);
  *select_path = path;
  return true;
}

const char* MvKindName(mv::meta::stream_kind k) {
  switch (k) {
    case mv::meta::stream_kind::video: return "video";
    case mv::meta::stream_kind::audio: return "audio";
    case mv::meta::stream_kind::subtitle: return "subtitle";
    case mv::meta::stream_kind::attachment: return "attachment";
    case mv::meta::stream_kind::data: return "data";
  }
  return "data";
}

}  // namespace

