// NSEvent -> host key + modifiers, at the edge (commands.h): letters are
// upper-case, a symbol is the character the layout produced with no Shift, and
// named keys are the `key` enumerators. Command and Control both map to `ctrl`
// (Cmd+O is the Mac's Ctrl+O), Option to `alt`. The Mac's Delete key is `del`
// (Trash), where a PC's Backspace is `backspace`.
static mv::shell::key MvKeyFromEvent(NSEvent* event, std::uint8_t* mods_out) {
  using mv::shell::key;
  const NSEventModifierFlags flags =
      event.modifierFlags & NSEventModifierFlagDeviceIndependentFlagsMask;
  std::uint8_t mods = mv::shell::mod_none;
  if (flags & (NSEventModifierFlagCommand | NSEventModifierFlagControl)) mods |= mv::shell::mod_ctrl;
  if (flags & NSEventModifierFlagShift) mods |= mv::shell::mod_shift;
  if (flags & NSEventModifierFlagOption) mods |= mv::shell::mod_alt;
  if (mods_out) *mods_out = mods;

  NSString* ignored = event.charactersIgnoringModifiers;
  const unichar c = ignored.length > 0 ? [ignored characterAtIndex:0] : 0;
  // PR 12 (docs/design/16 Rate): the keypad's digits are their own keys, apart from the
  // number row's, which stay zoom. (The keypad's arrows carry the same flag.)
  if ((event.modifierFlags & NSEventModifierFlagNumericPad) && c >= '0' && c <= '9') {
    return static_cast<key>(static_cast<int>(key::numpad0) + (c - '0'));
  }
  if (c >= NSF1FunctionKey && c <= NSF12FunctionKey) {
    return static_cast<key>(static_cast<int>(key::f1) + static_cast<int>(c - NSF1FunctionKey));
  }
  switch (c) {
    case ' ': return key::space;
    case 0x08: return key::backspace;
    case 0x7F: case NSDeleteFunctionKey: return key::del;
    case '\r': case 0x03: return key::enter;
    case 0x1b: return key::escape;
    case '\t': return key::tab;
    case NSInsertFunctionKey: return key::insert;
    case NSHomeFunctionKey: return key::home;
    case NSEndFunctionKey: return key::end;
    case NSPageUpFunctionKey: return key::page_up;
    case NSPageDownFunctionKey: return key::page_down;
    case NSLeftArrowFunctionKey: return key::left;
    case NSRightArrowFunctionKey: return key::right;
    case NSUpArrowFunctionKey: return key::up;
    case NSDownArrowFunctionKey: return key::down;
    default: break;
  }
  if (c >= 'a' && c <= 'z') return static_cast<key>(c - 'a' + 'A');
  if (c >= 'A' && c <= 'Z') return static_cast<key>(c);
  // `charactersIgnoringModifiers` does not drop Shift, so Shift+/ is '?' in
  // both that string and `characters`. Comparing them never cleared Shift,
  // and the table binds `?` / `+` with no Shift (same as translate_key on
  // Windows). The unshifted glyph comes from the layout, not that string.
  // Command / Control can turn `characters` into a control code; those keep
  // the ignored character.
  NSString* plain = [event charactersByApplyingModifiers:0];
  const unichar plainChar = plain.length > 0 ? [plain characterAtIndex:0] : c;
  const unichar produced = event.characters.length > 0 ? [event.characters characterAtIndex:0] : 0;
  const bool command = (flags & (NSEventModifierFlagCommand | NSEventModifierFlagControl)) != 0;
  return mv::shell::resolve_layout_symbol(plainChar, c, produced, command, mods_out);
}

// PR 15: ⌘⌥-drag hands out the edited copy (⌘⌥C's twin, docs/design/10 PR 15) as a
// file promise. The bake happens only if a drop asks for it, on this queue,
// never the main thread (rule 1), and writes straight to where the drop
// wants the file.
@interface MvFlattenPromise : NSObject <NSFilePromiseProviderDelegate>
- (instancetype)initWithPath:(const std::string&)path
                    geometry:(const mv::edit::geometry&)g
                      colour:(const mv::edit::colour&)c;
@end

@implementation MvFlattenPromise {
  std::string _path;
  mv::edit::geometry _geometry;
  mv::edit::colour _colour;
  NSOperationQueue* _queue;
}
- (instancetype)initWithPath:(const std::string&)path
                    geometry:(const mv::edit::geometry&)g
                      colour:(const mv::edit::colour&)c {
  if ((self = [super init])) {
    _path = path;
    _geometry = g;
    _colour = c;
    _queue = [[NSOperationQueue alloc] init];
    _queue.qualityOfService = NSQualityOfServiceUserInitiated;
  }
  return self;
}
- (NSString*)filePromiseProvider:(NSFilePromiseProvider*)provider fileNameForType:(NSString*)fileType {
  (void)provider;
  (void)fileType;
  return [NSString stringWithUTF8String:mv::shell::flattened_file_name(_path).c_str()] ?: @"edited.png";
}
- (NSOperationQueue*)operationQueueForFilePromiseProvider:(NSFilePromiseProvider*)provider {
  (void)provider;
  return _queue;
}
- (void)filePromiseProvider:(NSFilePromiseProvider*)provider
          writePromiseToURL:(NSURL*)url
          completionHandler:(void (^)(NSError* _Nullable))done {
  (void)provider;
  auto png = mv::shell::render_flattened_png(_path, _geometry, _colour);
  const char* dest = url.fileSystemRepresentation;
  if (!png || !dest || !mv::io::write_new(dest, png.value())) {
    done([NSError errorWithDomain:NSCocoaErrorDomain code:NSFileWriteUnknownError userInfo:nil]);
    return;
  }
  done(nil);
}
@end

// docs/plans/edit-refresh.md §2.3: the right column's edge. 6 pt wide and centred
// on the column's leading edge, above the panes; drag it to widen or narrow
// every right pane at once, double-click for the default. Its own layer draws
// a 1 px hairline, a 2 px accent line with a grip pill while hovered or
// dragged. Accessibility: a splitter whose value steps like pane_wider /
// pane_narrower.
@interface MvPaneEdgeView : NSView
@property(nonatomic, assign) MvLabApp* app;
// The theme's hairline and accent changed (MVChromeThemeDidChange).
- (void)restyle;
@end

@implementation MvPaneEdgeView {
  CALayer* _line;
  CALayer* _grip;
  NSTrackingArea* _tracking;
  BOOL _hot;
  BOOL _dragging;
}
- (instancetype)initWithFrame:(NSRect)frame {
  if ((self = [super initWithFrame:frame])) {
    self.wantsLayer = YES;
    _line = [CALayer layer];
    _grip = [CALayer layer];
    _grip.cornerRadius = 2.0;
    [self.layer addSublayer:_line];
    [self.layer addSublayer:_grip];
  }
  return self;
}
- (BOOL)isFlipped {
  return YES;
}
- (BOOL)acceptsFirstMouse:(NSEvent*)event {
  (void)event;
  return YES;
}
- (void)layout {
  [super layout];
  [self restyle];
}
- (void)viewDidChangeEffectiveAppearance {
  [super viewDidChangeEffectiveAppearance];
  [self restyle];
}
- (void)restyle {
  const BOOL lit = _hot || _dragging;
  const NSRect b = self.bounds;
  const CGFloat w = lit ? 2.0 : 1.0;
  [CATransaction begin];
  [CATransaction setDisableActions:YES];
  _line.frame = CGRectMake(NSMidX(b) - w * 0.5, 0.0, w, NSHeight(b));
  _grip.frame = CGRectMake(NSMidX(b) - 2.0, NSMidY(b) - 14.0, 4.0, 28.0);
  _grip.hidden = !lit;
  NSColor* line = lit ? MVChromeHost.paneEdgeAccent : MVChromeHost.paneEdgeHairline;
  NSColor* grip = MVChromeHost.paneEdgeAccent;
  CALayer* lineLayer = _line;
  CALayer* gripLayer = _grip;
  [self.effectiveAppearance performAsCurrentDrawingAppearance:^{
    lineLayer.backgroundColor = line.CGColor;
    gripLayer.backgroundColor = grip.CGColor;
  }];
  [CATransaction commit];
}
- (void)resetCursorRects {
  [self addCursorRect:self.bounds cursor:[NSCursor resizeLeftRightCursor]];
}
- (void)updateTrackingAreas {
  [super updateTrackingAreas];
  if (_tracking) [self removeTrackingArea:_tracking];
  _tracking = [[NSTrackingArea alloc]
      initWithRect:self.bounds
           options:NSTrackingMouseEnteredAndExited | NSTrackingActiveInKeyWindow | NSTrackingInVisibleRect
             owner:self
          userInfo:nil];
  [self addTrackingArea:_tracking];
}
- (void)mouseEntered:(NSEvent*)event {
  (void)event;
  _hot = YES;
  [self restyle];
}
- (void)mouseExited:(NSEvent*)event {
  (void)event;
  _hot = NO;
  [self restyle];
}
- (void)mouseDown:(NSEvent*)event {
  if (event.clickCount == 2) {
    [self.app paneEdgeReset];
    return;
  }
  _dragging = YES;
  [self restyle];
  [self.app paneEdgeDown:event];
}
- (void)mouseDragged:(NSEvent*)event {
  if (_dragging) [self.app paneEdgeDragged:event];
}
- (void)mouseUp:(NSEvent*)event {
  if (!_dragging) return;
  _dragging = NO;
  [self restyle];
  [self.app paneEdgeUp:event];
}
- (void)setHidden:(BOOL)hidden {
  [super setHidden:hidden];
  if (hidden && _hot) {
    _hot = NO;
    [self restyle];
  }
}
- (BOOL)isAccessibilityElement {
  return YES;
}
- (NSAccessibilityRole)accessibilityRole {
  return NSAccessibilitySplitterRole;
}
- (NSString*)accessibilityLabel {
  return @"Side pane width";
}
- (id)accessibilityValue {
  return @(static_cast<int>(self.app ? [self.app paneShownPoints] : 0.0));
}
- (BOOL)accessibilityPerformIncrement {
  [self.app paneStep:1];
  return YES;
}
- (BOOL)accessibilityPerformDecrement {
  [self.app paneStep:-1];
  return YES;
}
@end

@interface MvMetalView : NSView <NSDraggingSource>
@property(nonatomic, assign) mv::shell::present_lab_mac* lab;
@property(nonatomic, assign) mv::shell::input_snapshot* snap;
// Weak-by-convention (assign, not strong): MvLabApp owns this view for its
// whole lifetime, the reverse is never true. Used for the browse commands
// (arrows, Home/End/PageUp/PageDown, Space/Backspace once a folder is open)
// that need folder_model/browse_index state MvLabApp owns, not just an
// input_snapshot bump like every other key here.
@property(nonatomic, assign) MvLabApp* app;
- (void)syncSize;
- (void)syncChrome;
@end

@implementation MvMetalView {
  int _welcomePress;  // welcome row under the left press, + 1; 0 = none
  BOOL _welcomePressRemove;  // ... and the press was on its remove button
  BOOL _brushStroke;  // slice 7: the left press is a Remove brush stroke
  BOOL _cropDrag;     // docs/design/20: the left press holds a crop handle
  BOOL _compareDrag;  // docs/design/20 "Compare": the left press holds the split's divider
  BOOL _compareCursor;  // the left-right cursor is up over the divider
  BOOL _textBeam;            // the I-beam is up over text in a still
  // Issue #212 (shell/gesture.h): a pinch's sub-notch remainder, and the
  // two-finger sideways swipe that steps one item.
  mv::shell::pinch_to_wheel _pinch;
  mv::shell::swipe_detector _wheelSwipe;
  BOOL _contextMenuShown;  // the last menuForEvent: answered with a menu (issue #402)
}
- (void)viewDidChangeEffectiveAppearance {
  [super viewDidChangeEffectiveAppearance];
  if (self.app) [self.app syncHomeAppearance];
}
// NSDraggingSource: Cmd+drag-out (mouseDown: above). Copy-only -- dragging
// the displayed item out never removes it from the folder; that's what
// Delete/Trash and F8/move are for.
- (NSDragOperation)draggingSession:(NSDraggingSession*)session
    sourceOperationMaskForDraggingContext:(NSDraggingContext)context {
  (void)session;
  (void)context;
  return NSDragOperationCopy;
}
- (BOOL)wantsLayer {
  return YES;
}
- (CALayer*)makeBackingLayer {
  CAMetalLayer* layer = [CAMetalLayer layer];
  layer.pixelFormat = MTLPixelFormatBGRA8Unorm_sRGB;
  layer.framebufferOnly = YES;
  // 2, not 1: found on real hardware (2026-09-18) -- CAMetalLayer rejects
  // maximumDrawableCount outside [2, 3] and throws
  // CAMetalLayerInvalidMaximumDrawableCount. docs/design/15's PR 16 spec says "max
  // drawable 1", carried over from D3D11's SetMaximumFrameLatency(1); Metal
  // has no equivalent of 1, so 2 (the minimum it allows) is the actual
  // lowest-latency setting achievable, not a relaxation of the same intent.
  layer.maximumDrawableCount = 2;
  layer.displaySyncEnabled = YES;
  return layer;
}
- (BOOL)acceptsFirstResponder {
  // PR 30: in the Video Editor the keys are the editor's (its timeline has
  // focus); a click on the preview must not hand them to the browse router,
  // where A / D would walk the folder out from under the edit.
  return !(self.app && [self.app editorOwnsCanvas]);
}
- (BOOL)resignFirstResponder {
  // Issue #186: a command that hands focus to a pane (adjust, metadata, Jobs,
  // the gallery) or a click into one takes the key-up with it. Release what
  // the canvas holds now, or a held Y keeps showing the original.
  if (self.app) [self.app cancelKeyHolds];
  return [super resignFirstResponder];
}
- (BOOL)isOpaque {
  return YES;
}

- (void)publish {
  if (self.lab && self.snap) self.lab->publish(*self.snap);
}

// A real size, scale or backing change: the layer's drawable follows it
// (resize_seq). setFrameSize and the backing properties only.
- (void)syncSize {
  [self fillCanvasRect];
  ++self.snap->resize_seq;
  [self publish];
  if (self.lab) self.lab->wake();
}

// docs/design/12 2026-11-04 (refit_seq): the chrome moved the canvas rect (a
// pane docked, the right column's edge, the filmstrip, the bar, the page
// sidebar) and the window did not. The render thread re-fits the picture and
// never touches the layer. If the backing size did change under it (it should
// not: setFrameSize comes first), it is a resize after all.
- (void)syncChrome {
  const std::uint32_t w = self.snap->width, h = self.snap->height;
  const float scale = self.snap->dpi_scale;
  [self fillCanvasRect];
  if (self.snap->width != w || self.snap->height != h || self.snap->dpi_scale != scale) {
    ++self.snap->resize_seq;
  } else {
    ++self.snap->refit_seq;
  }
  [self publish];
  if (self.lab) self.lab->wake();
}

- (void)fillCanvasRect {
  const NSSize backing = [self convertSizeToBacking:self.bounds.size];
  self.snap->width = static_cast<std::uint32_t>(std::max(1.0, backing.width));
  self.snap->height = static_cast<std::uint32_t>(std::max(1.0, backing.height));
  self.snap->dpi_scale = static_cast<float>(self.window.backingScaleFactor);
  const CGFloat bar = self.app ? [self.app chromeBarHeight] : kChromeBarHeightPoints;
  self.snap->chrome_height_px = static_cast<std::uint32_t>(bar * self.window.backingScaleFactor);
  // PR 30: in the Video Editor's preview nothing is drawn over the canvas.
  if (self.app && [self.app editorOwnsCanvas]) self.snap->chrome_height_px = 0;
  // chrome_bottom_px: 0 when the filmstrip is hidden, so present_lab_mac.mm's
  // usable_window_h() lets the canvas reclaim that space the moment `T`
  // hides it -- single source of truth here, same as chrome_height_px above,
  // rather than -toggleFilmstrip computing this itself and risking the two
  // falling out of sync on a resize/DPI change.
  self.snap->chrome_bottom_px = (self.app && [self.app filmstripVisible] && ![self.app editorOwnsCanvas])
      ? static_cast<std::uint32_t>(kFilmstripHeightPoints * self.window.backingScaleFactor)
      : 0;
  // docs/plans/edit-refresh.md S3: the context bar's band below the photo
  // while a tool is armed (the transport's slot; nothing over the picture).
  if (self.app && [self.app toolBandShown]) {
    self.snap->chrome_bottom_px += static_cast<std::uint32_t>(mv::shell::kToolBarBand * self.window.backingScaleFactor);
  }
  // Issue #429: the page sidebar reserves the left edge the same way.
  self.snap->chrome_left_px = (self.app && [self.app pageSidebarShown])
      ? static_cast<std::uint32_t>(kPageSidebarWidthPoints * self.window.backingScaleFactor)
      : 0;
  // PR 29: the Edit workspace docks instead of covering the picture.
  self.snap->chrome_right_px = self.app
      ? static_cast<std::uint32_t>([self.app dockedRightPoints] * self.window.backingScaleFactor)
      : 0;
}

- (void)viewDidMoveToWindow {
  [super viewDidMoveToWindow];
  [self registerForDraggedTypes:@[ NSPasteboardTypeFileURL ]];
  [self syncSize];
}

// docs/design/16-commands.md "Opening (argv, drop, PR 6)": accept the drop as long
// as it names at least one file: URL, so -performDragOperation: can apply
// the same "first entry that exists wins" rule as argv (-openEntryPaths:failed:,
// over every URL dropped). Any other pasteboard content (text, a web
// link dragged from a browser, images) is not a file and is refused.
// NSPasteboardURLReadingFileURLsOnlyKey matters here, not just as a filter
// convenience: without it, readObjectsForClasses: happily decodes a
// non-file NSURL (e.g. a Safari address-bar drag) too, so
// -draggingEntered: would show the accept cursor for something
// -performDragOperation: can only fail (is_directory() on a non-file path)
// and silently beep on drop. A drag of ours (the canvas's ⌘-drag, a cell) is
// refused too: dropped back on our own window it would reopen what is shown.
- (NSDragOperation)draggingEntered:(id<NSDraggingInfo>)sender {
  if (sender.draggingSource != nil) return NSDragOperationNone;
  NSArray<NSURL*>* urls = [sender.draggingPasteboard
      readObjectsForClasses:@[ NSURL.class ]
                     options:@{NSPasteboardURLReadingFileURLsOnlyKey : @YES}];
  return urls.count > 0 ? NSDragOperationCopy : NSDragOperationNone;
}
- (NSDragOperation)draggingUpdated:(id<NSDraggingInfo>)sender {
  return [self draggingEntered:sender];
}
- (BOOL)performDragOperation:(id<NSDraggingInfo>)sender {
  NSArray<NSURL*>* urls = [sender.draggingPasteboard
      readObjectsForClasses:@[ NSURL.class ]
                     options:@{NSPasteboardURLReadingFileURLsOnlyKey : @YES}];
  if (sender.draggingSource != nil || urls.count == 0 || !self.app) return NO;
  NSMutableArray<NSString*>* paths = [NSMutableArray array];
  for (NSURL* url in urls) {
    if (url.path) [paths addObject:url.path];
  }
  if (paths.count == 0) return NO;
  [self.app openEntryPaths:paths failed:nil];
  return YES;
}

- (void)setFrameSize:(NSSize)newSize {
  [super setFrameSize:newSize];
  // The right column re-clamps to the new width first (pane_width.h), so the
  // docked rect this publishes is the one laid out.
  if (self.app) [self.app applyPaneWidth];
  [self syncSize];
}

- (void)viewDidChangeBackingProperties {
  [super viewDidChangeBackingProperties];
  ++self.snap->display_change_seq;
  [self syncSize];
}

- (void)mouseDown:(NSEvent*)event {
  // Drag-out (docs/design/16 "Opening (argv, drop, PR 6)"): Cmd+drag starts a file
  // drag of the currently displayed item instead of panning. Gated on a
  // modifier rather than any mouseDown+move, because mouseDragged: already
  // means "pan" for every existing gesture -- overloading the same bare
  // click-drag would make an accidental small drag-out fire on every pan.
  const bool edited = (event.modifierFlags & NSEventModifierFlagOption) != 0;
  if ((event.modifierFlags & NSEventModifierFlagCommand) && edited && self.app) {
    if (NSFilePromiseProvider* promise = [self.app flattenedPromiseForDrag]) {
      NSDraggingItem* dragItem = [[NSDraggingItem alloc] initWithPasteboardWriter:promise];
      const NSPoint p = [self convertPoint:event.locationInWindow fromView:nil];
      dragItem.draggingFrame = NSMakeRect(p.x - 16, p.y - 16, 32, 32);
      [self beginDraggingSessionWithItems:@[ dragItem ] event:event source:self];
      return;
    }
  }
  if ((event.modifierFlags & NSEventModifierFlagCommand) && self.app) {
    NSString* path = [self.app currentItemPathForDrag];
    if (path) {
      NSPasteboardItem* item = [[NSPasteboardItem alloc] init];
      [item setString:[[NSURL fileURLWithPath:path] absoluteString]
              forType:NSPasteboardTypeFileURL];
      NSDraggingItem* dragItem = [[NSDraggingItem alloc] initWithPasteboardWriter:item];
      const NSPoint p = [self convertPoint:event.locationInWindow fromView:nil];
      dragItem.draggingFrame = NSMakeRect(p.x - 16, p.y - 16, 32, 32);
      [self beginDraggingSessionWithItems:@[ dragItem ] event:event source:self];
      return;
    }
  }
  [self trackPointer:event];
  // docs/design/20 "Compare": a press on the split's divider drags it; nothing
  // pans (mouse_down is never published for it).
  if (self.app && [self.app compareGrabX:self.snap->mouse_x y:self.snap->mouse_y]) {
    _compareDrag = YES;
    return;
  }
  // docs/design/20 Behaviour 4: in crop mode a press on the draft's edge or
  // corner resizes it and one inside moves it; anywhere else pans as before.
  if (self.app && [self.app cropPressX:self.snap->mouse_x y:self.snap->mouse_y]) {
    _cropDrag = YES;
    return;
  }
  // docs/plans/edit-refresh.md S3: an armed canvas tool takes the press on the
  // photo (the brush strokes while the button is down; red-eye and the
  // white-balance picker click); nothing pans. Space held pans instead.
  if (self.app && [self.app toolArmed] && ![self.app toolPanHeld]) {
    if ([self.app brushActive]) {
      [self.app toolModifiers:(event.modifierFlags & NSEventModifierFlagOption) != 0];
      _brushStroke = [self.app brushPressX:self.snap->mouse_x y:self.snap->mouse_y];
    } else if ([self.app extendActive]) {
      // S6: a press on an edge (or inside) of Extend's frame drags it; the
      // drag and release go through the brush's path (-brushDragX:, -brushRelease).
      _brushStroke = [self.app extendPressX:self.snap->mouse_x y:self.snap->mouse_y];
    } else {
      [self.app adjustPickAtX:self.snap->mouse_x y:self.snap->mouse_y];
    }
    return;
  }
  _welcomePress = self.app ? [self.app welcomeRowAtPointerOnRemove:&_welcomePressRemove] + 1 : 0;
  // Text in images: a press on a word selects (published with the press, so
  // the render thread never starts a pan for it).
  // S3: with a tool armed (Space held) a press pans, never selects words.
  self.snap->text_press = self.app && ![self.app toolArmed] && [self.app textPressX:self.snap->mouse_x
                                                                                y:self.snap->mouse_y
                                                                           clicks:event.clickCount];
  self.snap->mouse_down[0] = true;
  ++self.snap->activity_seq;
  [self publish];
  if (self.lab) self.lab->wake();
  if (self.app) [self.app transportActivity];
}
- (void)mouseUp:(NSEvent*)event {
  if (_compareDrag) {
    _compareDrag = NO;
    [self trackPointer:event];
    if (self.app) [self.app compareReleaseX:self.snap->mouse_x y:self.snap->mouse_y];
    return;
  }
  if (_cropDrag) {
    _cropDrag = NO;
    if (self.app) [self.app cropRelease];
    return;
  }
  if (_brushStroke) {
    _brushStroke = NO;
    if (self.app) [self.app brushRelease];
  }
  self.snap->mouse_down[0] = false;
  if (self.snap->text_press) {
    self.snap->text_press = false;
    if (self.app) [self.app textRelease];
  }
  ++self.snap->activity_seq;
  [self publish];
  if (self.lab) self.lab->wake();
  // A click on a recent folder (or its x): pressed and released on the same
  // row and the same part of it.
  const int pressed = _welcomePress - 1;
  _welcomePress = 0;
  if (pressed >= 0 && self.app) {
    [self trackPointer:event];
    BOOL onRemove = NO;
    if ([self.app welcomeRowAtPointerOnRemove:&onRemove] == pressed && onRemove == _welcomePressRemove) {
      if (onRemove) {
        [self.app removeWelcomeRow:pressed];
        [([self.app welcomePointerMoved] ? NSCursor.pointingHandCursor : NSCursor.arrowCursor) set];
      } else {
        [self.app openWelcomeRow:pressed];
      }
    }
  }
}
- (void)rightMouseDown:(NSEvent*)event {
  self.snap->mouse_down[1] = true;
  ++self.snap->activity_seq;
  [self publish];
  if (self.app) [self.app transportActivity];
  // NSView's own shows menuForEvent:'s menu (and returns when it closes, its
  // tracking having taken the release), or passes the click on when it is nil.
  _contextMenuShown = NO;
  [super rightMouseDown:event];
  if (_contextMenuShown) {
    self.snap->mouse_down[1] = false;
    [self publish];
  }
}
// docs/design/25, issue #402: the add-ons' context-menu entries for the file on
// screen, as its gallery tile lists them (right-click or Control-click). Nil,
// so no menu, over the gallery, the editor, an empty window, or when no add-on
// contributes an entry.
- (NSMenu*)menuForEvent:(NSEvent*)event {
  NSMenu* menu = nil;
  // Issue #617: a welcome card folder row's own menu. The card lists rows only
  // while nothing is open, so it never competes with the add-ons' menu.
  if (self.app) {
    [self trackPointer:event];
    const int row = [self.app welcomeRowAtPointer];
    if (row >= 0) menu = [self.app welcomeRowMenu:row];
  }
  if (!menu && self.app && ![self.app galleryVisible] && ![self.app editorOwnsCanvas] && [self.app hasFolder]) {
    menu = [MVChromeHost canvasContextMenu];
  }
  _contextMenuShown = menu != nil;
  return menu;
}
- (void)rightMouseUp:(NSEvent*)event {
  (void)event;
  self.snap->mouse_down[1] = false;
  [self publish];
}
- (void)scrollWheel:(NSEvent*)event {
  // docs/plans/edit-refresh.md S3: ⌥ + wheel sizes the armed tool's ring.
  if ((event.modifierFlags & NSEventModifierFlagOption) != 0 && self.app &&
      [self.app toolWheel:event.scrollingDeltaY precise:event.hasPreciseScrollingDeltas]) {
    return;
  }
  // Over a document with the filmstrip hidden the wheel scrolls; Cmd zooms, as
  // does a pinch (docs/design/04 "Pages").
  if ((event.modifierFlags & NSEventModifierFlagCommand) == 0 && self.app && [self.app documentScrolls]) {
    [self.app scrollDocument:event];
    if (self.app) [self.app transportActivity];
    return;
  }
  // Issue #212: a two-finger sideways swipe (or a tilt) is swipe-next, one
  // item per swipe; its momentum runs out inside the detector's latch. A
  // negative delta moves the content left (natural scrolling: fingers left),
  // which brings in the next item, as on Windows. Precise deltas are points;
  // three of them weigh as one wheel unit.
  const double per_unit = event.hasPreciseScrollingDeltas ? 3.0 : 120.0;
  const int swipe = _wheelSwipe.feed(-event.scrollingDeltaX * per_unit, event.scrollingDeltaY * per_unit,
                                     static_cast<std::uint64_t>(event.timestamp * 1000.0));
  if (swipe != 0 && self.app) [self.app swipeStep:swipe];
  if (std::abs(event.scrollingDeltaX) > std::abs(event.scrollingDeltaY)) {
    // Sideways never zooms.
    if (self.app) [self.app transportActivity];
    return;
  }
  self.snap->wheel_total += static_cast<std::int64_t>(event.scrollingDeltaY * 120.0);
  ++self.snap->activity_seq;
  [self publish];
  if (self.lab) self.lab->wake();
  if (self.app) [self.app transportActivity];
  // The wheel zoomed a document because the strip is up: say how to scroll.
  if ((event.modifierFlags & NSEventModifierFlagCommand) == 0 && self.app) [self.app stripHintShow];
}
// A trackpad pinch zooms toward the pointer, as the wheel does: one wheel notch
// is a 15 % step (canvas/camera.cpp kWheelFactor). shell/gesture.h carries the
// sub-unit remainder, so a slow pinch is not rounded away (issue #212).
- (void)magnifyWithEvent:(NSEvent*)event {
  if (event.phase == NSEventPhaseBegan) _pinch.reset();
  const std::int64_t units = _pinch.feed(1.0 + event.magnification);
  if (units == 0) return;
  [self trackPointer:event];
  self.snap->wheel_total += units;
  ++self.snap->activity_seq;
  [self publish];
  if (self.lab) self.lab->wake();
}
// A three-finger swipe, when System Settings sends it as a swipe ("Swipe
// between pages" with three fingers): deltaX is +1 for a swipe to the left,
// the next item.
- (void)swipeWithEvent:(NSEvent*)event {
  if (event.deltaX != 0.0 && self.app) [self.app swipeStep:event.deltaX > 0.0 ? 1 : -1];
}
// Without a tracking area AppKit never sends mouseMoved: to a plain view, which is
// why the eyedropper had no cursor to read. Idle stays idle: the move only wakes
// the render thread while the eyedropper is on.
- (void)updateTrackingAreas {
  [super updateTrackingAreas];
  for (NSTrackingArea* area in [self.trackingAreas copy]) [self removeTrackingArea:area];
  [self addTrackingArea:[[NSTrackingArea alloc]
                            initWithRect:NSZeroRect
                                 options:NSTrackingMouseMoved | NSTrackingMouseEnteredAndExited |
                                         NSTrackingActiveInKeyWindow | NSTrackingInVisibleRect
                                   owner:self
                                userInfo:nil]];
}
- (void)mouseExited:(NSEvent*)event {
  (void)event;
  self.snap->mouse_in_client = false;
  if (self.app) [self.app toolCursorRestore];  // S3: the ring goes, the arrow comes back
  if (self.app && !_cropDrag) [self.app cropHoverX:self.snap->mouse_x y:self.snap->mouse_y];  // off the canvas: the arrow
  if (self.app && !_compareDrag) (void)[self.app compareHoverX:-1.0e9f y:-1.0e9f];
  _compareCursor = NO;
  if (_textBeam) {
    _textBeam = NO;
    [NSCursor.arrowCursor set];
  }
  if (self.app && self.snap->recents.hover >= 0) {
    (void)[self.app welcomePointerMoved];
    [NSCursor.arrowCursor set];
  }
  if (self.snap->eyedropper || self.snap->loupe) ++self.snap->activity_seq;
  [self publish];
  if ((self.snap->eyedropper || self.snap->loupe) && self.lab) self.lab->wake();
  if (self.app) [self.app transportActivity];  // a pointer hidden over the video comes back
}
- (void)trackPointer:(NSEvent*)event {
  const NSPoint p = [self convertPoint:event.locationInWindow fromView:nil];
  const NSPoint backing = [self convertPointToBacking:p];
  self.snap->mouse_x = static_cast<float>(backing.x);
  self.snap->mouse_y = static_cast<float>(self.snap->height) - static_cast<float>(backing.y);
  self.snap->mouse_in_client = NSPointInRect(p, self.bounds);
}
- (void)mouseMoved:(NSEvent*)event {
  [self trackPointer:event];
  // docs/design/20 "Compare": dragging the split's divider, or over it (the
  // left-right cursor, the divider in the accent).
  if (self.app && _compareDrag) {
    [self.app compareDragX:self.snap->mouse_x];
    return;
  }
  const BOOL overDivider =
      self.app && self.snap->mouse_in_client && [self.app compareHoverX:self.snap->mouse_x y:self.snap->mouse_y];
  // Slice 7 / S3: the tool's ring follows the pointer (it is the cursor over
  // the canvas); a drag paints. The red-eye ring snaps to an eye.
  if (self.app && [self.app toolArmed]) {
    if (_brushStroke) [self.app brushDragX:self.snap->mouse_x y:self.snap->mouse_y];
    else [self.app brushHoverX:self.snap->mouse_x y:self.snap->mouse_y];
    [self.app toolCursor];
  }
  // docs/design/20 Behaviour 4: a held crop handle drags the draft; the one
  // under the pointer picks the cursor (and gives it back once crop mode ends).
  const BOOL cropping = self.app && [self.app cropHandles];
  if (cropping && _cropDrag) [self.app cropDragX:self.snap->mouse_x y:self.snap->mouse_y];
  else if (self.app) [self.app cropHoverX:self.snap->mouse_x y:self.snap->mouse_y];
  // A recent folder under the pointer reads as a link. Only a change of row
  // redraws (the app bumps the snapshot); an empty welcome stays idle.
  if (self.app && self.snap->recents.count > 0) {
    [([self.app welcomePointerMoved] ? NSCursor.pointingHandCursor : NSCursor.arrowCursor) set];
  } else if (self.app && !cropping && (event.type == NSEventTypeMouseMoved || self.snap->text_press)) {
    // Text in images: the I-beam over words in a still.
    const BOOL beam = self.snap->mouse_in_client && [self.app textHoverX:self.snap->mouse_x y:self.snap->mouse_y];
    if (beam || _textBeam) [(beam ? NSCursor.IBeamCursor : NSCursor.arrowCursor) set];
    _textBeam = beam;
  }
  // docs/design/20 "Compare": the left-right cursor over the split's divider,
  // set last so it wins over the ring and the I-beam.
  if (overDivider) {
    [NSCursor.resizeLeftRightCursor set];
    _compareCursor = YES;
  } else if (_compareCursor) {
    _compareCursor = NO;
    [NSCursor.arrowCursor set];
    if (self.app && [self.app toolArmed]) [self.app toolCursor];
  }
  if (self.snap->eyedropper || self.snap->loupe) ++self.snap->activity_seq;
  [self publish];
  if ((self.snap->eyedropper || self.snap->loupe) && self.lab) self.lab->wake();
  // Issue #38: movement (and entry, which arrives as a move) wakes the clip's
  // transport. A bool test and nothing else when no clip is on screen.
  if (self.app) [self.app transportActivity];
  // Issue #408: the home's ground effect rests five seconds after the pointer.
  if (self.app) [self.app pointerActivity];
}
- (void)mouseDragged:(NSEvent*)event {
  [self mouseMoved:event];
  if (_compareDrag) return;
  if (self.snap->text_press && self.app) [self.app textDragX:self.snap->mouse_x y:self.snap->mouse_y];
  ++self.snap->activity_seq;
  [self publish];
  if (self.lab) self.lab->wake();
}
- (void)keyDown:(NSEvent*)event {
  // Every key goes through the shared router (docs/design/16); MvLabApp runs the
  // command. An unhandled key is simply ignored -- no system beep per stray key.
  if (self.app) (void)[self.app handleKeyEvent:event];
}
// docs/plans/edit-refresh.md S3: Option held makes the brush erase (its ring
// dashes at once, before the next move).
- (void)flagsChanged:(NSEvent*)event {
  if (self.app) [self.app toolModifiers:(event.modifierFlags & NSEventModifierFlagOption) != 0];
  [super flagsChanged:event];
}

- (void)keyUp:(NSEvent*)event {
  if (self.app) (void)[self.app handleKeyEvent:event];
}
@end

// ---- Default viewer (docs/design/13) --------------------------------------------------

// The types to become the default for are read back from our own Info.plist, so
// the prompt, Finder's Open With list and the Quick Look extension cannot
// disagree. `name` picks one CFBundleDocumentTypes entry ("Image", "Video");
// nil = every type the app may be made the default for: the photos and videos.
// The audio and document types are declared for Open With only and are never
// made the default here (owner, 2026-10-03; docs/plans/audio-and-documents.md §3).
static NSArray<NSString*>* MvDeclaredContentTypes(NSString* name) {
  NSMutableArray<NSString*>* types = [NSMutableArray array];
  for (NSDictionary* docType in NSBundle.mainBundle.infoDictionary[@"CFBundleDocumentTypes"]) {
    NSString* typeName = docType[@"CFBundleTypeName"];
    if (name != nil && ![typeName isEqual:name]) continue;
    // Only the photo and video types: not the Open With types (audio, documents)
    // and not the add-on package (docs/design/25), which is ours already
    // (LSHandlerRank Owner) and is not a photo type.
    if (name == nil && ![typeName isEqual:@"Image"] && ![typeName isEqual:@"Video"]) continue;
    for (NSString* identifier in docType[@"LSItemContentTypes"]) [types addObject:identifier];
  }
  return types;
}

static void MvSetDefaultViewer(NSArray<NSString*>* identifiers) {
  NSURL* app = NSBundle.mainBundle.bundleURL;
  for (NSString* identifier in identifiers) {
    UTType* type = [UTType typeWithIdentifier:identifier];
    if (!type) continue;
    [NSWorkspace.sharedWorkspace setDefaultApplicationAtURL:app
                                          toOpenContentType:type
                                          completionHandler:^(NSError* error) {
                                            if (error) MV_LOG_WARN("default viewer: a type was not set");
                                          }];
  }
}

// What the user was offered and whether they took it. A type added in a later
// release (video joined the stills after the first builds shipped) is not in
// MVDefaultViewerTypes; if they chose "all supported photos and videos",
// MvAdoptNewDefaultViewerTypes gives it to them too, once. A type they later
// moved to another app in Finder stays moved: it is already in the record.
static NSString* const kDefaultsViewerTypes = @"MVDefaultViewerTypes";
static NSString* const kDefaultsViewerChosen = @"MVDefaultViewerChosen";

static void MvRecordDefaultViewerOffer(BOOL chosen) {
  NSUserDefaults* d = NSUserDefaults.standardUserDefaults;
  [d setObject:MvDeclaredContentTypes(nil) forKey:kDefaultsViewerTypes];
  [d setBool:chosen forKey:kDefaultsViewerChosen];
}

#if MV_APP_BUNDLE
// Launch, off the main thread and after the first picture: LaunchServices
// queries are synchronous and never belong on the open path (rule 1).
static void MvAdoptNewDefaultViewerTypes() {
  dispatch_after(dispatch_time(DISPATCH_TIME_NOW, static_cast<int64_t>(3 * NSEC_PER_SEC)),
                 dispatch_get_global_queue(QOS_CLASS_UTILITY, 0), ^{
    NSUserDefaults* d = NSUserDefaults.standardUserDefaults;
    NSArray* offered = [d arrayForKey:kDefaultsViewerTypes];
    if (offered == nil) {
      // An install from before the record: that prompt offered the stills.
      // Still opening one of them means the user said yes.
      NSArray<NSString*>* stills = MvDeclaredContentTypes(@"Image");
      NSString* ours = NSBundle.mainBundle.bundleIdentifier;
      BOOL chosen = NO;
      for (NSString* identifier in stills) {
        UTType* type = [UTType typeWithIdentifier:identifier];
        NSURL* handler = type ? [NSWorkspace.sharedWorkspace URLForApplicationToOpenContentType:type] : nil;
        if (handler && [[NSBundle bundleWithURL:handler].bundleIdentifier isEqualToString:ours]) {
          chosen = YES;
          break;
        }
      }
      offered = stills;
      [d setObject:offered forKey:kDefaultsViewerTypes];
      [d setBool:chosen forKey:kDefaultsViewerChosen];
    }
    if (![d boolForKey:kDefaultsViewerChosen]) return;
    NSArray<NSString*>* declared = MvDeclaredContentTypes(nil);
    NSMutableArray<NSString*>* added = [NSMutableArray array];
    for (NSString* identifier in declared) {
      if (![offered containsObject:identifier]) [added addObject:identifier];
    }
    if (added.count == 0) return;
    MV_LOG_INFO("default viewer: adopting types added since the user chose MediaViewer");
    MvSetDefaultViewer(added);
    [d setObject:declared forKey:kDefaultsViewerTypes];
  });
}
#endif

// ---- Issue #614: Print (⌘P; docs/design/16 "Print", shell/print_layout.h) ---------
//
// The bake runs on the pool before the panel opens ("Preparing to print…"),
// sized for the paper Page Setup holds; nothing is written, so Cancel leaves no
// file. NSPrintOperation then runs modal for the window (a sheet) over
// MvPrintView, with MvPrintOptions as the panel's accessory: fit or fill, the
// sheet's layout and its file names. The operation spools on its own thread
// (canSpawnSeparateThread), so the main thread never draws a page.

// A CGImage over a baked picture: tagged sRGB (the bake), or with the picture's
// own ICC profile (the re-encode path keeps it), so Quartz colour-manages to
// the printer what the export's PNG holds. Any thread. The pixels are copied:
// the raster can go once this returns.
static CGImageRef MvPrintImage(const mv::codec::raster& r) {
  if (r.width == 0 || r.height == 0 || r.rgba.size() < static_cast<std::size_t>(r.width) * r.height * 4) {
    return nullptr;
  }
  CFDataRef bytes = CFDataCreate(nullptr, r.rgba.data(), static_cast<CFIndex>(r.rgba.size()));
  CGDataProviderRef provider = bytes ? CGDataProviderCreateWithCFData(bytes) : nullptr;
  if (bytes) CFRelease(bytes);
  CGColorSpaceRef space = nullptr;
  if (!r.icc.empty()) {
    CFDataRef icc = CFDataCreate(nullptr, r.icc.data(), static_cast<CFIndex>(r.icc.size()));
    if (icc) {
      space = CGColorSpaceCreateWithICCData(icc);
      CFRelease(icc);
    }
  }
  if (!space) space = CGColorSpaceCreateWithName(kCGColorSpaceSRGB);
  CGImageRef cg = provider && space
                      ? CGImageCreate(r.width, r.height, 8, 32, static_cast<std::size_t>(r.width) * 4, space,
                                      static_cast<CGBitmapInfo>(kCGImageAlphaLast), provider, nullptr, true,
                                      kCGRenderingIntentPerceptual)
                      : nullptr;
  CGColorSpaceRelease(space);
  CGDataProviderRelease(provider);
  return cg;
}

// The paper NSPrintInfo describes, in print_layout's terms (top-left origin).
static mv::shell::print_page MvPrintPage(NSPrintInfo* info) {
  const NSSize paper = info.paperSize;
  const NSRect ib = info.imageablePageBounds;  // bottom-left origin
  mv::shell::print_page page;
  page.width = paper.width;
  page.height = paper.height;
  page.printable = {ib.origin.x, paper.height - NSMaxY(ib), ib.size.width, ib.size.height};
  return page;
}

// The print panel's accessory. Each property is KVO-observed by the panel
// (keyPathsForValuesAffectingPreview), so the preview follows the controls.
@interface MvPrintOptions : NSViewController <NSPrintPanelAccessorizing>
@property(nonatomic) BOOL sheet;
@property(nonatomic) BOOL fill;
@property(nonatomic) BOOL captions;
@property(nonatomic) NSInteger grid;  // index into kContactGrids; -1 automatic
@end

@implementation MvPrintOptions

- (void)loadView {
  NSButton* fill = [NSButton checkboxWithTitle:@"Fill the page (crops the photo to the paper’s shape)"
                                        target:self
                                        action:@selector(fillChanged:)];
  fill.state = self.fill ? NSControlStateValueOn : NSControlStateValueOff;
  fill.enabled = !self.sheet;
  NSTextField* label = [NSTextField labelWithString:@"Contact sheet layout:"];
  NSPopUpButton* grid = [[NSPopUpButton alloc] initWithFrame:NSZeroRect pullsDown:NO];
  for (int i = -1; i < mv::shell::kContactGridCount; ++i) {
    [grid addItemWithTitle:@(mv::shell::contact_grid_label(i))];
  }
  [grid selectItemAtIndex:self.grid + 1];
  grid.target = self;
  grid.action = @selector(gridChanged:);
  grid.enabled = self.sheet;
  NSButton* captions = [NSButton checkboxWithTitle:@"Print file names" target:self action:@selector(captionsChanged:)];
  captions.state = self.captions ? NSControlStateValueOn : NSControlStateValueOff;
  captions.enabled = self.sheet;
  NSStackView* row = [NSStackView stackViewWithViews:@[ label, grid ]];
  NSStackView* stack = [NSStackView stackViewWithViews:@[ fill, row, captions ]];
  stack.orientation = NSUserInterfaceLayoutOrientationVertical;
  stack.alignment = NSLayoutAttributeLeading;
  stack.edgeInsets = NSEdgeInsetsMake(12, 20, 12, 20);
  [stack setFrameSize:stack.fittingSize];
  self.view = stack;
}

- (void)fillChanged:(NSButton*)sender {
  self.fill = sender.state == NSControlStateValueOn;
}

- (void)captionsChanged:(NSButton*)sender {
  self.captions = sender.state == NSControlStateValueOn;
}

- (void)gridChanged:(NSPopUpButton*)sender {
  self.grid = sender.indexOfSelectedItem - 1;
}

- (NSSet<NSString*>*)keyPathsForValuesAffectingPreview {
  return [NSSet setWithObjects:@"fill", @"captions", @"grid", nil];
}

- (NSArray<NSDictionary<NSPrintPanelAccessorySummaryKey, NSString*>*>*)localizedSummaryItems {
  NSString* layout = self.sheet ? @(mv::shell::contact_grid_label(static_cast<int>(self.grid)))
                                : (self.fill ? @"Fill the page" : @"Fit to the page");
  return @[ @{NSPrintPanelAccessorySummaryItemNameKey : @"Layout",
              NSPrintPanelAccessorySummaryItemDescriptionKey : layout} ];
}

- (mv::shell::print_options)chosenOptions {
  mv::shell::print_options o;
  o.fit = self.fill ? mv::shell::print_fit::fill : mv::shell::print_fit::fit;
  o.captions = self.captions;
  o.grid = static_cast<int>(self.grid);
  return o;
}

@end

// The pages: one photo, or the sheet's cells page by page, stacked down a
// flipped view one paper-height apart. Immutable once made, so the print
// thread may draw it.
@interface MvPrintView : NSView
- (instancetype)initWithImages:(NSArray*)images
                         names:(std::vector<std::string>)names
                         sheet:(BOOL)sheet
                       options:(MvPrintOptions*)options;
@end

@implementation MvPrintView {
  NSArray* _images;  // CGImageRef, bridged
  std::vector<std::string> _names;
  BOOL _sheet;
  MvPrintOptions* _options;
  mv::shell::print_page _page;
}

- (instancetype)initWithImages:(NSArray*)images
                         names:(std::vector<std::string>)names
                         sheet:(BOOL)sheet
                       options:(MvPrintOptions*)options {
  const mv::shell::print_page page = MvPrintPage(NSPrintInfo.sharedPrintInfo);
  self = [super initWithFrame:NSMakeRect(0, 0, page.width, page.height)];
  if (self) {
    _page = page;
    _images = images;
    _names = std::move(names);
    _sheet = sheet;
    _options = options;
  }
  return self;
}

- (BOOL)isFlipped {
  return YES;
}

- (mv::shell::print_grid)grid {
  return mv::shell::contact_grid(_images.count, static_cast<int>(_options.grid));
}

- (BOOL)knowsPageRange:(NSRangePointer)range {
  NSPrintOperation* op = [NSPrintOperation currentOperation];
  _page = MvPrintPage(op ? op.printInfo : NSPrintInfo.sharedPrintInfo);
  const NSInteger pages =
      _sheet ? std::max<NSInteger>(1, mv::shell::contact_pages(_images.count, [self grid])) : 1;
  [self setFrameSize:NSMakeSize(_page.width, _page.height * pages)];
  *range = NSMakeRange(1, static_cast<NSUInteger>(pages));
  return YES;
}

- (NSRect)rectForPage:(NSInteger)page {
  return NSMakeRect(0, _page.height * static_cast<CGFloat>(page - 1), _page.width, _page.height);
}

// `image` at `at` on page `page`: the drawn part of the picture into its rect.
- (void)drawImage:(CGImageRef)image at:(const mv::shell::print_placement&)at page:(std::uint32_t)page {
  const CGFloat w = CGImageGetWidth(image);
  const CGFloat h = CGImageGetHeight(image);
  NSImage* ns = [[NSImage alloc] initWithCGImage:image size:NSMakeSize(w, h)];
  // NSImage's own space is bottom-up: the top-left source rect flips.
  const NSRect from = NSMakeRect(at.source.x * w, (1.0 - at.source.y - at.source.h) * h, at.source.w * w,
                                 at.source.h * h);
  const NSRect to = NSMakeRect(at.dest.x, at.dest.y + _page.height * page, at.dest.w, at.dest.h);
  [ns drawInRect:to fromRect:from operation:NSCompositingOperationSourceOver fraction:1.0 respectFlipped:YES hints:nil];
}

- (void)drawRect:(NSRect)dirty {
  [[NSColor whiteColor] setFill];
  NSRectFill(dirty);
  const mv::shell::print_rect area = mv::shell::print_area(_page);
  if (!_sheet) {
    CGImageRef image = (__bridge CGImageRef)_images.firstObject;
    if (!image) return;
    const mv::shell::print_fit fit = _options.fill ? mv::shell::print_fit::fill : mv::shell::print_fit::fit;
    [self drawImage:image
                 at:mv::shell::place_picture(area, static_cast<std::uint32_t>(CGImageGetWidth(image)),
                                             static_cast<std::uint32_t>(CGImageGetHeight(image)), fit)
               page:0];
    return;
  }
  const mv::shell::print_grid grid = [self grid];
  const bool captions = _options.captions;
  NSMutableParagraphStyle* para = [[NSMutableParagraphStyle alloc] init];
  para.alignment = NSTextAlignmentCenter;
  para.lineBreakMode = NSLineBreakByTruncatingMiddle;
  NSDictionary* attrs = @{
    NSFontAttributeName : [NSFont systemFontOfSize:mv::shell::kCaptionPoints],
    NSForegroundColorAttributeName : [NSColor colorWithWhite:0.25 alpha:1.0],
    NSParagraphStyleAttributeName : para,
  };
  for (NSUInteger i = 0; i < _images.count; ++i) {
    const mv::shell::contact_cell cell = mv::shell::contact_cell_at(area, grid, i, captions);
    const CGFloat top = _page.height * cell.page;
    const NSRect bounds = NSMakeRect(cell.frame.x, cell.frame.y + top, cell.frame.w,
                                     cell.frame.h + (captions ? cell.caption.h : 0.0));
    if (!NSIntersectsRect(bounds, dirty)) continue;
    CGImageRef image = (__bridge CGImageRef)_images[i];
    [self drawImage:image
                 at:mv::shell::place_picture(cell.frame, static_cast<std::uint32_t>(CGImageGetWidth(image)),
                                             static_cast<std::uint32_t>(CGImageGetHeight(image)),
                                             mv::shell::print_fit::fit)
               page:cell.page];
    if (captions && i < _names.size()) {
      const std::string_view name = mv::shell::print_caption(_names[i]);
      NSString* text = [[NSString alloc] initWithBytes:name.data() length:name.size() encoding:NSUTF8StringEncoding];
      [text drawWithRect:NSMakeRect(cell.caption.x, cell.caption.y + top, cell.caption.w, cell.caption.h)
                 options:NSStringDrawingUsesLineFragmentOrigin | NSStringDrawingTruncatesLastVisibleLine
              attributes:attrs
                 context:nil];
    }
  }
}

@end

@implementation MvLabApp {
  // docs/plans/edit-refresh.md §2.3: the right column's preferred width (points),
  // the edge drag's grab offset, and whether a drag is under way. A
  // --pane-drag-soak never saves the width.
  CGFloat _panePref;
  CGFloat _paneGrabDx;
  BOOL _paneDragging;
  BOOL _paneDragSoak;
  mv::shell::present_lab_mac _lab;
  mv::shell::input_snapshot _snap;
  mv::job_system _jobs;
  mv::shell::mac_lab_options _options;
  bool _terminating;
  // #452: every window closed while an add-on keeps the process (Driftwire's
  // Receive when MediaViewer is closed). The viewer window is hidden, not
  // closed, and comes back on reopen, a file open, or the menu-bar item.
  bool _inBackground;
  bool _updateAsked;  // #532: this copy asked the others to quit for its update
  bool _quitForReal;
  id _backgroundCloseWatch;
  // A login-item start not yet kept by an add-on: an empty keep list means
  // "still loading", not "turned off"; -backgroundStartExpired decides.
  bool _backgroundStart;
  int _loginItemKept;  // the keep list last seen: -1 not yet, 0 empty, 1 not

  // Folder navigation (PR 18, folded-in PR 4/6 -- docs/design/12 2026-09-17).
  // `_items`/`_index` are a cache: refreshed only when -refreshFolderIfChanged
  // sees folder_model_mac's watch fire, not re-fetched on every keypress --
  // docs/design/16's own speed rule ("warm arrow-key < 40 ms... no marshalling hop
  // per key-repeat") is why this isn't just `_folder.items()` called from
  // -navigateNext etc, which would copy the whole listing (paths and all)
  // on every arrow key.
  mv::shell::folder_model _folder;
  mv::shell::browse_index _index;
  std::vector<mv::io::dir_entry> _items;
  // PR 26: the open folder's child folders (same relist as `_items`), the
  // breadcrumb trail through the tree, and the gallery's keyboard position
  // while it is on a folder tile (-1 = on the images).
  std::vector<mv::io::subdir_entry> _subdirs;
  mv::shell::browse_path _browsePath;
  NSInteger _folderCursor;
  // Child folder we just left. Applied once, when that parent's listing arrives,
  // so Up and a breadcrumb click land on the tile that was open.
  std::string _revealChild;
  // Sibling folders of the one open, so Cmd+Left / Cmd+Right can move sideways
  // without listing the parent on the UI thread. Filled from the listing we
  // left, then confirmed by a background read of the parent.
  std::vector<std::string> _siblings;
  NSInteger _siblingIndex;
  std::uint64_t _siblingGeneration;
  // File search (docs/design/16, 2026-09-28): the name filter the grid shows,
  // in grid order, for the listing generation it was made from. While it is
  // on and the gallery is up, the gallery's keys move among these only; the
  // viewer itself always walks the whole folder (the folder model is not
  // filtered).
  BOOL _galleryFilterOn;
  std::uint64_t _galleryFilterGeneration;
  std::vector<std::size_t> _galleryFilterItems;
  std::vector<NSInteger> _galleryFilterFolders;
  // `/` while the folder row is active: a short prefix matched against tile names.
  BOOL _folderFind;
  std::string _folderQuery;
  CFAbsoluteTime _folderFindTick;
  // Set by every open / navigation; the first relist of exactly that folder
  // opens the gallery if it holds no media of its own (a NAS root of year
  // folders would otherwise open onto an empty canvas).
  std::string _galleryIfEmptyDir;
  // The path -selectIndex: last asked to display. Anchors the selection
  // across a relist: found again -> that's the new index (files added
  // elsewhere in the folder don't move the selection); not found (removed)
  // -> falls back to clamping the old numeric index, which is "the next one
  // slides into its place" for a mid-list removal and "the previous one" for
  // the last item, without needing to special-case either (docs/design/16).
  std::string _wantSelectedPath;
  // Bumped by every -openDir: call, read from the background job it
  // submits. folder_model::open() writes state_->dir/generation under its
  // own mutex, but its thumbs.open()/watcher_.start() calls run outside
  // that lock -- two folder->open() calls for different directories
  // in flight at once (a startup --open immediately followed by a drop, say)
  // can then interleave and leave the watcher pointed at one directory while
  // the thumbnail cache is opened against another. A superseded open's job
  // checks this before ever calling folder->open() and bails instead,
  // rather than letting two opens race each other's side effects.
  // No brace-initializer: Objective-C ivar declarations don't support one
  // (unlike a C++ class body). std::atomic<T>'s default constructor
  // value-initializes to 0 as of C++20 (this file builds -std=c++2a), so
  // this starts at 0 regardless.
  std::atomic<std::uint64_t> _openGeneration;
  // Bumped by each -openEntryPaths:failed: request (main thread only): a stat
  // that lands after a newer request was made is dropped.
  std::uint64_t _entryGeneration;
  // Held by the open job across its _openGeneration check and the
  // folder->open() / open_list() call, so a superseded job cannot pass the
  // check and then run after the newer one (leaving a result list, or a
  // folder, the user has already left). Worker threads only.
  std::mutex _folderOpenMutex;
  // Issue #178: the clip transport's poll of the render thread's status. Runs
  // only while a clip or a sound is the current item (or its strip is still
  // up); on a still nothing ticks.
  NSTimer* _transportPollTimer;
  // What -selectIndex: last handed to the lab, and the lab's item id for it.
  // A relist that lands on the same file (same size and mtime) keeps that
  // load instead of decoding it again; opening a file starts its load before
  // the folder listing arrives, with the stamp unknown (_shownMtime ==
  // kShownStampUnknown) until the listing confirms it.
  std::string _shownPath;
  std::int64_t _shownMtime;
  std::uint64_t _shownSize;
  std::uint64_t _shownItem;
  // The page of a multi-page still on screen (docs/plans/audio-and-documents.md
  // §2.3): 0 for the file itself; a new stop starts at 0.
  std::uint32_t _shownPage;
  std::uint32_t _shownPageCount;  // last count the lab reported for this stop; 0 unknown
  // Issue #429, the page sidebar: wanted (Shift+T, NSUserDefaults
  // mv.pageSidebar, on unless turned off), shown (-pageSidebarVisible) and
  // the bookkeeping of its thumbnails, shared with jobs that outlive a call.
  BOOL _pageSidebarWanted;
  BOOL _pageSidebarShown;
  std::uint32_t _pageSidebarListed;  // the count the strip was last given
  std::shared_ptr<mv::image::page_thumb_book> _pageThumbs;
  // Document scrolling (docs/design/04 "Scrolling a document"): the shared
  // page-turn rule and its sub-pixel carry (canvas/document_scroll.h).
  mv::canvas::document_scroller _docScroll;
  // The "Press T" filmstrip hint is learned (NSUserDefaults mv.hint.filmstripT).
  BOOL _stripHintLearned;
  BOOL _stripHintCard;  // the card was sent up (-stripHintShow)
  CFTimeInterval _stripHintShownAt;
  // Milestone H: the moment the shown clip was opened at (-1 none). The same
  // result selected again keeps the clip where it is; another moment of it
  // reopens. kShownMomentStale after a new search, so its moment opens afresh.
  std::int64_t _shownMoment;
  NSTimer* _browseTimer;
  NSTimer* _pageSoakTimer;  // --page-soak (issue #429)
  NSTimer* _paneDragTimer;  // --pane-drag-soak (docs/plans/edit-refresh.md S1)
  // Issue #486: polls for "ready" until the boot timeline is logged / reported.
  NSTimer* _bootTimer;
  BOOL _bootWithPath;
  // Bumped whenever _items is replaced; Swift's name/thumbnail caches key off
  // it (mv_chrome_listing_generation).
  std::uint64_t _listingGeneration;
  // Bumped by every change to `_marks`; Swift rebuilds its marked-name set
  // when it moves (mv_chrome_marks_generation).
  std::uint64_t _marksGeneration;
  // Issue #413: the gallery's shift-click range, paths in listing order, and
  // its generation (mv_chrome_gallery_range_generation). Empty: none.
  std::vector<std::string> _galleryRange;
  std::uint64_t _galleryRangeGeneration;
  // Bumped when the app rewrites a listed file in place (lossless rotate, a
  // metadata write) and refreshes its size / mtime without a relist: Swift
  // re-reads the thumbnail keys when it moves (mv_chrome_thumb_generation).
  std::uint64_t _thumbGeneration;
  // #612: the thumbnail cache's sweep, once a launch, after the first image.
  BOOL _thumbSweepStarted;
  BOOL _helpVisible;

  // Settings screen + the router. _viewFlags uses the same bit layout as
  // Windows' view_settings::flags() (settings.h); the key overrides are the
  // rows of the live table that differ from the defaults.
  mv::shell::key_router _router;
  BOOL _settingsVisible;
  // docs/design/25, issue #408: the theme's palettes and ground, when a theme
  // is on; otherwise syncHomeAppearance resolves AppKit's colours.
  BOOL _themeActive;
  BOOL _themeHasDark;
  BOOL _themeHasLight;
  mv_home_palette _themeDark;
  mv_home_palette _themeLight;
  mv::shell::home_effect _themeEffect;
  uint32_t _themeEffectRgb;
  float _themeIntensity;
  float _themeSpeed;
  float _themeSize;
  // The ground's rest rule needs to hear the pointer, at most a few times a
  // second (input_snapshot::pointer_seq).
  CFTimeInterval _lastPointerBump;
  id _reduceMotionObserver;
  id _systemColoursObserver;

  // Issue #38: the clip transport's idle state (shell/transport_autohide.h, the
  // same rule Windows runs). One one-shot timer at most, only while a clip
  // plays with its controls up: idle playback adds no repaint and no polling.
  mv::shell::transport_autohide _autohide;
  NSTimer* _autohideTimer;
  bool _transportClip;
  bool _transportPlaying;
  bool _transportShown;
  int32_t _viewFlags;
  // Settings changed which kinds a listing leaves out: the next
  // -refreshFolderIfChanged re-applies the folder model's listing.
  BOOL _refilterListing;
  int _captureRow;
  id _captureMonitor;
  id _textEditMonitor;
  uint64_t _keysGeneration;

  // Marks, copy/move, Trash (docs/design/16 "Marks, copy, move"). Keyed by path, not
  // index -- docs/design/16: "Marks clear only for items that succeeded," which only
  // means something if a mark identifies a specific file rather than a slot
  // that survives a relist meaning something else.
  std::set<std::string> _marks;
  NSURL* _lastDestination;
  // Issue #206: View > Show, for this run only. "Marked" keeps the marks as
  // they were when it was chosen (_kindKept). _kindFilterChanged makes the
  // next relist the one that moves off a stop the filter no longer shows.
  mv::io::kind_filter _kindFilter;
  std::set<std::string> _kindKept;
  BOOL _kindFilterChanged;
  BOOL _renamePending;  // issue #210: one F2 rename at a time
  // Issue #614: ⌘P. One print prepared at a time; the panel's last answer
  // (this run only) and the accessory of the panel on screen.
  BOOL _printBusy;
  mv::shell::print_options _printOptions;
  MvPrintOptions* _printOptionsPanel;

  // Slideshow (docs/design/16 "Slideshow", folded into PR 18 -- stills only, no
  // video on Mac yet, PR 19). _enteredFullscreenForSlideshow distinguishes
  // "F5 made us fullscreen, so Esc/leave should undo that" from "the window
  // was already fullscreen when F5 fired, so leaving shouldn't un-fullscreen
  // it" (docs/design/16: "starts from the canvas in browse (fullscreen if the
  // window is not; leaving puts it back)").
  BOOL _slideshowActive;
  BOOL _gameOn;  // Space on an empty window started the runner (the lab owns its state)
  BOOL _slideshowPaused;
  BOOL _enteredFullscreenForSlideshow;
  double _slideshowIntervalSeconds;
  NSTimer* _slideshowTimer;
  // `R` in a slideshow: the shared no-repeat order (shell/slideshow.h). Only its
  // shuffle is used here; the timer above keeps the interval. Blackout (`.`)
