  void (^_installUpdateNow)(void);
  bool _backgroundUpdateRetry;  // #532: -applyUpdateInBackground tries again in a minute
  // What the command bar shows (-updatePhase): checking / downloading only
  // while Sparkle is in that step; ready while _installUpdateNow is held.
  int32_t _updateActivity;  // 0 idle, 1 checking, 2 downloading
  NSString* _updateVersionShown;
  NSString* _updateNotesShown;  // #620: -updateNotes
  // The preview channel's appcast: the newest release's, stable or not
  // (-resolveFeedThenCheck:). nil = Info.plist SUFeedURL, the stable feed.
  NSString* _previewFeedURL;
#endif
}
- (instancetype)initWithOptions:(const mv::shell::mac_lab_options&)options {
  self = [super init];
  if (self) {
    _options = options;
    _slideshowIntervalSeconds = 4.0;  // docs/design/16 Slideshow table's default
    _filmstripVisible = YES;
    _captureRow = -1;
    // PR 11: generation 0 is "never cancelled" (core/job_system.h); a build's
    // context must start at a real view intent.
    _adjustGen.store(1, std::memory_order_relaxed);
    _loginItemKept = -1;
    // The right column's width, read before the first layout (never waited
    // on by the core open: a defaults read).
    _panePref = mv::shell::preferred_width(
        static_cast<std::int32_t>([NSUserDefaults.standardUserDefaults integerForKey:kRightPaneWidthKey]),
        kPaneLimits);
    // A harness never saves the width it drags to.
    _paneDragSoak = g_pane_drag.enabled || std::getenv("MV_EDIT_SELFTEST") != nullptr;
  }
  return self;
}
- (void)applicationDidFinishLaunching:(NSNotification*)notification {
  // #452: a login item's launch says so in the open-application event (the
  // same check SMAppService.mainApp apps use). Never for a measuring run.
  {
    NSAppleEventDescriptor* e = NSAppleEventManager.sharedAppleEventManager.currentAppleEvent;
    if (e.eventClass == kCoreEventClass && e.eventID == kAEOpenApplication &&
        [e paramDescriptorForKeyword:keyAEPropData].enumCodeValue == keyAELaunchedAsLogInItem) {
      g_start_background = true;
    }
    // #532: Sparkle relaunched an update applied in the background; it comes
    // back there (Sparkle's relaunch takes no arguments).
    if ([NSUserDefaults.standardUserDefaults boolForKey:@"MVBackgroundAfterUpdate"]) {
      [NSUserDefaults.standardUserDefaults removeObjectForKey:@"MVBackgroundAfterUpdate"];
      g_start_background = true;
    }
    if (_options.soak_seconds > 0.0 || _options.harness || !_options.open_path.empty()) g_start_background = false;
    if (g_start_background) [NSApp setActivationPolicy:NSApplicationActivationPolicyAccessory];
  }
  // #532: another copy's "Update ready — restart" asks this one to quit.
  {
    __weak MvLabApp* weakSelf = self;
    NSString* me = [NSString stringWithFormat:@"%d", static_cast<int>(::getpid())];
    [NSDistributedNotificationCenter.defaultCenter addObserverForName:MvQuitForUpdateName()
                                                               object:nil
                                                                queue:NSOperationQueue.mainQueue
                                                           usingBlock:^(NSNotification* n) {
                                                             if ([n.object isEqual:me]) return;
                                                             [weakSelf quitForUpdateWhenIdle];
                                                           }];
  }
  // docs/design/25 PR 57 verify rigs: open add-ons from a scratch store, never the
  // profile's. Before anything lists the store.
  if (const char* dir = std::getenv("MV_SCRIPT_SELFTEST"); dir && *dir) {
    mv::io::set_open_addons_dir_override((std::string(dir) + "/store").c_str());
  } else if (const char* store = std::getenv("MV_SCRIPT_STORE"); store && *store) {
    mv::io::set_open_addons_dir_override(store);
  }
  _folderCursor = -1;
  _siblingIndex = -1;
  (void)notification;
  [self loadSettings];
  mv::boot::mark(mv::boot::stage::settings_loaded);
  // Milestone G: an installed Import add-on is verified and loaded off the
  // main thread; with none installed this only watches for the card hint.
  MvLabApp* __weak weakApp = self;
  static MvLabApp* __weak g_addon_app = nil;
  g_addon_app = weakApp;
  // The editor soak measures the editor: an add-on indexing in the background
  // (the AI pack compiles its models) would swamp it.
  const MvAddonsOpenPathFn open_from_addon = [](void*, const char* path) {
    MvLabApp* app = g_addon_app;
    NSString* entry = path ? [NSString stringWithUTF8String:path] : nil;
    if (app && entry) [app openEntryPaths:@[ entry ] failed:nil];
  };
  if (std::getenv("MV_EDIT_SELFTEST_SOAK") == nullptr) {
    MvAddonsSetFolderModel(&_folder);  // docs/design/25 PR 57: scripts with folder.read
    if (MvClaimAddonHost()) {
      MvAddonsStart(open_from_addon, nullptr);
      // docs/design/23: Final Cut Pro search stays as Settings left it (background, later).
      MvFcpStart();
    } else {
      // A later window (2026-10-07): Local search through the AI pack's
      // read-only reader, started on the first ⌘F; nothing at launch.
      MvAddonsStartReader(open_from_addon, nullptr);
    }
  }
  NSRect rect = NSMakeRect(0, 0, 1280, 720);
  self.window = [[NSWindow alloc]
      initWithContentRect:rect
                styleMask:NSWindowStyleMaskTitled | NSWindowStyleMaskClosable |
                          NSWindowStyleMaskMiniaturizable | NSWindowStyleMaskResizable
                  backing:NSBackingStoreBuffered
                    defer:NO];
  mv::boot::mark(mv::boot::stage::window_created);
  self.window.title = @"MediaViewer";
  // self.window holds it: AppKit's release on close would over-release it under ARC.
  self.window.releasedWhenClosed = NO;
  // Single-window viewer: without this AppKit adds Show Tab Bar / Show All
  // Tabs to the View menu.
  self.window.tabbingMode = NSWindowTabbingModeDisallowed;
  self.window.delegate = self;
  // F11/F (docs/design/16): -toggleFullscreen below needs this set once, up front,
  // or [self.window toggleFullScreen:nil] silently does nothing.
  self.window.collectionBehavior |= NSWindowCollectionBehaviorFullScreenPrimary;
  [self.window center];
  if (g_new_window && !NSEqualPoints(g_new_window_from, NSZeroPoint)) {
    // Cmd+N: down and to the right of the window that asked, as AppKit cascades.
    [self.window setFrameTopLeftPoint:NSMakePoint(g_new_window_from.x + 26.0, g_new_window_from.y - 26.0)];
  }
  // Found on real hardware (2026-09-18), alongside the Auto Layout fix a few
  // lines down: even with every subview properly pinned, a hard floor here
  // means a future layout mistake shrinks a control, not the whole window.
  self.window.contentMinSize = NSMakeSize(480.0, 320.0);

  // PR 18: contentView becomes a plain container holding two siblings — the
  // Metal canvas (full bounds, unchanged from PR 16/17) and the SwiftUI
  // command bar pinned to the top strip, drawn over the canvas's top pixels.
  // Neither view is resized to make room for the other; syncSize keeps
  // publishing the canvas's own full backing size, and chrome_height_px
  // tells the render thread how much of it the bar visually covers.
  NSView* container = [[NSView alloc] initWithFrame:rect];
  self.window.contentView = container;

  self.view = [[MvMetalView alloc] initWithFrame:container.bounds];
  self.view.lab = &_lab;
  self.view.snap = &_snap;
  self.view.app = self;
  [container addSubview:self.view];
  [self syncHomeAppearance];
  // Found on real hardware (2026-09-18): this used to be autoresizingMask =
  // NSViewWidthSizable|NSViewHeightSizable instead of an Auto Layout pin, on
  // the theory that a plain frame-based contentView (container, below) with
  // an autoresizing-mask subview needs no Auto Layout at all. That stopped
  // being true the moment the command bar/filmstrip/gallery views (added a
  // few lines down) became real Auto Layout participants: mixing an
  // autoresizing-mask-only view with Auto-Layout-driven siblings under one
  // container makes AppKit auto-size the *window* to the narrowest fitting
  // size Auto Layout can compute -- and since an autoresizing-mask view
  // contributes no intrinsic size to that computation, it's invisible to
  // it. The window collapsed to ~76pt wide (a SwiftUI button's minimum
  // width) with the canvas nowhere in the accounting; NSWindowStyleMask
  // Resizable was set correctly the entire time; there was nothing wrong to
  // resize, the window really was that narrow. Pinning all four edges here,
  // the same way the other three subviews already are, gives every
  // participant in the layout an actual say in the window's size.
  self.view.translatesAutoresizingMaskIntoConstraints = NO;
  [NSLayoutConstraint activateConstraints:@[
    [self.view.leadingAnchor constraintEqualToAnchor:container.leadingAnchor],
    [self.view.trailingAnchor constraintEqualToAnchor:container.trailingAnchor],
    [self.view.topAnchor constraintEqualToAnchor:container.topAnchor],
    [self.view.bottomAnchor constraintEqualToAnchor:container.bottomAnchor],
  ]];
  // Force the backing layer to exist now, not on AppKit's own lazy schedule:
  // _lab.start() below reads self.view.layer immediately (metal_layer's
  // attach()) and needs the real CAMetalLayer from -makeBackingLayer to
  // already exist. See the assignment a few lines down for why this can't
  // just be a `.layer` property read.
  // Found on real hardware (2026-09-18): reading `.layer` on a wantsLayer=YES
  // NSView does NOT synchronously call -makeBackingLayer the way the getter
  // comment above assumed -- AppKit only builds the layer during a real
  // layout/display pass (confirmed: the crash from the first version of this
  // fix showed -makeBackingLayer running deep inside
  // NSWindowUpdateLayerTree/_buildLayerTreeWithOwnLayerRequirement, not from
  // a direct property read). Assigning the layer directly, from
  // -makeBackingLayer itself, sidesteps AppKit's lazy timing entirely.
  self.view.layer = [self.view makeBackingLayer];

  self.commandBar = [MVChromeHost makeCommandBarView];
  // Found on real hardware (2026-09-18): without this, AppKit's default
  // translatesAutoresizingMaskIntoConstraints=YES auto-generates constraints
  // from the view's zero/default frame that fight the explicit ones just
  // below, which is what "squashed" chrome actually was -- both sets of
  // constraints active at once, Auto Layout breaking one arbitrarily.
  self.commandBar.translatesAutoresizingMaskIntoConstraints = NO;
  // Found on real hardware (2026-09-18), the actual root cause of the window
  // itself shrinking to ~76pt wide (not just its content), confirmed
  // empirically (forcing the frame back to 1280 wide, it silently reverted
  // to 76 on the very next layout pass, not just once at startup): the
  // leading/trailing==container equality below forces commandBar.width to
  // exactly equal container.width, but NSHostingView also auto-generates an
  // *internal* content-hugging constraint pulling commandBar toward its
  // intrinsicContentSize -- and because CommandBarView.swift's HStack ends
  // in a Spacer(), SwiftUI reports that intrinsic size as just the two
  // buttons' combined width (~76pt): a Spacer has no size of its own to
  // report when asked "what's your ideal size with nothing else to go on."
  // With no required constraint pinning container to anything *larger*,
  // Auto Layout is free to satisfy that hugging pull at zero cost by
  // shrinking container (and the window) down to exactly 76 -- every
  // layout pass, not just the first. (Compression resistance, tried first
  // and left at its default here, governs the *opposite* direction: how
  // hard a view resists being made *smaller* than its intrinsic size. That
  // was never the fight; nothing was trying to shrink commandBar below 76,
  // something was trying to shrink the *window* down *to* 76.) Lowering
  // hugging priority says "don't insist on staying at your natural size --
  // it's fine to be stretched wider by whatever the window actually is."
  [self.commandBar setContentHuggingPriority:NSLayoutPriorityDefaultLow
                               forOrientation:NSLayoutConstraintOrientationHorizontal];
  [container addSubview:self.commandBar];
  self.commandBarHeight =
      [self.commandBar.heightAnchor constraintEqualToConstant:[self chromeBarHeight]];
  [NSLayoutConstraint activateConstraints:@[
    [self.commandBar.leadingAnchor constraintEqualToAnchor:container.leadingAnchor],
    [self.commandBar.trailingAnchor constraintEqualToAnchor:container.trailingAnchor],
    [self.commandBar.topAnchor constraintEqualToAnchor:container.topAnchor],
    self.commandBarHeight,
  ]];
  mv::boot::mark(mv::boot::stage::chrome_bar);

  // Filmstrip: a bottom strip, the same "sibling drawn over the canvas's own
  // pixels" shape as the command bar above, not a resize of MvMetalView.
  // Hidden until there are items to strip (-applyFilmstripLayout, from
  // -selectIndex:) -- -syncSize is what actually reserves canvas space for it,
  // via chrome_bottom_px.
  self.filmstripHost = [MVChromeHost makeFilmstripView];
  self.filmstripHost.hidden = YES;
  self.filmstripHost.translatesAutoresizingMaskIntoConstraints = NO;
  [self.filmstripHost setContentHuggingPriority:NSLayoutPriorityDefaultLow
                                  forOrientation:NSLayoutConstraintOrientationHorizontal];
  [container addSubview:self.filmstripHost];
  [NSLayoutConstraint activateConstraints:@[
    [self.filmstripHost.leadingAnchor constraintEqualToAnchor:container.leadingAnchor],
    [self.filmstripHost.bottomAnchor constraintEqualToAnchor:container.bottomAnchor],
    [self.filmstripHost.heightAnchor constraintEqualToConstant:kFilmstripHeightPoints],
  ]];
  // Its trailing edge is the canvas's (below, once canvasGuide exists): the
  // docked Edit column pushes the strip over and runs to the window's foot
  // (owner 2026-11-05).

  // Clip transport (PR 19): bottom-centre, floating above the filmstrip. Hidden
  // until a clip is on screen (-pollTransport flips it).
  self.transportHost = [MVChromeHost makeTransportView];
  self.transportHost.hidden = YES;
  self.transportHost.translatesAutoresizingMaskIntoConstraints = NO;
  [container addSubview:self.transportHost];
  self.transportBottom = [self.transportHost.bottomAnchor
      constraintEqualToAnchor:container.bottomAnchor
                     constant:-10.0];
  NSLayoutConstraint* preferredWidth =
      [self.transportHost.widthAnchor constraintEqualToConstant:720.0];
  // Below NSLayoutPriorityWindowSizeStayPut: a wish, never a reason to resize
  // the window. At DefaultHigh (750) it outranked the window's own size, so a
  // canvas narrower than 752 pt (the docked column dragged wide) grew the
  // window instead of shrinking the transport (S1 review, 2026-11-05).
  preferredWidth.priority = kChromeWishPriority;
  // Centred on the canvas, not the window (docs/plans/edit-refresh.md §2.3):
  // the right column's guide pins the docked edge (-syncCanvasGuide).
  self.canvasGuide = [[NSLayoutGuide alloc] init];
  [container addLayoutGuide:self.canvasGuide];
  self.canvasLeading = [self.canvasGuide.leadingAnchor constraintEqualToAnchor:container.leadingAnchor];
  self.canvasTrailingFull = [self.canvasGuide.trailingAnchor constraintEqualToAnchor:container.trailingAnchor];
  [NSLayoutConstraint activateConstraints:@[
    self.canvasLeading,
    self.canvasTrailingFull,
    [self.canvasGuide.topAnchor constraintEqualToAnchor:container.topAnchor],
    [self.canvasGuide.bottomAnchor constraintEqualToAnchor:container.bottomAnchor],
  ]];
  [self.filmstripHost.trailingAnchor constraintEqualToAnchor:self.canvasGuide.trailingAnchor].active = YES;
  [NSLayoutConstraint activateConstraints:@[
    [self.transportHost.centerXAnchor constraintEqualToAnchor:self.canvasGuide.centerXAnchor],
    [self.transportHost.widthAnchor constraintLessThanOrEqualToConstant:720.0],
    [self.transportHost.leadingAnchor constraintGreaterThanOrEqualToAnchor:self.canvasGuide.leadingAnchor
                                                                  constant:16.0],
    [self.transportHost.trailingAnchor constraintLessThanOrEqualToAnchor:self.canvasGuide.trailingAnchor
                                                                constant:-16.0],
    [self.transportHost.heightAnchor constraintEqualToConstant:44.0],
    self.transportBottom,
    preferredWidth,
  ]];

  // docs/plans/edit-refresh.md S3: the canvas tools' context bar, in the
  // transport's slot (a still has no transport) and the band the canvas leaves
  // for it (chrome_bottom_px + kToolBarBand), so it never covers the photo.
  self.toolBarHost = [MVChromeHost makeToolBarView];
  self.toolBarHost.hidden = YES;
  self.toolBarHost.translatesAutoresizingMaskIntoConstraints = NO;
  [container addSubview:self.toolBarHost];
  self.toolBarBottom = [self.toolBarHost.bottomAnchor constraintEqualToAnchor:container.bottomAnchor
                                                                     constant:-8.0];
  NSLayoutConstraint* toolBarWidth = [self.toolBarHost.widthAnchor constraintEqualToConstant:640.0];
  toolBarWidth.priority = kChromeWishPriority;  // as the transport's: never grows the window
  [NSLayoutConstraint activateConstraints:@[
    [self.toolBarHost.centerXAnchor constraintEqualToAnchor:self.canvasGuide.centerXAnchor],
    [self.toolBarHost.widthAnchor constraintLessThanOrEqualToConstant:640.0],
    [self.toolBarHost.leadingAnchor constraintGreaterThanOrEqualToAnchor:self.canvasGuide.leadingAnchor
                                                                constant:8.0],
    [self.toolBarHost.trailingAnchor constraintLessThanOrEqualToAnchor:self.canvasGuide.trailingAnchor
                                                              constant:-8.0],
    [self.toolBarHost.heightAnchor constraintEqualToConstant:44.0],
    self.toolBarBottom,
    toolBarWidth,
  ]];

  // #345: the AI-generated badge. Chrome over the canvas like the transport, so
  // it never presents; hidden until the item on screen says it was AI-made.
  // -layoutAIBadge keeps it clear of the filmstrip, a clip's transport and the
  // right-hand panes.
  self.aiBadgeHost = [MVChromeHost makeAIBadgeView];
  self.aiBadgeHost.hidden = YES;
  self.aiBadgeHost.translatesAutoresizingMaskIntoConstraints = NO;
  [container addSubview:self.aiBadgeHost];
  self.aiBadgeBottom = [self.aiBadgeHost.bottomAnchor constraintEqualToAnchor:container.bottomAnchor
                                                                     constant:-10.0];
  self.aiBadgeTrailing = [self.aiBadgeHost.trailingAnchor constraintEqualToAnchor:container.trailingAnchor
                                                                         constant:-16.0];
  [NSLayoutConstraint activateConstraints:@[
    [self.aiBadgeHost.widthAnchor constraintEqualToConstant:MVChromeHost.aiBadgeWidth],
    [self.aiBadgeHost.heightAnchor constraintEqualToConstant:MVChromeHost.aiBadgeHeight],
    self.aiBadgeBottom,
    self.aiBadgeTrailing,
  ]];

  // Gallery: an overlay over the canvas below the command bar (docs/design/16:
  // "covers the canvas like an overlay"), hidden by default -- `G` shows it, a
  // click or Esc hides it again. The canvas keeps rendering underneath; hiding
  // this view is enough, no chrome_*_px accounting needed the way the
  // filmstrip strip needs. It starts under the bar, as the Windows gallery
  // island does (chrome_host::show_gallery, y = bar): covering the bar hid the
  // folder path, its search icon and a result list's "Back to folder" while
  // the grid was up (owner report, 2026-09-28).
  self.galleryHost = [MVChromeHost makeGalleryView];
  self.galleryHost.hidden = YES;
  self.galleryHost.translatesAutoresizingMaskIntoConstraints = NO;
  [self.galleryHost setContentHuggingPriority:NSLayoutPriorityDefaultLow
                                forOrientation:NSLayoutConstraintOrientationHorizontal];
  [container addSubview:self.galleryHost];
  [NSLayoutConstraint activateConstraints:@[
    [self.galleryHost.leadingAnchor constraintEqualToAnchor:container.leadingAnchor],
    [self.galleryHost.trailingAnchor constraintEqualToAnchor:container.trailingAnchor],
    [self.galleryHost.topAnchor constraintEqualToAnchor:self.commandBar.bottomAnchor],
    [self.galleryHost.bottomAnchor constraintEqualToAnchor:container.bottomAnchor],
  ]];

  // `?` cheat sheet: a full-container overlay above everything, hidden until
  // toggled -- the same shape as the gallery.
  self.helpHost = [MVChromeHost makeHelpView];
  self.helpHost.hidden = YES;
  self.helpHost.translatesAutoresizingMaskIntoConstraints = NO;
  [container addSubview:self.helpHost];
  [NSLayoutConstraint activateConstraints:@[
    [self.helpHost.leadingAnchor constraintEqualToAnchor:container.leadingAnchor],
    [self.helpHost.trailingAnchor constraintEqualToAnchor:container.trailingAnchor],
    [self.helpHost.topAnchor constraintEqualToAnchor:container.topAnchor],
    [self.helpHost.bottomAnchor constraintEqualToAnchor:container.bottomAnchor],
  ]];

  // PR 9: metadata pane (right) and folder tree (left). Both float over the canvas
  // between the command bar and the filmstrip, hidden until `I` / Cmd+Shift+E. The
  // canvas keeps its full width: a horizontal inset is a present-path change, and
  // PR 1's present-loop verify has to keep holding (docs/design/12 2026-09-24).
  self.metaHost = [MVChromeHost makeMetadataView];
  self.metaHost.hidden = YES;
  self.metaHost.translatesAutoresizingMaskIntoConstraints = NO;
  [container addSubview:self.metaHost];
  self.metaBottom = [self.metaHost.bottomAnchor constraintEqualToAnchor:container.bottomAnchor
                                                               constant:0.0];
  // Issue #429: the page sidebar, left of the canvas from the command bar
  // down. Added before the tree, so the tree (when open) floats over it.
  self.pageSidebarHost = [MVChromeHost makePageSidebarView];
  self.pageSidebarHost.hidden = YES;
  self.pageSidebarHost.translatesAutoresizingMaskIntoConstraints = NO;
  [container addSubview:self.pageSidebarHost];
  [NSLayoutConstraint activateConstraints:@[
    [self.pageSidebarHost.leadingAnchor constraintEqualToAnchor:container.leadingAnchor],
    [self.pageSidebarHost.topAnchor constraintEqualToAnchor:self.commandBar.bottomAnchor],
    [self.pageSidebarHost.bottomAnchor constraintEqualToAnchor:container.bottomAnchor],
    [self.pageSidebarHost.widthAnchor constraintEqualToConstant:kPageSidebarWidthPoints],
  ]];
  self.treeHost = [MVChromeHost makeFolderTreeView];
  self.treeHost.hidden = YES;
  self.treeHost.translatesAutoresizingMaskIntoConstraints = NO;
  [container addSubview:self.treeHost];
  self.treeBottom = [self.treeHost.bottomAnchor constraintEqualToAnchor:container.bottomAnchor
                                                               constant:0.0];
  // docs/plans/edit-refresh.md §2.3: the right column. Every right pane pins its
  // leading edge to it; its one width is the user's (-applyPaneWidth).
  self.rightColumn = [[NSLayoutGuide alloc] init];
  [container addLayoutGuide:self.rightColumn];
  self.rightColumnWidth = [self.rightColumn.widthAnchor
      constraintEqualToConstant:mv::shell::shown_inspector(static_cast<float>(_panePref),
                                                           static_cast<float>(NSWidth(container.bounds)),
                                                           static_cast<float>(MVChromeHost.inspectorMinimumWidth),
                                                           kPaneLimits)];
  self.columnTrailingFull = [self.rightColumn.trailingAnchor constraintEqualToAnchor:container.trailingAnchor];
  [NSLayoutConstraint activateConstraints:@[
    self.columnTrailingFull,
    [self.rightColumn.topAnchor constraintEqualToAnchor:self.commandBar.bottomAnchor],
    [self.rightColumn.bottomAnchor constraintEqualToAnchor:container.bottomAnchor],
    self.rightColumnWidth,
  ]];
  // PR 11: the adjust pane, same edge and width as the metadata pane.
  self.adjustHost = [MVChromeHost makeAdjustView];
  self.adjustHost.hidden = YES;
  self.adjustHost.translatesAutoresizingMaskIntoConstraints = NO;
  [container addSubview:self.adjustHost];
  self.adjustBottom = [self.adjustHost.bottomAnchor constraintEqualToAnchor:container.bottomAnchor
                                                                   constant:0.0];
  // docs/plans/edit-refresh.md S2: the Adjust pane's cards and scopes never spill
  // over the command bar or the rail.
  self.adjustHost.wantsLayer = YES;
  self.adjustHost.layer.masksToBounds = YES;
  [NSLayoutConstraint activateConstraints:@[
    [self.adjustHost.trailingAnchor constraintEqualToAnchor:self.rightColumn.trailingAnchor],
    self.adjustTop = [self.adjustHost.topAnchor constraintEqualToAnchor:self.commandBar.bottomAnchor],
    [self.adjustHost.leadingAnchor constraintEqualToAnchor:self.rightColumn.leadingAnchor],
    self.adjustBottom,
  ]];
  // PR 13 / 14: the Jobs pane, same edge and width again (one at a time).
  self.jobsHost = [MVChromeHost makeJobsView];
  self.jobsHost.hidden = YES;
  self.jobsHost.translatesAutoresizingMaskIntoConstraints = NO;
  [container addSubview:self.jobsHost];
  self.jobsBottom = [self.jobsHost.bottomAnchor constraintEqualToAnchor:container.bottomAnchor
                                                               constant:0.0];
  [NSLayoutConstraint activateConstraints:@[
    [self.jobsHost.trailingAnchor constraintEqualToAnchor:self.rightColumn.trailingAnchor],
    self.jobsTop = [self.jobsHost.topAnchor constraintEqualToAnchor:self.commandBar.bottomAnchor],
    [self.jobsHost.leadingAnchor constraintEqualToAnchor:self.rightColumn.leadingAnchor],
    self.jobsBottom,
  ]];
  // PR 29 (docs/design/20): the Edit workspace. The strip sits where the panes'
  // tops were; while it is open they (and the Crop / Trim / Enhance pane)
  // start under it. docs/plans/edit-refresh.md S2: the strip is the header,
  // as tall as its content (one row or two, labels or icons, the type scale).
  self.editStripHost = [MVChromeHost makeEditStripView];
  [self.editStripHost setContentHuggingPriority:NSLayoutPriorityDefaultLow
                                 forOrientation:NSLayoutConstraintOrientationHorizontal];
  [self.editStripHost setContentCompressionResistancePriority:NSLayoutPriorityDefaultLow
                                               forOrientation:NSLayoutConstraintOrientationHorizontal];
  [self.editStripHost setContentHuggingPriority:NSLayoutPriorityRequired
                                 forOrientation:NSLayoutConstraintOrientationVertical];
  [self.editStripHost setContentCompressionResistancePriority:NSLayoutPriorityRequired
                                               forOrientation:NSLayoutConstraintOrientationVertical];
  self.editStripHost.hidden = YES;
  self.editStripHost.translatesAutoresizingMaskIntoConstraints = NO;
  // Below the transport, so a clip's volume and More stay on top of the pane.
  [container addSubview:self.editStripHost positioned:NSWindowBelow relativeTo:self.transportHost];
  self.editPaneHost = [MVChromeHost makeEditPaneView];
  self.editPaneHost.hidden = YES;
  self.editPaneHost.translatesAutoresizingMaskIntoConstraints = NO;
  [container addSubview:self.editPaneHost positioned:NSWindowBelow relativeTo:self.transportHost];
  // Nothing the SwiftUI content draws may spill over the command bar or the
  // path row above it.
  for (NSView* host in @[ self.editStripHost, self.editPaneHost ]) {
    host.wantsLayer = YES;
    host.layer.masksToBounds = YES;
  }
  [NSLayoutConstraint activateConstraints:@[
    [self.editStripHost.trailingAnchor constraintEqualToAnchor:self.rightColumn.trailingAnchor],
    [self.editStripHost.topAnchor constraintEqualToAnchor:self.commandBar.bottomAnchor],
    [self.editStripHost.leadingAnchor constraintEqualToAnchor:self.rightColumn.leadingAnchor],
    [self.editPaneHost.trailingAnchor constraintEqualToAnchor:self.rightColumn.trailingAnchor],
    [self.editPaneHost.topAnchor constraintEqualToAnchor:self.editStripHost.bottomAnchor],
    [self.editPaneHost.leadingAnchor constraintEqualToAnchor:self.rightColumn.leadingAnchor],
    [self.editPaneHost.bottomAnchor constraintEqualToAnchor:self.adjustHost.bottomAnchor],
  ]];
  self.adjustTopUnder = [self.adjustHost.topAnchor constraintEqualToAnchor:self.editStripHost.bottomAnchor];
  self.jobsTopUnder = [self.jobsHost.topAnchor constraintEqualToAnchor:self.editStripHost.bottomAnchor];
  // The icon rail (EditRailView.swift): the window's right edge, from the
  // command bar to where the panes end (above the filmstrip), only while the
  // workspace is open. The column's trailing edge moves to its leading edge.
  self.railHost = [MVChromeHost makeEditRailView];
  self.railHost.hidden = YES;
  self.railHost.translatesAutoresizingMaskIntoConstraints = NO;
  [container addSubview:self.railHost positioned:NSWindowBelow relativeTo:self.transportHost];
  [NSLayoutConstraint activateConstraints:@[
    [self.railHost.trailingAnchor constraintEqualToAnchor:container.trailingAnchor],
    [self.railHost.topAnchor constraintEqualToAnchor:self.commandBar.bottomAnchor],
    [self.railHost.bottomAnchor constraintEqualToAnchor:self.adjustHost.bottomAnchor],
    [self.railHost.widthAnchor constraintEqualToConstant:kRailLimits.rail],
  ]];
  self.columnTrailingRail = [self.rightColumn.trailingAnchor constraintEqualToAnchor:self.railHost.leadingAnchor];
  // The column's edge: above every right pane (Info, Adjust and Jobs are added
  // over the transport, the workspace's strip and pane under it), so all 6 pt
  // of it take the pointer. The transport centres on the canvas guide, clear
  // of a docked column. It shows only while a right pane does and the
  // gallery, Settings and the Video Editor are away (-syncPaneEdge).
  {
    MvPaneEdgeView* edge = [[MvPaneEdgeView alloc] initWithFrame:NSZeroRect];
    edge.app = self;
    edge.hidden = YES;
    edge.translatesAutoresizingMaskIntoConstraints = NO;
    [container addSubview:edge];
    [NSLayoutConstraint activateConstraints:@[
      [edge.centerXAnchor constraintEqualToAnchor:self.rightColumn.leadingAnchor],
      [edge.widthAnchor constraintEqualToConstant:mv::shell::kPaneEdgeGrab],
      [edge.topAnchor constraintEqualToAnchor:self.commandBar.bottomAnchor],
      [edge.bottomAnchor constraintEqualToAnchor:self.adjustHost.bottomAnchor],
    ]];
    self.paneEdge = edge;
    // A theme's density or type scale moves the column's minimum, and its
    // hairline and accent are the edge's colours: re-clamp and repaint when
    // the chrome repaints (posted after every theme change, Theme.swift).
    __weak MvLabApp* weakSelf = self;
    __weak MvPaneEdgeView* weakEdge = edge;
    (void)[NSNotificationCenter.defaultCenter addObserverForName:@"MVChromeThemeDidChange"
                                                          object:nil
                                                           queue:NSOperationQueue.mainQueue
                                                      usingBlock:^(NSNotification*) {
                                                        [weakEdge restyle];
                                                        [weakSelf paneThemeChanged];
                                                      }];
  }
  self.canvasTrailingDocked = [self.canvasGuide.trailingAnchor constraintEqualToAnchor:self.rightColumn.leadingAnchor];
  // The clip job queue. Its completions arrive on its workers and hop to the
  // main queue here (docs/design/14: the core never calls the host's dispatcher).
  {
    MvLabApp* __weak weakClip = self;
    _clipJobs = std::make_unique<mv::abi::clip_session>([weakClip](const mv_completion& c) {
      const mv_completion copy = c;
      dispatch_async(dispatch_get_main_queue(), ^{
        [weakClip clipCompletion:copy];
      });
    });
    // Encode and decode jobs run in MediaViewerClipJob, never in the viewer
    // (docs/design/12 2026-09-25): Contents/Helpers in the app, beside the lab in a
    // build tree. Set even when missing, so those jobs fail instead.
    NSString* macos = [[[NSBundle mainBundle] executablePath] stringByDeletingLastPathComponent];
    NSString* bundled = [[macos stringByAppendingPathComponent:@"../Helpers/MediaViewerClipJob"]
        stringByStandardizingPath];
    NSString* beside = [macos stringByAppendingPathComponent:@"MediaViewerClipJob"];
    NSFileManager* fm = [NSFileManager defaultManager];
    NSString* helper = [fm isExecutableFileAtPath:bundled] || ![fm isExecutableFileAtPath:beside] ? bundled : beside;
    _clipJobs->set_helper(helper.UTF8String ? helper.UTF8String : "");
  }
  self.metaTopUnder = [self.metaHost.topAnchor constraintEqualToAnchor:self.editStripHost.bottomAnchor];
  [NSLayoutConstraint activateConstraints:@[
    [self.metaHost.trailingAnchor constraintEqualToAnchor:self.rightColumn.trailingAnchor],
    self.metaTop = [self.metaHost.topAnchor constraintEqualToAnchor:self.commandBar.bottomAnchor],
    [self.metaHost.leadingAnchor constraintEqualToAnchor:self.rightColumn.leadingAnchor],
    self.metaBottom,
    [self.treeHost.leadingAnchor constraintEqualToAnchor:container.leadingAnchor],
    [self.treeHost.topAnchor constraintEqualToAnchor:self.commandBar.bottomAnchor],
    [self.treeHost.widthAnchor constraintEqualToConstant:kTreeWidthPoints],
    self.treeBottom,
  ]];

#if MV_WITH_SPARKLE
  // Started here, not at init: the updater's first check must not race the
  // window and lab coming up. Checks and downloads run in the background
  // (Info.plist: SUEnableAutomaticChecks, SUAutomaticallyUpdate); the
  // delegate below holds a staged update until the user restarts.
  _updater = [[SPUStandardUpdaterController alloc] initWithStartingUpdater:YES
                                                            updaterDelegate:self
                                                         userDriverDelegate:nil];
  // Sparkle's scheduled check only fires once SUScheduledCheckInterval has
  // elapsed since the last one, so a release published between launches went
  // unseen for up to 6 h. Check on every start; still silent unless an update
  // exists. Skipped when the user turned automatic checks off.
  [self resolveFeedThenCheck:YES];
#endif
  // Settings screen: a full-container overlay like the help sheet, hidden until
  // opened (Settings button, Cmd+,).
  self.settingsHost = [MVChromeHost makeSettingsView];
  self.settingsHost.hidden = YES;
  self.settingsHost.translatesAutoresizingMaskIntoConstraints = NO;
  [container addSubview:self.settingsHost];
  [NSLayoutConstraint activateConstraints:@[
    [self.settingsHost.leadingAnchor constraintEqualToAnchor:container.leadingAnchor],
    [self.settingsHost.trailingAnchor constraintEqualToAnchor:container.trailingAnchor],
    [self.settingsHost.topAnchor constraintEqualToAnchor:self.commandBar.bottomAnchor],
    [self.settingsHost.bottomAnchor constraintEqualToAnchor:container.bottomAnchor],
  ]];

  // Issue #299 (docs/design/17 "Unfinished roots wait for Resume"): a small
  // notice in the bottom-right corner, not a modal, when an index was left
  // unfinished last session. Last in, so it is above the panes and Settings.
  // It sizes itself (a fixed-width card) and stays hidden, taking no clicks,
  // until there is a question (ResumeNoticeView.swift).
  self.resumeHost = [MVChromeHost makeResumeNoticeView];
  [container addSubview:self.resumeHost];
  self.resumeBottom = [self.resumeHost.bottomAnchor constraintEqualToAnchor:container.bottomAnchor
                                                                   constant:-8.0];
  [NSLayoutConstraint activateConstraints:@[
    [self.resumeHost.trailingAnchor constraintEqualToAnchor:container.trailingAnchor constant:-8.0],
    self.resumeBottom,
  ]];
  // The "Press T" filmstrip hint card: the same corner, above the resume
  // notice while that is up (-layoutHintNotice). Hidden until shown.
  self.hintHost = [MVChromeHost makeHintNoticeView];
  [container addSubview:self.hintHost];
  self.hintBottom = [self.hintHost.bottomAnchor constraintEqualToAnchor:container.bottomAnchor constant:-8.0];
  [NSLayoutConstraint activateConstraints:@[
    [self.hintHost.trailingAnchor constraintEqualToAnchor:container.trailingAnchor constant:-8.0],
    self.hintBottom,
  ]];
  mv::boot::mark(mv::boot::stage::chrome_islands);

  [self installMainMenu];
  [self installTextEditKeys];

  g_chrome_snap = &_snap;
  g_chrome_lab = &_lab;
  g_chrome_app = self;
  mvApplyParkedHomeTheme();  // issue #408: the chrome's first paint came before this
  [self scheduleChromeCrashTest];
  [self scheduleEditSelfTest];
  [self scheduleAddonSelfTest];
  [self scheduleScriptSelfTest];

  _snap.window_visible = YES;
  _snap.window_active = YES;
  [self.view syncSize];

  if (auto started = _jobs.start(); !mv::ok(started)) {
    MV_LOG_ERROR("job_system failed to start");
    [NSApp terminate:nil];
    return;
  }
  // The Mac host has no mv_session: its job workers are the session's twin.
  mv::boot::mark(mv::boot::stage::session_created);
  _options.jobs = &_jobs;
  // #612: Clear reaches the folder model from Swift's background task; the
  // cache's cap is the user's choice from before (no file read: defaults).
  g_storage_folder.store(&_folder, std::memory_order_release);
  g_thumb_cache_cap.store(static_cast<std::uint64_t>(std::max<long long>(
                              0, [[[NSUserDefaults standardUserDefaults] objectForKey:kThumbCacheCapDefault]
                                     longLongValue])),
                          std::memory_order_relaxed);
  _tags = std::make_unique<mv::meta::tag_index>(
      mv::meta::tag_index::cache_fn([] { return &mv::meta::default_meta_cache(); }),
      [](std::string_view path) -> mv::result<mv::meta::search_facts> {
        // docs/design/26: a Photos item is a key; its position and date come
        // from PHAsset (location, creationDate), read locally.
        if (mv::shell::photos::is_key(path)) {
          const std::string key(path);
          MV_TRY(auto described, mv::shell::photos::describe(std::span<const std::string>(&key, 1)));
          mv::meta::search_facts f;
          if (!described.empty() && described[0]) {
            const auto& it = *described[0];
            if (it.has_location) f.where = mv::meta::geo_point{it.lat, it.lon, std::nullopt};
            f.date_taken_key = it.created;
          }
          return f;
        }
        return mv::meta::read_search_facts(path);
      });
  // Milestone H: a clip opened on its moment shows its cached thumbnail first.
  // _folder lives as long as the process (MvLabApp is never destroyed).
  {
    const mv::shell::folder_model* folder = &_folder;
    _options.clip_thumb = [folder](const std::string& path, std::int64_t mtime, std::uint64_t size,
                                   std::int64_t moment_ms) {
      return folder->cached_clip_thumb(path, mtime, size, moment_ms);
    };
    _options.page_thumb = [folder](const std::string& path, std::int64_t mtime, std::uint64_t size,
                                   std::uint32_t page) {
      return folder->cached_page_thumb(path, mtime, size, page);
    };
  }
  // Issue #429: a document's page count arrives with its decode; the page
  // sidebar appears on it, on the main thread, as the bridge calls do.
  _options.page_count_known = [](std::uint64_t item, std::uint32_t count) {
    dispatch_async(dispatch_get_main_queue(), ^{
      if (g_chrome_app) [g_chrome_app pageCount:count knownForItem:item];
    });
  };
  if (auto started = _lab.start((__bridge void*)self.view, _options); !started) {
    MV_LOG_ERROR("present lab failed to start");
    [NSApp terminate:nil];
    return;
  }
  mv::boot::mark(mv::boot::stage::render_started);

  // docs/design/16 "Opening (argv, drop, PR 6)": --open (or a bare positional path,
  // parsed into the same options_.open_path below) resolves through the same
  // folder+select rule a drop does, now that folder_model_mac exists to
  // resolve it -- not a direct one-off open_item() with no folder context.
#if MV_APP_BUNDLE
  // An update restart puts the user back where they were (docs/design/13 "Preserve
  // state across the restart"): the folder and the selected file. Only an
  // explicit open (argv, Finder) outranks it.
  NSUserDefaults* defaults = NSUserDefaults.standardUserDefaults;
  if (NSString* resume = [defaults stringForKey:@"MVResumeAfterUpdate"]) {
    [defaults removeObjectForKey:@"MVResumeAfterUpdate"];
    if (_options.open_path.empty()) _options.open_path = resume.fileSystemRepresentation;
  }
  _askedDefaultViewer = [defaults boolForKey:@"MVAskedDefaultViewer"];
  _installerChecked = _askedDefaultViewer;
  if (_askedDefaultViewer && _options.soak_seconds <= 0.0) MvAdoptNewDefaultViewerTypes();
  if (!_askedDefaultViewer) {
    mv::shell::find_installer_leftover(^(mv::shell::installer_leftover found) {
      self->_installer = found;
      self->_installerChecked = YES;
      [self refreshFolderIfChanged];  // asks now: no timer polls for it (issue #178)
    });
  }
#else
  _askedDefaultViewer = YES;  // the lab never asks
  _installerChecked = YES;
#endif
  // A finished listing reaches the UI now, not on the poll timer's next tick
  // (up to 0.2 s later, on every open). The pool thread only posts.
  _folder.set_changed_notify(
      [](void*) {
        dispatch_async(dispatch_get_main_queue(), ^{
          [g_chrome_app refreshFolderIfChanged];
        });
      },
      nullptr);
  // docs/design/26: Photos library items. Their tiles come from PhotoKit under the
  // "photos:" key; every file in the cache folder (previews, on-view
  // downloads) is read-only; the folder starts the session empty.
  mv::shell::set_read_only_prefix(mv::shell::photos::cache_dir());
  // Owner 2026-11-04: Enhance, faces and Save copy read a library item's file
  // and add what they make back to the library as a new photo. S0: an
  // original only iCloud has shows its progress in the notice while it comes
  // (the job's cancel stops it), and the new photo is listed beside its
  // source (Show, or the arrow, reaches it).
  mv::addon::media::set_photos_hooks(
      [](const std::string& key, const mv::job_context* ctx) -> mv::result<std::string> {
        auto reported = std::make_shared<std::atomic<bool>>(false);
        const mv::shell::photos::fetch_progress progress = [ctx, reported](double fraction) {
          reported->store(true, std::memory_order_release);
          dispatch_async(dispatch_get_main_queue(), ^{
            [g_chrome_app photosFetchProgress:fraction];
          });
          return !(ctx && ctx->cancelled());
        };
        auto r = mv::shell::photos::resolve(key, /*want_original=*/true, nullptr, progress);
        // Only a fetch from iCloud reports progress (PhotoKit's queue, before
        // resolve returns); a file this Mac has says nothing.
        if (reported->load(std::memory_order_acquire)) {
          dispatch_async(dispatch_get_main_queue(), ^{
            [g_chrome_app photosFetchEnded];
          });
        }
        if (!r) return mv::err(r.error());
        return std::move(r).value().path;
      },
      [](const std::string& file, const std::string& source) -> mv::result<std::string> {
        auto key = mv::shell::photos::add_photo(file);
        if (key) {
          const std::string added = *key;
          dispatch_async(dispatch_get_main_queue(), ^{
            [g_chrome_app photosAdded:added source:source];
          });
        }
        return key;
      });
  _folder.set_virtual_items(std::string(mv::shell::photos::kKeyPrefix), [](const std::string& key) {
    return mv::shell::photos::thumb_jpeg(key, mv::image::kThumbLongEdge);
  });
  _jobs.submit_at(mv::background_generation, [](const mv::job_context&) -> mv::status {
    mv::shell::photos::clear_cache();
    return mv::status::ok;
  });
  _launched = YES;
  if (!_options.open_path.empty() && ![self openEntryPath:_options.open_path.c_str()]) {
    NSBeep();
  }

  // folder_model_mac's relist/thumb watch fires on its own FSEvents thread
  // (io/dir.h: "must not block and must not re-enter the watcher" -- it
  // just flips an atomic) and relists on the pool, whose notify above hops
  // to the main queue: "a file dropped into the folder appears without
  // restart" (docs/design/10-roadmap.md PR 4's verify line) needs no poll.
  // Issue #178: the 0.2 s timer that used to poll it ran for the whole
  // session; what else it watched now posts, or polls only while a clip is up.
  // Issue #38: closing one of the transport's menus (speed, More) restarts the
  // idle clock, as the Windows flyout's Closed does. SwiftUI's borderless
  // menus are NSMenus, and a menu closed without a pick posts nothing else.
  [[NSNotificationCenter defaultCenter] addObserver:self
                                           selector:@selector(menuDidEndTracking:)
                                               name:NSMenuDidEndTrackingNotification
                                             object:nil];

  if (g_mac_pages.enabled) {
    _pageSoakTimer = [NSTimer scheduledTimerWithTimeInterval:1.0 / 120.0
                                                      target:self
                                                    selector:@selector(pageSoakTick)
                                                    userInfo:nil
                                                     repeats:YES];
  }
  if (g_pane_drag.enabled) {
    _paneDragTimer = [NSTimer scheduledTimerWithTimeInterval:1.0 / 120.0
                                                      target:self
                                                    selector:@selector(paneDragTick)
                                                    userInfo:nil
                                                     repeats:YES];
  }
  if (g_mac_browse.enabled) {
    _browseTimer = [NSTimer scheduledTimerWithTimeInterval:0.01
                                                    target:self
                                                  selector:@selector(browseTick)
                                                  userInfo:nil
                                                   repeats:YES];
  }

  if (_options.soak_seconds > 0.0 || _options.harness) {
    // A measuring run shows its window but does not take the keyboard: keys
    // typed into another app must not land here (Delete would send the
    // photo on screen to the Trash). It floats above other apps' windows so
    // using the machine meanwhile does not cover it (a covered window stops
    // presenting and voids the soak).
    self.window.level = NSFloatingWindowLevel;
    [self.window orderFrontRegardless];
  } else if (g_start_background) {
    [self startInBackground];
  } else {
    [self.window makeKeyAndOrderFront:nil];
    [NSApp activateIgnoringOtherApps:YES];
  }
  if (!g_start_background) {
    mv::boot::mark(mv::boot::stage::window_shown);
    [self markInteractiveWhenIdle];
  }
  _bootWithPath = !_options.open_path.empty();
  _bootTimer = [NSTimer scheduledTimerWithTimeInterval:0.05
                                                target:self
                                              selector:@selector(bootReportTick)
                                              userInfo:nil
                                               repeats:YES];
  _bootTimer.tolerance = 0.02;
}

// Issue #486: interactive is the first time the main thread goes idle waiting
// for input after launch: the run loop's BeforeWaiting, ordered after Core
// Animation's commit, so the SwiftUI chrome has been laid out and drawn.
- (void)markInteractiveWhenIdle {
  CFRunLoopObserverRef observer = CFRunLoopObserverCreateWithHandler(
      kCFAllocatorDefault, kCFRunLoopBeforeWaiting, false, INT_MAX, ^(CFRunLoopObserverRef, CFRunLoopActivity) {
        mv::boot::mark(mv::boot::stage::interactive);
      });
  if (observer) {
    CFRunLoopAddObserver(CFRunLoopGetMain(), observer, kCFRunLoopCommonModes);
    CFRelease(observer);
  }
}

// Issue #486: once the launch is ready, logs the boot timeline and, for
// --boot-report, writes it on a worker (rule 1) and quits. Ready: the UI is
// interactive, a frame is on screen and, with a path, its full resolution was
// presented (or kBootReportGiveUpMs passed). The timer stops once it has run.
- (void)bootReportTick {
  const mv::boot::snapshot s = mv::boot::read();
  const auto at = [&](mv::boot::stage st) { return s.ms[static_cast<std::size_t>(st)]; };
  if (!g_start_background &&
      (at(mv::boot::stage::interactive) < 0.0 || at(mv::boot::stage::first_frame) < 0.0)) {
    return;
  }
  if (_bootWithPath && at(mv::boot::stage::full_resolution) < 0.0 && mv::boot::now_ms() < kBootReportGiveUpMs) {
    return;
  }
  [_bootTimer invalidate];
  _bootTimer = nil;
  char line[1024];
  // stderr, not MV_LOG_INFO: the POSIX log keeps only warnings and errors.
  if (mv::boot::write_line(s, line, sizeof line)) std::fprintf(stderr, "%s\n", line);
  if (g_boot_report.empty()) return;
  _jobs.submit_at(mv::background_generation, [s](const mv::job_context&) -> mv::status {
    char json[4096];
    const std::size_t n = mv::boot::write_json(s, json, sizeof json);
    if (FILE* f = n ? std::fopen(g_boot_report.c_str(), "wb") : nullptr) {
      (void)std::fwrite(json, 1, n, f);
      (void)std::fclose(f);
    }
    dispatch_async(dispatch_get_main_queue(), ^{
      [NSApp terminate:nil];
    });
    return mv::status::ok;
  });
}

// --- --page-soak (see mac_page_run) --------------------------------------------

- (std::uint32_t)pageSoakLanded:(std::uint32_t)first count:(std::uint32_t)count {
  std::uint32_t n = 0;
  for (std::uint32_t p = first; p < first + count; ++p) {
    if (_pageThumbs && !_pageThumbs->path(p).empty()) ++n;
  }
  return n;
}

- (void)pageSoakFinish:(const char*)error {
  auto& p = g_mac_pages;
  if (p.step == mac_page_phase::finish) return;
  p.step = mac_page_phase::finish;
  [_pageSoakTimer invalidate];
  _pageSoakTimer = nil;
  if (FILE* f = std::fopen(p.json_path.c_str(), "wb")) {
    std::fprintf(f, "{\n  \"schema\": 1,\n  \"error\": ");
    if (error) browse_json_string(f, error);
    else std::fputs("null", f);
    std::fprintf(f,
                 ",\n  \"pages\": %u,\n  \"sidebar_s\": %.3f,\n  \"fling_s\": %.3f,\n"
                 "  \"drain_s\": %.3f,\n  \"landed\": %u,\n  \"jumps\": [\n",
                 p.pages, p.sidebar_s, p.fling_s, p.drain_s, p.landed);
    for (std::size_t i = 0; i < p.rows.size(); ++i) {
      const auto& r = p.rows[i];
      std::fprintf(f,
                   "    {\"page\": %d, \"timed_out\": %d, \"placeholder\": %d, \"ready_ms\": %.3f, "
                   "\"present_ms\": %.3f, \"full_ms\": %.3f}%s\n",
                   r.page + 1, r.timed_out, r.placeholder, r.ready_ms, r.present_ms, r.full_ms,
                   i + 1 < p.rows.size() ? "," : "");
    }
    std::fputs("  ]\n}\n", f);
    std::fclose(f);
  }
  // Under --soak the soak's own timer ends the run and writes its report.
  if (_options.soak_seconds <= 0.0) [NSApp terminate:nil];
}

- (void)pageSoakTick {
  auto& p = g_mac_pages;
  const double now = browse_now();
  if (p.t0 == 0.0) p.t0 = p.phase_t = now;
  switch (p.step) {
    case mac_page_phase::wait_doc:
      if ([self filmstripVisible]) [self setFilmstripVisible:NO];
      if (_pageSidebarShown && _pageSidebarListed > 1 && _shownPageCount == _pageSidebarListed) {
        p.pages = _pageSidebarListed;
        p.sidebar_s = now - p.t0;
        p.step = mac_page_phase::settle;
        p.phase_t = now;
      } else if (now - p.t0 > kMacBrowseOpenTimeout) {
        [self pageSoakFinish:"no paged document with its sidebar appeared"];
      }
      return;
    case mac_page_phase::settle:
      if (now - p.phase_t < 2.0) return;
      p.step = mac_page_phase::fling;
      p.phase_t = now;
      return;
    case mac_page_phase::fling: {
      const double t = std::min(1.0, (now - p.phase_t) / kMacPageFlingSeconds);
      const std::uint32_t span = p.pages > kMacPageWindow ? p.pages - kMacPageWindow : 0;
      [MVChromeHost pageSidebarHarnessScrollWithPage:static_cast<int32_t>(std::lround(t * span))];
      if (t < 1.0) return;
      p.fling_s = now - p.phase_t;
      p.step = mac_page_phase::drain;
      p.phase_t = now;
      return;
    }
    case mac_page_phase::drain: {
      const std::uint32_t window = std::min(kMacPageWindow, p.pages);
      const std::uint32_t first = p.pages - window;
      if ([self pageSoakLanded:first count:window] < window && now - p.phase_t < kMacBrowseStepTimeout) {
        return;
      }
      p.drain_s = now - p.phase_t;
      p.landed = [self pageSoakLanded:0 count:p.pages];
      for (const std::uint32_t want : {249u, 9u, 149u, p.pages - 1, 0u, 249u, 99u}) {
        p.targets.push_back(std::min(want, p.pages - 1));
      }
      p.step = mac_page_phase::jump;
      p.phase_t = now;
      return;
    }
    case mac_page_phase::jump: {
      if (now - p.phase_t < 1.0) return;  // dwell: the page before is settled
      if (p.next >= p.targets.size()) return [self pageSoakFinish:nullptr];
      const std::uint32_t page = p.targets[p.next++];
      if (page == _shownPage) return;  // already there: nothing to time
      p.seq = _lab.mark_navigation();
      if (p.seq == 0) return [self pageSoakFinish:"could not mark a jump"];
      p.rows.push_back({static_cast<int>(page), 0, 0, -1.0, -1.0, -1.0});
      [self selectPage:static_cast<int32_t>(page)];
      p.step = mac_page_phase::wait_jump;
      p.phase_t = now;
      return;
    }
    case mac_page_phase::wait_jump: {
      const bool done = _lab.navigation_done(p.seq) && _lab.navigation_full_ms(p.seq) >= 0.0;
      if (!done && now - p.phase_t <= kMacBrowseStepTimeout) return;
      mac_page_row& row = p.rows.back();
      row.timed_out = done ? 0 : 1;
      if (done) {
        const auto sample = _lab.navigation_sample(p.seq);
        row.ready_ms = sample.ready_ms;
        row.present_ms = sample.present_ms;
        row.full_ms = _lab.navigation_full_ms(p.seq);
        row.placeholder = sample.cached ? 0 : 1;
      }
      p.step = mac_page_phase::jump;
      p.phase_t = now;
      return;
    }
    case mac_page_phase::finish:
      return;
  }
}

// --- --pane-drag-soak (see mac_pane_drag_run) -------------------------------

- (void)paneDragFinish:(const char*)error {
  auto& d = g_pane_drag;
  if (d.step == mac_pane_drag_phase::finish) return;
  d.step = mac_pane_drag_phase::finish;
  [_paneDragTimer invalidate];
  _paneDragTimer = nil;
  char hidden[128];
  if (!error && d.hidden_s > 0.5) {
    std::snprintf(hidden, sizeof hidden, "window hidden for %.1f s; rerun with it on screen", d.hidden_s);
    error = hidden;
  }
  const auto frames = mv::shell::summarise(_lab.drag_log().intervals(), _lab.drag_log().refresh_ms());
  const float layout_p50 = mv::shell::percentile(d.layout_ms, 0.50);
  const float layout_p95 = mv::shell::percentile(d.layout_ms, 0.95);
  const float layout_max = d.layout_ms.empty() ? 0.0f : *std::max_element(d.layout_ms.begin(), d.layout_ms.end());
  const bool pass = !error && frames.frames > 0 && frames.over_2x == 0 && d.presents_after_settle == 0 &&
                    d.drawable_sets_during == 0;
  if (FILE* f = std::fopen(d.json_path.c_str(), "wb")) {
    std::fputs("{\n  \"schema\": 1,\n  \"host\": \"mac\",\n  \"error\": ", f);
    if (error) browse_json_string(f, error);
    else std::fputs("null", f);
    std::fprintf(f,
                 ",\n  \"sweep_s\": %.1f,\n  \"leg_s\": %.1f,\n  \"min_width\": %.0f,\n  \"max_width\": %.0f,\n"
                 "  \"frames\": %u,\n  \"refresh_ms\": %.3f,\n  \"p50_ms\": %.3f,\n  \"p99_ms\": %.3f,\n"
                 "  \"max_ms\": %.3f,\n  \"over_2x\": %u,\n  \"layout_steps\": %zu,\n"
                 "  \"layout_p50_ms\": %.3f,\n  \"layout_p95_ms\": %.3f,\n  \"layout_max_ms\": %.3f,\n"
                 "  \"drawable_sets_during_drag\": %u,\n  \"presents_after_settle\": %llu,\n  \"pass\": %s\n}\n",
                 kPaneDragSweepSeconds, kPaneDragLegSeconds, kPaneLimits.min, kPaneLimits.max, frames.frames,
                 frames.refresh_ms, frames.p50_ms, frames.p99_ms, frames.max_ms, frames.over_2x, d.layout_ms.size(),
                 layout_p50, layout_p95, layout_max, d.drawable_sets_during,
                 static_cast<unsigned long long>(d.presents_after_settle), pass ? "true" : "false");
    std::fclose(f);
  }
  [NSApp terminate:nil];
}

- (void)paneDragTick {
  auto& d = g_pane_drag;
  const double now = browse_now();
  if (d.t0 == 0.0) d.t0 = d.phase_t = d.last_tick = now;
  if (d.step != mac_pane_drag_phase::finish && !(self.window.occlusionState & NSWindowOcclusionStateVisible)) {
    d.hidden_s += now - d.last_tick;
  }
  d.last_tick = now;
  switch (d.step) {
    case mac_pane_drag_phase::wait_media:
      if (_lab.showing_still()) {
        // The docked column: the Edit workspace takes its width from the canvas.
        if (!_ws.open) (void)[self runCommand:mv::shell::command_id::edit_workspace back:mv::shell::back_target::none];
        if (!_ws.open) return [self paneDragFinish:"the Edit workspace did not open"];
        d.step = mac_pane_drag_phase::dwell;
        d.phase_t = now;
      } else if (now - d.t0 > kMacBrowseOpenTimeout) {
        [self paneDragFinish:"no photo appeared"];
      }
      return;
    case mac_pane_drag_phase::dwell:
      if (now - d.phase_t < kPaneDragDwellSeconds) return;
      d.drawable_sets_before = _lab.drawable_sets();
      [self paneEdgeDown:nil];
      d.step = mac_pane_drag_phase::drag;
      d.phase_t = now;
      return;
    case mac_pane_drag_phase::drag: {
      const double t = now - d.phase_t;
      if (t >= kPaneDragSweepSeconds) {
        d.drawable_sets_during = _lab.drawable_sets() - d.drawable_sets_before;
        [self paneEdgeUp:nil];
        d.step = mac_pane_drag_phase::settle;
        d.phase_t = now;
        return;
      }
      // A triangle: min -> max in one leg, back in the next.
      const double phase = std::fmod(t, 2.0 * kPaneDragLegSeconds) / kPaneDragLegSeconds;
      const double tri = phase <= 1.0 ? phase : 2.0 - phase;
      const CGFloat want = kPaneLimits.min + (kPaneLimits.max - kPaneLimits.min) * tri;
      const double t_layout = browse_now();
      [self paneDragTo:[self paneClientPoints] - [self paneLimits].rail - want];
      [self.window.contentView layoutSubtreeIfNeeded];
      d.layout_ms.push_back(static_cast<float>((browse_now() - t_layout) * 1000.0));
      return;
    }
    case mac_pane_drag_phase::settle:
      if (now - d.phase_t < kPaneDragSettleSeconds) return;
      d.presents_before = _lab.drag_log().presents();
      d.step = mac_pane_drag_phase::measure;
      d.phase_t = now;
      return;
    case mac_pane_drag_phase::measure:
      if (now - d.phase_t < kPaneDragMeasureSeconds) return;
      d.presents_after_settle = _lab.drag_log().presents() - d.presents_before;
      [self paneDragFinish:nullptr];
      return;
    case mac_pane_drag_phase::finish:
      return;
  }
}

// --- --browse-soak (see mac_browse_run) ------------------------------------

- (BOOL)browseSelect:(std::size_t)index record:(BOOL)record cold:(BOOL)cold {
  if (index >= _items.size()) return NO;
  const std::uint64_t seq = _lab.mark_navigation();
  if (seq == 0) return NO;
  g_mac_browse.seq = seq;
  g_mac_browse.record = record;
  g_mac_browse.pending_index = static_cast<int>(index);
  g_mac_browse.pending_cold = cold ? 1 : 0;
  g_mac_browse.pending_name = _items[index].name_utf8;
  g_mac_browse.phase_t = browse_now();
  [self selectIndex:index];
  return YES;
}

- (void)browseTake:(BOOL)timedOut {
  if (!g_mac_browse.record) return;
  mac_browse_row row;
  row.name = g_mac_browse.pending_name;
  row.index = g_mac_browse.pending_index;
  row.cold = g_mac_browse.pending_cold;
  row.timed_out = timedOut ? 1 : 0;
  if (!timedOut) {
    const auto sample = _lab.navigation_sample(g_mac_browse.seq);
    row.cached = sample.cached;
    row.ready_ms = sample.ready_ms;
    row.present_ms = sample.present_ms;
    row.refresh_ms = sample.refresh_ms;
  }
  g_mac_browse.rows.push_back(std::move(row));
}

- (BOOL)browseStepFinished {
  if (_lab.navigation_done(g_mac_browse.seq)) {
    [self browseTake:NO];
    return YES;
  }
  if (browse_now() - g_mac_browse.phase_t > kMacBrowseStepTimeout) {
    [self browseTake:YES];
    return YES;
  }
  return NO;
}

- (void)browseFinish:(const char*)error {
  if (g_mac_browse.step == mac_browse_phase::finish) return;
  g_mac_browse.step = mac_browse_phase::finish;
  char hidden[128];
  if (!error && g_mac_browse.hidden_s > 0.5) {
    std::snprintf(hidden, sizeof hidden, "window hidden for %.1f s; rerun with it on screen",
                  g_mac_browse.hidden_s);
    error = hidden;
  }
  [_browseTimer invalidate];
  _browseTimer = nil;
  if (FILE* f = std::fopen(g_mac_browse.json_path.c_str(), "wb")) {
    std::fprintf(f, "{\n  \"schema\": 1,\n  \"dwell_s\": %.1f,\n  \"count\": %zu,\n  \"edit_tab\": %d,\n  \"error\": ",
                 kMacBrowseDwell, g_mac_browse.count, g_browse_edit_tab);
    if (error) browse_json_string(f, error);
    else std::fputs("null", f);
    std::fputs(",\n  \"steps\": [\n", f);
    for (std::size_t i = 0; i < g_mac_browse.rows.size(); ++i) {
      const auto& row = g_mac_browse.rows[i];
      std::fputs("    {\"name\": ", f);
      browse_json_string(f, row.name);
      std::fprintf(f,
                   ", \"index\": %d, \"kind\": \"%s\", \"cached\": %d, \"timed_out\": %d, "
                   "\"ready_ms\": %.3f, \"present_ms\": %.3f, \"refresh_ms\": %.3f}%s\n",
                   row.index, row.cold ? "cold" : "warm", row.cached, row.timed_out, row.ready_ms,
                   row.present_ms, row.refresh_ms, i + 1 < g_mac_browse.rows.size() ? "," : "");
    }
    std::fputs("  ]\n}\n", f);
    std::fclose(f);
  }
  [NSApp terminate:nil];
}

- (void)browseTick {
  auto& b = g_mac_browse;
  if (b.t0 == 0.0) b.t0 = b.phase_t = b.last_tick = browse_now();
  {
    const double now = browse_now();
    if (b.step != mac_browse_phase::finish && !(self.window.occlusionState & NSWindowOcclusionStateVisible)) {
      b.hidden_s += now - b.last_tick;
    }
    b.last_tick = now;
  }
  switch (b.step) {
    case mac_browse_phase::wait_media:
      if (_lab.showing_still() && !_items.empty()) {
        b.count = _items.size();
        if (b.count < 2) return [self browseFinish:"fewer than 2 items"];
        if (g_browse_edit_tab >= 0) {
          if (!_ws.open) (void)[self runCommand:mv::shell::command_id::edit_workspace back:mv::shell::back_target::none];
          if (!_ws.open) return [self browseFinish:"the Edit workspace did not open"];
          [self editSelectTab:g_browse_edit_tab];
        }
        b.cold_n = 0;
        for (std::size_t i = 3; i < b.count && b.cold_n < 6; ++i) b.cold_targets[b.cold_n++] = static_cast<int>(i);
        b.warm_left = static_cast<int>(std::min<std::size_t>(b.count - 1, 12));
        b.step = mac_browse_phase::dwell;
        b.after_dwell = b.cold_n > 0 ? mac_browse_phase::cold : mac_browse_phase::warm;
        b.phase_t = browse_now();
      } else if (browse_now() - b.t0 > kMacBrowseOpenTimeout) {
        [self browseFinish:"no photo appeared"];
      }
      return;
    case mac_browse_phase::dwell:
      if (browse_now() - b.phase_t < kMacBrowseDwell) return;
      b.step = b.after_dwell;
      return [self browseTick];
    case mac_browse_phase::cold:
      if (b.cold_i >= b.cold_n) {
        b.step = mac_browse_phase::warm;
        return [self browseTick];
      }
      if (![self browseSelect:static_cast<std::size_t>(b.cold_targets[b.cold_i++]) record:YES cold:YES]) {
        return [self browseFinish:"could not mark a jump"];
      }
      b.step = mac_browse_phase::wait_away;
      return;
    case mac_browse_phase::wait_away:
      if (![self browseStepFinished]) return;
      b.step = mac_browse_phase::go_home;
      return [self browseTick];
    case mac_browse_phase::go_home:
      if (_index.current() == 0) {
        b.step = mac_browse_phase::dwell;
        b.after_dwell = mac_browse_phase::cold;
        b.phase_t = browse_now();
        return;
      }
      if (![self browseSelect:0 record:NO cold:NO]) return [self browseFinish:"could not return to the first photo"];
      b.step = mac_browse_phase::wait_home;
      return;
    case mac_browse_phase::wait_home:
      if (!_lab.navigation_done(b.seq) && browse_now() - b.phase_t <= kMacBrowseStepTimeout) return;
      b.step = mac_browse_phase::dwell;
      b.after_dwell = mac_browse_phase::cold;
      b.phase_t = browse_now();
      return;
    case mac_browse_phase::warm:
      if (b.warm_left <= 0 || _index.current() + 1 >= b.count) return [self browseFinish:nullptr];
      --b.warm_left;
      if (![self browseSelect:_index.current() + 1 record:YES cold:NO]) {
        return [self browseFinish:"could not mark a step"];
      }
      b.step = mac_browse_phase::wait_warm;
      return;
    case mac_browse_phase::wait_warm:
      if (![self browseStepFinished]) return;
      if (b.warm_left <= 0) return [self browseFinish:nullptr];
      b.step = mac_browse_phase::dwell;
      b.after_dwell = mac_browse_phase::warm;
      b.phase_t = browse_now();
      return;
    case mac_browse_phase::finish:
      return;
  }
}

- (BOOL)hasFolder {
  return !_items.empty();
}

- (BOOL)openEntryPath:(const char*)utf8_path {
  // docs/design/25: an add-on package handed to the app (a drop, Open With, the
  // command line) goes to Settings' install sheet, never to the viewer.
  // Nothing is read here; the chrome inspects it on a worker.
  if (utf8_path && *utf8_path) {
    NSString* path = [NSString stringWithUTF8String:utf8_path];
    if (path && [path.pathExtension caseInsensitiveCompare:@"mvaddon"] == NSOrderedSame) {
      [self setSettingsVisible:YES];
      [MVChromeHost offerAddonPackage:path];
      return YES;
    }
  }
  if (!utf8_path || !*utf8_path) return NO;
  // The launch open only (argv, a Finder open before launch finished): its stat
  // is on the first pixel's path either way, and done here it cannot queue
  // behind the chrome's main-thread work. Every later fresh open asks off the
  // main thread (-openEntryPaths:failed:).
  std::string dir;
  std::string select_path;
  if (!MvResolveEntry(utf8_path, &dir, &select_path)) return NO;
  [self openDir:dir select:select_path navigation:NO];
  return YES;
}

// docs/design/16 "Opening": the first of `paths` that exists wins (a folder opens
// that folder, a file its folder with the file selected; an add-on package goes
// to Settings). What is there is asked on a worker, never here (rule 1: a Recent
// folder on a sleeping disk or a dropped share stats for seconds), then the open
// continues on the main thread. Nothing existing runs `failed` (a beep when
// nil). Any open that starts meanwhile (another of these, a navigation, a list)
// supersedes this one, which then does nothing.
- (void)openEntryPaths:(NSArray<NSString*>*)paths failed:(void (^)(void))failed {
  const std::uint64_t entry = ++_entryGeneration;
  const std::uint64_t opened = _openGeneration.load(std::memory_order_acquire);
  NSArray<NSString*>* candidates = [paths copy];
  __weak MvLabApp* weakSelf = self;
  dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
    NSString* addon = nil;
    std::string dir;
    std::string select_path;
    bool found = false;
    for (NSString* path in candidates) {
      if ([path.pathExtension caseInsensitiveCompare:@"mvaddon"] == NSOrderedSame) {
        addon = path;
        break;
      }
      const char* fs = path.length > 0 ? path.fileSystemRepresentation : nullptr;
      if (fs && MvResolveEntry(fs, &dir, &select_path)) {
        found = true;
        break;
      }
    }
    dispatch_async(dispatch_get_main_queue(), ^{
      MvLabApp* app = weakSelf;
      if (!app || app->_entryGeneration != entry ||
          app->_openGeneration.load(std::memory_order_acquire) != opened) {
        return;
      }
      if (addon) {
        [app setSettingsVisible:YES];
        [MVChromeHost offerAddonPackage:addon];
      } else if (found) {
        [app openDir:dir select:select_path navigation:NO];
      } else if (failed) {
        failed();
      } else {
        NSBeep();
      }
    });
  });
}

// `navigation` = moving through the folder tree the user already opened (a
// folder tile, a breadcrumb, a sibling, up, the tree): the trail keeps its root
// and the filmstrip setting is left alone. Those are folders the app listed, so
// nothing is asked of the disk here; one that went since fails in
// folder_model::open() below, which beeps. A fresh open (Open, a drop, Recent)
// goes through -openEntryPaths:failed:, which starts a new trail.
- (BOOL)openPath:(const char*)utf8_path navigation:(BOOL)navigation {
  if (!utf8_path || !*utf8_path) return NO;
  [self openDir:utf8_path select:std::string() navigation:navigation];
  return YES;
}

// `dir` is a folder; `select_path` the file in it to show, or empty.
- (void)openDir:(const std::string&)dir select:(const std::string&)select_path navigation:(BOOL)navigation {
  // Moving up into a folder that contains the one we are leaving: remember
  // that child so its tile is selected when the parent listing arrives.
  if (navigation && !_currentDir.empty() && dir != _currentDir &&
      mv::shell::browse_path::within(_currentDir, dir)) {
    _revealChild = _currentDir;
  } else {
    _revealChild.clear();
  }
  // The destination is one of the folders on screen: those paths are its
  // siblings, already in memory, so sideways navigation does not wait.
  bool seeded = false;
  for (std::size_t i = 0; i < _subdirs.size(); ++i) {
    if (_subdirs[i].path_utf8 != dir) continue;
    _siblings.clear();
    _siblings.reserve(_subdirs.size());
    for (const auto& sub : _subdirs) _siblings.push_back(sub.path_utf8);
    _siblingIndex = static_cast<NSInteger>(i);
    seeded = true;
    break;
  }
  if (!seeded) {
    bool kept = false;
    for (std::size_t i = 0; i < _siblings.size(); ++i) {
      if (_siblings[i] == dir) {
        _siblingIndex = static_cast<NSInteger>(i);
        kept = true;
        break;
      }
    }
    if (!kept) {
      _siblings.clear();
      _siblingIndex = -1;
    }
  }
  _folderFind = NO;
  _folderQuery.clear();
  // Opening a directory ends a result listing (mv_folder_open_list's rule).
  if (_listOpen) {
    [self photosListEnding];
    _listOpen = NO;
    _listTitle.clear();
    _listReturnDir.clear();
    _moments.clear();
    _listNames.clear();
    ++_listingGeneration;
  }
  if (navigation) {
    _browsePath.visit(dir);
  } else {
    _browsePath.reset(dir);
  }
  _folderCursor = -1;
  _subdirs.clear();
  _galleryIfEmptyDir = dir;
  // Settings: a folder open earns the filmstrip; opening one image is a viewing
  // intent and keeps it off until asked (docs/design/16, same as Windows).
  if (!navigation) {
    const auto prefs = mv::shell::view_settings::from_flags(_viewFlags);
    const BOOL want = select_path.empty() ? prefs.filmstrip_for_folder : prefs.filmstrip_for_image;
    if (want != _filmstripVisible) [self setFilmstripVisible:want];
  }

  // The listing itself is already async (folder_model_mac::relist_async
  // submits its own job); -refreshFolderIfChanged picks it up once
  // consume_changed() fires and resolves `_wantSelectedPath` against the
  // real listing. Resetting `_index`/`_items` now, synchronously (no I/O
  // here, just clearing C++ containers), means a relist that lands for a
  // *different* folder in flight can never be mistaken for this one's.
  _wantSelectedPath = select_path;
  _currentDir = dir;
  // Walking siblings and the tree is browsing, not a new place to go back to.
  if (!navigation) [self noteRecentFolder:dir];
  _items.clear();
  _index.reset(0);
  _metaRecord.reset();
  ++_metaGeneration;
  // Opening a file: start its decode now, beside the folder listing, rather
  // than after it (rule 3's first pixel should not wait on a directory scan).
  // -selectIndex: adopts this load when the listing selects the same path.
  if (!select_path.empty()) {
    _shownItem = _lab.open_item(select_path);
    _shownPage = 0;
    _shownPageCount = 0;
    _shownPath = select_path;
    _shownMtime = kShownStampUnknown;
    _shownSize = 0;
    _shownMoment = -1;
  }

  // folder_model::open() itself is real I/O -- opening, and maybe creating,
  // the thumbnail cache's SQLite file -- so it never runs on the UI thread
  // (CLAUDE.md rule 1: "no I/O"), any more than the stat that found `dir`.
  // `&_folder`/`&_jobs` stay valid for the job's duration because MvLabApp
  // is never destroyed before the process exits -- unlike folder_model_mac's
  // own internal jobs, which capture a shared_ptr<shared_state> precisely
  // because a folder_model *can* be destroyed mid-job in general.
  mv::shell::folder_model* folder = &_folder;
  mv::job_system* jobs = &_jobs;
  const std::uint64_t my_generation = _openGeneration.fetch_add(1, std::memory_order_acq_rel) + 1;
  std::atomic<std::uint64_t>* open_generation = &_openGeneration;
  std::mutex* open_mutex = &_folderOpenMutex;
  _jobs.submit_at(mv::background_generation,
                  [folder, jobs, dir, my_generation, open_generation, open_mutex](
                      const mv::job_context&) -> mv::status {
                    // A newer -openDir: call already arrived: calling
                    // folder->open() now would race that one's own open()
                    // call outside folder_model's internal locking (see
                    // _openGeneration's declaration comment). Let the newer
                    // request own this folder_model unopposed instead.
                    std::lock_guard<std::mutex> lock(*open_mutex);
                    if (open_generation->load(std::memory_order_acquire) != my_generation) {
                      return mv::status::cancelled;
                    }
                    auto opened = folder->open(dir, *jobs);
                    if (!opened) {
                      dispatch_async(dispatch_get_main_queue(), ^{
                        NSBeep();
                      });
                      return opened.error();
                    }
                    return mv::status::ok;
                  });
  [self updateChromeBarHeight];
  // Milestone H: the AI chrome notes the folder (note_folder_opened) so a
  // covered root queues its delta and the search panel knows its scope.
  MvAddonsFolderOpened(dir);
}

// The transport strip belongs to a clip: shown while one is on screen (the
// render thread publishes that), hidden otherwise so it never blocks the
// canvas's mouse. Polled every 0.2 s while a clip or a sound is the current
// item (issue #178: not on a still); a clip opening, pausing, ending, or the
// gallery / Settings covering it is what re-runs the idle rule (issue #38).
// Pause and end bring it back.
- (void)transportPollItemChanged {
  const bool want = [self currentItemIsVideo] || [self currentItemIsAudio] || _transportClip;
  if (!want || _transportPollTimer) return;
  _transportPollTimer = [NSTimer scheduledTimerWithTimeInterval:0.2
                                                         target:self
                                                       selector:@selector(transportPollTick:)
                                                       userInfo:nil
                                                        repeats:YES];
  _transportPollTimer.tolerance = 0.04;
}

- (void)transportPollTick:(NSTimer*)timer {
  (void)timer;
  [self pollTransport];
  // A play the editor's tick missed (it stops while paused) is caught here.
  if (_editorOpen && !_editorTick && _transportPlaying) [self editorTickResume];
  if ([self currentItemIsVideo] || [self currentItemIsAudio] || _transportClip) return;
  [_transportPollTimer invalidate];
  _transportPollTimer = nil;
}

- (void)pollTransport {
  if (!self.transportHost) return;
  const auto st = _lab.video_status_snapshot();
  const bool clip = st.active && !_galleryVisible && !_settingsVisible;
  const bool playing = clip && st.playing;
  if (clip != _transportClip || playing != _transportPlaying) {
    _transportClip = clip;
    _transportPlaying = playing;
    [self applyTransportAutohide];
    [self layoutAIBadge];  // #345: the badge sits above a clip's strip
  }
}

- (void)refreshFolderIfChanged {
  if (!_askedDefaultViewer && _installerChecked && _options.soak_seconds <= 0.0) {
    [self askDefaultViewerOnce];
  }
  [self pollTransport];
  // #345: the badge follows the transport, the filmstrip and the panes. No
  // timer polls this any more (issue #178), so each of those changes calls
  // -layoutAIBadge too; here it catches an item list that emptied or filled.
  [self layoutAIBadge];
  // Date-taken keys arriving on the pool re-sort the listing in place: the same
  // items, the current one still selected, no image reload. Once, when the pass
  // ends (as Windows and the date scan before it): a re-sort per chunk re-sorted
  // and republished a 20 k listing five times a second while the pass ran.
  if (_tags && _tags->consume_changed()) {
    ++_tagGeneration;  // an open file search re-runs its tag half
    if (_sort.key == mv::io::sort_key::date_taken && !_listOpen && !_tags->progress().reading) {
      [self resortKeepingSelection];
    }
  }
  [self startTagScanIfDue];
  [self startThumbSweepIfDue];
  // Issue #207: ratings and labels arriving on the pool re-apply a cull filter.
  if (_meta.consume_cull_changed() && mv::io::needs_cull_marks(mv::io::kind_filter_mask(_kindFilter))) {
    _refilterListing = YES;
  }
  // Issue #210: an F2 rename is on its way; its relist waits for it, so the
  // stop is found under its new name instead of the next one sliding in.
  if (_renamePending) return;
  if (!_folder.consume_changed() && !_refilterListing) return;
  _refilterListing = NO;
  mv::shell::folder_model::listing listing = _folder.snapshot();
  // A relist that belongs to the other kind of listing (a folder's watch
  // firing just as a result list opens, or the list a folder open is
  // replacing) is not what is on screen now.
  if (listing.is_list != static_cast<bool>(_listOpen)) return;
  const std::uint32_t filter = mv::io::kind_filter_mask(_kindFilter);
  // Issue #207: a cull filter (Picks, Not rejected, a colour) needs every
  // file's rating and label. Here they are only looked up (one lock, no file
  // read); the missing ones are read on a worker (meta_store, keyed by path +
  // size + mtime) and their arrival relists again. A stop not read yet counts
  // as unrated and unlabelled. A newly chosen filter waits for them instead,
  // keeping what is shown, so it moves off the stop on screen only once.
  std::vector<std::optional<mv::io::cull_marks>> cull;
  if (mv::io::needs_cull_marks(filter)) {
    cull = _meta.cull_marks_of(listing.items);
    std::vector<mv::io::dir_entry> missing;
    for (std::size_t i = 0; i < cull.size(); ++i) {
      if (!cull[i]) missing.push_back(listing.items[i]);
    }
    if (!missing.empty()) {
      _meta.resolve_cull_marks(std::move(missing), _jobs, {});
      if (_kindFilterChanged && !_items.empty()) return;
    }
  }
  _items = std::move(listing.items);
  // Every file in the folder, before any kind is left out: a mark on a file
  // the listing merely hides (View > Show, Settings' kinds) is not a mark on
  // a file that has gone.
  std::set<std::string> livePaths;
  if (!_marks.empty()) {
    for (const auto& entry : _items) livePaths.insert(entry.path_utf8);
  }
  const std::uint32_t hide = mv::shell::view_settings::from_flags(_viewFlags).hidden_kinds();
  const bool filterChanged = _kindFilterChanged;
  _kindFilterChanged = NO;
  if (hide != 0 || filter != 0) {
    // Settings left a kind out, or View > Show narrowed the listing: the rule
    // abi.cpp's apply_folder_list applies (io::keeps_stop). The file being
    // opened or on screen stays, so an explicit open still shows, except on
    // the relist a new filter makes. A filter that leaves nothing keeps that
    // stop, so the canvas never goes blank. A result list keeps its moments
    // aligned with its items. This host does not pair, so each half of a
    // RAW+JPEG is its own stop: the RAW under RAW, the JPEG under Photos.
    const bool aligned = _listOpen && listing.moments.size() == _items.size();
    std::vector<mv::io::dir_entry> all;
    std::vector<std::int64_t> allMoments;
    if (filter != 0) {
      all = _items;
      if (aligned) allMoments = listing.moments;
    }
    std::size_t out = 0;
    for (std::size_t i = 0; i < _items.size(); ++i) {
      const auto& e = _items[i];
      const bool stays = !_wantSelectedPath.empty() && e.path_utf8 == _wantSelectedPath;
      const mv::io::cull_marks marks = i < cull.size() && cull[i] ? *cull[i] : mv::io::cull_marks{};
      if (!mv::io::keeps_stop(e.name_utf8, {}, _kindKept.count(e.path_utf8) != 0, stays, hide,
                              filter, filterChanged, marks)) {
        continue;
      }
      if (aligned) listing.moments[out] = listing.moments[i];
      if (out != i) _items[out] = std::move(_items[i]);
      ++out;
    }
    _items.resize(out);
    if (aligned) listing.moments.resize(out);
    if (filter != 0 && _items.empty() && !_wantSelectedPath.empty()) {
      for (std::size_t i = 0; i < all.size(); ++i) {
        if (all[i].path_utf8 != _wantSelectedPath) continue;
        _items.push_back(std::move(all[i]));
        if (aligned) listing.moments.assign(1, i < allMoments.size() ? allMoments[i] : -1);
        break;
      }
    }
  }
  _subdirs = std::move(listing.subdirs);
  if (_folderCursor >= static_cast<NSInteger>(_subdirs.size())) {
    _folderCursor = static_cast<NSInteger>(_subdirs.size()) - 1;
  }
  if (_listOpen) {
    // Best match first: a result list keeps the order it was given.
    _moments = std::move(listing.moments);
    _moments.resize(_items.size(), -1);
    _listTitle = listing.title;
    [self makeListNames];
  } else {
    [self sortItems];
    _tagScanListedAt = CFAbsoluteTimeGetCurrent();
    // Sorting by date is asked for, so its keys start now, as the date scan
    // always did; otherwise the pass waits for the item's first pixel.
    if (_sort.key == mv::io::sort_key::date_taken) {
      [self startTagScan];
    } else {
      [self armTagScan];
    }
  }
  ++_listingGeneration;

  // Marks are kept by path specifically so they survive a relist that
  // merely reorders _items, but a path can also drop out of the listing
  // entirely here -- external deletion/rename, not just this app's own
  // copy/move/Trash (which already prune their own successes directly).
  // Without this, a mark for a file that is simply gone would sit in
  // _marks forever, inflating _snap.marked_count.
  if (!_marks.empty()) {
    std::erase_if(_marks, [&livePaths](const std::string& path) {
      return !livePaths.count(path);
    });
    ++_marksGeneration;
  }
  [self clearGalleryRange];  // #413: indices of the old listing

  std::size_t new_index = 0;
  if (!_items.empty()) {
    bool found = false;
    if (!_wantSelectedPath.empty()) {
      for (std::size_t i = 0; i < _items.size(); ++i) {
        if (_items[i].path_utf8 == _wantSelectedPath) {
          new_index = i;
          found = true;
          break;
        }
      }
    }
    if (!found) {
      new_index = std::min(_index.current(), _items.size() - 1);
    }
  }
  [self selectIndex:new_index];

  bool revealed = false;
  if (!_revealChild.empty()) {
    for (std::size_t i = 0; i < _subdirs.size(); ++i) {
      if (_subdirs[i].path_utf8 == _revealChild) {
        _folderCursor = static_cast<NSInteger>(i);
        revealed = true;
        break;
      }
    }
    _revealChild.clear();
  }

  // A folder that holds only folders opens the gallery so the tiles are what
  // the user lands on. Coming back up also opens it, on the tile that was left.
  if (!_galleryIfEmptyDir.empty() && _folder.directory() == _galleryIfEmptyDir) {
    _galleryIfEmptyDir.clear();
    if (_items.empty() && !_subdirs.empty()) {
      [self setGalleryVisible:YES];
      if (!revealed) _folderCursor = 0;
    }
  }
  if (revealed) [self setGalleryVisible:YES];
  [self refreshSiblings];
}

- (void)selectIndex:(std::size_t)new_index {
  // Issue #413: another selection ends a gallery range (arrows move one cell).
  [self clearGalleryRange];
  _index.reset(_items.size(), new_index);
  [self applyFilmstripLayout];
  [self trimItemChanged];
  [self nowPlayingItemChanged];
  [self transportPollItemChanged];

  if (!_scrubMs.empty()) ++_scrubGeneration;  // markers belong to one clip
  // docs/design/26: a preview's pending fetch belongs to the item the user has left.
  [_photosFetchTimer invalidate];
  _photosFetchTimer = nil;
  if (_items.empty()) {
    MvAddonsItemChanged(std::string());
    _wantSelectedPath.clear();
    _shownPath.clear();
    _shownItem = 0;
    _edits.clear_item();
    _itemId = 0;
    [self publishEdit];
    _snap.item_index = 0;
    _snap.item_count = 0;
    _snap.item_name[0] = '\0';
  } else {
    const mv::io::dir_entry& entry = _items[_index.current()];
    _wantSelectedPath = entry.path_utf8;
    // Milestone H: a clip from a result list opens paused on its moment.
    const std::size_t at = _index.current();
    const std::int64_t moment = _listOpen && at < _moments.size() ? _moments[at] : -1;
    // Already on screen or loading: a relist (a file added elsewhere in the
    // folder, a thumbnail written) or the listing that follows an open keeps
    // that load. Every FSEvents change used to re-read and re-decode it. A
    // result keeps it too when it is the same moment (the tile already shown,
    // or next/prev held at the list's edge); another moment of the same clip
    // opens afresh.
    const bool same = _shownItem != 0 && entry.path_utf8 == _shownPath &&
                      moment == _shownMoment &&
                      (_shownMtime == kShownStampUnknown ||
                       (_shownMtime == entry.mtime_unix && _shownSize == entry.size));
    if (!same) {
      if (mv::shell::photos::is_key(entry.path_utf8)) {
        // docs/design/26: through its file, resolved on a worker if not yet.
        if (_photosFetchCancel) _photosFetchCancel->store(true, std::memory_order_release);
        _photosFetchCancel.reset();
        _shownItem = 0;
        [self openPhotosEntry:entry moment:moment];
      } else if (moment > 0 && mv::io::is_document_name(entry.path_utf8)) {
        // #354: a document from a result list opens on the page that matched.
        _shownItem = _lab.open_item(entry.path_utf8, entry.mtime_unix, entry.size, -1,
                                    static_cast<std::uint32_t>(std::min<std::int64_t>(moment, UINT32_MAX)));
      } else {
        _shownItem = _lab.open_item(entry.path_utf8, entry.mtime_unix, entry.size, moment);
      }
      _shownPage = moment > 0 && mv::io::is_document_name(entry.path_utf8)
                       ? static_cast<std::uint32_t>(std::min<std::int64_t>(moment, UINT32_MAX))
                       : 0;
      _shownPageCount = 0;
    }
    _shownMoment = moment;
    _shownPath = entry.path_utf8;
    _shownMtime = entry.mtime_unix;
    _shownSize = entry.size;
    [self editItemOpened:entry item:_shownItem];
    MvAddonsItemChanged(entry.path_utf8);
    // Decode the neighbours behind it, so the next arrow shows a full image
    // at once (Windows' ±2 prefetch). The lab skips clips, animations and
    // what it already holds; the next navigation abandons the rest.
    if (!same) {
      std::vector<std::string> near;
      const std::size_t cur = _index.current();
      for (const int off : {1, -1, 2, -2}) {
        const auto i = static_cast<std::ptrdiff_t>(cur) + off;
        if (i >= 0 && static_cast<std::size_t>(i) < _items.size()) {
          const std::string& p = _items[static_cast<std::size_t>(i)].path_utf8;
          // A Photos item prefetches through its resolve (openPhotosEntry).
          if (!mv::shell::photos::is_key(p)) near.push_back(p);
        }
      }
      if (!near.empty()) _lab.prefetch(near);
    }
    _snap.item_index = static_cast<std::uint32_t>(_index.current());
    _snap.item_count = static_cast<std::uint32_t>(_items.size());
    const std::size_t n = std::min(entry.name_utf8.size(), sizeof(_snap.item_name) - 1);
    std::memcpy(_snap.item_name, entry.name_utf8.data(), n);
    _snap.item_name[n] = '\0';
  }
  [self updateMarkSnapshot];
  [self metadataSelectionChanged];
  [self aiBadgeSelectionChanged];
  [self publish];
}

// input_snapshot.item_marked/marked_count (src/shell/input_state.h) refresh
// point, shared by -selectIndex: (selection changed) and every mark
// mutator below (the set changed, selection didn't). Does not bump
// activity_seq/publish/wake itself -- callers that are not already doing
// that as part of a larger update (the mark mutators) do it themselves.
- (void)updateMarkSnapshot {
  _snap.marked_count = static_cast<std::uint32_t>(_marks.size());
  _snap.item_marked = !_items.empty() && _index.current() < _items.size() &&
                      _marks.count(_items[_index.current()].path_utf8) != 0;
}

// A small RAII-ish helper `publish` wrapper every mutator below shares, so
// none of them has to repeat the three-line "bump, publish, wake" dance
// -selectIndex: already established.
- (void)publish {
  ++_snap.activity_seq;
  [self.view publish];
  _lab.wake();
  [self editorTickResume];
}

- (void)setHomeThemeActive:(BOOL)active
                       dark:(const mv_home_palette*)dark
                      light:(const mv_home_palette*)light
                     effect:(int)effect
                  effectRgb:(uint32_t)effectRgb
                  intensity:(float)intensity
                      speed:(float)speed
                       size:(float)size {
  _themeActive = active && (dark != nullptr || light != nullptr);
  _themeHasDark = dark != nullptr;
  _themeHasLight = light != nullptr;
  if (dark) _themeDark = *dark;
  if (light) _themeLight = *light;
  // An add-on theme has no ground; neither has Default or increased contrast.
  const bool known = effect >= 0 && effect < static_cast<int>(mv::shell::home_effect::count);
  _themeEffect = _themeActive && known ? static_cast<mv::shell::home_effect>(effect)
                                       : mv::shell::home_effect::none;
  _themeEffectRgb = effectRgb & 0xFFFFFFu;
  const auto unit = [](float v) { return v > 0.0f && v <= 1.0f ? v : 1.0f; };
  _themeIntensity = unit(intensity);
  _themeSpeed = unit(speed);
  _themeSize = unit(size);
  [self syncHomeAppearance];
}

// The ground's five seconds restart on a pointer move. Rate-limited: a bump
// wakes the render thread, which only notes the time (no frame).
- (void)pointerActivity {
  const CFTimeInterval now = CACurrentMediaTime();
  if (now - _lastPointerBump < 0.5) return;
  _lastPointerBump = now;
  ++_snap.pointer_seq;
  [self.view publish];
  _lab.wake();
}

- (void)syncHomeAppearance {
  // AppKit resolves the semantic colours for this window's effective appearance.
  // Do this on the UI thread; the Metal thread reads only the POD snapshot.
  if (!self.view.window) return;
  if (!_reduceMotionObserver) {
    __weak MvLabApp* weakSelf = self;
    _reduceMotionObserver = [[NSWorkspace sharedWorkspace].notificationCenter
        addObserverForName:NSWorkspaceAccessibilityDisplayOptionsDidChangeNotification
                    object:nil
                     queue:NSOperationQueue.mainQueue
                usingBlock:^(NSNotification*) { [weakSelf syncHomeAppearance]; }];
    // Default's accent is the system's: follow a change made in System Settings.
    _systemColoursObserver = [NSNotificationCenter.defaultCenter
        addObserverForName:NSSystemColorsDidChangeNotification
                    object:nil
                     queue:NSOperationQueue.mainQueue
                usingBlock:^(NSNotification*) { [weakSelf syncHomeAppearance]; }];
  }
  mv::shell::home_theme home;
  if (_themeActive) {
    // A theme with one palette keeps the chrome in that appearance, so the
    // palette it has is the one in use.
    NSAppearanceName match = [self.view.effectiveAppearance
        bestMatchFromAppearancesWithNames:@[ NSAppearanceNameAqua, NSAppearanceNameDarkAqua ]];
    const bool dark = [match isEqualToString:NSAppearanceNameDarkAqua];
    const mv_home_palette& p = (dark && _themeHasDark) || !_themeHasLight ? _themeDark : _themeLight;
    home.canvas = p.canvas;
    home.surface = p.surface;
    home.title = p.title;
    home.body = p.body;
    home.hairline = p.hairline;
    home.accent = p.accent;
    home.effect = _themeEffect;
    home.effect_rgb = _themeEffectRgb;
    home.intensity = _themeIntensity;
    home.speed = _themeSpeed;
    home.size = _themeSize;
  } else {
    // Default (and increased contrast): the chrome's own tokens are AppKit's
    // semantic colours (Theme.swift MVTheme), resolved here the same way. A
    // dynamic colour resolves against the current drawing appearance, so
    // convert it while this view's appearance is current (macOS 11+).
    const auto rgba = [](NSColor* c) -> std::uint32_t {
      if (!c) return 0;
      const auto component = [](CGFloat value) -> std::uint32_t {
        return static_cast<std::uint32_t>(
            std::lround(std::clamp(static_cast<double>(value), 0.0, 1.0) * 255.0));
      };
      return (component(c.redComponent) << 24) | (component(c.greenComponent) << 16) |
             (component(c.blueComponent) << 8) | component(c.alphaComponent);
    };
    std::array<std::uint32_t, 6> resolved{};
    std::array<std::uint32_t, 6>* const out = &resolved;  // a block cannot capture a C array
    [self.view.effectiveAppearance performAsCurrentDrawingAppearance:^{
      NSColor* const colours[6] = {NSColor.windowBackgroundColor, NSColor.controlBackgroundColor,
                                   NSColor.labelColor, NSColor.secondaryLabelColor,
                                   NSColor.separatorColor, NSColor.controlAccentColor};
      for (std::size_t i = 0; i < 6; ++i)
        (*out)[i] = rgba([colours[i] colorUsingColorSpace:NSColorSpace.sRGBColorSpace]);
    }];
    const std::array<std::uint32_t, 6>& t = resolved;
    if (t[0] == 0) return;
    home.canvas = t[0] | 0xFFu;  // the clear is opaque
    home.surface = t[1];
    home.title = t[2];
    home.body = t[3];
    home.hairline = t[4];
    home.accent = t[5];
  }
  const bool reduce = NSWorkspace.sharedWorkspace.accessibilityDisplayShouldReduceMotion;
  if (_snap.home == home && _snap.reduce_motion == reduce) return;
  _snap.home = home;
  _snap.reduce_motion = reduce;
  [self publish];
}

- (NSString*)currentItemPathForDrag {
  if (_items.empty() || _index.current() >= _items.size()) return nil;
  // docs/design/26: a Photos item drags as its file, once it has one (not a preview).
  const std::string path = [self fileForEntry:_items[_index.current()]];
  if (path.empty()) return nil;
  return [NSString stringWithUTF8String:path.c_str()];
}

- (NSFilePromiseProvider*)flattenedPromiseForDrag {
  if (_items.empty() || _index.current() >= _items.size() || [self currentItemIsVideo] ||
      _lab.anim_active()) {
    return nil;
  }
  MvFlattenPromise* writer = [[MvFlattenPromise alloc] initWithPath:_items[_index.current()].path_utf8
                                                           geometry:_edits.export_geometry()
                                                             colour:_edits.colour()];
  NSFilePromiseProvider* promise =
      [[NSFilePromiseProvider alloc] initWithFileType:UTTypePNG.identifier delegate:writer];
  promise.userInfo = writer;  // the delegate is weak; this keeps it for the drag
  return promise;
}

- (std::vector<mv::io::dir_entry>)markedOrCurrentEntries {
  std::vector<mv::io::dir_entry> out;
  // Issue #413: a gallery range is the selection while it holds files: copy,
  // F7/F8, Delete, copy path and Share act on it, in listing order.
  if (!_galleryRange.empty()) {
    const std::set<std::string> in(_galleryRange.begin(), _galleryRange.end());
    for (const auto& entry : _items) {
      if (in.count(entry.path_utf8)) out.push_back(entry);
    }
    if (!out.empty()) return out;
  }
  if (!_marks.empty()) {
    for (const auto& entry : _items) {
      if (_marks.count(entry.path_utf8)) out.push_back(entry);
    }
    return out;
  }
  if (!_items.empty() && _index.current() < _items.size()) {
    out.push_back(_items[_index.current()]);
  }
  return out;
}

// Issue #72: a file from the Photos library (in place, or a preview / on-view
// download the list registered) is never changed, renamed, moved or trashed,
// and nothing is saved beside it (shell/write_guard.h). YES: refused, and said.
- (BOOL)refuseWriteTo:(const std::string&)path {
  if (!mv::shell::write_protected(path)) return NO;
  NSBeep();
  [self noticeShow:std::string(mv::shell::kWriteProtectedNotice)];
  return YES;
}

- (BOOL)refuseWriteToEntries:(const std::vector<mv::io::dir_entry>&)entries {
  for (const auto& e : entries) {
    if ([self refuseWriteTo:e.path_utf8]) return YES;
  }
  return NO;
}

// Issue #210: F2 (and File > Rename…). The name without its extension, in an
// alert's field, selected as Finder selects it; the rename runs on the pool
// (io::rename_stop) and carries the file's pair -- found by the scan-time
// pairing rule, though this host lists both halves -- and its XMP sidecars.
// Refused in a result list (its items live in other folders), for a Photos
// library file, while the file has unsaved edits (keyed by its path) or a
// metadata write in flight (it would land on the old name).
- (BOOL)renameCurrentItem {
  const mv::io::dir_entry* entry = [self currentEntry];
  if (!entry) return NO;
  if (_listOpen) {
    [self noticeShow:"Rename it from its own folder"];
    return YES;
  }
  if ([self refuseWriteTo:entry->path_utf8]) return YES;
  if (_edits.edit_count() > 0 || _edits.crop_active() || _edits.write_in_flight()) {
    [self noticeShow:"Save or reset the edits first"];
    return YES;
  }
  if (_metaWriter.busy_for(entry->path_utf8) || _renamePending) {
    [self noticeShow:"Wait for the last change to finish"];
    return YES;
  }
  const std::string path = entry->path_utf8;
  const std::string oldStem(mv::io::stem_of(path));
  const std::string ext = std::string(mv::io::file_name_of(path)).substr(oldStem.size());

  // The pair's other half, by the rule the Windows core pairs with at scan.
  std::string partner;
  {
    const std::string key = mv::io::pairing_detail::key_of(entry->name_utf8);
    std::vector<mv::io::dir_entry> same;
    for (const auto& e : _items) {
      if (mv::io::pairing_detail::key_of(e.name_utf8) == key) same.push_back(e);
    }
    for (const auto& stop : mv::io::pair_listing(std::move(same))) {
      if (stop.secondary.path_utf8.empty()) continue;
      if (stop.primary.path_utf8 == path) partner = stop.secondary.path_utf8;
      else if (stop.secondary.path_utf8 == path) partner = stop.primary.path_utf8;
    }
  }

  NSAlert* alert = [[NSAlert alloc] init];
  alert.messageText = @"Rename";
  alert.informativeText = partner.empty()
      ? [NSString stringWithFormat:@"Keeps %s; any .xmp sidecar follows. Never overwrites.", ext.c_str()]
      : [NSString stringWithFormat:@"Keeps %s and its pair; any .xmp sidecar follows. Never overwrites.",
                                   ext.c_str()];
  NSTextField* field = [[NSTextField alloc] initWithFrame:NSMakeRect(0, 0, 300, 24)];
  field.stringValue = [NSString stringWithUTF8String:oldStem.c_str()] ?: @"";
  field.accessibilityLabel = @"New name";
  alert.accessoryView = field;
  [alert addButtonWithTitle:@"Rename"];
  [alert addButtonWithTitle:@"Cancel"];
  alert.window.initialFirstResponder = field;
  [alert layout];
  [field selectText:nil];
  if ([alert runModal] != NSAlertFirstButtonReturn) return YES;

  NSString* typed = [field.stringValue stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceCharacterSet];
  const std::string stem = typed.UTF8String ? typed.UTF8String : "";
  if (const auto problem = mv::io::check_stem(stem); problem != mv::io::stem_problem::ok) {
    NSBeep();
    [self noticeShow:mv::io::stem_problem_text(problem)];
    return YES;
  }
  if (stem == oldStem) return YES;

  _renamePending = YES;
  MvLabApp* __weak weakSelf = self;
  _jobs.submit_at(mv::background_generation,
                  [path, partner, stem, weakSelf](const mv::job_context&) -> mv::status {
                    auto r = mv::io::rename_stop(path, partner, stem);
                    const mv::status st = r ? mv::status::ok : r.error();
                    const std::string to = r ? r->primary : std::string();
                    const std::string partnerTo = r ? r->secondary : std::string();
                    dispatch_async(dispatch_get_main_queue(), ^{
                      MvLabApp* strongSelf = weakSelf;
                      if (strongSelf) [strongSelf renameFinished:path to:to partner:partner partnerTo:partnerTo status:st];
                    });
                    return st;
                  });
  return YES;
}

- (void)renameFinished:(const std::string&)from
                    to:(const std::string&)to
               partner:(const std::string&)partner
             partnerTo:(const std::string&)partnerTo
                status:(mv::status)st {
  _renamePending = NO;
  if (st != mv::status::ok || to.empty()) {
    NSBeep();
    [self noticeShow:st == mv::status::not_found ? "The file is gone" : "Could not rename the file"];
    return;
  }
  // A mark moves with its file; both halves are stops on this host.
  bool marks = false;
  if (_marks.erase(from) != 0) { _marks.insert(to); marks = true; }
  if (!partner.empty() && _marks.erase(partner) != 0) { _marks.insert(partnerTo); marks = true; }
  if (marks) [self marksDidChange];
  // The relist selects the file under its new name; what is on screen is the
  // same bytes (same size and stamp), so it is not loaded again.
  if (_wantSelectedPath == from) _wantSelectedPath = to;
  if (_shownPath == from) _shownPath = to;
  _folder.relist();
  [self noticeShow:"Renamed to " + std::string(mv::io::file_name_of(to))];
  [self publish];
}

- (void)toggleMarkCurrent {
  if (_items.empty() || _index.current() >= _items.size()) return;
  const std::string& path = _items[_index.current()].path_utf8;
  if (!_marks.insert(path).second) _marks.erase(path);
  [self marksDidChange];
  [self publish];
}
- (void)markAll {
  for (const auto& entry : _items) _marks.insert(entry.path_utf8);
  [self marksDidChange];
  [self publish];
}
- (void)unmarkAll {
  _marks.clear();
  [self marksDidChange];
  [self publish];
}

- (void)copyMarkedPickDestination:(BOOL)pick {
  [self transferMarkedPickDestination:pick move:NO];
}
- (void)moveMarkedPickDestination:(BOOL)pick {
  [self transferMarkedPickDestination:pick move:YES];
}

// docs/design/16 "Marks, copy, move": F7/F8 to the last destination, Shift+F7/F8 to
// pick one first; never overwrite an original (collision: "name (2).ext");
// same-volume move is a rename, cross-volume falls back to copy+delete
// (-[NSFileManager moveItemAtURL:toURL:error:] does this internally -- it is
// not a thin wrapper over rename(2) the way Windows' MoveFileEx needs an
// explicit COPY_ALLOWED flag for). Runs on the job pool, never the UI thread
// (CLAUDE.md rule 1: file I/O) -- background_generation, like folder_model's
// own jobs, because a copy/move a user started should finish even if they
// navigate away before it does.
- (void)transferMarkedPickDestination:(BOOL)pick move:(BOOL)move {
  if (_items.empty()) return;
  const std::vector<mv::io::dir_entry> entries = [self markedOrCurrentEntries];
  if (entries.empty()) return;
  if (move && [self refuseWriteToEntries:entries]) return;  // copying out is fine

  if (pick || !_lastDestination) {
    NSOpenPanel* panel = [NSOpenPanel openPanel];
    panel.canChooseDirectories = YES;
    panel.canChooseFiles = NO;
    panel.canCreateDirectories = YES;
    panel.allowsMultipleSelection = NO;
    panel.prompt = move ? @"Move" : @"Copy";
    if ([panel runModal] != NSModalResponseOK || panel.URL == nil) return;
    _lastDestination = panel.URL;
  }

  NSURL* destDir = _lastDestination;
  std::vector<std::string> src_paths;
  std::vector<std::string> src_names;
  src_paths.reserve(entries.size());
  src_names.reserve(entries.size());
  for (const auto& entry : entries) {
    src_paths.push_back(entry.path_utf8);
    src_names.push_back(entry.name_utf8);
  }

  // A move relocates the marked file's identity (its old path stops
  // existing); a copy leaves the original untouched. Only move needs to walk
  // succeeded paths out of `_marks` afterward -- weak, the same lifetime
  // guard -deleteMarkedToTrash's completion handler uses, since this job can
  // finish after the window (and MvLabApp) has gone away.
  MvLabApp* __weak weakSelf = self;
  _jobs.submit_at(
      mv::background_generation,
      [src_paths, src_names, destDir, move, weakSelf](const mv::job_context&) -> mv::status {
        NSFileManager* fm = [NSFileManager defaultManager];
        NSString* destPath = destDir.path;
        // To or from a share: several files at once, and each verified copy
        // with several requests in flight (io/verified_copy.h, docs/design/12
        // 2026-10-01). A card or a local disk keeps one file at a time.
        const mv::io::copy_profile profile = mv::io::batch_copy_profile(
            std::string(mv::io::parent_of(src_paths.front())), destPath.UTF8String);
        // One slot per file, each written by the one thread that copies it.
        std::vector<char> done(src_paths.size(), 0);

        mv::io::for_each_in_flight(src_paths.size(), profile.files_in_flight, [&](std::size_t i) {
          @autoreleasepool {
            // unique_name's `exists` callback is a plain fileExistsAtPath check
            // against the destination directory -- cheap, and exactly the
            // "never overwrite" rule collision_name.h was written for.
            const std::string chosen = mv::io::unique_name(
                src_names[i].c_str(), [&](std::string_view candidate) {
                  NSString* candidateName =
                      [[NSString alloc] initWithBytes:candidate.data()
                                                length:candidate.size()
                                              encoding:NSUTF8StringEncoding];
                  NSString* candidatePath = [destPath stringByAppendingPathComponent:candidateName];
                  return [fm fileExistsAtPath:candidatePath];
                });
            if (chosen.empty()) return;  // every "(n).ext" up to the cap is taken
            // docs/design/26: a Photos item copies out as its original, fetched from
            // iCloud here if this Mac does not hold it (the user asked for the file).
            std::string src_path = src_paths[i];
            if (mv::shell::photos::is_key(src_path)) {
              auto r = mv::shell::photos::resolve(src_path, true);
              if (!r) return;
              src_path = std::move(r).value().path;
            }
            NSString* chosenName = [NSString stringWithUTF8String:chosen.c_str()];
            NSURL* srcURL =
                [NSURL fileURLWithPath:[NSString stringWithUTF8String:src_path.c_str()]];
            NSURL* dstURL = [destDir URLByAppendingPathComponent:chosenName];

            NSError* error = nil;
            BOOL ok = NO;
            if (move && !MvSameVolume(srcURL, destDir)) {
              // docs/design/18: F8 across volumes deletes the source only after the
              // copy is verified (hashed while read, F_FULLFSYNC, read back
              // with F_NOCACHE, compared). -moveItemAtURL: would copy and
              // delete with no check in between.
              const std::string targets[] = {std::string(dstURL.path.UTF8String)};
              mv::io::copy_options options;
              profile.apply(options);
              const auto copied = mv::io::verified_copy(src_path, targets, options);
              ok = copied && copied->targets[0].outcome == mv::io::copy_target_outcome::verified &&
                   [fm removeItemAtURL:srcURL error:&error];
              if (copied && !ok && mv::io::copy_succeeded(copied->targets[0].outcome)) {
                // The source would not go: a move that leaves two copies is not
                // a move. Take the verified copy back and report it.
                (void)mv::io::remove_file(targets[0]);
              }
            } else {
              ok = move ? [fm moveItemAtURL:srcURL toURL:dstURL error:&error]
                        : [fm copyItemAtURL:srcURL toURL:dstURL error:&error];
            }
            done[i] = ok ? 1 : 0;
          }
        });

        std::vector<std::string> succeeded;
        NSUInteger failures = 0;
        for (std::size_t i = 0; i < src_paths.size(); ++i) {
          if (done[i]) {
            succeeded.push_back(src_paths[i]);
          } else {
            ++failures;
          }
        }

        dispatch_async(dispatch_get_main_queue(), ^{
          if (failures > 0) NSBeep();
          if (!move) return;
          MvLabApp* strongSelf = weakSelf;
          if (!strongSelf) return;
          for (const auto& path : succeeded) strongSelf->_marks.erase(path);
          [strongSelf marksDidChange];
          [strongSelf publish];
        });
        return failures == 0 ? mv::status::ok : mv::status::io;
      });
}

// docs/design/16 "Delete only ever uses the Recycle Bin [Trash]... refused, not
// deleted... there is no silent permanent delete." -recycleURLs:completionHandler:
// is documented async (it returns immediately and reports back through the
// handler), which is why this calls it directly from the confirm alert's
// main-thread continuation rather than routing through job_system the way
// copy/move's genuinely-synchronous NSFileManager calls have to.
- (void)deleteMarkedToTrash {
  if (_items.empty()) return;
  const std::vector<mv::io::dir_entry> entries = [self markedOrCurrentEntries];
  if (entries.empty()) return;
  if ([self refuseWriteToEntries:entries]) return;

  NSAlert* alert = [[NSAlert alloc] init];
  alert.messageText = entries.size() == 1
      ? [NSString stringWithFormat:@"Move “%s” to the Trash?", entries[0].name_utf8.c_str()]
      : [NSString stringWithFormat:@"Move %lu items to the Trash?", (unsigned long)entries.size()];
  alert.alertStyle = NSAlertStyleWarning;
  [alert addButtonWithTitle:@"Move to Trash"];
  [alert addButtonWithTitle:@"Cancel"];
  if ([alert runModal] != NSAlertFirstButtonReturn) return;

  NSMutableArray<NSURL*>* urls = [NSMutableArray arrayWithCapacity:entries.size()];
  for (const auto& entry : entries) {
    [urls addObject:[NSURL fileURLWithPath:[NSString stringWithUTF8String:entry.path_utf8.c_str()]]];
  }

  MvLabApp* __weak weakSelf = self;
  [[NSWorkspace sharedWorkspace]
      recycleURLs:urls
      completionHandler:^(NSDictionary<NSURL*, NSURL*>* newURLs, NSError* error) {
        dispatch_async(dispatch_get_main_queue(), ^{
          MvLabApp* strongSelf = weakSelf;
          if (!strongSelf) return;
          for (NSURL* url in newURLs) {
            const char* path = url.path.UTF8String;
            if (path) strongSelf->_marks.erase(std::string(path));
          }
          if (error) NSBeep();
          // The watcher's own FSEvents fire independently and will relist;
          // this only needs to refresh the mark count now that some may have
          // been cleared.
          [strongSelf marksDidChange];
          [strongSelf publish];
        });
      }];
}

- (void)toggleFullscreen {
  [self.window toggleFullScreen:nil];
}

- (BOOL)isSlideshowActive {
  return _slideshowActive;
}

// The timer's tick: the next item in folder order, or in the shuffled order
// once `R` turned it on (every item once per round, wrapping as browse does).
- (void)slideshowAdvance {
  if (_items.empty()) return;
  if (!_slideshowOrder.shuffled()) {
    [self navigateNext];
    return;
  }
  const auto current = static_cast<std::uint32_t>(_index.current());
  _slideshowOrder.set_count(static_cast<std::uint32_t>(_items.size()), current);
  if (const auto next = _slideshowOrder.next(current, _index.wrap())) [self selectIndex:*next];
}

- (void)armSlideshowTimer {
  [_slideshowTimer invalidate];
  _slideshowTimer = [NSTimer scheduledTimerWithTimeInterval:_slideshowIntervalSeconds
                                                      target:self
                                                    selector:@selector(slideshowAdvance)
                                                    userInfo:nil
                                                     repeats:YES];
}

- (void)startSlideshow {
  if (_slideshowActive || _items.empty()) return;
  _slideshowActive = YES;
  _slideshowPaused = NO;
  // docs/design/16: "starts from the canvas in browse (fullscreen if the window is
  // not; leaving puts it back)".
  _enteredFullscreenForSlideshow = (self.window.styleMask & NSWindowStyleMaskFullScreen) ? NO : YES;
  if (_enteredFullscreenForSlideshow) [self.window toggleFullScreen:nil];
  _slideshowOrder.start(static_cast<std::uint32_t>(_items.size()),
                        static_cast<std::uint32_t>(_index.current()),
                        static_cast<std::uint64_t>(CACurrentMediaTime() * 1000.0));
  _snap.blackout = false;
  [self armSlideshowTimer];
  [self syncKeepAwake];
}

- (void)leaveSlideshow {
  if (!_slideshowActive) return;
  _slideshowActive = NO;
  _slideshowPaused = NO;
  [_slideshowTimer invalidate];
  _slideshowTimer = nil;
  _slideshowOrder.stop();
  if (_snap.blackout) {
    _snap.blackout = false;
    [self pokeSnapshot];
  }
  if (_enteredFullscreenForSlideshow && (self.window.styleMask & NSWindowStyleMaskFullScreen)) {
    [self.window toggleFullScreen:nil];
  }
  _enteredFullscreenForSlideshow = NO;
  [self syncKeepAwake];
}

- (void)toggleSlideshowPause {
  if (!_slideshowActive) return;
  _slideshowPaused = !_slideshowPaused;
  if (_slideshowPaused) {
    [_slideshowTimer invalidate];
    _slideshowTimer = nil;
  } else {
    [self armSlideshowTimer];
  }
  [self syncKeepAwake];
}

- (void)adjustSlideshowInterval:(double)deltaSeconds {
  if (!_slideshowActive) return;
  // docs/design/16's step ladder: 1/2/3/4/5/7/10/15/20/30/60s. +/- move one rung,
  // not a fixed number of seconds -- deltaSeconds here is +1/-1, a rung
  // index delta, despite the "seconds" name matching the public selector's
  // intent (adjust the interval); the ladder itself is the actual unit.
  static const double kLadder[] = {1, 2, 3, 4, 5, 7, 10, 15, 20, 30, 60};
  constexpr int kLadderCount = static_cast<int>(sizeof(kLadder) / sizeof(kLadder[0]));
  int rung = 0;
  double best = 1e9;
  for (int i = 0; i < kLadderCount; ++i) {
    const double d = std::fabs(kLadder[i] - _slideshowIntervalSeconds);
    if (d < best) {
      best = d;
      rung = i;
    }
  }
  rung = std::clamp(rung + (deltaSeconds > 0 ? 1 : -1), 0, kLadderCount - 1);
  _slideshowIntervalSeconds = kLadder[rung];
  if (!_slideshowPaused) [self armSlideshowTimer];
}

// Filmstrip/gallery bridge (mv_chrome_bridge.h), folded-in PR 4 -- docs/design/12
// 2026-09-17. `itemCount`/`currentIndex`/`itemNameAtIndex:into:size:` mirror
// the same `_items`/`_index` state -selectIndex: and the navigate* methods
// already use; nothing new is computed here, just exposed across the bridge.
- (NSInteger)itemCount {
  return static_cast<NSInteger>(_items.size());
}
- (NSInteger)currentIndex {
  return _items.empty() ? -1 : static_cast<NSInteger>(_index.current());
}
- (BOOL)itemNameAtIndex:(NSInteger)index into:(char*)buf size:(int32_t)size {
  if (index < 0 || static_cast<std::size_t>(index) >= _items.size()) return NO;
  const std::string& name = [self displayNameAt:static_cast<std::size_t>(index)];
  const std::size_t n = std::min(name.size(), static_cast<std::size_t>(size) - 1);
  std::memcpy(buf, name.data(), n);
  buf[n] = '\0';
  return YES;
}

// folder_model::request_thumb's callback runs on the pool thread that
// produced the result (folder_model_mac.h's contract) -- this hops to the
// main thread before calling the Swift-registered callback, so
// mv_chrome_bridge.h's promise ("always the main thread") holds regardless
// of which job_system worker actually decoded the thumbnail.
- (void)requestThumbAtIndex:(NSInteger)index {
  if (index < 0 || static_cast<std::size_t>(index) >= _items.size()) return;
  const mv::io::dir_entry& entry = _items[static_cast<std::size_t>(index)];
  // Captured by value (not read from `_items`/index again when the job
  // completes): if a relist reorders `_items` or another folder opens between
  // the request and the callback firing, `key` still names the file (and the
  // bytes) this thumbnail is actually for, which is exactly why
  // mv_chrome_bridge.h keys the callback by it rather than by the index this
  // request started at, or by a name another folder can repeat (issue #177).
  const std::string key = [self thumbKeyAtIndex:index];
  // Milestone H: a result list's clip tile shows its matched moment.
  const auto at = static_cast<std::size_t>(index);
  const std::int64_t moment = _listOpen && at < _moments.size() ? _moments[at] : -1;
  _folder.request_thumb(entry.path_utf8, entry.mtime_unix, entry.size,
                        [key](std::string /*path_utf8*/, std::string thumb_path) {
                          dispatch_async(dispatch_get_main_queue(), ^{
                            if (!g_thumb_ready_callback) return;
                            g_thumb_ready_callback(key.c_str(), thumb_path.empty()
                                                                      ? nullptr
                                                                      : thumb_path.c_str());
                          });
                        },
                        moment);
}

- (BOOL)filmstripVisible {
  return _filmstripVisible && !_items.empty();
}
- (BOOL)galleryVisible {
  return _galleryVisible;
}
- (void)setGalleryVisible:(BOOL)visible {
  const BOOL changed = _galleryVisible != visible;
  if (!visible) [self clearGalleryRange];  // #413: the range belongs to the grid
  _galleryVisible = visible;
  self.galleryHost.hidden = !visible;
  [self applyPageSidebarLayout];  // issue #429: not under the grid
  [self syncToolBar];  // S3: the tool bar is not over the grid
  [self textSync];
  [self layoutAIBadge];  // #345
  if (changed && visible) [self followGalleryFilter];
  // File search belongs to the grid: it closes with it, filter and all.
  if (changed && !visible) [MVChromeHost closeFileSearch];
  // Closed with the search field focused: the keyboard goes back to the canvas.
  if (!visible && self.window.firstResponder != self.view) {
    NSResponder* first = self.window.firstResponder;
    if ([first isKindOfClass:[NSView class]] && [(NSView*)first isDescendantOf:self.galleryHost]) {
      [self.window makeFirstResponder:self.view];
    }
  }
  // Issue #44: nothing plays under the grid. The lab pauses a playing clip,
  // keeps one selected meanwhile on its first frame, and resumes only the clip
  // that was playing when the grid opened (player/playback_hold.h).
  if (_snap.video_hold != static_cast<bool>(visible)) {
    _snap.video_hold = visible;
    _snap.video_hold_resume = true;
    [self pokeSnapshot];
  }
}
- (void)toggleFilmstrip {
  // Nothing open: nothing to toggle, and no preference silently flipped for
  // the next folder by a key that looked like it did nothing (Windows'
  // toggle_filmstrip_setting makes the same call).
  if (_items.empty()) return;
  [self stripHintToggled];
  [self setFilmstripVisible:!_filmstripVisible];
}
- (void)setFilmstripVisible:(BOOL)visible {
  _filmstripVisible = visible;
  [self applyFilmstripLayout];
}
// Re-run whenever the wish or the item list changes; a no-op when what is on
// screen already matches.
- (void)applyFilmstripLayout {
  const BOOL shown = [self filmstripVisible];
  // The page sidebar takes the filmstrip's role for a document (issue #429).
  [self applyPageSidebarLayout];
  if (self.filmstripHost.hidden == !shown) return;
  self.filmstripHost.hidden = !shown;
  self.transportBottom.constant = -(shown ? kFilmstripHeightPoints + 10.0 : 10.0);
  self.toolBarBottom.constant = -(shown ? kFilmstripHeightPoints + 8.0 : 8.0);  // S3
  const CGFloat pane_bottom = -(shown ? kFilmstripHeightPoints : 0.0);
  self.treeBottom.constant = pane_bottom;
  self.resumeBottom.constant = pane_bottom - 8.0;
  [self syncColumnBottom];
  [self layoutHintNotice];
  [self layoutAIBadge];  // #345
  // chrome_bottom_px must reflect the toggle immediately (canvas fit/pan
  // math reads it via present_lab_mac.mm's usable_window_h()) -- -syncSize
  // already recomputes it from -filmstripVisible and republishes, the same
  // "single source of truth" shape chrome_height_px already has. A refit:
  // the window did not change (refit_seq).
  [self.view syncChrome];
}
- (void)toggleGallery {
  [self setGalleryVisible:!_galleryVisible];
}
// File search (docs/design/16 "File search"): the grid comes up if it is not, and the
// field above it takes the keyboard. NO with nothing listed to search.
- (BOOL)openFileSearch {
  if (_items.empty() && _subdirs.empty()) return NO;
  if (!_galleryVisible) [self setGalleryVisible:YES];
  [self.window makeFirstResponder:self.galleryHost];
  [MVChromeHost openFileSearch];
  return YES;
}
- (uint64_t)listingGeneration {
  return _listingGeneration;
}
- (BOOL)currentItemIsVideo {
  if (_items.empty()) return NO;
  const std::size_t i = _index.current();
  return i < _items.size() && mv::shell::is_video_name(_items[i].name_utf8);
}
- (BOOL)currentItemIsAudio {
  if (_items.empty()) return NO;
  const std::size_t i = _index.current();
  return i < _items.size() && mv::shell::is_audio_name(_items[i].name_utf8);
}
- (BOOL)currentItemIsDocument {
  if (_items.empty()) return NO;
  const std::size_t i = _index.current();
  return i < _items.size() && mv::io::is_document_name(_items[i].name_utf8);
}
// "Open in <app>" and Return on a PDF or DOCX (docs/design/20): the file goes to
// another app; MediaViewer never edits a document. `app` nil is the file's
// default app, or the first other one when MediaViewer is the default. The Launch
// Services lookups and the open run off the main thread (CLAUDE.md rule 1).
- (void)openDocumentInApp:(NSURL*)app {
  if (![self currentItemIsDocument]) return;
  const std::string path = [self currentItemPath];
  if (path.empty()) return;
  NSURL* file = [NSURL fileURLWithPath:[NSString stringWithUTF8String:path.c_str()] isDirectory:NO];
  // Every MediaViewer build (release, .dev, a test copy) shares this id prefix.
  NSString* const ours = @"io.github.longtimeno-c.mediaviewer";
  BOOL (^isOurs)(NSURL*) = ^BOOL(NSURL* candidate) {
    NSString* bid = [NSBundle bundleWithURL:candidate].bundleIdentifier;
    return bid != nil && [bid hasPrefix:ours];
  };
  dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
    NSURL* with = app;
    NSWorkspace* ws = NSWorkspace.sharedWorkspace;
    if (with == nil) {
      with = [ws URLForApplicationToOpenURL:file];
      if (with == nil || isOurs(with)) {
        with = nil;
        for (NSURL* candidate in [ws URLsForApplicationsToOpenURL:file]) {
          if (!isOurs(candidate)) {
            with = candidate;
            break;
          }
        }
      }
    }
    if (with == nil) {
      dispatch_async(dispatch_get_main_queue(), ^{ NSBeep(); });
      return;
    }
    [ws openURLs:@[ file ]
        withApplicationAtURL:with
               configuration:[NSWorkspaceOpenConfiguration configuration]
           completionHandler:^(NSRunningApplication*, NSError* error) {
             if (error) dispatch_async(dispatch_get_main_queue(), ^{ NSBeep(); });
           }];
  });
}
- (BOOL)itemIsVideoAtIndex:(NSInteger)index {
  return index >= 0 && static_cast<std::size_t>(index) < _items.size() &&
         mv::shell::is_video_name(_items[static_cast<std::size_t>(index)].name_utf8);
}
- (uint64_t)marksGeneration {
  return _marksGeneration;
}
- (void)setGalleryRangeIndices:(const int32_t*)indices count:(int32_t)count {
  std::vector<std::string> range;
  range.reserve(static_cast<std::size_t>(count));
  for (int32_t i = 0; i < count; ++i) {
    const int32_t at = indices[i];
    if (at >= 0 && static_cast<std::size_t>(at) < _items.size()) {
      range.push_back(_items[static_cast<std::size_t>(at)].path_utf8);
    }
  }
  _galleryRange = std::move(range);
  ++_galleryRangeGeneration;
}
- (void)clearGalleryRange {
  if (_galleryRange.empty()) return;
  _galleryRange.clear();
  ++_galleryRangeGeneration;
}
- (uint64_t)galleryRangeGeneration {
  return _galleryRangeGeneration;
}
- (NSInteger)galleryRangeCount {
  return static_cast<NSInteger>(_galleryRange.size());
}
- (uint64_t)thumbGeneration {
  return _thumbGeneration;
}
- (NSInteger)markedCount {
  return static_cast<NSInteger>(_marks.size());
}
- (BOOL)isIndexMarked:(NSInteger)index {
  if (index < 0 || static_cast<std::size_t>(index) >= _items.size()) return NO;
  return _marks.count(_items[static_cast<std::size_t>(index)].path_utf8) != 0;
}
// Every place that changes `_marks` goes through this rather than calling
// -updateMarkSnapshot directly, so the chrome's marked-set cache can't go stale.
- (void)marksDidChange {
  ++_marksGeneration;
  [self updateMarkSnapshot];
}
- (BOOL)folderStrip {
  return !_subdirs.empty() && !_items.empty();
}
// File search (2026-09-28): whether its name filter decides what the
// gallery's keys move over. Only while the grid is up and only for the listing
// it was made from (a relist waits for Swift's next push, ≤ 150 ms).
- (BOOL)galleryFiltered {
  return _galleryVisible && _galleryFilterOn && _galleryFilterGeneration == _listingGeneration;
}
// Grid positions. Unfiltered, a position is the index itself; filtered, it is
// the place among the tiles the filter shows.
- (NSInteger)galleryItemCount {
  return static_cast<NSInteger>([self galleryFiltered] ? _galleryFilterItems.size() : _items.size());
}
- (NSInteger)galleryFolderCount {
  return static_cast<NSInteger>([self galleryFiltered] ? _galleryFilterFolders.size() : _subdirs.size());
}
- (std::size_t)galleryItemAt:(NSInteger)position {
  return [self galleryFiltered] ? _galleryFilterItems[static_cast<std::size_t>(position)]
                                : static_cast<std::size_t>(position);
}
- (NSInteger)galleryFolderAt:(NSInteger)position {
  return [self galleryFiltered] ? _galleryFilterFolders[static_cast<std::size_t>(position)] : position;
}
// -1 when the selection is not among the tiles shown.
- (NSInteger)galleryItemPosition {
  const NSInteger cur = [self currentIndex];
  if (![self galleryFiltered] || cur < 0) return cur;
  const auto& v = _galleryFilterItems;
  const auto it = std::find(v.begin(), v.end(), static_cast<std::size_t>(cur));
  return it == v.end() ? -1 : static_cast<NSInteger>(it - v.begin());
}
- (NSInteger)galleryFolderPosition {
  if (_folderCursor < 0 || ![self galleryFiltered]) return _folderCursor;
  const auto& f = _galleryFilterFolders;
  const auto it = std::find(f.begin(), f.end(), _folderCursor);
  return it == f.end() ? -1 : static_cast<NSInteger>(it - f.begin());
}

- (void)galleryMoveRows:(NSInteger)rows {
  const NSInteger cols = std::max<NSInteger>(1, g_gallery_columns);
  const NSInteger folders = [self galleryFolderCount];
  const NSInteger count = [self galleryItemCount];
  NSInteger fpos = [self galleryFolderPosition];
  if (_folderCursor >= 0 && fpos < 0) {
    // On a folder tile the filter hides (it only just changed): start over.
    _folderCursor = -1;
    if (folders > 0 && count == 0) fpos = 0;
  }
  // Mixed folder: the tiles are one horizontal row above the photos, not a
  // block in the same grid. Down leaves that row for the first photo row.
  if ([self folderStrip]) {
    if (fpos >= 0) {
      if (rows < 0 || count == 0) return;
      const NSInteger col = std::min(fpos, cols - 1);
      _folderCursor = -1;
      [self selectIndex:[self galleryItemAt:std::min(col, count - 1)]];
      return;
    }
    const NSInteger cur = std::max<NSInteger>(0, [self galleryItemPosition]);
    if (rows < 0 && cur < cols) {
      if (folders > 0) _folderCursor = [self galleryFolderAt:std::min(cur, folders - 1)];
      return;
    }
  }
  // No images to move over (a folder of folders): the tiles are all there is.
  if (count == 0) {
    if (folders == 0) return;
    if (fpos < 0) fpos = 0;
  }
  if (fpos >= 0) {
    NSInteger target = fpos + rows * cols;
    if (target < 0) {
      _folderCursor = [self galleryFolderAt:fpos];
      return;  // already on the first row of tiles
    }
    if (target >= folders) {
      if (fpos / cols < (folders - 1) / cols) {
        target = folders - 1;  // short last row: land on its final tile
      } else {
        // Down from the last row of tiles: onto the images, same column.
        if (count == 0) {
          _folderCursor = [self galleryFolderAt:fpos];
          return;
        }
        const NSInteger col = fpos % cols;
        _folderCursor = -1;
        [self selectIndex:[self galleryItemAt:std::min(col, count - 1)]];
        return;
      }
    }
    _folderCursor = [self galleryFolderAt:target];
    return;
  }
  const NSInteger cur = [self galleryItemPosition];
  if (cur < 0) {
    // The selection is filtered out: the first tile shown.
    if (count > 0) [self selectIndex:[self galleryItemAt:0]];
    return;
  }
  NSInteger target = cur + rows * cols;
  if (target < 0) {
    // Up from the first row of images: onto the folder tiles, same column.
    if (folders > 0 && rows < 0) {
      const NSInteger col = cur % cols;
      _folderCursor = [self galleryFolderAt:std::min<NSInteger>(folders - 1, ((folders - 1) / cols) * cols + col)];
    }
    return;
  }
  if (target >= count) {
    // Down from a row above the last: land on the final item rather than
    // doing nothing (a short last row has no cell directly below).
    if (cur / cols >= (count - 1) / cols) return;
    target = count - 1;
  }
  [self selectIndex:[self galleryItemAt:target]];
}

// Left / Right (and A / D) while the gallery's cursor is on a folder tile.
// Returns NO when the keys should keep walking images.
- (BOOL)folderCursorStep:(NSInteger)delta {
  const NSInteger folders = [self galleryFolderCount];
  if (!_galleryVisible || folders == 0) return NO;
  NSInteger pos = [self galleryFolderPosition];
  if (pos < 0) {
    if ([self galleryItemCount] > 0) return NO;
    pos = 0;
  }
  pos = std::clamp<NSInteger>(pos + delta, 0, folders - 1);
  _folderCursor = [self galleryFolderAt:pos];
  return YES;
}

// Left / Right among the images while the name filter is on: the tiles it
// shows, in order, stopping at either end. NO when unfiltered (the folder's
// own walk applies).
- (BOOL)galleryFilteredStep:(NSInteger)delta {
  if (![self galleryFiltered]) return NO;
  const NSInteger count = [self galleryItemCount];
  if (count == 0) return YES;
  const NSInteger pos = [self galleryItemPosition];
  const NSInteger target = pos < 0 ? 0 : std::clamp<NSInteger>(pos + delta, 0, count - 1);
  if (target != pos) [self selectIndex:[self galleryItemAt:target]];
  return YES;
}

- (void)setGalleryFilter:(uint64_t)generation
                  active:(BOOL)active
                   items:(const int32_t*)items
                   count:(int32_t)itemCount
                 folders:(const int32_t*)folders
                   count:(int32_t)folderCount {
  _galleryFilterOn = active;
  _galleryFilterGeneration = generation;
  _galleryFilterItems.clear();
  _galleryFilterFolders.clear();
  if (!active) return;
  const auto n_items = static_cast<std::size_t>(_items.size());
  const auto n_folders = static_cast<NSInteger>(_subdirs.size());
  if (items) {
    _galleryFilterItems.reserve(static_cast<std::size_t>(std::max(0, itemCount)));
    for (int32_t i = 0; i < itemCount; ++i) {
      if (items[i] >= 0 && static_cast<std::size_t>(items[i]) < n_items) {
        _galleryFilterItems.push_back(static_cast<std::size_t>(items[i]));
      }
    }
  }
  if (folders) {
    for (int32_t i = 0; i < folderCount; ++i) {
      if (folders[i] >= 0 && folders[i] < n_folders) _galleryFilterFolders.push_back(folders[i]);
    }
  }
  [self followGalleryFilter];
}

// The selection follows the filter: a folder tile or an image that is no
// longer shown gives way to the first one that is (docs/design/17). Also when the
// grid comes back after the viewer walked onto a tile the filter hides.
- (void)followGalleryFilter {
  if (![self galleryFiltered]) return;
  if (_folderCursor >= 0 && [self galleryFolderPosition] < 0) {
    _folderCursor = !_galleryFilterFolders.empty() && _galleryFilterItems.empty()
                        ? _galleryFilterFolders.front()
                        : -1;
  }
  if (_folderCursor < 0 && !_galleryFilterItems.empty() && [self galleryItemPosition] < 0) {
    [self selectIndex:_galleryFilterItems.front()];
  }
}

- (NSInteger)folderCursor {
  return _folderCursor;
}

- (NSInteger)subfolderCount {
  return static_cast<NSInteger>(_subdirs.size());
}

static BOOL MvCopyUtf8(const std::string& text, char* buf, int32_t size) {
  const std::size_t n = std::min(text.size(), static_cast<std::size_t>(size) - 1);
  std::memcpy(buf, text.data(), n);
  buf[n] = '\0';
  return YES;
}

- (BOOL)subfolderPathAtIndex:(NSInteger)index into:(char*)buf size:(int32_t)size {
  if (index < 0 || static_cast<std::size_t>(index) >= _subdirs.size()) return NO;
  return MvCopyUtf8(_subdirs[static_cast<std::size_t>(index)].path_utf8, buf, size);
}

- (void)openSubfolderAtIndex:(NSInteger)index {
  if (index < 0 || static_cast<std::size_t>(index) >= _subdirs.size()) return;
  const std::string path = _subdirs[static_cast<std::size_t>(index)].path_utf8;
  [self openPath:path.c_str() navigation:YES];
}

// Same shape as -requestThumbAtIndex: (pool thread -> main-thread callback,
// keyed by path so a relist that reorders tiles cannot misfile a result). The
// cover's thumbnail rides the ordinary thumb pipeline, so it is cached like
// any other and is a poster frame when the folder's first item is a clip.
- (void)requestFolderSummaryAtIndex:(NSInteger)index {
  if (index < 0 || static_cast<std::size_t>(index) >= _subdirs.size()) return;
  const std::string dir = _subdirs[static_cast<std::size_t>(index)].path_utf8;
  mv::shell::folder_model* folder = &_folder;
  auto deliver = [](std::string dir_path, bool ok, std::uint32_t media, std::uint32_t subs,
                    int32_t flags, std::string thumb) {
    dispatch_async(dispatch_get_main_queue(), ^{
      if (!g_folder_summary_callback) return;
      g_folder_summary_callback(dir_path.c_str(), ok, static_cast<int32_t>(media),
                                static_cast<int32_t>(subs), flags,
                                thumb.empty() ? nullptr : thumb.c_str());
    });
  };
  _folder.request_summary(
      dir, [folder, deliver](std::string dir_path, bool ok, mv::io::folder_summary summary) {
        if (!ok) {
          deliver(dir_path, false, 0, 0, 0, {});
          return;
        }
        int32_t flags = 0;
        if (summary.photos_inside) flags |= 1;
        if (summary.search_incomplete) flags |= 2;
        if (!summary.has_cover) {
          deliver(dir_path, true, summary.media_count, summary.subdir_count, flags, {});
          return;
        }
        const std::uint32_t media = summary.media_count;
        const std::uint32_t subs = summary.subdir_count;
        folder->request_thumb(summary.cover.path_utf8, summary.cover.mtime_unix,
                              summary.cover.size,
                              [deliver, dir_path, media, subs, flags](std::string, std::string thumb) {
                                deliver(dir_path, true, media, subs, flags, std::move(thumb));
                              });
      });
}

- (NSInteger)crumbCount {
  return static_cast<NSInteger>(_browsePath.crumbs().size());
}

- (BOOL)crumbPathAtIndex:(NSInteger)index into:(char*)buf size:(int32_t)size {
  const auto crumbs = _browsePath.crumbs();
  if (index < 0 || static_cast<std::size_t>(index) >= crumbs.size()) return NO;
  return MvCopyUtf8(crumbs[static_cast<std::size_t>(index)].path, buf, size);
}

- (void)openCrumbAtIndex:(NSInteger)index {
  const auto crumbs = _browsePath.crumbs();
  if (index < 0 || static_cast<std::size_t>(index) >= crumbs.size()) return;
  const std::string path = crumbs[static_cast<std::size_t>(index)].path;
  if (path == _browsePath.current()) return;
  [self openPath:path.c_str() navigation:YES];
}

- (BOOL)canGoUp {
  return !_browsePath.parent().empty();
}

- (CGFloat)chromeBarHeight {
  // The folder trail lives inside the bar, beside `?`; opening a folder does not grow it.
  return kChromeBarHeightPoints;
}

- (void)updateChromeBarHeight {
  if (self.commandBarHeight) self.commandBarHeight.constant = [self chromeBarHeight];
  if (self.view) [self.view syncChrome];
}

- (void)refreshSiblings {
  const std::string parent = _browsePath.parent();
  const std::string here = _currentDir;
  const std::uint64_t gen = ++_siblingGeneration;
  if (parent.empty() || here.empty()) return;
  __weak MvLabApp* weakSelf = self;
  _jobs.submit_at(mv::background_generation,
                  [parent, here, gen, weakSelf](const mv::job_context&) -> mv::status {
                    auto subs = mv::io::list_subfolders(parent);
                    const bool ok = static_cast<bool>(subs);
                    std::vector<std::string> paths;
                    NSInteger index = -1;
                    if (ok) {
                      paths.reserve(subs.value().size());
                      for (std::size_t i = 0; i < subs.value().size(); ++i) {
                        paths.push_back(subs.value()[i].path_utf8);
                        if (subs.value()[i].path_utf8 == here) index = static_cast<NSInteger>(i);
                      }
                    }
                    const auto error = ok ? mv::status::ok : subs.error();
                    dispatch_async(dispatch_get_main_queue(), ^{
                      MvLabApp* app = weakSelf;
                      if (!app || gen != app->_siblingGeneration || here != app->_currentDir || !ok) return;
                      app->_siblings = paths;
                      app->_siblingIndex = index;
                    });
                    return error;
                  });
}

- (BOOL)navigateSibling:(NSInteger)delta {
  if (_siblingIndex < 0 || _siblings.empty()) return NO;
  const NSInteger next = _siblingIndex + delta;
  if (next < 0 || next >= static_cast<NSInteger>(_siblings.size())) return NO;
  const std::string path = _siblings[static_cast<std::size_t>(next)];
  _siblingIndex = next;
  return [self openPath:path.c_str() navigation:YES];
}

- (BOOL)folderFindLive {
  if (!_folderFind) return NO;
  if (CFAbsoluteTimeGetCurrent() - _folderFindTick > 1.2) {
    _folderFind = NO;
    _folderQuery.clear();
    return NO;
  }
  return YES;
}

- (void)touchFolderFind {
  _folderFind = YES;
  _folderFindTick = CFAbsoluteTimeGetCurrent();
}

- (void)moveFolderCursorToQuery {
  if (_folderQuery.empty() || _subdirs.empty()) return;
  NSString* query = [NSString stringWithUTF8String:_folderQuery.c_str()];
  if (query.length == 0) return;
  for (std::size_t i = 0; i < _subdirs.size(); ++i) {
    NSString* name = [NSString stringWithUTF8String:_subdirs[i].name_utf8.c_str()];
    if ([name rangeOfString:query options:NSAnchoredSearch | NSCaseInsensitiveSearch].location == 0) {
      _folderCursor = static_cast<NSInteger>(i);
      [self setGalleryVisible:YES];
      return;
    }
  }
}

- (BOOL)folderQueryInto:(char*)buf size:(int32_t)size {
  if (![self folderFindLive] || !buf || size <= 0) return NO;
  return MvCopyUtf8(_folderQuery, buf, size);
}

- (BOOL)handleFolderFind:(NSEvent*)event key:(mv::shell::key)k mods:(std::uint8_t)mods {
  if (![self folderFindLive]) return NO;
  if (event.type != NSEventTypeKeyDown) return YES;
  using mv::shell::key;
  if (k == key::escape && mods == mv::shell::mod_none) {
    _folderFind = NO;
    _folderQuery.clear();
    return YES;
  }
  if (k == key::backspace && mods == mv::shell::mod_none) {
    if (!_folderQuery.empty()) {
      // Drop one UTF-8 code point, not one byte.
      while (!_folderQuery.empty() &&
             (static_cast<unsigned char>(_folderQuery.back()) & 0xC0) == 0x80) {
        _folderQuery.pop_back();
      }
      if (!_folderQuery.empty()) _folderQuery.pop_back();
    }
    [self touchFolderFind];
    [self moveFolderCursorToQuery];
    return YES;
  }
  if (k == key::enter && mods == mv::shell::mod_none) {
    _folderFind = NO;
    _folderQuery.clear();
    if (_folderCursor >= 0) [self openSubfolderAtIndex:_folderCursor];
    return YES;
  }
  if (mods != mv::shell::mod_none) {
    _folderFind = NO;
    _folderQuery.clear();
    return NO;
  }
  NSString* chars = event.charactersIgnoringModifiers;
  if (chars.length != 1) {
    _folderFind = NO;
    _folderQuery.clear();
    return NO;
  }
  unichar c = [chars characterAtIndex:0];
  if (c < 0x20 || c == 0x7F || c == '/') {
    if (c == '/') return YES;
    _folderFind = NO;
    _folderQuery.clear();
    return NO;
  }
  NSString* next = [NSString stringWithUTF8String:_folderQuery.c_str()];
  next = [next stringByAppendingString:chars];
  _folderQuery = next.UTF8String;
  [self touchFolderFind];
  [self moveFolderCursorToQuery];
  return YES;
}

- (BOOL)navigateUp {
  const std::string parent = _browsePath.parent();
  if (parent.empty()) return NO;
  return [self openPath:parent.c_str() navigation:YES];
}
- (void)adjustGalleryCellSize:(NSInteger)direction {
  [MVChromeHost adjustGalleryCellSize:direction];
}
- (BOOL)helpVisible {
  return _helpVisible;
}
- (void)setHelpVisible:(BOOL)visible {
  _helpVisible = visible;
  if (visible) {
    // `?` lists the bindings of the mode underneath (docs/design/16), as the
    // Windows flyout does: not the popup's own state.
    mv::shell::view_state under = [self currentViewState];
    under.popup_open = false;
    const mv::shell::mode under_mode = mv::shell::resolve_mode(under);
    auto modes = static_cast<std::int32_t>(mv::shell::mask_of(under_mode));
    // Trim and skim layer over video (key_router.cpp), so `?` lists both, as on Windows.
    if (under_mode == mv::shell::mode::trim || under_mode == mv::shell::mode::skim) {
      modes |= mv::shell::kVideo;
    }
    // S3: a tool layers over browse.
    if (under_mode == mv::shell::mode::tool) modes |= mv::shell::kBrowse;
    [MVChromeHost reloadHelpWithModes:modes];
  }
  self.helpHost.hidden = !visible;
}
- (void)toggleHelp {
  [self setHelpVisible:!_helpVisible];
}

// ---- Main menu ------------------------------------------------------------
// A real menu bar (it had none: the bar showed only the process name). Every
// item routes to an action the key router already performs, so the menu and
// the keys cannot disagree. The router owns the keys: only a few ⌘ chords are
// key equivalents (a bare letter there would run twice), and `?` lists the rest.
// The item tags (MvMenuCmd) are in mv_chrome_bridge.h, shared with the
// command bar's buttons (CommandBarView.swift).
static_assert(kMenuShowPurple - kMenuShowAll + 1 == mv::io::kKindFilterCount);
static_assert(kMenuShowPicks - kMenuShowAll == mv::io::kFirstCullFilter);

// Issue #182: the table row behind a menu item, for its mode mask. None for
// the Sort items (no row) and the Edit menu, which validateMenuItem: gates by
// the edit subject.
static mv::shell::command_id MvMenuCommand(NSInteger cmd) {
  using enum mv::shell::command_id;
  switch (static_cast<MvMenuCmd>(cmd)) {
    case kMenuOpen: return open;
    case kMenuOpenFolder: case kMenuOpenPhotos: return open_folder;
    case kMenuTrash: return delete_to_recycle_bin;
    case kMenuCopyTo: return copy_to_pick;
    case kMenuMoveTo: return move_to_pick;
    case kMenuMark: return toggle_mark;
    case kMenuFit: return fit;
    case kMenuOneToOne: return one_to_one;
    case kMenuFilmstrip: return toggle_filmstrip;
    case kMenuPageSidebar: return toggle_page_sidebar;
    case kMenuPaneWider: return pane_wider;
    case kMenuPaneNarrower: return pane_narrower;
    case kMenuAutoEnhance: return auto_enhance;
    case kMenuToolBrush: return tool_brush;
    case kMenuToolRedEye: return tool_red_eye;
    case kMenuToolExtend: return tool_extend;
    case kMenuToolFaces: return tool_faces;
    case kMenuGallery: return toggle_gallery;
    case kMenuFullscreen: return fullscreen;
    case kMenuSlideshow: return slideshow_start;
    case kMenuNext: return next;
    case kMenuPrev: return prev;
    case kMenuFirst: return first;
    case kMenuLast: return last;
    case kMenuHelp: return help;
    case kMenuSettings: return open_settings;
    case kMenuOverlay: return overlay;
    case kMenuReveal: return reveal_in_explorer;
    case kMenuMetadata: return metadata_pane;
    case kMenuFolderTree: return folder_tree;
    case kMenuShare: return share;
    case kMenuCopyPath: return copy_path;
    case kMenuCopyEdited: return copy_flattened;
    case kMenuPrint: return print;
    case kMenuNewWindow: return new_window;
    case kMenuRename: return rename_file;
    default: return none;
  }
}

// Issue #182: the menu items whose key equivalent is a table row. Their chord
// is read from the live table (syncMenuKeyEquivalents), never fixed here, so a
// remap in Settings moves the menu with the router.
static mv::shell::command_id MvMenuChordCommand(NSMenuItem* item) {
  using enum mv::shell::command_id;
  if (item.action == @selector(performClose:)) return close_window;
  if (item.action != @selector(menuAction:)) return none;
  switch (static_cast<MvMenuCmd>(item.tag)) {
    case kMenuSettings: return open_settings;
    case kMenuNewWindow: return new_window;
    case kMenuOpen: return open;
    case kMenuFolderTree: return folder_tree;
    case kMenuPrint: return print;
    default: return none;
  }
}

// The key equivalent AppKit matches for a table key, or nil for one a menu
// does not carry (the router keeps it). Delete is ⌫, as Move to Trash shows it.
static NSString* MvKeyEquivalent(mv::shell::key k) {
  using mv::shell::key;
  const auto v = static_cast<std::uint16_t>(k);
  if (v >= 'A' && v <= 'Z') return [NSString stringWithFormat:@"%c", static_cast<char>(v - 'A' + 'a')];
  if (v >= 0x21 && v <= 0x7E) return [NSString stringWithFormat:@"%c", static_cast<char>(v)];
  unichar c = 0;
  if (k >= key::f1 && k <= key::f12) {
    c = static_cast<unichar>(NSF1FunctionKey + (v - static_cast<std::uint16_t>(key::f1)));
  } else {
    switch (k) {
      case key::space: c = ' '; break;
      case key::enter: c = '\r'; break;
      case key::del: c = NSBackspaceCharacter; break;
      case key::home: c = NSHomeFunctionKey; break;
      case key::end: c = NSEndFunctionKey; break;
      case key::page_up: c = NSPageUpFunctionKey; break;
      case key::page_down: c = NSPageDownFunctionKey; break;
      case key::left: c = NSLeftArrowFunctionKey; break;
      case key::right: c = NSRightArrowFunctionKey; break;
      case key::up: c = NSUpArrowFunctionKey; break;
      case key::down: c = NSDownArrowFunctionKey; break;
      default: return nil;
    }
  }
  return [NSString stringWithFormat:@"%C", c];
}

static NSEventModifierFlags MvModifierMask(std::uint8_t mods) {
  NSEventModifierFlags mask = 0;
  if (mods & mv::shell::mod_ctrl) mask |= NSEventModifierFlagCommand;
  if (mods & mv::shell::mod_shift) mask |= NSEventModifierFlagShift;
  if (mods & mv::shell::mod_alt) mask |= NSEventModifierFlagOption;
  return mask;
}

// MvKeyFromEvent's answer for a menu item's own key equivalent, or none. Only
// a plain Command chord counts: AppKit also injects items such as Start
// Dictation (fn D), Emoji & Symbols (fn E) and the window tiling items
// (fn Control F, C, ...), which a plain key or a Command chord never fires, so
// counting them would refuse E, D or Cmd+F in Settings for no reason.
static mv::shell::key MvKeyOfEquivalent(NSMenuItem* item, std::uint8_t* mods) {
  NSString* eq = item.keyEquivalent;
  if (eq.length != 1) return mv::shell::key::none;
  const NSEventModifierFlags flags = item.keyEquivalentModifierMask;
  if ((flags & NSEventModifierFlagCommand) == 0) return mv::shell::key::none;
  if (flags & (NSEventModifierFlagControl | NSEventModifierFlagFunction)) return mv::shell::key::none;
  std::uint8_t m = mv::shell::mod_ctrl;
  if (flags & NSEventModifierFlagShift) m |= mv::shell::mod_shift;
  if (flags & NSEventModifierFlagOption) m |= mv::shell::mod_alt;
  *mods = m;
  const unichar c = [eq characterAtIndex:0];
  if (c == NSBackspaceCharacter) return mv::shell::key::del;
  if (c >= 0x21 && c <= 0x7E) return mv::shell::char_key(static_cast<char>(c));
  return mv::shell::key::none;
}

// Issue #182: a chord a fixed menu item answers (⌘H Hide, ⌘Q Quit, ⌘M
// Minimize, ⌘⌫ Move to Trash) reaches the menu before keyDown:, so a row
// given it would never run. Settings refuses it; the chord items are skipped,
// they follow the table.
static BOOL MvMenuOwnsChord(NSMenu* menu, mv::shell::key k, std::uint8_t mods) {
  if (k == mv::shell::key::none) return NO;
  for (NSMenuItem* item in menu.itemArray) {
    if (item.submenu != nil && MvMenuOwnsChord(item.submenu, k, mods)) return YES;
    if (MvMenuChordCommand(item) != mv::shell::command_id::none) continue;
    std::uint8_t m = 0;
    if (MvKeyOfEquivalent(item, &m) == k && m == mods) return YES;
  }
  return NO;
}

static void MvSyncKeyEquivalents(NSMenu* menu, NSMenu* bar) {
  for (NSMenuItem* item in menu.itemArray) {
    if (item.submenu != nil) MvSyncKeyEquivalents(item.submenu, bar);
    const mv::shell::command_id command = MvMenuChordCommand(item);
    if (command == mv::shell::command_id::none) continue;
    const mv::shell::binding* chord = mv::shell::menu_chord(command);
    NSString* eq = chord ? MvKeyEquivalent(chord->k) : nil;
    if (eq != nil && MvMenuOwnsChord(bar, chord->k, chord->mods)) eq = nil;
    item.keyEquivalent = eq ?: @"";
    item.keyEquivalentModifierMask = eq != nil ? MvModifierMask(chord->mods) : 0;
  }
}

// docs/design/16 "Window": another window is another MediaViewer process, on the
// empty window, cascaded from this one. The bundle starts as a new instance
// (LaunchServices would otherwise just activate this one); the bare lab
// binary, which has no bundle, starts itself.
- (void)openNewWindow {
  const NSRect frame = self.window.frame;
  NSArray<NSString*>* args = @[
    @"--new-window", [NSString stringWithFormat:@"%.0f", NSMinX(frame)],
    [NSString stringWithFormat:@"%.0f", NSMaxY(frame)]
  ];
  NSBundle* bundle = NSBundle.mainBundle;
  if ([bundle.bundlePath.pathExtension isEqualToString:@"app"]) {
    NSWorkspaceOpenConfiguration* config = [NSWorkspaceOpenConfiguration configuration];
    config.createsNewApplicationInstance = YES;
    config.arguments = args;
    config.activates = YES;
    [NSWorkspace.sharedWorkspace openApplicationAtURL:bundle.bundleURL
                                        configuration:config
                                    completionHandler:^(NSRunningApplication* app, NSError*) {
                                      if (!app) dispatch_async(dispatch_get_main_queue(), ^{
                                        NSBeep();
                                      });
                                    }];
    return;
  }
  NSError* error = nil;
  if (!bundle.executableURL ||
      ![NSTask launchedTaskWithExecutableURL:bundle.executableURL arguments:args error:&error terminationHandler:nil]) {
    NSBeep();
  }
}

- (void)menuAction:(NSMenuItem*)item {
  [self runMenuCmd:item.tag];
}

// Shared by the menu bar and the in-window menu buttons (CommandBarView), so
// the two cannot disagree.
- (void)runMenuCmd:(NSInteger)cmd {
  if ([self menuCmdBlocked:cmd]) {
    NSBeep();
    return;
  }
  switch (static_cast<MvMenuCmd>(cmd)) {
    case kMenuOpen: [self openFolderPanel:NO]; break;
    case kMenuNewWindow: [self openNewWindow]; break;
    case kMenuOpenFolder: [self openFolderPanel:YES]; break;
    case kMenuOpenPhotos: [self openPhotosLibrary]; break;
    case kMenuTrash: [self deleteMarkedToTrash]; break;
    case kMenuRename: (void)[self renameCurrentItem]; break;
    case kMenuCopyTo: [self copyMarkedPickDestination:YES]; break;
    case kMenuMoveTo: [self moveMarkedPickDestination:YES]; break;
    case kMenuMark: [self toggleMarkCurrent]; break;
    case kMenuFit: mv_chrome_fit(); break;
    case kMenuOneToOne: mv_chrome_one_to_one(); break;
    case kMenuFilmstrip: [self toggleFilmstrip]; break;
    case kMenuPageSidebar: [self togglePageSidebar]; break;
    case kMenuPaneWider: [self paneStep:1]; break;
    case kMenuPaneNarrower: [self paneStep:-1]; break;
    case kMenuAutoEnhance: [self autoEnhance]; break;
    // docs/plans/edit-refresh.md S3: the canvas tools, as their keys.
    case kMenuToolBrush: (void)[self runCommand:mv::shell::command_id::tool_brush back:mv::shell::back_target::none]; break;
    case kMenuToolRedEye: (void)[self runCommand:mv::shell::command_id::tool_red_eye back:mv::shell::back_target::none]; break;
    case kMenuToolExtend: (void)[self runCommand:mv::shell::command_id::tool_extend back:mv::shell::back_target::none]; break;
    case kMenuToolFaces: (void)[self runCommand:mv::shell::command_id::tool_faces back:mv::shell::back_target::none]; break;
    case kMenuGallery: [self toggleGallery]; break;
    case kMenuFullscreen: [self toggleFullscreen]; break;
    case kMenuSlideshow: [self startSlideshow]; break;
    case kMenuNext: [self navigateNext]; break;
    case kMenuPrev: [self navigatePrev]; break;
    case kMenuFirst: [self navigateFirst]; break;
    case kMenuLast: [self navigateLast]; break;
    case kMenuHelp: [self toggleHelp]; break;
    case kMenuSettings: [self setSettingsVisible:!_settingsVisible]; break;
    case kMenuOverlay: [self runCommand:mv::shell::command_id::overlay back:mv::shell::back_target::none]; break;
    case kMenuReveal: [self runCommand:mv::shell::command_id::reveal_in_explorer back:mv::shell::back_target::none]; break;
    case kMenuMetadata: [self runCommand:mv::shell::command_id::metadata_pane back:mv::shell::back_target::none]; break;
    case kMenuFolderTree: [self runCommand:mv::shell::command_id::folder_tree back:mv::shell::back_target::none]; break;
    case kMenuShare: [self runCommand:mv::shell::command_id::share back:mv::shell::back_target::none]; break;
    case kMenuCopyPath: [self runCommand:mv::shell::command_id::copy_path back:mv::shell::back_target::none]; break;
    case kMenuCopyEdited:
      if (![self runCommand:mv::shell::command_id::copy_flattened back:mv::shell::back_target::none]) NSBeep();
      break;
    case kMenuPrint:
      if (![self runCommand:mv::shell::command_id::print back:mv::shell::back_target::none]) NSBeep();
      break;
    case kMenuEditWorkspace: [self runCommand:mv::shell::command_id::edit_workspace back:mv::shell::back_target::none]; break;
    case kMenuEditCrop: [self runCommand:mv::shell::command_id::crop_mode back:mv::shell::back_target::none]; break;
    case kMenuEditColour: [self runCommand:mv::shell::command_id::adjust_pane back:mv::shell::back_target::none]; break;
    case kMenuRotateLeft: [self runCommand:mv::shell::command_id::rotate_ccw back:mv::shell::back_target::none]; break;
    case kMenuRotateRight: [self runCommand:mv::shell::command_id::rotate_cw back:mv::shell::back_target::none]; break;
    case kMenuFlipH: [self runCommand:mv::shell::command_id::flip_horizontal back:mv::shell::back_target::none]; break;
    case kMenuFlipV: [self runCommand:mv::shell::command_id::flip_vertical back:mv::shell::back_target::none]; break;
    case kMenuUndoEdit: [self runCommand:mv::shell::command_id::undo_edit back:mv::shell::back_target::none]; break;
    case kMenuResetEdits: [self runCommand:mv::shell::command_id::reset_edits back:mv::shell::back_target::none]; break;
    case kMenuSaveCopy: [self editSaveCopy]; break;
    case kMenuTrim: [self runCommand:mv::shell::command_id::trim_mode back:mv::shell::back_target::none]; break;
    case kMenuSortName: case kMenuSortModified: case kMenuSortSize: case kMenuSortType:
    case kMenuSortDateTaken: {
      mv::io::sort_order o = _sort;
      o.key = static_cast<mv::io::sort_key>(cmd - kMenuSortName);
      [self setSortOrder:mv::io::pack_sort(o)];
      break;
    }
    case kMenuSortDescending: {
      mv::io::sort_order o = _sort;
      o.descending = !o.descending;
      [self setSortOrder:mv::io::pack_sort(o)];
      break;
    }
    case kMenuShowAll: case kMenuShowPhotos: case kMenuShowVideos: case kMenuShowRaw:
    case kMenuShowMarked: case kMenuShowPicks: case kMenuShowNotRejected: case kMenuShowRed:
    case kMenuShowYellow: case kMenuShowGreen: case kMenuShowBlue: case kMenuShowPurple:
      (void)[self setKindFilter:mv::io::kind_filter_from(static_cast<int>(cmd - kMenuShowAll))];
      break;
  }
}

// Issue #182: mid-crop, an item whose command the table does not run there
// (Open, Go ▸ Next, Settings…) is off, as its key is: walking away would drop
// the crop draft. The menu bar and the command bar's flyouts both ask.
// Closing Settings is never refused.
- (BOOL)menuCmdBlocked:(NSInteger)cmd {
  const mv::shell::command_id command = MvMenuCommand(cmd);
  if (command == mv::shell::command_id::none) return NO;
  if (cmd == kMenuSettings && _settingsVisible) return NO;
  if (!_brush.empty() && mv::shell::blocked_by_strokes(command)) return YES;  // S4a
  const mv::shell::view_state vs = [self currentViewState];
  const mv::shell::mode m = mv::shell::resolve_mode(vs);
  // S3: what tool mode refuses on a key it refuses from the menu too.
  if (m == mv::shell::mode::tool) return mv::shell::blocked_in_tool(command, vs.tool_pending) ? YES : NO;
  if (m != mv::shell::mode::crop) return NO;
  return !mv::shell::command_live_in(command, mv::shell::kCrop);
}

- (BOOL)validateMenuItem:(NSMenuItem*)item {
#if MV_WITH_SPARKLE
  if (item.action == @selector(toggleAutomaticUpdateChecks:)) {
    item.state = _updater.updater.automaticallyChecksForUpdates ? NSControlStateValueOn
                                                               : NSControlStateValueOff;
    return YES;
  }
#endif
  if (item.action != @selector(menuAction:)) return YES;
  const NSInteger tag = item.tag;
  if (tag >= kMenuSortName && tag <= kMenuSortDateTaken) {
    item.state = (static_cast<NSInteger>(_sort.key) == tag - kMenuSortName) ? NSControlStateValueOn
                                                                            : NSControlStateValueOff;
    return [self hasFolder];
  }
  if (tag == kMenuSortDescending) {
    item.state = _sort.descending ? NSControlStateValueOn : NSControlStateValueOff;
    return [self hasFolder];
  }
  if (tag >= kMenuShowAll && tag <= kMenuShowPurple) {
    item.state = static_cast<NSInteger>(_kindFilter) == tag - kMenuShowAll ? NSControlStateValueOn
                                                                         : NSControlStateValueOff;
    return tag != kMenuShowMarked || !_marks.empty() || _kindFilter == mv::io::kind_filter::marked;
  }
  if (tag == kMenuMetadata) item.state = _metaPaneVisible ? NSControlStateValueOn : NSControlStateValueOff;
  if (tag >= kMenuEditWorkspace && tag <= kMenuTrim) {
    const mv::shell::edit_subject subject = [self editSubject];
    // S3: the geometry greys while a tool is armed (strokes are never wiped).
    if ([self toolArmed] && (tag == kMenuRotateLeft || tag == kMenuRotateRight || tag == kMenuFlipH ||
                             tag == kMenuFlipV || tag == kMenuEditCrop)) {
      return NO;
    }
    if (tag == kMenuEditWorkspace) {
      item.title = @(mv::shell::workspace_title(subject == mv::shell::edit_subject::none
                                                    ? mv::shell::edit_subject::still : subject));
      item.state = _ws.open ? NSControlStateValueOn : NSControlStateValueOff;
      return subject != mv::shell::edit_subject::none;
    }
    if (tag == kMenuTrim) return subject == mv::shell::edit_subject::clip;
    // Nothing on the stack: nothing to undo; Reset also drops a crop draft.
    if (tag == kMenuUndoEdit) return subject == mv::shell::edit_subject::still && _edits.edit_count() > 0;
    if (tag == kMenuResetEdits) {
      return subject == mv::shell::edit_subject::still && (_edits.edit_count() > 0 || _edits.crop_active());
    }
    return subject == mv::shell::edit_subject::still;
  }
  // S3: the canvas tools are for a still; the armed one shows checked.
  if (tag >= kMenuToolBrush && tag <= kMenuToolFaces) {
    item.state = (tag == kMenuToolBrush && _tool.tool == mv::shell::canvas_tool::remove_brush) ||
                         (tag == kMenuToolRedEye && _tool.tool == mv::shell::canvas_tool::red_eye) ||
                         (tag == kMenuToolExtend && _tool.tool == mv::shell::canvas_tool::extend)
                     ? NSControlStateValueOn
                     : NSControlStateValueOff;
    return [self editSubject] == mv::shell::edit_subject::still;
  }
  if (tag == kMenuFolderTree) item.state = _treeVisible ? NSControlStateValueOn : NSControlStateValueOff;
  if (tag == kMenuPageSidebar) item.state = _pageSidebarWanted ? NSControlStateValueOn : NSControlStateValueOff;
  if ([self menuCmdBlocked:tag]) return NO;
  switch (static_cast<MvMenuCmd>(item.tag)) {
    case kMenuOpen: case kMenuOpenFolder: case kMenuFit: case kMenuOneToOne: case kMenuFullscreen: case kMenuHelp: case kMenuSettings: case kMenuOverlay:
    case kMenuNewWindow:
      return YES;
    case kMenuOpenPhotos:
      item.hidden = ![self photosLibraryAvailable];
      return !item.hidden;
    case kMenuRename:
      return [self currentEntry] != nullptr && !_listOpen && !_slideshowActive && !_edits.crop_active();
    case kMenuTrash:
      // The menu answers ⌘⌫ before any first responder sees it (issue #180).
      // A text field's ⌘⌫ is "delete to start of line"; in trim and crop
      // Delete edits, in the Video Editor it removes a piece, and a slideshow
      // is not browsing: none of them trashes the file on screen.
      if ([NSApp.keyWindow.firstResponder isKindOfClass:[NSText class]] || _editorOpen || _slideshowActive ||
          _edits.crop_active() || (_trim.armed() && [self currentItemIsVideo])) {
        return NO;
      }
      [[fallthrough]];
    case kMenuMoveTo: {
      // Photos library files are never trashed or moved (issue #72). The
      // marks themselves, not a copy of their entries: this runs per validation.
      if (![self hasFolder]) return NO;
      if (!_marks.empty()) {
        for (const std::string& path : _marks) {
          if (mv::shell::write_protected(path)) return NO;
        }
        return YES;
      }
      const mv::io::dir_entry* entry = [self currentEntry];
      return entry == nullptr || !mv::shell::write_protected(entry->path_utf8);
    }
    // A pane with nothing to show is off; one already up can still be closed.
    // The tree lists the open folder (even an empty one) and the Photos row.
    case kMenuMetadata: return [self hasFolder] || _metaPaneVisible;
    case kMenuFolderTree: return !_currentDir.empty() || _treeVisible || [self photosLibraryAvailable];
    case kMenuSlideshow: return [self hasFolder] && !_slideshowActive;
    // A clip or an animation has no still to bake (-copyFlattened refuses it).
    case kMenuCopyEdited: return [self hasFolder] && ![self currentItemIsVideo] && !_lab.anim_active();
    // Issue #614: the marks as a sheet, or a still (-printRequest refuses the rest).
    // Not in a slideshow, as the key's row; mid-crop menuCmdBlocked says no.
    case kMenuPrint:
      return [self hasFolder] && !_slideshowActive &&
             (mv::shell::print_as_sheet(std::max(_marks.size(), _galleryRange.size())) ||
              (![self currentItemIsVideo] && !_lab.anim_active()));
    default:
      return [self hasFolder];
  }
}

- (void)openFolderPanel:(BOOL)foldersOnly {
  NSOpenPanel* panel = [NSOpenPanel openPanel];
  panel.canChooseDirectories = YES;
  panel.canChooseFiles = !foldersOnly;
  panel.allowsMultipleSelection = NO;
  if ([panel runModal] != NSModalResponseOK || panel.URL.path == nil) return;
  [self openEntryPaths:@[ panel.URL.path ] failed:nil];
}

- (NSMenuItem*)addMenuItem:(NSString*)title
                       cmd:(MvMenuCmd)cmd
                       key:(NSString*)key
                      mods:(NSEventModifierFlags)mods
                    toMenu:(NSMenu*)menu {
  NSMenuItem* item = [menu addItemWithTitle:title action:@selector(menuAction:) keyEquivalent:key];
  item.target = self;
  item.tag = cmd;
  item.keyEquivalentModifierMask = mods;
  return item;
}

// App-menu About. ApplicationVersion is the bare number; AppKit draws the
// "Version " prefix. The command-bar flyout formats that prefix itself.
- (void)showAbout:(id)sender {
  (void)sender;
  char buf[64];
  NSDictionary* options = nil;
  if (mv_chrome_app_version(buf, static_cast<int32_t>(sizeof buf))) {
    options = @{NSAboutPanelOptionApplicationVersion : [NSString stringWithUTF8String:buf]};
  }
  [NSApp orderFrontStandardAboutPanelWithOptions:options];
}

- (void)installMainMenu {
  NSMenu* bar = [[NSMenu alloc] init];
  auto submenu = [bar](NSString* title) {
    NSMenuItem* holder = [bar addItemWithTitle:title action:nil keyEquivalent:@""];
    NSMenu* menu = [[NSMenu alloc] initWithTitle:title];
    holder.submenu = menu;
    return menu;
  };

  NSMenu* app = submenu(@"MediaViewer");
  NSMenuItem* about = [app addItemWithTitle:@"About MediaViewer"
                                      action:@selector(showAbout:)
                               keyEquivalent:@""];
  about.target = self;
  [app addItem:[NSMenuItem separatorItem]];
  // ⌘, ⌘N ⌘O ⇧⌘E ⌘W are the table's rows: syncMenuKeyEquivalents sets them.
  [self addMenuItem:@"Settings…" cmd:kMenuSettings key:@"" mods:0 toMenu:app];
#if MV_WITH_SPARKLE
  // The update check is a network call even with nothing else ever sent
  // (docs/design/13): it can be turned off here and stays off.
  NSMenuItem* check = [app addItemWithTitle:@"Check for Updates…"
                                     action:@selector(checkForUpdates:)
                              keyEquivalent:@""];
  check.target = _updater;
  NSMenuItem* automatic = [app addItemWithTitle:@"Check for Updates Automatically"
                                         action:@selector(toggleAutomaticUpdateChecks:)
                                  keyEquivalent:@""];
  automatic.target = self;
#endif
#if MV_APP_BUNDLE
  NSMenuItem* makeDefault = [app addItemWithTitle:@"Make MediaViewer the Default for Photos and Videos"
                                           action:@selector(makeDefaultViewer)
                                    keyEquivalent:@""];
  makeDefault.target = self;
#endif
  [app addItem:[NSMenuItem separatorItem]];
  [app addItemWithTitle:@"Hide MediaViewer" action:@selector(hide:) keyEquivalent:@"h"];
  [app addItem:[NSMenuItem separatorItem]];
  // #452: Quit goes to the background while an add-on keeps the process;
  // otherwise it is terminate:, as before. Logout and the Dock's Quit still
  // terminate.
  NSMenuItem* quit = [app addItemWithTitle:@"Quit MediaViewer" action:@selector(quitFromMenu:) keyEquivalent:@"q"];
  quit.target = self;

  NSMenu* file = submenu(@"File");
  [self addMenuItem:@"New Window" cmd:kMenuNewWindow key:@"" mods:0 toMenu:file];
  [self addMenuItem:@"Open…" cmd:kMenuOpen key:@"" mods:0 toMenu:file];
  // docs/design/26: shown once the library was added in Settings (validateMenuItem:).
  [self addMenuItem:@"Open Photos Library" cmd:kMenuOpenPhotos key:@"" mods:0 toMenu:file];
  NSMenuItem* openRecent = [file addItemWithTitle:@"Open Recent" action:nil keyEquivalent:@""];
  _openRecentMenu = [[NSMenu alloc] initWithTitle:@"Open Recent"];
  _openRecentMenu.delegate = self;
  openRecent.submenu = _openRecentMenu;
  [file addItem:[NSMenuItem separatorItem]];
  [self addMenuItem:@"Mark / Unmark" cmd:kMenuMark key:@"" mods:0 toMenu:file];
  [self addMenuItem:@"Copy Marked To…" cmd:kMenuCopyTo key:@"" mods:0 toMenu:file];
  [self addMenuItem:@"Move Marked To…" cmd:kMenuMoveTo key:@"" mods:0 toMenu:file];
  // No key equivalent: F2 is a row in the remappable table.
  [self addMenuItem:@"Rename…" cmd:kMenuRename key:@"" mods:0 toMenu:file];
  [self addMenuItem:@"Move to Trash"
                cmd:kMenuTrash
                key:[NSString stringWithFormat:@"%C", static_cast<unichar>(NSBackspaceCharacter)]
               mods:NSEventModifierFlagCommand
             toMenu:file];
  [file addItem:[NSMenuItem separatorItem]];
  // PR 15. No key equivalents here: the keys are rows in the remappable table.
  [self addMenuItem:@"Share…" cmd:kMenuShare key:@"" mods:0 toMenu:file];
  [self addMenuItem:@"Copy Path" cmd:kMenuCopyPath key:@"" mods:0 toMenu:file];
  [self addMenuItem:@"Copy Edited Image" cmd:kMenuCopyEdited key:@"" mods:0 toMenu:file];
  [file addItem:[NSMenuItem separatorItem]];
  // Issue #614. ⌘P comes from the live table (MvMenuChordCommand), as Open's ⌘O.
  [self addMenuItem:@"Print…" cmd:kMenuPrint key:@"" mods:0 toMenu:file];
  [file addItem:[NSMenuItem separatorItem]];
  [file addItemWithTitle:@"Close Window" action:@selector(performClose:) keyEquivalent:@""];

  // PR 29 (docs/design/20). No key equivalents: the router owns Return, ⇧C, ⇧A, [ ]
  // and ⌘Z, so a menu equivalent would run them twice. `?` lists the keys.
  NSMenu* edit = submenu(@"Edit");
  [self addMenuItem:@"Edit Image" cmd:kMenuEditWorkspace key:@"" mods:0 toMenu:edit];
  [edit addItem:[NSMenuItem separatorItem]];
  [self addMenuItem:@"Crop and Straighten" cmd:kMenuEditCrop key:@"" mods:0 toMenu:edit];
  [self addMenuItem:@"Adjust" cmd:kMenuEditColour key:@"" mods:0 toMenu:edit];
  [self addMenuItem:@"Auto Enhance" cmd:kMenuAutoEnhance key:@"" mods:0 toMenu:edit];
  // S3: the canvas tools (B arms the brush; the others ship unbound).
  [self addMenuItem:@"Remove Brush" cmd:kMenuToolBrush key:@"" mods:0 toMenu:edit];
  [self addMenuItem:@"Red-Eye" cmd:kMenuToolRedEye key:@"" mods:0 toMenu:edit];
  [self addMenuItem:@"Faces" cmd:kMenuToolFaces key:@"" mods:0 toMenu:edit];
  [self addMenuItem:@"Extend Edges" cmd:kMenuToolExtend key:@"" mods:0 toMenu:edit];
  [self addMenuItem:@"Rotate Left" cmd:kMenuRotateLeft key:@"" mods:0 toMenu:edit];
  [self addMenuItem:@"Rotate Right" cmd:kMenuRotateRight key:@"" mods:0 toMenu:edit];
  [self addMenuItem:@"Flip Horizontal" cmd:kMenuFlipH key:@"" mods:0 toMenu:edit];
  [self addMenuItem:@"Flip Vertical" cmd:kMenuFlipV key:@"" mods:0 toMenu:edit];
  [edit addItem:[NSMenuItem separatorItem]];
  [self addMenuItem:@"Undo Edit" cmd:kMenuUndoEdit key:@"" mods:0 toMenu:edit];
  [self addMenuItem:@"Reset to Original" cmd:kMenuResetEdits key:@"" mods:0 toMenu:edit];
  [self addMenuItem:@"Save Copy…" cmd:kMenuSaveCopy key:@"" mods:0 toMenu:edit];
  [edit addItem:[NSMenuItem separatorItem]];
  [self addMenuItem:@"Trim Video" cmd:kMenuTrim key:@"" mods:0 toMenu:edit];

  NSMenu* view = submenu(@"View");
  [self addMenuItem:@"Fit to Window" cmd:kMenuFit key:@"" mods:0 toMenu:view];
  [self addMenuItem:@"Actual Size" cmd:kMenuOneToOne key:@"" mods:0 toMenu:view];
  [view addItem:[NSMenuItem separatorItem]];
  [self addMenuItem:@"Filmstrip" cmd:kMenuFilmstrip key:@"" mods:0 toMenu:view];
  [self addMenuItem:@"Page Sidebar" cmd:kMenuPageSidebar key:@"" mods:0 toMenu:view];
  [self addMenuItem:@"Gallery" cmd:kMenuGallery key:@"" mods:0 toMenu:view];
  [self addMenuItem:@"Metadata" cmd:kMenuMetadata key:@"" mods:0 toMenu:view];
  [self addMenuItem:@"Folder Tree" cmd:kMenuFolderTree key:@"" mods:0 toMenu:view];
  [self addMenuItem:@"Wider Side Pane" cmd:kMenuPaneWider key:@"" mods:0 toMenu:view];
  [self addMenuItem:@"Narrower Side Pane" cmd:kMenuPaneNarrower key:@"" mods:0 toMenu:view];
  NSMenuItem* sortHolder = [view addItemWithTitle:@"Sort By" action:nil keyEquivalent:@""];
  NSMenu* sortMenu = [[NSMenu alloc] initWithTitle:@"Sort By"];
  sortHolder.submenu = sortMenu;
  [self addMenuItem:@"Name" cmd:kMenuSortName key:@"" mods:0 toMenu:sortMenu];
  [self addMenuItem:@"Date Modified" cmd:kMenuSortModified key:@"" mods:0 toMenu:sortMenu];
  [self addMenuItem:@"Size" cmd:kMenuSortSize key:@"" mods:0 toMenu:sortMenu];
  [self addMenuItem:@"Type" cmd:kMenuSortType key:@"" mods:0 toMenu:sortMenu];
  [self addMenuItem:@"Date Taken" cmd:kMenuSortDateTaken key:@"" mods:0 toMenu:sortMenu];
  [sortMenu addItem:[NSMenuItem separatorItem]];
  [self addMenuItem:@"Descending" cmd:kMenuSortDescending key:@"" mods:0 toMenu:sortMenu];
  NSMenuItem* showHolder = [view addItemWithTitle:@"Show" action:nil keyEquivalent:@""];
  NSMenu* showMenu = [[NSMenu alloc] initWithTitle:@"Show"];
  showHolder.submenu = showMenu;
  [self addMenuItem:@"All" cmd:kMenuShowAll key:@"" mods:0 toMenu:showMenu];
  [self addMenuItem:@"Photos" cmd:kMenuShowPhotos key:@"" mods:0 toMenu:showMenu];
  [self addMenuItem:@"Videos" cmd:kMenuShowVideos key:@"" mods:0 toMenu:showMenu];
  [self addMenuItem:@"RAW" cmd:kMenuShowRaw key:@"" mods:0 toMenu:showMenu];
  [self addMenuItem:@"Marked" cmd:kMenuShowMarked key:@"" mods:0 toMenu:showMenu];
  // Issue #207: on rating and colour label (read on a worker, not at scan).
  [showMenu addItem:[NSMenuItem separatorItem]];
  [self addMenuItem:@"Picks" cmd:kMenuShowPicks key:@"" mods:0 toMenu:showMenu];
  [self addMenuItem:@"Not Rejected" cmd:kMenuShowNotRejected key:@"" mods:0 toMenu:showMenu];
  [self addMenuItem:@"Red" cmd:kMenuShowRed key:@"" mods:0 toMenu:showMenu];
  [self addMenuItem:@"Yellow" cmd:kMenuShowYellow key:@"" mods:0 toMenu:showMenu];
  [self addMenuItem:@"Green" cmd:kMenuShowGreen key:@"" mods:0 toMenu:showMenu];
  [self addMenuItem:@"Blue" cmd:kMenuShowBlue key:@"" mods:0 toMenu:showMenu];
  [self addMenuItem:@"Purple" cmd:kMenuShowPurple key:@"" mods:0 toMenu:showMenu];
  [view addItem:[NSMenuItem separatorItem]];
  // The standard action (nil target -> the window via the responder chain):
  // AppKit titles it Enter/Exit Full Screen itself, and doesn't inject a
  // second copy of its own into this menu when one already exists.
  [view addItemWithTitle:@"Enter Full Screen" action:@selector(toggleFullScreen:) keyEquivalent:@""]
      .keyEquivalentModifierMask = 0;
  [self addMenuItem:@"Start Slideshow" cmd:kMenuSlideshow key:@"" mods:0 toMenu:view];

  NSMenu* go = submenu(@"Go");
  [self addMenuItem:@"Next" cmd:kMenuNext key:@"" mods:0 toMenu:go];
  [self addMenuItem:@"Previous" cmd:kMenuPrev key:@"" mods:0 toMenu:go];
  [self addMenuItem:@"First" cmd:kMenuFirst key:@"" mods:0 toMenu:go];
  [self addMenuItem:@"Last" cmd:kMenuLast key:@"" mods:0 toMenu:go];

  NSMenu* window = submenu(@"Window");
  [window addItemWithTitle:@"Minimize" action:@selector(performMiniaturize:) keyEquivalent:@"m"];
  [window addItemWithTitle:@"Zoom" action:@selector(performZoom:) keyEquivalent:@""];
  NSApp.windowsMenu = window;

  NSMenu* help = submenu(@"Help");
  [self addMenuItem:@"Keyboard Shortcuts" cmd:kMenuHelp key:@"" mods:0 toMenu:help];
  NSApp.helpMenu = help;

  NSApp.mainMenu = bar;
  [self syncMenuKeyEquivalents];
}

// Issue #182: after every change to the live table (a remap, Reset, loading
// Settings, an add-on's rows), so the menu answers the chord the router would.
- (void)syncMenuKeyEquivalents {
  if (NSApp.mainMenu != nil) MvSyncKeyEquivalents(NSApp.mainMenu, NSApp.mainMenu);
}

- (void)rebuildKeys {
  _router.rebuild(mv::shell::live_bindings());
  [self syncMenuKeyEquivalents];
}

// Finder: double-click, Open With, or a drop on the Dock icon (PR 20).
// Same "first entry that exists wins" rule as argv and drag-in (docs/design/16).
- (void)application:(NSApplication*)application openURLs:(NSArray<NSURL*>*)urls {
  (void)application;
  NSMutableArray<NSString*>* paths = [NSMutableArray array];
  for (NSURL* url in urls) {
    if (!url.isFileURL || !url.path) continue;
    if (!_launched) {
      if (const char* path = url.fileSystemRepresentation) {
        _options.open_path = path;
        return;
      }
      continue;
    }
    [paths addObject:url.path];
  }
  if (paths.count == 0) return NSBeep();
  if (_inBackground) [self leaveBackground];
  [self.window makeKeyAndOrderFront:nil];
  [self openEntryPaths:paths failed:nil];
}

// First-launch setup: the default-viewer checkbox starts on, but is applied
// only after Continue. Existing choices are preserved across updates; the app
// menu keeps the command available later. The canvas keeps presenting.
// After a drag install a second checkbox, also on, ejects the MediaViewer
// disk if it is still mounted and moves the .dmg to the Trash (docs/design/13).
- (void)askDefaultViewerOnce {
  if (!self.window || self.window.attachedSheet) return;
  _askedDefaultViewer = YES;
  [NSUserDefaults.standardUserDefaults setBool:YES forKey:@"MVAskedDefaultViewer"];
  NSAlert* alert = [[NSAlert alloc] init];
  alert.messageText = @"Set up MediaViewer";
  alert.informativeText =
      @"MediaViewer can be the app that opens JPEG, PNG, HEIC, RAW, MP4, MOV and the other "
      @"photo and video formats it reads when you double-click them in Finder. You can "
      @"untick the option below or change this later in the MediaViewer menu.";
  NSButton* makeDefault = [NSButton checkboxWithTitle:@"Use MediaViewer for all supported photos and videos"
                                              target:nil action:nullptr];
  makeDefault.state = NSControlStateValueOn;
  [makeDefault sizeToFit];
  alert.accessoryView = makeDefault;

  const mv::shell::installer_leftover leftover = _installer;
  NSButton* tidy = nil;
  if (leftover.any()) {
    NSString* dmg = leftover.image.empty() ? nil : @(leftover.image.c_str()).lastPathComponent;
    NSString* title =
        leftover.mount.empty()
            ? [NSString stringWithFormat:@"Move the installer (%@) to the Trash", dmg]
        : dmg == nil ? @"Eject the MediaViewer installer disk"
                     : [NSString stringWithFormat:@"Eject the installer disk and move %@ to the Trash", dmg];
    tidy = [NSButton checkboxWithTitle:title target:nil action:nullptr];
    tidy.state = NSControlStateValueOn;
    [tidy sizeToFit];
    NSStackView* stack = [NSStackView stackViewWithViews:@[ makeDefault, tidy ]];
    stack.orientation = NSUserInterfaceLayoutOrientationVertical;
    stack.alignment = NSLayoutAttributeLeading;
    stack.spacing = 8;
    stack.frame = NSMakeRect(0, 0, std::max(makeDefault.frame.size.width, tidy.frame.size.width),
                             makeDefault.frame.size.height + tidy.frame.size.height + 8);
    alert.accessoryView = stack;
  }
  [alert addButtonWithTitle:@"Continue"];
  [alert addButtonWithTitle:@"Not Now"];
  [alert beginSheetModalForWindow:self.window
                completionHandler:^(NSModalResponse response) {
                  const bool go = response == NSAlertFirstButtonReturn;
                  if (go && makeDefault.state == NSControlStateValueOn) {
                    [self makeDefaultViewer];
                  } else {
                    MvRecordDefaultViewerOffer(NO);
                  }
                  if (go && tidy != nil && tidy.state == NSControlStateValueOn) {
                    mv::shell::clean_up_installer(leftover, ^(bool ok) {
                      if (!ok) [self installerCleanUpFailed];
                    });
                  } else {
                    mv::shell::forget_installer_leftover();
                  }
                }];
}

// Finder or a Terminal can hold the disk; say so once, and leave it be.
- (void)installerCleanUpFailed {
  if (!self.window || self.window.attachedSheet) return;
  NSAlert* alert = [[NSAlert alloc] init];
  alert.messageText = @"The installer could not be tidied up";
  alert.informativeText =
      @"The MediaViewer disk is still in use, or the installer could not be moved to the "
      @"Trash. Eject the disk in Finder and drag the .dmg to the Trash yourself; "
      @"MediaViewer is installed either way.";
  [alert addButtonWithTitle:@"OK"];
  [alert beginSheetModalForWindow:self.window completionHandler:nil];
}

- (void)makeDefaultViewer {
  MvSetDefaultViewer(MvDeclaredContentTypes(nil));
  MvRecordDefaultViewerOffer(YES);
}

- (int32_t)updatePhase {
#if MV_WITH_SPARKLE
  return _installUpdateNow != nil ? 3 : _updateActivity;
#else
  return 0;
#endif
}

- (NSString*)updateVersion {
#if MV_WITH_SPARKLE
  return _updateVersionShown;
#else
  return nil;
#endif
}

- (NSString*)updateNotes {
#if MV_WITH_SPARKLE
  return _installUpdateNow != nil ? _updateNotesShown : nil;
#else
  return nil;
#endif
}

- (void)restartToUpdate {
#if MV_WITH_SPARKLE
  if (!_installUpdateNow) return;
  if (!_wantSelectedPath.empty()) {
    [NSUserDefaults.standardUserDefaults
        setObject:[NSString stringWithUTF8String:_wantSelectedPath.c_str()]
           forKey:@"MVResumeAfterUpdate"];
  }
  void (^install)(void) = _installUpdateNow;
  _installUpdateNow = nil;
  // #532: Sparkle quits every copy with a quit event; with Driftwire keeping
  // the process (#452) that event hid the window instead, and the update
  // never installed, transfer or not.
  _quitForReal = true;
  install();  // Sparkle quits, installs, and relaunches
#endif
}

// An add-on update installed beside a running copy (a loaded bundle cannot
// be replaced in the running app) and the user clicked restart. A staged app
// update goes the Sparkle way, which relaunches too and loads the newest
// add-on. Otherwise a small waiter opens MediaViewer again once this process
// has exited: macOS would only bring a still-running copy forward. The waiter
// gives up after a minute rather than open the app at some later moment.
- (void)restartForAddons {
#if MV_WITH_SPARKLE
  if (_installUpdateNow) {
    [self restartToUpdate];
    return;
  }
#endif
  if (!_wantSelectedPath.empty()) {
    [NSUserDefaults.standardUserDefaults
        setObject:[NSString stringWithUTF8String:_wantSelectedPath.c_str()]
           forKey:@"MVResumeAfterUpdate"];
  }
  NSBundle* bundle = NSBundle.mainBundle;
  const BOOL app = [bundle.bundlePath.pathExtension isEqualToString:@"app"];
  NSString* target = app ? bundle.bundlePath : bundle.executablePath;
  if (target.length == 0) return;
  NSTask* waiter = [[NSTask alloc] init];
  waiter.executableURL = [NSURL fileURLWithPath:@"/bin/sh"];
  NSString* script =
      @"i=0; while /bin/kill -0 \"$1\" 2>/dev/null; do i=$((i+1)); [ $i -gt 600 ] && exit 0; "
      @"/bin/sleep 0.1; done; if [ \"$3\" = app ]; then exec /usr/bin/open \"$2\"; else exec \"$2\"; fi";
  waiter.arguments = @[
    @"-c", script, @"mv-relaunch", [NSString stringWithFormat:@"%d", static_cast<int>(::getpid())], target,
    app ? @"app" : @"exe"
  ];
  waiter.standardInput = NSFileHandle.fileHandleWithNullDevice;
  waiter.standardOutput = NSFileHandle.fileHandleWithNullDevice;
  waiter.standardError = NSFileHandle.fileHandleWithNullDevice;
  NSError* error = nil;
  if (![waiter launchAndReturnError:&error]) {
    MV_LOG_WARN("relaunch: could not start the waiter");
    NSBeep();
    return;
  }
  [NSApp terminate:nil];
}

// #532: open MediaViewer again once this process has exited and the bundle's
// version has changed (another copy's install has finished), or after two
// minutes whatever happened. The selection comes back as after an update.
- (void)relaunchAfterUpdateInstalls {
  NSBundle* bundle = NSBundle.mainBundle;
  if (![bundle.bundlePath.pathExtension isEqualToString:@"app"]) return;
  if (!_wantSelectedPath.empty()) {
    [NSUserDefaults.standardUserDefaults
        setObject:[NSString stringWithUTF8String:_wantSelectedPath.c_str()]
           forKey:@"MVResumeAfterUpdate"];
  }
  NSString* version = [bundle objectForInfoDictionaryKey:@"CFBundleVersion"] ?: @"";
  NSTask* waiter = [[NSTask alloc] init];
  waiter.executableURL = [NSURL fileURLWithPath:@"/bin/sh"];
  NSString* script =
      @"i=0; while /bin/kill -0 \"$1\" 2>/dev/null; do i=$((i+1)); [ $i -gt 600 ] && exit 0; /bin/sleep 0.1; done; "
      @"j=0; while :; do v=$(/usr/libexec/PlistBuddy -c 'Print :CFBundleVersion' \"$2/Contents/Info.plist\" 2>/dev/null); "
      @"[ -n \"$v\" ] && [ \"$v\" != \"$3\" ] && break; j=$((j+1)); [ $j -gt 1200 ] && break; /bin/sleep 0.1; done; "
      @"/bin/sleep 1; exec /usr/bin/open \"$2\"";
  waiter.arguments = @[
    @"-c", script, @"mv-relaunch", [NSString stringWithFormat:@"%d", static_cast<int>(::getpid())], bundle.bundlePath,
    version
  ];
  waiter.standardInput = NSFileHandle.fileHandleWithNullDevice;
  waiter.standardOutput = NSFileHandle.fileHandleWithNullDevice;
  waiter.standardError = NSFileHandle.fileHandleWithNullDevice;
  NSError* error = nil;
  if (![waiter launchAndReturnError:&error]) MV_LOG_WARN("update: could not start the relaunch waiter");
}

#if MV_WITH_SPARKLE
// #620: "What's new" is the appcast item's description, which the feed's EdDSA
// signature covers and which arrived with the feed (the release embeds it;
// tools/mac/macpack.py refuses a releaseNotesLink, so nothing else is fetched).
// Only plain text is shown, and only within the rule the Windows manifest
// applies (tools/package/whats_new.py): up to three lines, 400 bytes.
static NSString* MvUpdateNotes(SUAppcastItem* item) {
  NSString* text = item.itemDescription;
  if (text.length == 0 || ![item.itemDescriptionFormat isEqualToString:@"plain-text"]) return nil;
  text = [text stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];
  if (text.length == 0 || [text lengthOfBytesUsingEncoding:NSUTF8StringEncoding] > 400) return nil;
  if ([text componentsSeparatedByString:@"\n"].count > 3) return nil;
  return text;
}

// Sparkle has a verified update staged. YES = we own the timing: nothing
// installs until the user clicks "Update ready — restart", or quits normally
// (then it installs on the way out, without a relaunch). Never a modal, never
// a forced restart (docs/design/13 "Never interrupt").
- (BOOL)updater:(SPUUpdater*)updater
    willInstallUpdateOnQuit:(SUAppcastItem*)item
    immediateInstallationBlock:(void (^)(void))immediateInstallHandler {
  (void)updater;
  _installUpdateNow = [immediateInstallHandler copy];
  _updateActivity = 0;
  _updateVersionShown = [item.displayVersionString copy];
  _updateNotesShown = MvUpdateNotes(item);
  dispatch_async(dispatch_get_main_queue(), ^{
    [self applyUpdateInBackground];
  });
  return YES;
}

// The steps before that, for the command bar's quiet status (docs/design/13 "never
// interrupt": text only, nothing to click until the update is staged). A
// check that finds nothing, or fails, just clears it.
- (BOOL)updater:(SPUUpdater*)updater
    mayPerformUpdateCheck:(SPUUpdateCheck)updateCheck
                    error:(NSError* __autoreleasing*)error {
  (void)updater;
  (void)updateCheck;
  (void)error;
  if (_installUpdateNow == nil) _updateActivity = 1;
  return YES;
}

- (void)updater:(SPUUpdater*)updater didFindValidUpdate:(SUAppcastItem*)item {
  (void)updater;
  _updateVersionShown = [item.displayVersionString copy];
}

- (void)updater:(SPUUpdater*)updater
    willDownloadUpdate:(SUAppcastItem*)item
           withRequest:(NSMutableURLRequest*)request {
  (void)updater;
  (void)request;
  _updateActivity = 2;
  _updateVersionShown = [item.displayVersionString copy];
}

- (void)updater:(SPUUpdater*)updater didAbortWithError:(NSError*)error {
  (void)updater;
  (void)error;
  _updateActivity = 0;
}

- (void)toggleAutomaticUpdateChecks:(NSMenuItem*)item {
  (void)item;
  [self setUpdateAutoCheck:!_updater.updater.automaticallyChecksForUpdates];
}

// The preview channel reads the appcast of the newest release, prerelease or
// not; GitHub's /releases/latest never serves a prerelease. Sparkle still
// checks the feed's EdDSA signature, the archive's, and that the version is
// newer than this one, so the listing only picks which signed feed is read.
- (nullable NSString*)feedURLStringForUpdater:(SPUUpdater*)updater {
  (void)updater;
  return [self updateChannel] == 1 ? _previewFeedURL : nil;
}

// Sparkle's own schedule reuses the URL above; refresh it after every cycle so
// the next scheduled check sees a release published since.
- (void)updater:(SPUUpdater*)updater
    didFinishUpdateCycleForUpdateCheck:(SPUUpdateCheck)updateCheck
                                 error:(nullable NSError*)error {
  (void)updater;
  (void)updateCheck;
  (void)error;
  _updateActivity = 0;
  [self resolveFeedThenCheck:NO];
}

// Highest x.y.z among published releases that carry appcast.xml, from the
// public listing. Tags are v1.2.3 (older unsigned previews carried a
// .preview.N suffix and no appcast). nil when nothing qualifies.
static NSString* MvNewestAppcastURL(NSData* listing) {
  NSString* const prefix = @"https://github.com/longtimeno-c/mediaviewer/releases/download/";
  id root = listing ? [NSJSONSerialization JSONObjectWithData:listing options:0 error:nil] : nil;
  if (![root isKindOfClass:[NSArray class]]) return nil;
  NSString* best = nil;
  long long bestVersion = -1;
  for (id r in (NSArray*)root) {
    if (![r isKindOfClass:[NSDictionary class]]) continue;
    NSDictionary* release = (NSDictionary*)r;
    id draft = release[@"draft"];
    if ([draft isKindOfClass:[NSNumber class]] && [draft boolValue]) continue;
    id tag = release[@"tag_name"];
    if (![tag isKindOfClass:[NSString class]] || ![tag hasPrefix:@"v"]) continue;
    NSArray<NSString*>* parts = [[tag substringFromIndex:1] componentsSeparatedByString:@"."];
    if (parts.count < 3) continue;
    long long version = 0;
    bool ok = true;
    for (NSUInteger i = 0; i < 3 && ok; ++i) {
      NSScanner* scan = [NSScanner scannerWithString:parts[i]];
      long long n = 0;
      ok = [scan scanLongLong:&n] && scan.atEnd && n >= 0 && n < 1000000;
      version = version * 1000000 + n;
    }
    if (!ok || version <= bestVersion) continue;
    id assets = release[@"assets"];
    if (![assets isKindOfClass:[NSArray class]]) continue;
    for (id a in (NSArray*)assets) {
      if (![a isKindOfClass:[NSDictionary class]]) continue;
      NSDictionary* asset = (NSDictionary*)a;
      if (![asset[@"name"] isEqual:@"appcast.xml"]) continue;
      id url = asset[@"browser_download_url"];
      if ([url isKindOfClass:[NSString class]] && [url hasPrefix:prefix]) {
        best = url;
        bestVersion = version;
      }
      break;
    }
  }
  return best;
}

// Sparkle drops -checkForUpdatesInBackground (logging only "called but
// .sessionInProgress == YES") while a session of its own is open, and one is
// briefly open just after launch, which is exactly when the preview listing
// comes back. Retry once a second until it is idle, then give up: the
// scheduled check still runs.
- (void)checkForUpdatesWhenIdle:(int)attempts {
  if (!_updater.updater.sessionInProgress) {
    [_updater.updater checkForUpdatesInBackground];
    return;
  }
  if (attempts <= 0) return;
  __weak MvLabApp* weakSelf = self;
  dispatch_after(dispatch_time(DISPATCH_TIME_NOW, NSEC_PER_SEC), dispatch_get_main_queue(), ^{
    [weakSelf checkForUpdatesWhenIdle:attempts - 1];
  });
}

// Stable: check straight away (Info.plist feed). Preview: read the release
// listing off the main thread first. `check` is the launch / channel-change
// check; it still honours "Check for Updates Automatically".
- (void)resolveFeedThenCheck:(BOOL)check {
  const BOOL wantCheck = check && _updater.updater.automaticallyChecksForUpdates;
  if ([self updateChannel] != 1) {
    _previewFeedURL = nil;
    if (wantCheck) [self checkForUpdatesWhenIdle:20];
    return;
  }
  NSURL* api = [NSURL URLWithString:@"https://api.github.com/repos/longtimeno-c/mediaviewer/releases?per_page=10"];
  NSMutableURLRequest* req = [NSMutableURLRequest requestWithURL:api];
  [req setValue:@"application/vnd.github+json" forHTTPHeaderField:@"Accept"];
  req.HTTPShouldHandleCookies = NO;
  __weak MvLabApp* weakSelf = self;
  [[NSURLSession.sharedSession
      dataTaskWithRequest:req
        completionHandler:^(NSData* data, NSURLResponse* response, NSError* error) {
          NSInteger status = [response isKindOfClass:[NSHTTPURLResponse class]]
                                 ? ((NSHTTPURLResponse*)response).statusCode
                                 : 0;
          NSString* url = (!error && status == 200) ? MvNewestAppcastURL(data) : nil;
          dispatch_async(dispatch_get_main_queue(), ^{
            MvLabApp* app = weakSelf;
            if (!app || [app updateChannel] != 1) return;
            // A failed lookup keeps the last good feed; with none yet, the
            // check reads the stable feed, which is never wrong, only older.
            if (url) app->_previewFeedURL = url;
            if (wantCheck) [app checkForUpdatesWhenIdle:20];
          });
        }] resume];
}
#endif

- (int32_t)updateChannel {
#if MV_WITH_SPARKLE
  return [[NSUserDefaults.standardUserDefaults stringForKey:@"mv.updateChannel"] isEqualToString:@"preview"] ? 1 : 0;
#else
  return -1;
#endif
}

- (void)setUpdateChannel:(int32_t)channel {
#if MV_WITH_SPARKLE
  if (channel != 0 && channel != 1) return;
  if (channel == [self updateChannel]) return;
  [NSUserDefaults.standardUserDefaults setObject:(channel == 1 ? @"preview" : @"stable")
                                          forKey:@"mv.updateChannel"];
  [self resolveFeedThenCheck:YES];
#else
  (void)channel;
#endif
}

- (int32_t)updateAutoCheck {
#if MV_WITH_SPARKLE
  return _updater ? (_updater.updater.automaticallyChecksForUpdates ? 1 : 0) : -1;
#else
  return -1;
#endif
}

// Sparkle persists the choice (SUEnableAutomaticChecks in the app's defaults).
// Turning it on checks now, as Windows pokes its updater.
- (void)setUpdateAutoCheck:(BOOL)on {
#if MV_WITH_SPARKLE
  if (!_updater || _updater.updater.automaticallyChecksForUpdates == on) return;
  _updater.updater.automaticallyChecksForUpdates = on;
  if (on) [self resolveFeedThenCheck:YES];
#else
  (void)on;
#endif
}

// Settings' "Check now" (Windows' row, issue #220): what the app menu's
// "Check for Updates…" does, Sparkle's own window saying what it found.
- (void)checkForUpdatesNow {
#if MV_WITH_SPARKLE
  if (_updater) [_updater checkForUpdates:nil];
#endif
}

// ---- Keys, commands, settings -----------------------------------------------

- (void)pokeSnapshot {
  ++_snap.activity_seq;
  [self.view publish];
  _lab.wake();
}

- (mv::shell::view_state)currentViewState {
  mv::shell::view_state s;
  s.focus = mv::shell::focus_kind::canvas;
  if (_items.empty()) s.item = mv::shell::item_kind::none;
  else if ([self currentItemIsVideo]) s.item = mv::shell::item_kind::clip;
  else if (_lab.anim_active()) s.item = mv::shell::item_kind::animation;
  else s.item = mv::shell::item_kind::still;
  s.gallery_open = _galleryVisible;
  s.slideshow = _slideshowActive;
  s.fullscreen = (self.window.styleMask & NSWindowStyleMaskFullScreen) != 0;
  s.popup_open = _helpVisible;
  s.loupe_held = _snap.loupe;
  if (!_items.empty()) _gameOn = NO;  // a file opened over the runner; the lab leaves it too
  s.game = _gameOn;
  s.settings_open = _settingsVisible;
  s.pane_open = _metaPaneVisible || _treeVisible || _adjust.visible() || _jobsVisible || _ws.open;
  s.crop = _edits.crop_active();
  s.trim = _trim.armed() && s.item == mv::shell::item_kind::clip;
  // Issue #416: on a clip, ← → skip ±2 s only with the strip hidden (T);
  // playing or paused is not a mode.
  s.filmstrip_visible = [self filmstripVisible];
  // Milestone H: Esc from a result list is the path bar's "Back to folder".
  s.list_open = _listOpen;
  s.text_selected = _text.has_selection();
  // docs/plans/edit-refresh.md S3: a canvas tool layers over browse.
  s.tool = [self toolArmed] == YES;
  s.tool_pending = [self toolPending] == YES;
  return s;
}

- (BOOL)handleKeyEvent:(NSEvent*)event {
  using namespace mv::shell;
  const bool up = event.type == NSEventTypeKeyUp;
  std::uint8_t mods = 0;
  const key k = MvKeyFromEvent(event, &mods);
  if (k == key::none) return NO;
  if ([self handleFolderFind:event key:k mods:mods]) return YES;
  // Settings owns the keyboard (the router agrees: settings_open routes
  // nothing); Esc closes it when no capture is pending, or first goes back
  // from an add-on's page to the list (#510, as on Windows).
  if (_settingsVisible) {
    if (!up && k == key::escape && mods == mod_none && _captureRow < 0) {
      if (![MVChromeHost settingsBack]) [self setSettingsVisible:NO];
      return YES;
    }
    return NO;
  }
  // PR 10: the export sheet owns the keyboard while it is up (it is first
  // responder; this only catches a key that still reached the canvas).
  if (_exportVisible) {
    if (!up && k == key::escape && mods == mod_none) {
      [self setExportVisible:NO];
      return YES;
    }
    return NO;
  }
  // PR 14: the clip tools sheet likewise.
  if (_clipToolsVisible) {
    if (!up && k == key::escape && mods == mod_none) {
      [self setClipToolsVisible:NO];
      return YES;
    }
    return NO;
  }
  key_event e;
  e.k = k;
  e.mods = mods;
  e.repeat = !up && event.isARepeat;
  e.up = up;
  const route r = _router.on_key(e, [self currentViewState]);
  // Issue #38: a transport key, or Tab heading for the controls, also wakes
  // them. The key still runs exactly its own command, nothing more.
  if (!up && (k == key::tab || is_transport_command(r.command))) [self transportActivity];
  // S3: tool mode refused the key (blocked_in_tool): say why, once.
  if (r.blocked) {
    [self toolBlocked];
    return YES;
  }
  if (r.command == command_id::none) return r.handled;
  return [self runCommand:r.command back:r.back];
}

- (void)cancelKeyHolds {
  mv::shell::command_id released[mv::shell::key_router::kHeldSlots];
  const std::size_t n = _router.cancel_holds(released);
  for (std::size_t i = 0; i < n; ++i) {
    [self runCommand:released[i] back:mv::shell::back_target::none];
  }
}

- (BOOL)runCanvasCommand:(mv::shell::command_id)command back:(mv::shell::back_target)target {
  using enum mv::shell::command_id;
  const bool clip = [self currentItemIsVideo];
  switch (command) {
    case open: [self openFolderPanel:NO]; return YES;
    case open_folder: [self openFolderPanel:YES]; return YES;
    case fit: case reset_view:
      _zoomIntentAt = 0.0;
      ++_snap.fit_seq; [self pokeSnapshot]; return YES;
    case one_to_one:
      _zoomIntentAt = CACurrentMediaTime();
      ++_snap.one_to_one_seq; [self pokeSnapshot]; return YES;
    case zoom_in:
      _zoomIntentAt = CACurrentMediaTime();
      ++_snap.zoom_in_seq; [self pokeSnapshot]; return YES;
    case zoom_out: ++_snap.zoom_out_seq; [self pokeSnapshot]; return YES;
    case zoom_200: case zoom_400:
      _snap.zoom_preset = command == zoom_200 ? 2.0f : 4.0f;
      _zoomIntentAt = CACurrentMediaTime();
      ++_snap.zoom_preset_seq; [self pokeSnapshot]; return YES;
    case fill:
      _zoomIntentAt = CACurrentMediaTime();
      ++_snap.fill_seq; [self pokeSnapshot]; return YES;
    case overlay: ++_snap.toggle_overlay_seq; [self pokeSnapshot]; return YES;
    case reset_stats: ++_snap.reset_stats_seq; [self pokeSnapshot]; return YES;
    case game_toggle_3d:
      if (!_items.empty() || !_gameOn) return NO;
      ++_snap.game_view_seq; [self pokeSnapshot]; return YES;
    case prev:
      if ([self folderCursorStep:-1]) return YES;
      if ([self galleryFilteredStep:-1]) return YES;
      if (_items.empty()) return NO;
      [self navigatePrev];
      return YES;
    case next:
      if ([self folderCursorStep:1]) return YES;
      if ([self galleryFilteredStep:1]) return YES;
      // Space with no folder open starts the empty-window runner (a soak
      // keeps the lab's sweep).
      if (_items.empty()) {
        _gameOn = YES;
        ++_snap.toggle_animation_seq;
        [self pokeSnapshot];
        return YES;
      }
      [self navigateNext];
      return YES;
    case first: [self navigateFirst]; return YES;
    case last: [self navigateLast]; return YES;
    case skip_back: [self navigateSkip:-10]; return YES;
    case skip_forward: [self navigateSkip:10]; return YES;
    case next_page: [self turnPage:1]; return YES;
    case prev_page: [self turnPage:-1]; return YES;
    case back:
      switch (target) {
        case mv::shell::back_target::popup: [self setHelpVisible:NO]; break;
        case mv::shell::back_target::settings: [self setSettingsVisible:NO]; break;
        case mv::shell::back_target::gallery: [self setGalleryVisible:NO]; break;
        case mv::shell::back_target::crop:
          _edits.cancel_crop();
          [self publishEdit];
          [self pokeSnapshot];
          break;
        case mv::shell::back_target::trim: [self setTrimArmed:NO]; break;
        case mv::shell::back_target::tool: [self toolDown]; break;
        case mv::shell::back_target::pane:
          if (_ws.open) {
            [self editClose];
            break;
          }
          [self setMetaPaneVisible:NO];
          [self setTreeVisible:NO];
          [self setAdjustVisible:NO];
          [self setJobsVisible:NO];
          break;
        case mv::shell::back_target::slideshow: [self leaveSlideshow]; break;
        case mv::shell::back_target::fullscreen: [self toggleFullscreen]; break;
        case mv::shell::back_target::game:
          _gameOn = NO;
          ++_snap.game_exit_seq;
          [self pokeSnapshot];
          break;
        case mv::shell::back_target::result_list: [self closeList]; break;
        case mv::shell::back_target::text_selection:
          if (_text.clear()) [self textPublish];
          break;
        default: break;
      }
      return YES;
    case toggle_gallery: [self toggleGallery]; return YES;
    case toggle_filmstrip: [self toggleFilmstrip]; return YES;
    case toggle_page_sidebar: [self togglePageSidebar]; return YES;
    case pane_wider: [self paneStep:1]; return YES;
    case pane_narrower: [self paneStep:-1]; return YES;
    case auto_enhance: [self autoEnhance]; return YES;
    case gallery_up: [self galleryMoveRows:-1]; return YES;
    case gallery_down: [self galleryMoveRows:1]; return YES;
    case gallery_open_selected:
      if (_galleryVisible && _folderCursor >= 0) {
        [self openSubfolderAtIndex:_folderCursor];
        return YES;
      }
      // The name filter shows no image: there is nothing selected to open.
      if ([self galleryFiltered] && _galleryFilterItems.empty()) return YES;
      [self setGalleryVisible:NO];
      return YES;
    case folder_up: return [self navigateUp];
    case folder_prev: return [self navigateSibling:-1];
    case folder_next: return [self navigateSibling:1];
    case typeahead: {
      const bool on_folders = _galleryVisible && !_subdirs.empty() &&
                              (_folderCursor >= 0 || _items.empty());
      // #291: over files, `/` is file search (names, then tags), as ⌘F is
      // without Local search (docs/design/16 "File search").
      if (!on_folders) return _items.empty() || _listOpen ? NO : [self openFileSearch];
      _folderQuery.clear();
      [self touchFolderFind];
      if (_folderCursor < 0 && !_subdirs.empty()) _folderCursor = 0;
      return YES;
    }
    case gallery_larger: [self adjustGalleryCellSize:1]; return YES;
    case gallery_smaller: [self adjustGalleryCellSize:-1]; return YES;
    case fullscreen: [self toggleFullscreen]; return YES;
    case sticky_zoom: [self setViewFlags:_viewFlags ^ mv::shell::kSettingStickyZoom]; return YES;
    // docs/design/16: pan only when zoomed. At fit the view is locked, so the key is
    // not ours and falls through; on a fitted clip ↑ ↓ are its volume.
    case pan_up: case pan_down: case pan_left: case pan_right: {
      const bool zooming = _zoomIntentAt > 0.0 && CACurrentMediaTime() - _zoomIntentAt < kZoomIntentSeconds;
      if (_lab.view_fitted() && !zooming) {
        if (!clip || (command != pan_up && command != pan_down)) return NO;
        _snap.video_volume_steps += command == pan_up ? 1 : -1; [self pokeSnapshot]; return YES;
      }
      if (command == pan_up) --_snap.pan_steps_y;
      if (command == pan_down) ++_snap.pan_steps_y;
      if (command == pan_left) --_snap.pan_steps_x;
      if (command == pan_right) ++_snap.pan_steps_x;
      [self pokeSnapshot];
      return YES;
    }
    // View state the render thread draws from (levels, not edges).
    case clipping: _snap.clipping = !_snap.clipping; [self pokeSnapshot]; return YES;
    case loupe: case loupe_release:
      // The loupe magnifies a still. On a clip or an empty canvas Z is not
      // ours: do not swallow it and then draw nothing.
      if (command == loupe && (clip || _items.empty() || !_lab.showing_still())) return NO;
      _snap.loupe = command == loupe;
      if (command == loupe) {
        // Each hold starts at the cursor, or the canvas centre with none.
        _snap.loupe_steps_x = 0;
        _snap.loupe_steps_y = 0;
      }
      [self pokeSnapshot];
      return YES;
    case loupe_nudge_left: --_snap.loupe_steps_x; [self pokeSnapshot]; return YES;
    case loupe_nudge_right: ++_snap.loupe_steps_x; [self pokeSnapshot]; return YES;
    case loupe_nudge_up: --_snap.loupe_steps_y; [self pokeSnapshot]; return YES;
    case loupe_nudge_down: ++_snap.loupe_steps_y; [self pokeSnapshot]; return YES;
    case hold_previous: case hold_previous_release:
      _snap.hold_previous = command == hold_previous;
      [self pokeSnapshot];
      return YES;
    case compare_two_up:
      // A level: the render thread splits only while a still is up.
      _snap.compare = !_snap.compare;
      [self pokeSnapshot];
      return YES;
    // PR 9. The overlays are levels the render thread draws from `_snap.meta`;
    // turning one on asks for the record if it is not already here, and never
    // reads the file a second time.
    case info_overlay:
      _snap.info_overlay = !_snap.info_overlay;
      if (_snap.info_overlay) [self requestMetadataNow];
      [self pokeSnapshot];
      return YES;
    case af_points:
      _snap.af_points = !_snap.af_points;
      if (_snap.af_points) [self requestMetadataNow];
      [self pokeSnapshot];
      return YES;
    // Issue #209: 100 % on the AF point, from the record already held (or one
    // read on the pool); the render thread moves the camera.
    case zoom_af_point:
      if (_metaRecord) {
        [self afFocusFire];
      } else {
        _afFocusPending = YES;
        [self requestMetadataNow];
      }
      return YES;
    case eyedropper:
      _snap.eyedropper = !_snap.eyedropper;
      [self pokeSnapshot];
      return YES;
    default:
      // command_coverage.inc sent this id here. A missing case is a
      // no-op, the same as the old switch's default.
      return NO;
  }
}

- (BOOL)runTransportCommand:(mv::shell::command_id)command {
  using enum mv::shell::command_id;
  const bool clip = [self currentItemIsVideo];
  const bool anim = !clip && _lab.anim_active();
  switch (command) {
    // Clip / animation transport. Space, K and `,` `.` reach the render thread as
    // latched counters (input_snapshot), like pan and zoom.
    case play_pause: case pause:
      if (!clip && !anim) return NO;
      ++_snap.anim_toggle_seq; [self pokeSnapshot]; return YES;
    case frame_back: case frame_forward:
      if (!clip && !anim) return NO;
      _snap.anim_steps += command == frame_forward ? 1 : -1; [self pokeSnapshot]; return YES;
    case jump_back: case jump_forward:
      if (!clip) return NO;
      _snap.video_skip_ms += command == jump_forward ? 10000 : -10000; [self pokeSnapshot]; return YES;
    case skim_back: case skim_forward:
      if (!clip) return NO;
      _snap.video_skip_ms += command == skim_forward ? 2000 : -2000; [self pokeSnapshot]; return YES;
    case skim_settle: return YES;
    case rate_down: case rate_up:
      if (!clip) return NO;
      _snap.video_speed_steps += command == rate_up ? 1 : -1; [self pokeSnapshot]; return YES;
    case mute:
      if (!clip) return NO;
      ++_snap.video_mute_seq; [self pokeSnapshot]; return YES;
    default:
      // command_coverage.inc sent this id here. A missing case is a
      // no-op, the same as the old switch's default.
      return NO;
  }
}

- (BOOL)runMarksCommand:(mv::shell::command_id)command {
  using enum mv::shell::command_id;
  switch (command) {
    case reveal_in_explorer: {
      // docs/design/26: a Photos library item is shown where it lives, in
      // Photos, not as its rendition inside the library bundle or the cache.
      if (!_items.empty() && _index.current() < _items.size() &&
          mv::shell::photos::is_key(_items[_index.current()].path_utf8)) {
        return mv::shell::photos::show_in_photos(_items[_index.current()].path_utf8) ? YES : NO;
      }
      NSString* path = [self currentItemPathForDrag];
      if (!path) return NO;
      [[NSWorkspace sharedWorkspace] activateFileViewerSelectingURLs:@[ [NSURL fileURLWithPath:path] ]];
      return YES;
    }
    case toggle_mark: [self toggleMarkCurrent]; return YES;
    case mark_all:
      // With words selected in the still, Select All is every word (Photos);
      // otherwise it marks every file.
      if (_text.has_selection() && _text.select_all()) {
        [self textPublish];
        return YES;
      }
      [self markAll];
      return YES;
    case unmark_all: [self unmarkAll]; return YES;
    case copy_to: [self copyMarkedPickDestination:NO]; return YES;
    case copy_to_pick: [self copyMarkedPickDestination:YES]; return YES;
    case move_to: [self moveMarkedPickDestination:NO]; return YES;
    case move_to_pick: [self moveMarkedPickDestination:YES]; return YES;
    case delete_to_recycle_bin:
      if (_items.empty()) return NO;
      [self deleteMarkedToTrash];
      return YES;
    case copy_clipboard: {
      NSPasteboard* board = [NSPasteboard generalPasteboard];
      // Words selected in the still (text in images): that text.
      if (_text.has_selection()) {
        const std::string text = _text.text();
        [board clearContents];
        if (![board setString:[NSString stringWithUTF8String:text.c_str()] forType:NSPasteboardTypeString]) {
          NSBeep();
          return YES;
        }
        [self noticeShow:mv::shell::copy_text_notice(_text.words())];
        return YES;
      }
      // Eyedropper on and a pixel under the cursor: that colour.
      if (_snap.eyedropper) {
        const std::string text = _lab.eyedropper_text();
        if (!text.empty()) {
          [board clearContents];
          [board setString:[NSString stringWithUTF8String:text.c_str()] forType:NSPasteboardTypeString];
          return YES;
        }
      }
      // Otherwise the file(s): the marks, else the current item, which is the selected
      // cell while the gallery is up. Pasteable in Finder, Mail, Messages.
      NSMutableArray<NSURL*>* urls = [NSMutableArray array];
      for (const auto& entry : [self markedOrCurrentEntries]) {
        [urls addObject:[NSURL fileURLWithPath:[NSString stringWithUTF8String:entry.path_utf8.c_str()]]];
      }
      if (urls.count == 0) return NO;
      [board clearContents];
      return [board writeObjects:urls] ? YES : NO;
    }
    // PR 15 (docs/design/16 View): the keyboard twins of drag-out.
    case copy_path: {
      std::vector<std::string> paths;
      for (const auto& entry : [self markedOrCurrentEntries]) paths.push_back(entry.path_utf8);
      const std::string text = mv::shell::paths_as_text(paths, "\n");
      if (text.empty()) return NO;
      NSPasteboard* board = [NSPasteboard generalPasteboard];
      [board clearContents];
      return [board setString:[NSString stringWithUTF8String:text.c_str()] forType:NSPasteboardTypeString];
    }
    case copy_flattened: return [self copyFlattened];
    // Issue #614 (docs/design/16 "Print"): the photo on screen, or the marks as a sheet.
    case print: return [self printRequest];
    case share: return [self shareRequest:{}];  // the key's request: the menu, on the selection
    default:
      // command_coverage.inc sent this id here. A missing case is a
      // no-op, the same as the old switch's default.
      return NO;
  }
}

- (BOOL)runSlideshowCommand:(mv::shell::command_id)command {
  using enum mv::shell::command_id;
  switch (command) {
    case slideshow_start:
      if (_items.empty()) return NO;
      [self startSlideshow];
      return YES;
    case slideshow_pause: [self toggleSlideshowPause]; return YES;
    case slideshow_faster: [self adjustSlideshowInterval:-1.0]; return YES;
    case slideshow_slower: [self adjustSlideshowInterval:1.0]; return YES;
    case blackout:
      if (!_slideshowActive) return NO;
      _snap.blackout = !_snap.blackout;
      [self pokeSnapshot];
      return YES;
    case shuffle:
      if (!_slideshowActive) return NO;
      _slideshowOrder.toggle_shuffle(static_cast<std::uint32_t>(_index.current()),
                                     static_cast<std::uint64_t>(CACurrentMediaTime() * 1000.0));
      return YES;
    default:
      // command_coverage.inc sent this id here. A missing case is a
      // no-op, the same as the old switch's default.
      return NO;
  }
}

- (BOOL)runEditStackCommand:(mv::shell::command_id)command {
  using enum mv::shell::command_id;
  const bool clip = [self currentItemIsVideo];
  const bool anim = !clip && _lab.anim_active();
  switch (command) {
    // PR 11 (docs/design/16 Pane): ⇧A shows the adjust pane and focuses it.
    case adjust_pane: [self setAdjustVisible:!_adjust.visible()]; return YES;
    // PR 10 geometry, crop mode and export (docs/design/16 View + Crop).
    case rotate_ccw: case rotate_cw: case flip_horizontal: case flip_vertical: case crop_mode:
    case crop_commit: case crop_move_left: case crop_move_right: case crop_move_up:
    case crop_move_down: case crop_narrower: case crop_wider: case crop_shorter:
    case crop_taller: case straighten_ccw: case straighten_cw: case export_image:
    case undo_edit: case reset_edits:
    case crop_aspect_cycle: case crop_aspect_swap:
      return [self runEditCommand:command];
    // PR 29: Y held shows the original pixels; the stack is untouched.
    case show_original: case show_original_release:
      if (_items.empty() || clip || anim) return NO;
      [self editShowOriginal:command == show_original];
      return YES;
    // docs/plans/edit-refresh.md S3: canvas tools (shell/canvas_tool.h).
    case tool_smaller: case tool_bigger: case tool_undo: case tool_redo: case tool_clear:
    case tool_apply: case tool_pan: case tool_pan_release: case tool_brush: case tool_red_eye:
    case tool_extend: case tool_faces:
      if (clip || anim) return NO;
      return [self runToolCommand:command];
    default:
      // command_coverage.inc sent this id here. A missing case is a
      // no-op, the same as the old switch's default.
      return NO;
  }
}

- (BOOL)runSessionCommand:(mv::shell::command_id)command {
  using enum mv::shell::command_id;
  switch (command) {
    case close_window: [self.window performClose:nil]; return YES;
    case new_window: [self openNewWindow]; return YES;
    case kind_filter_next:
      return [self setKindFilter:mv::io::next_kind_filter(_kindFilter, !_marks.empty())];
    case rename_file: return [self renameCurrentItem];
    case always_on_top:
      self.window.level = self.window.level == NSFloatingWindowLevel ? NSNormalWindowLevel
                                                                      : NSFloatingWindowLevel;
      return YES;
    case help: [self toggleHelp]; return YES;
    case open_settings: [self setSettingsVisible:!_settingsVisible]; return YES;
    // Milestone G (docs/design/18 "Commands"): ⌘⇧I and ⌘⇧F7, while Import is loaded.
    case open_import: {
      if (!mv::shell::addon_commands_available()) return NO;
      std::vector<std::string> marks(_marks.begin(), _marks.end());
      MvAddonsOpenImport(marks);
      return YES;
    }
    // docs/design/25: a row an add-on's manifest contributed. The payload it asked
    // for rides along as JSON; the add-on's chrome does the work.
    case addon_cmd_0: case addon_cmd_1: case addon_cmd_2: case addon_cmd_3:
    case addon_cmd_4: case addon_cmd_5: case addon_cmd_6: case addon_cmd_7: {
      const mv::shell::addon_command_row* row = mv::shell::addon_command(command);
      if (!row) return NO;
      // One-click (owner 2026-11-05): Enhance's palette rows on the photo on
      // screen open the Edit pane's Enhance tab, never the sheet (a clip or an
      // audio file keeps the sheet: there is no Edit pane for it).
      if (row->addon == "enhance" && (row->id == "open" || row->id == "restyle" || row->id == "faces")) {
        std::vector<std::string> paths;
        for (const auto& entry : [self markedOrCurrentEntries]) paths.push_back(entry.path_utf8);
        if ([self enhanceOpenTabFor:paths]) return YES;
      }
      mv::json::writer w;
      if (row->payload == "marks") {
        w.begin_array();
        for (const std::string& m : _marks) w.string(m);
        w.end_array();
      } else if (row->payload == "marked_or_current") {
        w.begin_array();
        for (const auto& entry : [self markedOrCurrentEntries]) w.string(entry.path_utf8);
        w.end_array();
      } else if (row->payload == "screen") {
        w.begin_object();
        w.key("path").string([self currentItemPathForDrag].UTF8String ?: "");
        w.key("video").boolean([self currentItemIsVideo] == YES);
        w.end_object();
      } else {
        w.null();
      }
      return MvAddonsRunContributedCommand(row->addon, row->id, w.str()) ? YES : NO;
    }
    case import_now: {
      if (!mv::shell::addon_commands_available()) return NO;
      std::vector<std::string> paths;
      for (const auto& entry : [self markedOrCurrentEntries]) paths.push_back(entry.path_utf8);
      MvAddonsImportNow(paths);
      return !paths.empty();
    }
    // Milestone H (docs/design/17 "UI and commands"): the AI chrome runs these; the
    // key falls through, as if unbound, while the pack is not loaded. ⌘F
    // then opens its panel once a starting pack attaches, or file search
    // when nothing is on its way (docs/design/16 "File search", 2026-09-28).
    case search_open:
    case search_similar:
    case search_next_match:
    case search_prev_match: {
      if (!mv::shell::addon_command_available(command)) {
        if (command != search_open) return NO;
        // The pack waiting since launch (issue #292), or a later window's
        // reader (docs/design/18 "One host process"), starts now.
        if (MvAddonsSearchOnDemand()) return YES;
        if ([MVChromeHost openLocalSearchWhenStarting]) return YES;
        return [self openFileSearch];
      }
      const char* name = command == search_open         ? "search_open"
                         : command == search_similar    ? "search_similar"
                         : command == search_next_match ? "search_next_match"
                                                        : "search_prev_match";
      return MvAddonsRunCommand(name) ? YES : NO;
    }
    case metadata_pane:
      if (!_metaPaneVisible && _adjust.visible()) [self setAdjustVisible:NO];
      if (!_metaPaneVisible && _jobsVisible) [self setJobsVisible:NO];
      [self setMetaPaneVisible:!_metaPaneVisible];
      return YES;
    // PR 12 (docs/design/16 Rate): 0-5 write the rating of the item on screen.
    case set_rating_0: case set_rating_1: case set_rating_2: case set_rating_3:
    case set_rating_4: case set_rating_5:
      return [self rateCurrentItem:mv::shell::rating_of_command(command)];
    // Issue #207: culling, the same writer as the ratings.
    case reject: return [self rejectCurrentItem];
    case label_red: case label_yellow: case label_green: case label_blue: case clear_label:
      return [self labelCurrentItem:static_cast<mv::shell::colour_label>(
                                        mv::shell::label_of_command(command))];
    case edit_comment: return [self focusCommentField];
    // PR 13 / 14 (docs/design/08, docs/design/16 "Video and trim").
    case trim_mode: case trim_in: case trim_out: case trim_clear: case trim_preview:
    case trim_keyframe: case trim_reencode: case trim_remove_middle: case keyframe_prev:
    case keyframe_next: case jobs_pane: case clip_tools: case clip_split:
      return [self runClipCommand:command];
    case folder_tree: [self setTreeVisible:!_treeVisible]; return YES;
    default:
      // command_coverage.inc sent this id here. A missing case is a
      // no-op, the same as the old switch's default.
      return NO;
  }
}
- (BOOL)runCommand:(mv::shell::command_id)command back:(mv::shell::back_target)target {
  using enum mv::shell::command_id;
  // PR 11 (docs/design/13): every command is a native call with its own id, so a
  // chrome exception or a crash in the work it starts carries the same one.
  (void)mv::shell::crash::note_native_call();
  // docs/plans/edit-refresh.md S3: what tool mode refuses on a key it refuses
  // from the chrome's buttons too (Rotate, Flip, Crop, the Bin; and walking away
  // while strokes are pending), so strokes are never wiped.
  if ([self toolArmed] && mv::shell::blocked_in_tool(command, [self toolPending] == YES)) {
    [self toolBlocked];
    return YES;
  }
  // S4a: strokes kept with the tool put down refuse a turn or a flip too.
  if (!_brush.empty() && mv::shell::blocked_by_strokes(command)) {
    [self noticeShow:"Remove or clear the strokes first"];
    return YES;
  }
  // PR 29 (docs/design/20): the keys that open a tab of the Edit workspace. The
  // workspace decides the tab; crop_mode and trim_mode then do their own work.
  // PR 30 (docs/design/21, owner): video is edited in its own window, not a pane.
  // Return (the bar's "Open in <app>") on a PDF or DOCX: its own app opens it.
  if (command == edit_workspace && !_ws.open && !_editorOpen && [self currentItemIsDocument]) {
    [self openDocumentInApp:nil];
    return YES;
  }
  if (command == edit_workspace && (_editorOpen || [self editSubject] == mv::shell::edit_subject::clip)) {
    if (_editorOpen) {
      [self editorRequestClose];
    } else {
      [self setEditorOpen:YES];
    }
    return YES;
  }
  if (command == edit_workspace || command == crop_mode || command == adjust_pane ||
      command == trim_mode || command == metadata_pane || command == jobs_pane) {
    const mv::shell::workspace_step step = mv::shell::route_workspace(_ws, [self editSubject], command);
    if (step.action != mv::shell::workspace_action::none) {
      if (mv::shell::apply_step(_ws, step)) [self syncWorkspace];
      if (command != crop_mode && command != trim_mode) return YES;
    } else if (command == edit_workspace) {
      NSBeep();  // nothing on the canvas to edit
      return YES;
    } else if (_ws.open && (command == metadata_pane || command == jobs_pane || command == adjust_pane)) {
      // A pane the workspace does not hold here takes the edge on its own.
      [self editClose];
    }
  }
  switch (mv::shell::mac_command_area(command)) {
    case mv::shell::command_area::canvas:
      return [self runCanvasCommand:command back:target];
    case mv::shell::command_area::transport:
      return [self runTransportCommand:command];
    case mv::shell::command_area::marks:
      return [self runMarksCommand:command];
    case mv::shell::command_area::slideshow:
      return [self runSlideshowCommand:command];
    case mv::shell::command_area::edit:
      return [self runEditStackCommand:command];
    case mv::shell::command_area::session:
      return [self runSessionCommand:command];
    case mv::shell::command_area::excluded:
      return NO;
  }
  return NO;
}

// ---- PR 10: edit stack, lossless rotate, crop, export ---------------------------

// A new item (or the same file reopened) is on its way to the canvas. The old
// item's geometry moves to slot 1 so its texture keeps it until the new
// pixels land; slot 0 is the new item's.
- (void)editItemOpened:(const mv::io::dir_entry&)entry item:(std::uint64_t)item {
  [self applyPageSidebarLayout];  // issue #429: a new stop or page
  _snap.edit[1] = _snap.edit[0];
  _itemId = item;
  mv::shell::edit_item e;
  e.path = entry.path_utf8;
  e.size = entry.size;
  e.mtime = entry.mtime_unix;
  // A hint: the write job probes the magic bytes and refuses anything else.
  NSString* ext = [[NSString stringWithUTF8String:entry.name_utf8.c_str()] pathExtension].lowercaseString;
  e.jpeg = [ext isEqualToString:@"jpg"] || [ext isEqualToString:@"jpeg"] || [ext isEqualToString:@"jpe"];
  const bool carried_turn = _edits.set_item(e);
  _showOriginal = NO;
  [self compareItemChanged:entry.path_utf8];
  [self publishEdit];
  if (carried_turn) [self scheduleRotationWrite];
  [self adjustItemChanged:mv::shell::is_video_name(entry.name_utf8) ? 0 : item];
  // One-click: the Enhance tab's cards follow the photo (a run on the last
  // one stops, as leaving it always did).
  [self enhanceCardsFollow:entry.path_utf8];
  // PR 29: an open workspace follows the item to a tab it offers.
  if (mv::shell::follow_subject(_ws, [self editSubject])) [self syncWorkspace];
  // S3: an armed tool stays armed on the next still (the bar and its band go
  // on a clip); red-eye reads the new photo's eyes, Faces its faces (S8).
  if (_tool.tool == mv::shell::canvas_tool::red_eye) [self toolFetchEyes];
  if (_tool.tool == mv::shell::canvas_tool::faces && [self adjustStill]) [self facesFetch];
  if (_tool.tool == mv::shell::canvas_tool::extend) [self extendReset];  // S6: a frame is the photo's own
  [self syncToolBar];
  [self toolCursor];
  // A document or a clip arriving under the filmstrip: say what T changes.
  [self stripHintShow];
}

- (void)publishEdit {
  // docs/design/20 "Compare": the before (Y held, or the split) is the lab's
  // second draw (input_snapshot::before_after); the edit view stays the edit.
  {
    const mv::shell::edit_view before = _snap.edit[0];
    _snap.edit[0] = mv::shell::view_of(_edits, _itemId, 0);
    // Slice 7: strokes lie over what was brushed only while the item and its
    // geometry stay; otherwise they go (and Enhance's copy of them).
    if (!_brush.pristine() &&
        (before.item != _itemId || !mv::shell::same_geometry(before, _snap.edit[0]) || _edits.crop_active())) {
      _brush.reset();     // S4a: forgotten with its history, not an undoable Clear
      _brushMask.reset();  // whatever the lab holds or builds is stale
      mv::addon::media::set_still_mask({}, {});
      [self bumpAdjustView];
    }
    [self brushMaskSync];
    ++_brushRev;
    mv::shell::apply_brush(_snap.edit[0], _brush, _brushMask, [self brushActive] == YES, _brushRev, _brushCursor);
    [self toolApplyView];  // S3: the tool's ring and red-eye fixes survive the new view
  }
  ++_editGeneration;  // the strip's edit count, the Crop pane's draft
  // Slice 5: Enhance's copy of the photo being edited carries its edit.
  if (_edits.has_item() && !_items.empty() && _index.current() < _items.size() &&
      !(_edits.export_geometry().identity() && _edits.colour().identity())) {
    mv::addon::media::set_still_edit(_items[_index.current()].path_utf8, _edits.export_geometry(),
                                     _edits.colour());
  } else {
    mv::addon::media::clear_still_edit();
  }
  // A new item, a turn or a crop: words read before no longer line up.
  [self textSync];
  [self comparePublish];
}

- (BOOL)runEditCommand:(mv::shell::command_id)command {
  // Stills only: a clip keeps `[` `]` for trim (PR 13), an animation has no
  // single frame to turn.
  if (_items.empty() || [self currentItemIsVideo] || _lab.anim_active()) return NO;
  std::uint32_t w = 0, h = 0;
  if (_lab.still_size(_itemId, &w, &h)) _edits.set_size(w, h);
  else if (command == mv::shell::command_id::crop_mode) {
    NSBeep();  // no pixels yet: nothing to frame a crop against
    return YES;
  }
  // A Photos library file: turning it rewrites it and Save copy writes beside
  // it; neither is allowed (issue #72). Cropping and the adjust sliders only
  // change the view, and stay.
  using mv::shell::command_id;
  // Owner 2026-11-04: a turn stays an edit (never written into the library;
  // startRotationWrite skips protected files) and Save copy adds a new photo
  // to the library (exportCurrentItem); a file merely inside the cache folder
  // (not a library item) is still refused.
  if (command == command_id::export_image) {
    const std::string& current = _items[std::min(_index.current(), _items.size() - 1)].path_utf8;
    if (!mv::shell::photos::is_key(current) && [self refuseWriteTo:current]) return YES;
  }
  [self applyEditEffect:_edits.run(command)];
  return YES;
}

- (void)applyEditEffect:(mv::shell::edit_effect)effect {
  switch (effect) {
    case mv::shell::edit_effect::none: return;
    case mv::shell::edit_effect::refused: NSBeep(); return;
    case mv::shell::edit_effect::redraw:
      [self publishEdit];
      [self pokeSnapshot];
      [self adjustColourChanged];  // undo / reset may have moved a slider
      return;
    case mv::shell::edit_effect::write_rotation:
      [self publishEdit];
      [self pokeSnapshot];
      [self scheduleRotationWrite];
      [self adjustColourChanged];
      return;
    case mv::shell::edit_effect::export_image:
      [self setExportVisible:YES];
      return;
  }
}

// ---- PR 29: the Edit workspace (docs/design/20) --------------------------------------

- (mv::shell::edit_subject)editSubject {
  if (_items.empty() || _itemId == 0) return mv::shell::edit_subject::none;
  // An audio file plays through the video path but has nothing to edit.
  if ([self currentItemIsAudio]) return mv::shell::edit_subject::none;
  // A document opens in its own app instead (the bar's "Open in <app>").
  if ([self currentItemIsDocument]) return mv::shell::edit_subject::none;
  if ([self currentItemIsVideo]) return mv::shell::edit_subject::clip;
  if (_lab.anim_active()) return mv::shell::edit_subject::none;
  return mv::shell::edit_subject::still;
}

// Shows what _ws says: the strip, the tab's pane, and the panes' tops under
// the strip. Closing hides only what the workspace had shown.
- (void)syncWorkspace {
  using mv::shell::edit_tab;
  _wsSyncing = YES;
  const BOOL open = _ws.open ? YES : NO;
  const edit_tab tab = _ws.tab;
  // A canvas tool belongs to Edit: closing it puts the tool down (S3), and
  // Enhance's docked panel goes with it (S5).
  if (!open && _tool.tool != mv::shell::canvas_tool::none) [self toolDown];
  if (!open) [self enhanceDockClose];
  // One-click: the Enhance tab shows its cards on the photo on screen.
  if (open && tab == edit_tab::enhance) [self enhanceCardsSync];
  // docs/design/20 "Compare": the split belongs to Edit; closing takes it down.
  if (!open && _compareOn) {
    [self comparePublish];
    [self pokeSnapshot];
  }
  // A crop draft belongs to the Crop tab: leaving it applies the draft
  // (Lightroom's rule), so no crop is lost to a tab click.
  if (_edits.crop_active() && !(open && tab == edit_tab::crop)) {
    [self runEditCommand:mv::shell::command_id::crop_commit];
  }
  // docs/plans/edit-refresh.md S2: the icon rail docks at the window's edge
  // while the workspace is open, and the column (the inspector) beside it. A
  // folded inspector (the rail's active icon, or a window too narrow for any)
  // shows the rail alone.
  self.railHost.hidden = !open;
  if (open != self.columnTrailingRail.active) {
    if (open) {
      self.columnTrailingFull.active = NO;
      self.columnTrailingRail.active = YES;
    } else {
      self.columnTrailingRail.active = NO;
      self.columnTrailingFull.active = YES;
    }
  }
  (void)[self layoutPaneWidth];
  const BOOL shown = open && ![self inspectorFolded];
  self.editStripHost.hidden = !shown;
  [self textSync];
  // The panes start under the header while it shows (its height is its own).
  for (NSArray<NSLayoutConstraint*>* pair in @[ @[ self.metaTop, self.metaTopUnder ],
                                                 @[ self.adjustTop, self.adjustTopUnder ],
                                                 @[ self.jobsTop, self.jobsTopUnder ] ]) {
    if (pair[1].active != shown) {
      if (shown) {
        pair[0].active = NO;
        pair[1].active = YES;
      } else {
        pair[1].active = NO;
        pair[0].active = YES;
      }
    }
  }
  self.editPaneHost.hidden =
      !(shown && (tab == edit_tab::crop || tab == edit_tab::trim || tab == edit_tab::enhance));
  [self layoutAIBadge];  // #345
  if (open || _wsShown) {
    // One right-edge pane at a time: each setter below closes the others.
    const BOOL colour = shown && tab == edit_tab::colour;
    const BOOL info = shown && tab == edit_tab::info;
    const BOOL jobs = shown && tab == edit_tab::jobs;
    if (!colour && _adjust.visible()) [self setAdjustVisible:NO];
    if (!info && _metaPaneVisible) [self setMetaPaneVisible:NO];
    if (!jobs && _jobsVisible) [self setJobsVisible:NO];
    if (colour) [self setAdjustVisible:YES];
    if (info) [self setMetaPaneVisible:YES focus:NO];
    if (jobs) [self setJobsVisible:YES focus:NO];
  }
  // Crop and Trim keys are the canvas's: keep the keyboard there.
  if (open && (tab == edit_tab::crop || tab == edit_tab::trim || !shown)) [self.window makeFirstResponder:self.view];
  const BOOL redock = _wsShown != open || _wsFolded != !shown;
  _wsShown = open;
  _wsFolded = !shown;
  [self syncCanvasGuide];
  _wsSyncing = NO;
  ++_editGeneration;
  // The canvas refits into the rect beside the docked pane (or back): the
  // window did not change, so no drawable size (refit_seq).
  if (redock) [self.view syncChrome];
}

- (CGFloat)dockedRightPoints {
  return mv::shell::docked_right(static_cast<float>([self paneShownPoints]), _ws.open, [self inspectorFolded],
                                 [self paneLimits]);
}

// docs/plans/edit-refresh.md S2: the docked workspace has the 44 pt rail beside
// its inspector; the floating panes (the workspace closed) have none.
- (mv::shell::pane_width_limits)paneLimits {
  return _ws.open ? kRailLimits : kPaneLimits;
}

// The inspector is folded to the rail: by the rail's active icon, or because
// the window is too narrow for any inspector beside the canvas.
- (BOOL)inspectorFolded {
  return _ws.open && (_ws.collapsed || [self paneShownPoints] <= 0.0);
}

// ---- The right column (docs/plans/edit-refresh.md §2.1, §2.3) ------------------------
// One width for every right pane. The preference is the user's (the defaults'
// MVRightPaneWidth, rounded to 4, saved on release); what is laid out is that
// clamped to the window (shell/pane_width.h). Only the docked workspace takes
// the width from the canvas, as before; the floating panes cover it.

- (CGFloat)paneClientPoints {
  NSView* container = self.window.contentView;
  return container ? NSWidth(container.bounds) : 0.0;
}

- (CGFloat)paneShownPoints {
  return mv::shell::shown_inspector(static_cast<float>(_panePref), static_cast<float>([self paneClientPoints]),
                                    static_cast<float>(MVChromeHost.inspectorMinimumWidth), [self paneLimits]);
}

// Lays the column out at the preference, re-clamped. True when its width changed.
- (BOOL)layoutPaneWidth {
  if (!self.rightColumnWidth) return NO;
  // Folded to the rail: the column has no width, so the canvas guide (and the
  // transport centred on it) ends at the rail.
  const CGFloat w = [self inspectorFolded] ? 0.0 : [self paneShownPoints];
  if (self.rightColumnWidth.constant == w) return NO;
  self.rightColumnWidth.constant = w;
  [self layoutAIBadge];
  return YES;
}

// -[MvMetalView setFrameSize:] (the window resized): it publishes itself. A
// window too narrow for an inspector beside the canvas folds it to the rail
// (and wide enough again, unfolds it).
- (void)applyPaneWidth {
  (void)[self layoutPaneWidth];
  if (_ws.open && !_wsSyncing && _wsFolded != [self inspectorFolded]) [self syncWorkspace];
}

// A new preference from a step, a reset or a drag's release: laid out, kept,
// and the docked canvas refitted with the spring.
- (void)setPanePreference:(CGFloat)want persist:(BOOL)persist {
  _panePref = std::clamp(want, static_cast<CGFloat>(kPaneLimits.min), static_cast<CGFloat>(kPaneLimits.max));
  (void)[self layoutPaneWidth];
  if (persist) {
    [NSUserDefaults.standardUserDefaults setInteger:mv::shell::stored_width(static_cast<float>(_panePref))
                                             forKey:kRightPaneWidthKey];
  }
  [self.view syncChrome];
}

- (void)paneStep:(int)direction {
  [self setPanePreference:mv::shell::step_inspector(static_cast<float>([self paneShownPoints]), direction,
                                                    kPaneLimits)
                  persist:!_paneDragSoak];
}

- (void)paneEdgeReset {
  [self setPanePreference:kInspectorDefaultPoints persist:!_paneDragSoak];
}

- (void)paneEdgeDown:(NSEvent*)event {
  // A scripted drag (the self-test, --pane-drag-soak) has no event and grabs
  // the edge itself.
  _paneGrabDx = 0.0;
  if (event) {
    NSView* container = self.window.contentView;
    const NSPoint at = [container convertPoint:event.locationInWindow fromView:nil];
    const CGFloat edge = [self paneClientPoints] - [self paneLimits].rail - self.rightColumnWidth.constant;
    _paneGrabDx = at.x - edge;
  }
  _paneDragging = YES;
  [MVChromeHost setPaneLiveResize:YES];
  _snap.chrome_live_resize = 1;
  [self.view publish];
}

// The picture tracks the edge exactly: an immediate refit per step (AppKit
// already coalesces drags to one per frame). Nothing is saved until release.
// A pointer where the column already is leaves the preference alone (a click
// on the edge in a narrow window keeps a wider wish; the Windows twin too).
- (void)paneDragTo:(CGFloat)leading {
  const CGFloat client = [self paneClientPoints];
  const mv::shell::pane_width_limits limits = [self paneLimits];
  const CGFloat shown = mv::shell::shown_inspector(static_cast<float>(client - limits.rail - leading),
                                                   static_cast<float>(client),
                                                   static_cast<float>(MVChromeHost.inspectorMinimumWidth),
                                                   limits);
  if (shown <= 0.0 || shown == self.rightColumnWidth.constant) return;
  _panePref = shown;
  if ([self layoutPaneWidth] && _ws.open) [self.view syncChrome];
}

// MVChromeThemeDidChange: the theme's minimum may have moved under the column.
- (void)paneThemeChanged {
  if ([self layoutPaneWidth] && _ws.open) [self.view syncChrome];
  if (_ws.open && !_wsSyncing && _wsFolded != [self inspectorFolded]) [self syncWorkspace];
}

- (void)paneEdgeDragged:(NSEvent*)event {
  if (!_paneDragging) return;
  NSView* container = self.window.contentView;
  const NSPoint at = [container convertPoint:event.locationInWindow fromView:nil];
  [self paneDragTo:at.x - _paneGrabDx];
}

- (void)paneEdgeUp:(NSEvent*)event {
  (void)event;
  if (!_paneDragging) return;
  _paneDragging = NO;
  _snap.chrome_live_resize = 0;
  [MVChromeHost setPaneLiveResize:NO];  // the Info pane asks its add-ons once
  [self setPanePreference:mv::shell::snap_inspector(static_cast<float>(_panePref)) persist:!_paneDragSoak];
}

// The canvas guide follows what the canvas frames the picture in: right of the
// page sidebar, left of the docked workspace (dockedRightPoints).
// The right panes stop above the filmstrip, except docked: the Edit column
// (strip, rail, its tab's pane) runs to the window's foot and the filmstrip
// stops at the canvas's edge (owner 2026-11-05).
- (void)syncColumnBottom {
  const CGFloat bottom = (!self.filmstripHost.hidden && !_ws.open) ? -kFilmstripHeightPoints : 0.0;
  if (self.metaBottom.constant != bottom) self.metaBottom.constant = bottom;
  if (self.adjustBottom.constant != bottom) self.adjustBottom.constant = bottom;
  if (self.jobsBottom.constant != bottom) self.jobsBottom.constant = bottom;
}

- (void)syncCanvasGuide {
  [self syncColumnBottom];
  if (!self.canvasGuide) return;
  const CGFloat lead = _pageSidebarShown ? kPageSidebarWidthPoints : 0.0;
  if (self.canvasLeading.constant != lead) self.canvasLeading.constant = lead;
  const BOOL docked = _ws.open;
  if (self.canvasTrailingDocked.active != docked) {
    if (docked) {
      self.canvasTrailingFull.active = NO;
      self.canvasTrailingDocked.active = YES;
    } else {
      self.canvasTrailingDocked.active = NO;
      self.canvasTrailingFull.active = YES;
    }
  }
}

// The edge shows while a right pane does and nothing covers it.
- (void)syncPaneEdge {
  if (!self.paneEdge) return;
  const BOOL covered = _galleryVisible || _settingsVisible || _editorOpen;
  const BOOL pane = !self.metaHost.hidden || !self.adjustHost.hidden || !self.jobsHost.hidden ||
                    !self.editPaneHost.hidden || !self.editStripHost.hidden;
  const BOOL want = pane && !covered;
  if (self.paneEdge.hidden == !want) return;
  self.paneEdge.hidden = !want;
  [self.window invalidateCursorRectsForView:self.paneEdge];
}

// A pane's own close button (or its key) while it is the workspace's tab
// closes the workspace, not just the pane under the strip.
- (void)workspacePaneClosed:(mv::shell::edit_tab)tab {
  if (_wsSyncing || !_ws.open || _ws.tab != tab) return;
  [self editClose];
}

- (uint64_t)editGeneration {
  return _editGeneration;
}

- (void)editViewInto:(mv_edit_view*)out {
  *out = mv_edit_view{};
  const mv::shell::edit_subject subject = [self editSubject];
  out->document = [self currentItemIsDocument] ? 1 : 0;
  out->open = _ws.open ? 1 : 0;
  out->tab = static_cast<int32_t>(_ws.tab);
  out->subject = static_cast<int32_t>(subject);
  out->crop_active = _edits.crop_active() ? 1 : 0;
  out->aspect = static_cast<int32_t>(_edits.aspect());
  out->portrait = _edits.aspect_portrait() ? 1 : 0;
  out->straighten = _edits.crop_active() ? _edits.crop_angle() : _edits.export_geometry().straighten;
  out->edit_count = static_cast<int32_t>(_edits.edit_count());
  out->show_original = _compareOn || _showOriginal ? 1 : 0;
  out->compare = static_cast<int32_t>([self compareKind]);
  out->enhance = mv::shell::find_addon_command("enhance", "open") != mv::shell::command_id::none ? 1 : 0;
  const bool enhance_loaded = out->enhance != 0;
  out->wand = (_tool.tool == mv::shell::canvas_tool::remove_brush ? mv::shell::kWandBrushOn : 0) | (_brush.empty() ? 0 : mv::shell::kWandBrushStrokes) |
              (_brush.full() ? mv::shell::kWandBrushFull : 0) |
              (mv::shell::find_addon_command("enhance", "restyle") != mv::shell::command_id::none
                   ? mv::shell::kWandRestyle : 0) |
              (_eyesRunning ? mv::shell::kWandEyesBusy : 0) |
              // docs/plans/edit-refresh.md S2: the Enhance tab's cards and ✦ Auto.
              // Extend is served by Enhance's Remove model (the add-on's photo
              // choice); the faces need the AI pack (People).
              (enhance_loaded ? mv::shell::kWandExtend | mv::shell::kWandDetail : 0) |
              (mv::shell::addon_commands_available(mv::shell::addon_family::ai) ? mv::shell::kWandFacesReady : 0) |
              (_adjust.auto_enhance_on(_edits.edit_count(), _edits.colour()) ? mv::shell::kWandAutoOn : 0) |
              (_autoEnhanceToken != 0 || _autoEnhancePending ? mv::shell::kWandAutoBusy : 0) |
              (mv::shell::find_addon_command("enhance", "faces") != mv::shell::command_id::none
                   ? mv::shell::kWandRestoreFaces : 0);  // S10
  out->collapsed = [self inspectorFolded] ? 1 : 0;
  // The header's chip: a Photos-library item, or an iCloud original being fetched.
  if (!_items.empty() && _index.current() < _items.size()) {
    const std::string& path = _items[_index.current()].path_utf8;
    if (mv::shell::photos::is_key(path)) out->chips |= 1;
    if (!_photosFetchingKey.empty() && _photosFetchingKey == path) out->chips |= 2;
  }
  if (subject == mv::shell::edit_subject::still && _edits.has_item()) {
    std::uint32_t w = 0, h = 0;
    if (_lab.still_size(_itemId, &w, &h)) {
      _edits.set_size(w, h);
      const mv::edit::placement p = _edits.preview_placement();
      if (_edits.crop_active()) {
        const mv::edit::rect r = _edits.crop_overlay();
        out->crop_width = static_cast<int32_t>(std::lround(r.w * p.cropped.w));
        out->crop_height = static_cast<int32_t>(std::lround(r.h * p.cropped.h));
      } else {
        out->crop_width = static_cast<int32_t>(p.cropped.w);
        out->crop_height = static_cast<int32_t>(p.cropped.h);
      }
    }
  }
}

- (std::string)editName {
  if (_items.empty() || _index.current() >= _items.size()) return {};
  return _items[_index.current()].name_utf8;
}

- (void)editSelectTab:(int32_t)tab {
  if (tab < 0 || tab >= static_cast<int32_t>(mv::shell::edit_tab::count)) return;
  const auto t = static_cast<mv::shell::edit_tab>(tab);
  if (!mv::shell::tab_offered([self editSubject], t)) return;
  if (mv::shell::apply_step(_ws, {mv::shell::workspace_action::select, t})) [self syncWorkspace];
}

// docs/plans/edit-refresh.md S2: a click on the rail's icon for `tab` (another
// tab selects it, the active one folds the inspector, a folded rail unfolds).
- (void)editRailPick:(int32_t)tab {
  if (tab < 0 || tab >= static_cast<int32_t>(mv::shell::edit_tab::count)) return;
  const mv::shell::workspace_step step =
      mv::shell::rail_pick(_ws, [self editSubject], static_cast<mv::shell::edit_tab>(tab));
  if (mv::shell::apply_step(_ws, step)) [self syncWorkspace];
}

// The rail's and the Enhance tab's tools (EditRailView / EnhanceHubView):
// 0 Remove (the brush, on the Enhance tab), 1 Red-eye (on Adjust), 2 Faces
// (the Enhance tab), 3 Extend (the Enhance tab's card and Edit ▸ Extend Edges,
// not the rail; S6: Extend's frame on the canvas, and with
// Enhance its docked panel on Extend, S5, where Fill runs). S3: Remove and
// Red-eye are canvas tools (shell/canvas_tool.h), S8 Faces too; a second
// click on the armed one puts it down.
- (void)editTool:(int32_t)tool {
  if ([self editSubject] != mv::shell::edit_subject::still) {
    NSBeep();
    return;
  }
  using mv::shell::edit_tab;
  switch (tool) {
    case 0:
    case 1:
    case 2: {
      // S8: Faces is a canvas tool too (a box per face, the Faces panel).
      const mv::shell::canvas_tool t = tool == 0   ? mv::shell::canvas_tool::remove_brush
                                       : tool == 1 ? mv::shell::canvas_tool::red_eye
                                                   : mv::shell::canvas_tool::faces;
      if (_tool.tool == t) [self toolDown];
      else [self armTool:t];
      break;
    }
    case 3:
      // S6: Extend is a canvas tool: its frame is dragged past the photo's
      // edges (a crop-only frame needs no add-on; Fill says when one is
      // needed). With Enhance, its docked panel opens under the Extend card
      // (S5): Fill runs there, on the frame.
      if (_tool.tool == mv::shell::canvas_tool::extend) {
        [self toolDown];
      } else {
        [self armTool:mv::shell::canvas_tool::extend];
        if (_tool.tool == mv::shell::canvas_tool::extend &&
            mv::shell::find_addon_command("enhance", "open") != mv::shell::command_id::none) {
          [self enhanceTool:"extend" run:NO];
        }
      }
      break;
    default: break;
  }
}

// docs/plans/edit-refresh.md S2 (auto_enhance, the header's ✦ Auto): tone, then
// white balance, read on the pool from the working image and landed as one op.
// Right after it landed (the stack still exactly that), a click undoes it.
- (void)autoEnhance {
  if (![self adjustStill]) {
    NSBeep();
    return;
  }
  if (_adjust.auto_enhance_on(_edits.edit_count(), _edits.colour())) {
    (void)[self runEditCommand:mv::shell::command_id::undo_edit];  // one step: Auto's own
    ++_editGeneration;
    return;
  }
  if (_adjust.auto_busy()) return;
  if (!_working) {
    // The working image is not there yet (Adjust builds it): ask for it and
    // run once it lands, on this photo only (-autoEnhanceSettle).
    [self adjustBuildIf:_adjust.show(_adjust.visible(), true)];
    if (_adjust.readiness() != mv::shell::adjust_readiness::preparing) {
      NSBeep();  // it cannot be read: nothing will land
      return;
    }
    _autoEnhancePending = YES;
    _autoEnhanceItem = _adjust.item();
    ++_editGeneration;  // the header's ✦ shows it is waiting
    [self noticeShow:std::string("Preparing the photo for Auto…")];
    return;
  }
  const std::optional<std::uint64_t> token = _adjust.request_auto(mv::edit::kAutoEnhanceSections);
  if (!token) return;
  _autoEnhanceToken = *token;
  ++_editGeneration;  // the header's ✦ shows it is working
  [self bumpAdjustView];
  const std::shared_ptr<const mv::image::linear_image> working = _working;
  const mv::edit::colour current = _edits.colour();
  const std::uint64_t t = *token;
  __weak MvLabApp* weakSelf = self;
  _jobs.submit_at(mv::background_generation,
                  [working, current, t, weakSelf](const mv::job_context& ctx) -> mv::status {
                    auto r = mv::edit::compute_auto_sections(*working, current, mv::edit::kAutoEnhanceSections, &ctx);
                    const bool ok = r.has_value();
                    const mv::edit::colour value = ok ? r->value : current;
                    dispatch_async(dispatch_get_main_queue(), ^{
                      [weakSelf autoLanded:t ok:ok value:value];
                    });
                    return ok ? mv::status::ok : r.error();
                  });
}

// ✦ Auto waiting for the working image: it runs once the image is ready for
// the photo it was clicked on; when the build stopped instead (another photo,
// the pane dropped the image, it failed), the wait ends and nothing runs.
- (void)autoEnhanceSettle {
  if (!_autoEnhancePending) return;
  const bool same = _adjust.item() == _autoEnhanceItem;
  const mv::shell::adjust_readiness r = _adjust.readiness();
  if (same && r == mv::shell::adjust_readiness::preparing) return;
  _autoEnhancePending = NO;
  if (same && r == mv::shell::adjust_readiness::ready && _working) {
    [self autoEnhance];
  } else {
    ++_editGeneration;  // the header's ✦ stops waiting
  }
}

- (void)editClose {
  if (!_ws.open) return;
  _ws.open = false;
  [self syncWorkspace];
}

// docs/plans/edit-refresh.md S5 (owner call B): an Enhance tool inside the Edit
// pane. Enhance's docked panel (place "edit") opens on the photo under the
// tool's card on the Enhance tab and gets the workspace's enhance/tool
// command; `run` starts it (Remove hands the brushed dabs over first, as the
// sheet's Remove did). An Enhance without the panel opens its sheet instead.
- (void)enhanceTool:(const std::string&)photo run:(BOOL)run {
  [self enhanceTool:photo run:run faces:{}];
}

// `faces` (S8's Faces panel, Restore face): the chosen faces' boxes, x, y, w,
// h quads 0..1 of the upright photo; Enhance restores only those. Empty: every face.
- (void)enhanceTool:(const std::string&)photo run:(BOOL)run faces:(const std::vector<float>&)faces {
  if ([self editSubject] != mv::shell::edit_subject::still || _items.empty() || _index.current() >= _items.size()) {
    NSBeep();
    return;
  }
  const std::string path = _items[_index.current()].path_utf8;
  if (photo == "remove" && run) {
    if (_brush.empty()) {
      [self noticeShow:"Brush over what to remove first"];
      return;
    }
    mv::addon::media::set_still_mask(path, _brush.handoff());
  }
  // A crop draft goes into the copy, as Enhance… applies it.
  if (_edits.crop_active()) (void)[self runEditCommand:mv::shell::command_id::crop_commit];
  mv::json::writer w;
  w.begin_object().key("photo").string(photo);
  if (run) w.key("run").boolean(true);
  if (!faces.empty()) {
    w.key("faces").begin_array();
    for (const float v : faces) w.number(static_cast<double>(v));
    w.end_array();
  }
  w.end_object();
  // The panel's content width: the column less the pane's and the card's margins.
  const CGFloat column = self.rightColumnWidth ? self.rightColumnWidth.constant : kInspectorDefaultPoints;
  const CGFloat width = std::max<CGFloat>(200.0, column - 2 * 14.0 - 2 * 12.0);
  const CGFloat scale = self.window.backingScaleFactor > 0 ? self.window.backingScaleFactor : 2.0;
  const mv::status st = mv::addon::default_slots().screen_command("enhance", "tool", path, w.str(),
                                                                  static_cast<float>(width), static_cast<float>(scale));
  if (st == mv::status::ok) {
    _enhanceDockPath = path;
    const mv::shell::workspace_action a = _ws.open ? mv::shell::workspace_action::select : mv::shell::workspace_action::open;
    if (mv::shell::apply_step(_ws, {a, mv::shell::edit_tab::enhance})) [self syncWorkspace];
    ++_editGeneration;
    return;
  }
  // One-click (owner 2026-11-05): never the sheet for a photo. An Enhance
  // without the cards screen is one to update.
  [self noticeShow:mv::shell::find_addon_command("enhance", "open") == mv::shell::command_id::none
                       ? "This needs the Enhance add-on (Settings → Add-ons)."
                       : "Update Enhance (Settings → Add-ons) to run its tools here."];
}

// One-click: the Enhance tab's cards (Enhance's "tool" screen) on the photo
// on screen, opened while the tab shows. Its width is the cards' column.
- (void)enhanceCardsSync {
  if (!_ws.open || _ws.tab != mv::shell::edit_tab::enhance || [self editSubject] != mv::shell::edit_subject::still ||
      _items.empty() || _index.current() >= _items.size()) {
    return;
  }
  if (mv::shell::find_addon_command("enhance", "open") == mv::shell::command_id::none) return;
  const std::string path = _items[_index.current()].path_utf8;
  if (path == _enhanceDockPath) return;
  mv::json::writer w;
  w.begin_object().key("path").string(path).end_object();
  const CGFloat column = self.rightColumnWidth ? self.rightColumnWidth.constant : kInspectorDefaultPoints;
  const CGFloat width = std::max<CGFloat>(200.0, column - 2 * 14.0 - 2 * 12.0);
  const CGFloat scale = self.window.backingScaleFactor > 0 ? self.window.backingScaleFactor : 2.0;
  if (mv::addon::default_slots().screen_command("enhance", "tool", path, w.str(), static_cast<float>(width),
                                                static_cast<float>(scale)) == mv::status::ok) {
    _enhanceDockPath = path;
  }
}

// Another photo: on the Enhance tab the cards follow it (Enhance stops a run
// on the last one); elsewhere they close (a run stops the same way).
- (void)enhanceCardsFollow:(const std::string&)path {
  if (_enhanceDockPath.empty()) {
    [self enhanceCardsSync];  // the tab showing with nothing open yet (no add-on then)
    return;
  }
  if (_enhanceDockPath == path) return;
  if (_enhanceRun.reset(mv::shell::steady_ms(), path)) {
    [self syncToolBar];
    [self brushPublish];
  }
  if (_ws.open && _ws.tab == mv::shell::edit_tab::enhance && [self editSubject] == mv::shell::edit_subject::still) {
    [self enhanceCardsSync];
  } else {
    [self enhanceDockClose];
  }
}

// The cards' run, as the chrome read it (EnhanceRun in EnhanceHubView.swift):
// the glow over the photo while it works, the tool bar's band while it has a
// line, and its result opened once, Edit staying on the Enhance tab.
- (void)enhanceRunState:(int32_t)state run:(std::uint64_t)run result:(const std::string&)result {
  if (state < 0 || state > static_cast<int32_t>(mv::shell::enhance_run_state::downloading)) return;
  mv::shell::enhance_run_report r;
  r.state = static_cast<mv::shell::enhance_run_state>(state);
  r.id = run;
  r.result = result;
  if (r.state == mv::shell::enhance_run_state::running && _enhanceRun.glow_on_ms == 0) _enhanceRunPath = _enhanceDockPath;
  if (r.state == mv::shell::enhance_run_state::downloading && run != _enhanceRun.seen_running) {
    _enhanceRunPath = _enhanceDockPath;
  }
  const mv::shell::enhance_run_follow::step step = _enhanceRun.update(r, mv::shell::steady_ms());
  if (step.changed) {
    [self syncToolBar];
    [self brushPublish];
  }
  if (!step.open.empty()) {
    // docs/design/20 "Compare": the result compares with the photo it was made from.
    if (!_enhanceRunPath.empty()) mv::shell::note_result(step.open, _enhanceRunPath);
    // The payoff (docs/design/20 "Craft rules"): the new photo cross-fades in
    // over this one as the glow fades, in the render thread (canvas/refinement.h).
    _snap.result_fade_ms = mv::shell::steady_ms();
    [self publish];
    [self enhanceShowResult:step.open keep:YES];
  }
}

// Enhance's palette rows, the context entry and the strip's Enhance… on the
// photo on screen: the Edit pane opens on its Enhance tab (one click from
// there). NO for anything else (a clip, an audio file, several files, another
// file): Enhance's sheet takes those.
- (BOOL)enhanceOpenTabFor:(const std::vector<std::string>&)paths {
  if (_items.empty() || _index.current() >= _items.size()) return NO;
  if ([self editSubject] != mv::shell::edit_subject::still) return NO;
  const std::string& current = _items[_index.current()].path_utf8;
  if (paths.size() > 1 || (paths.size() == 1 && paths.front() != current)) return NO;
  const mv::shell::workspace_action a = _ws.open ? mv::shell::workspace_action::select : mv::shell::workspace_action::open;
  if (mv::shell::apply_step(_ws, {a, mv::shell::edit_tab::enhance})) [self syncWorkspace];
  else [self enhanceCardsSync];
  return YES;
}

// The docked panel belongs to the photo it opened on: another photo, or Edit
// closing, closes it (a run still going stops, as the sheet's does).
- (void)enhanceDockClose {
  if (_enhanceDockPath.empty()) return;
  _enhanceDockPath.clear();
  (void)mv::addon::default_slots().close_screen("enhance", "tool");
}

// The result row: Show leaves Edit and shows the new file (or library photo);
// Keep editing shows it with Edit still open on the Enhance tab. One not
// listed yet is selected by the relist that lists it (`_wantSelectedPath`):
// a new library photo is inserted beside its source once PhotoKit describes
// it (-photosAdded:source:), a file beside the original arrives with the
// folder's relist, asked for here in case the watch is slow.
- (void)enhanceShowResult:(const std::string&)path keep:(BOOL)keep {
  if (!keep) [self editClose];
  // Kept editing, the cards follow the new photo when it shows (its notice
  // stays: "Saved as …").
  if (!keep) [self enhanceDockClose];
  const bool library = mv::shell::photos::is_key(path);
  bool found = false;
  for (std::size_t i = 0; i < _items.size(); ++i) {
    if (_items[i].path_utf8 != path) continue;
    if (i != _index.current()) [self selectIndex:i];
    found = true;
    break;
  }
  if (!found) {
    const std::size_t slash = path.find_last_of('/');
    const std::string dir = slash == std::string::npos ? std::string() : path.substr(0, slash);
    if (library) {
      if (_listOpen) _wantSelectedPath = path;  // the insert's relist selects it
      [self noticeShow:std::string(mv::shell::photos::kAddedBesideNotice)];
    } else if (!_listOpen && !dir.empty() && dir == _currentDir) {
      _wantSelectedPath = path;
      _folder.relist();
    } else if (!dir.empty()) {
      [self openDir:dir select:path navigation:YES];
    }
  }
  if (keep) {
    const mv::shell::workspace_action a = _ws.open ? mv::shell::workspace_action::select : mv::shell::workspace_action::open;
    if (mv::shell::apply_step(_ws, {a, mv::shell::edit_tab::enhance})) [self syncWorkspace];
  }
}

// The Crop pane's buttons and slider: stills only, once the pixels are known.
- (BOOL)prepareStillEdit {
  if (_items.empty() || [self currentItemIsVideo] || _lab.anim_active()) return NO;
  std::uint32_t w = 0, h = 0;
  if (!_lab.still_size(_itemId, &w, &h)) return NO;
  _edits.set_size(w, h);
  return YES;
}

- (void)editSetAspect:(int32_t)aspect portrait:(BOOL)portrait {
  if (aspect < 0 || aspect >= mv::shell::kCropAspectCount || ![self prepareStillEdit]) {
    NSBeep();
    return;
  }
  [self applyEditEffect:_edits.set_crop_aspect(static_cast<mv::shell::crop_aspect>(aspect), portrait)];
}

- (void)editSetStraighten:(float)degrees {
  if (![self prepareStillEdit]) {
    NSBeep();
    return;
  }
  [self applyEditEffect:_edits.set_straighten(degrees)];
}

- (void)editCancelCrop {
  if (!_edits.crop_active()) return;
  _edits.cancel_crop();
  [self publishEdit];
  [self pokeSnapshot];
}

// Y held (and MV_EDIT_SELFTEST): the before alone while held.
- (void)editShowOriginal:(BOOL)on {
  if (on && !mv::shell::can_compare([self compareKind])) {
    // Nothing to compare: say why instead of showing the same picture.
    if (!_showOriginal) [self noticeShow:mv::shell::compare_unavailable_reason([self compareKind])];
    return;
  }
  if (_showOriginal == on) return;
  _showOriginal = on;
  ++_editGeneration;
  [self publishEdit];
  [self pokeSnapshot];
}

// ---- Compare (docs/design/20 "Compare", shell/compare_source.h) -------------

// What the photo on screen compares with: an Enhance result's source, else its
// edits, else why not.
- (mv::shell::compare_kind)compareKind {
  using mv::shell::compare_kind;
  if ([self editSubject] != mv::shell::edit_subject::still) return compare_kind::none;
  if (_compareResult != compare_kind::source && !_items.empty() && _index.current() < _items.size()) {
    // note_result may come after the open (the one-click flow): a few strings.
    mv::shell::compare_rect where;
    std::string noted = mv::shell::noted_source(_items[_index.current()].path_utf8, &where);
    if (!noted.empty()) [self compareFound:std::move(noted) rect:where];
  }
  if (_compareResult == compare_kind::source) return compare_kind::source;
  if (_edits.has_item() && _edits.edit_count() > 0) return compare_kind::edits;
  return _compareResult;
}

- (void)compareFound:(std::string)key rect:(mv::shell::compare_rect)where {
  _compareResult = mv::shell::compare_kind::source;
  _compareSourceKey = std::move(key);
  _compareSourcePath = mv::shell::photos::is_key(_compareSourceKey) ? std::string() : _compareSourceKey;
  if (_compareSourcePath.empty()) {
    const auto hit = _photosResolved.find(_compareSourceKey);
    if (hit != _photosResolved.end() && !hit->second.preview) _compareSourcePath = hit->second.path;
  }
  _compareRect = where;
  _compareToken = 0;
  ++_editGeneration;
}

// A new photo: the split goes down, and an Enhance result's source is looked
// for: the noted one, else the folder listing (no I/O: a result sorts beside
// its photo), else a stat of each candidate on a worker (a result list).
- (void)compareItemChanged:(const std::string&)path {
  using mv::shell::compare_kind;
  _compareOn = NO;
  _compareDragging = NO;
  _snap.before_split = 0.5f;
  _snap.before_hot = false;
  _snap.before_layout = static_cast<std::uint8_t>(mv::shell::result_layout(path));
  const std::uint64_t seq = ++_compareSeq;
  _compareResult = compare_kind::none;
  _compareSourceKey.clear();
  _compareSourcePath.clear();
  _compareRect = {};
  _compareToken = 0;
  mv::shell::compare_rect where;
  std::string noted = mv::shell::noted_source(path, &where);
  if (!noted.empty()) {
    [self compareFound:std::move(noted) rect:where];
    return;
  }
  if (!mv::shell::looks_like_result(path)) return;
  const std::size_t n = _items.size();
  const std::size_t at = _index.current();
  for (std::size_t d = 1; d < n; ++d) {
    // Outward from the result, so its neighbour is found first.
    const std::size_t picks[2] = {at >= d ? at - d : n, at + d};
    for (const std::size_t i : picks) {
      if (i >= n || !mv::shell::is_source_name(path, _items[i].path_utf8)) continue;
      [self compareFound:_items[i].path_utf8 rect:mv::shell::compare_rect{}];
      return;
    }
    if (at < d && at + d >= n) break;
  }
  _compareResult = compare_kind::looking;
  __weak MvLabApp* weakSelf = self;
  const std::string result = path;
  dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY, 0), ^{
    std::string found = mv::shell::source_of(result, [](const std::string& p) {
      struct stat st{};
      return ::stat(p.c_str(), &st) == 0 && S_ISREG(st.st_mode);
    });
    dispatch_async(dispatch_get_main_queue(), ^{
      MvLabApp* strongSelf = weakSelf;
      if (!strongSelf || seq != strongSelf->_compareSeq) return;  // the user has moved on
      if (found.empty()) {
        strongSelf->_compareResult = compare_kind::source_missing;
        ++strongSelf->_editGeneration;
      } else {
        [strongSelf compareFound:found rect:mv::shell::compare_rect{}];
      }
      [strongSelf comparePublish];
      [strongSelf pokeSnapshot];
    });
  });
}

// The side still for the split's before: decoded on the lab's pool (a
// Photos-library source is resolved to its file on a worker first).
- (void)compareLoadSource {
  if (_compareToken != 0 || _compareSourceKey.empty()) return;
  if (!_compareSourcePath.empty()) {
    _compareToken = _lab.load_side_still(_compareSourcePath);
    return;
  }
  if (!mv::shell::photos::is_key(_compareSourceKey)) return;
  _compareToken = ~0ull;  // asked; the resolve answers
  __weak MvLabApp* weakSelf = self;
  const std::string key = _compareSourceKey;
  const std::uint64_t seq = _compareSeq;
  _jobs.submit_at(mv::background_generation, [weakSelf, key, seq](const mv::job_context&) -> mv::status {
    auto got = mv::shell::photos::resolve(key, false);
    auto resolved = std::make_shared<std::optional<mv::shell::photos::resolved>>();
    if (got) *resolved = std::move(got).value();
    dispatch_async(dispatch_get_main_queue(), ^{
      MvLabApp* strongSelf = weakSelf;
      if (!strongSelf) return;
      if (*resolved) strongSelf->_photosResolved[key] = **resolved;
      if (seq != strongSelf->_compareSeq || strongSelf->_compareSourceKey != key) return;
      strongSelf->_compareToken = 0;
      if (!*resolved) {
        strongSelf->_compareResult = mv::shell::compare_kind::source_missing;
        strongSelf->_compareSourceKey.clear();
        strongSelf->_compareOn = NO;
        strongSelf->_showOriginal = NO;
        ++strongSelf->_editGeneration;
        [strongSelf noticeShow:"Compare: the original photo could not be read from Photos"];
      } else {
        strongSelf->_compareSourcePath = (*resolved)->path;
      }
      [strongSelf comparePublish];
      [strongSelf pokeSnapshot];
    });
    return mv::status::ok;
  });
}

// The split as the snapshot says it: the before's kind, Y held, the divider.
- (void)comparePublish {
  const mv::shell::compare_kind kind = [self compareKind];
  if (!mv::shell::can_compare(kind) || !_ws.open) _compareOn = NO;
  if (!mv::shell::can_compare(kind)) _showOriginal = NO;
  const bool show = (_compareOn || _showOriginal) && !_edits.crop_active();
  const bool by_source = kind == mv::shell::compare_kind::source;
  if (show && by_source) [self compareLoadSource];
  _snap.before_after = show ? (by_source ? 2 : 1) : 0;
  _snap.before_whole = _showOriginal;
  _snap.before_token = _compareToken;
  _snap.before_rect[0] = _compareRect.x;
  _snap.before_rect[1] = _compareRect.y;
  _snap.before_rect[2] = _compareRect.w;
  _snap.before_rect[3] = _compareRect.h;
  if (!show || _showOriginal) {
    _snap.before_hot = false;
    _compareDragging = NO;
  }
}

// The header's and the rail's Compare: the split on or off.
- (void)compareSet:(BOOL)on {
  if (on && !mv::shell::can_compare([self compareKind])) {
    [self noticeShow:mv::shell::compare_unavailable_reason([self compareKind])];
    return;
  }
  if (_compareOn == on) return;
  _compareOn = on;
  if (on) _snap.before_split = 0.5f;
  ++_editGeneration;
  [self comparePublish];
  [self pokeSnapshot];
}

- (BOOL)compareGrabX:(float)x y:(float)y {
  if (_snap.before_after == 0 || _snap.before_whole) return NO;
  if (!mv::shell::divider_hit(_lab.compare_frame_now(), x, y, _snap.dpi_scale)) return NO;
  _compareDragging = YES;
  _snap.before_hot = true;
  [self pokeSnapshot];
  return YES;
}

- (void)compareDragX:(float)x {
  if (!_compareDragging) return;
  const mv::shell::compare_frame f = _lab.compare_frame_now();
  if (!f.valid) return;
  const float split = mv::shell::split_at(f, x);
  if (split == _snap.before_split) return;
  _snap.before_split = split;
  [self pokeSnapshot];
}

- (void)compareReleaseX:(float)x y:(float)y {
  _compareDragging = NO;
  const bool over = _snap.before_after != 0 &&
                    mv::shell::divider_hit(_lab.compare_frame_now(), x, y, _snap.dpi_scale);
  if (_snap.before_hot != over) {
    _snap.before_hot = over;
    [self pokeSnapshot];
  }
}

- (BOOL)compareHoverX:(float)x y:(float)y {
  if (_compareDragging) return YES;
  const bool over = _snap.before_after != 0 && !_snap.before_whole &&
                    mv::shell::divider_hit(_lab.compare_frame_now(), x, y, _snap.dpi_scale);
  if (_snap.before_hot != over) {
    _snap.before_hot = over;
    [self pokeSnapshot];
  }
  return over ? YES : NO;
}

- (void)editSaveCopy {
  if (_edits.crop_active()) [self runEditCommand:mv::shell::command_id::crop_commit];
  [self runEditCommand:mv::shell::command_id::export_image];
}

// `[` `]` `H` `V` on a JPEG: the preview has already turned. The file is
// rewritten once the keys stop (a quick `]]` is one half-turn write), on the
// pool, never the main thread (docs/design/16 speed rule 2).
- (void)scheduleRotationWrite {
  [_rotateDebounce invalidate];
  __weak MvLabApp* weakSelf = self;
  _rotateDebounce = [NSTimer scheduledTimerWithTimeInterval:0.4
                                                    repeats:NO
                                                      block:^(NSTimer* timer) {
                                                        (void)timer;
                                                        [weakSelf startRotationWrite];
                                                      }];
}

- (void)startRotationWrite {
  _rotateDebounce = nil;
  // PR 12: a metadata write is rewriting a JPEG; wait for it (it re-keys the
  // item's edits when it lands, so the rotation then checks the new bytes).
  if (_metaWriter.in_flight()) {
    [self scheduleRotationWrite];
    return;
  }
  const std::optional<mv::shell::rotation_write> w = _edits.take_pending_write();
  if (!w) return;
  if (mv::shell::write_protected(w->path)) return;  // a turn carried onto a Photos file: never written
  const mv::shell::rotation_write job = *w;
  const std::string path = job.path;
  __weak MvLabApp* weakSelf = self;
  _jobs.submit_at(mv::background_generation, [job, path, weakSelf](const mv::job_context&) -> mv::status {
    const mv::expected written = mv::shell::run_rotation_write(job);
    const bool ok = static_cast<bool>(written);
    dispatch_async(dispatch_get_main_queue(), ^{
      [weakSelf rotationWriteFinished:ok path:path];
    });
    return ok ? mv::status::ok : written.error();
  });
}

- (void)rotationWriteFinished:(bool)ok path:(const std::string&)path {
  _edits.write_finished(ok);
  if (!ok) {
    NSBeep();
    [self publishEdit];
    [self pokeSnapshot];
    return;
  }
  // The file changed under the listing: refresh its size / mtime (the edit
  // key) the way the folder scan would, then reopen it if it is on screen.
  struct stat st{};
  if (::stat(path.c_str(), &st) == 0) {
    for (auto& entry : _items) {
      if (entry.path_utf8 != path) continue;
      entry.size = static_cast<std::uint64_t>(st.st_size);
      entry.mtime_unix = static_cast<std::int64_t>(st.st_mtimespec.tv_sec);
    }
    ++_thumbGeneration;
  }
  if (!_items.empty() && _index.current() < _items.size() &&
      _items[_index.current()].path_utf8 == path) {
    _shownItem = 0;  // the bytes changed: reload even if the second-resolution stamp did not
    [self selectIndex:_index.current()];
  }
}

- (int32_t)exportChoice {
  return _exportChoice != 0 ? _exportChoice : mv::shell::pack_export(mv::edit::export_options{});
}

- (void)setExportVisible:(BOOL)visible {
  if (visible == _exportVisible) return;
  _exportVisible = visible;
  if (visible) {
    [self cancelKeyHolds];
    NSView* container = self.window.contentView;
    self.exportHost = [MVChromeHost makeExportView];
    self.exportHost.translatesAutoresizingMaskIntoConstraints = NO;
    [container addSubview:self.exportHost];
    [NSLayoutConstraint activateConstraints:@[
      [self.exportHost.leadingAnchor constraintEqualToAnchor:container.leadingAnchor],
      [self.exportHost.trailingAnchor constraintEqualToAnchor:container.trailingAnchor],
      [self.exportHost.topAnchor constraintEqualToAnchor:container.topAnchor],
      [self.exportHost.bottomAnchor constraintEqualToAnchor:container.bottomAnchor],
    ]];
    [self.window makeFirstResponder:self.exportHost];
  } else {
    [self.exportHost removeFromSuperview];
    self.exportHost = nil;
    [self.window makeFirstResponder:self.view];
  }
}

- (void)confirmExport:(int32_t)packed {
  _exportChoice = packed;
  [self setExportVisible:NO];
  [self exportCurrentItem:mv::shell::unpack_export(packed)];
}

// ---- PR 13 / 14: trim mode, the clip tools and the Jobs pane (docs/design/08) --------
// The twin of main.cpp's block of the same name. Trim is host state over the
// clip on screen (shell/trim_state.h); the keyframe index and every job run in
// the core (abi/clip_session over edit/clip). Nothing here reads the file or
// waits on a job (rule 1).

- (std::string)currentClipPath {
  if (![self currentItemIsVideo]) return {};
  return _items[_index.current()].path_utf8;
}

- (std::int64_t)clipPositionNs {
  const auto st = _lab.video_status_snapshot();
  return st.active ? std::max<std::int64_t>(0, st.position_ns) : 0;
}

- (void)seekClipNs:(std::int64_t)t {
  _snap.video_seek_ns = std::max<std::int64_t>(0, t);
  _snap.video_seek_ms = _snap.video_seek_ns / 1'000'000;
  _snap.video_seek_exact = true;
  ++_snap.video_seek_seq;
  [self pokeSnapshot];
}

- (void)bumpTrim {
  ++_trimGeneration;
}

// P: the A-B loop over exactly what Path 1 will write; off clears it.
- (void)applyTrimPreview {
  if (_trim.previewing()) {
    const mv::edit::clip::range r = _trim.keyframe_range();
    _snap.video_loop_a_ns = r.in_ns;
    _snap.video_loop_b_ns = r.out_ns;
  } else {
    _snap.video_loop_a_ns = 0;
    _snap.video_loop_b_ns = -1;
  }
  ++_snap.video_loop_seq;
  [self pokeSnapshot];
}

// The selection moved: trim and its markers belong to the clip that was left.
- (void)trimItemChanged {
  if (_trim.path().empty()) return;
  const std::size_t i = _index.current();
  if (i < _items.size() && _items[i].path_utf8 == _trim.path()) return;
  _trim.forget();
  _trimIndexRequest = 0;
  [self bumpTrim];
}

- (BOOL)setTrimArmed:(BOOL)on {
  if (on) {
    const std::string path = [self currentClipPath];
    const auto st = _lab.video_status_snapshot();
    if (path.empty() || !st.active || !_clipJobs) return NO;
    const bool fresh = path != _trim.path();
    _trim.arm(path, st.duration_ms * 1'000'000);
    // The grid is read once per clip on a worker; it lands in -clipCompletion:.
    if ((fresh || !_trim.index_ready()) && _trimIndexRequest == 0) {
      std::uint64_t id = 0;
      if (_clipJobs->request_index(path, id) == mv::status::ok) _trimIndexRequest = id;
    }
  } else {
    const bool looping = _trim.previewing();
    _trim.disarm();
    if (looping) [self applyTrimPreview];
  }
  [self bumpTrim];
  return YES;
}

- (void)clipCompletion:(mv_completion)c {
  if (!_clipJobs) return;
  if (c.kind == MV_COMPLETION_CLIP_INDEX) {
    if (c.job_id != _trimIndexRequest) return;
    _trimIndexRequest = 0;
    std::uint32_t count = 0;
    std::int64_t duration = 0;
    if (_clipJobs->index_get(c.job_id, nullptr, 0, &count, &duration) != mv::status::ok) return;
    std::vector<std::int64_t> keyframes(count);
    if (count > 0 &&
        _clipJobs->index_get(c.job_id, keyframes.data(), count, &count, &duration) != mv::status::ok) {
      return;
    }
    keyframes.resize(std::min<std::size_t>(count, keyframes.size()));
    _trim.set_index(_trim.path(), std::move(keyframes), duration);
    if (_trim.previewing()) [self applyTrimPreview];
    [self bumpTrim];
  } else if (c.kind == MV_COMPLETION_CLIP_JOB) {
    ++_jobsGeneration;
  }
}

// Queues a job and shows the Jobs pane (without taking the keyboard); the
// pane is where it is cancelled (docs/design/08: never a modal progress dialog).
- (BOOL)submitClipJob:(const mv::edit::clip::request&)r {
  if (!_clipJobs || r.source.empty()) return NO;
  // Trims, splits and exports write beside their source: never inside a
  // Photos library (issue #72). A retry re-runs a job that got past this.
  if (r.out_dir.empty() && [self refuseWriteTo:r.source]) return NO;
  mv_clip_request q{};
  q.struct_size = sizeof(q);
  q.op = static_cast<std::uint32_t>(r.kind);
  q.in_ns = r.in_ns;
  q.out_ns = r.out_ns;
  namespace clip = mv::edit::clip;
  switch (r.kind) {
    case clip::op::rotate: q.option = r.rotate_degrees == 270 ? 2u : r.rotate_degrees == 180 ? 3u : 1u; break;
    case clip::op::remux: q.option = r.remux == clip::remux_target::mkv ? 2u : 1u; break;
    case clip::op::frame: q.option = r.frame == clip::frame_format::jpeg ? 2u : 1u; break;
    case clip::op::audio:
      q.option = r.audio == clip::audio_format::wav ? 2u : r.audio == clip::audio_format::flac ? 3u : 1u;
      break;
    case clip::op::animation: q.option = r.animation == clip::anim_format::webp ? 2u : 1u; break;
    default: break;
  }
  // PR 30: the Video Editor's pieces, flattened for the ABI (read during the call).
  std::vector<std::int64_t> flat;
  if (r.kind == clip::op::keep_ranges) {
    for (const clip::range& g : r.ranges) {
      flat.push_back(g.in_ns);
      flat.push_back(g.out_ns);
    }
    q.ranges_ns = flat.data();
    q.range_count = static_cast<std::uint32_t>(r.ranges.size());
    q.option = r.ranges_exact ? 2u : 1u;
  }
  // ABI 0.36: the Video Editor's look (its pieces' export, Save frame).
  const mv_clip_look look = mv::shell::abi_look(r.look);
  if (!r.look.identity()) q.look = &look;
  std::uint64_t job = 0;
  if (_clipJobs->submit(r.source, q, job) != mv::status::ok) {
    NSBeep();
    return YES;
  }
  ++_jobsGeneration;
  if (!_jobsVisible) [self setJobsVisible:YES focus:NO];
  return YES;
}

- (BOOL)runClipCommand:(mv::shell::command_id)command {
  using enum mv::shell::command_id;
  namespace clip = mv::edit::clip;
  const bool clip_on = [self currentItemIsVideo] && _lab.video_status_snapshot().active;
  switch (command) {
    case trim_mode: return [self setTrimArmed:!(_trim.armed() && clip_on)];
    case trim_in:
    case trim_out: {
      if (!_trim.armed()) return NO;
      const std::int64_t at = [self clipPositionNs];
      if (command == trim_in) _trim.mark_in(at);
      else _trim.mark_out(at);
      if (_trim.previewing()) [self applyTrimPreview];
      [self bumpTrim];
      return YES;
    }
    case trim_clear: {
      if (!_trim.armed()) return NO;
      const bool looping = _trim.previewing();
      _trim.clear();
      if (looping) [self applyTrimPreview];
      [self bumpTrim];
      return YES;
    }
    case trim_preview: {
      if (!_trim.armed()) return NO;
      if (!_trim.has_marker() && !_trim.previewing()) {
        NSBeep();  // nothing to preview: set `[` or `]` first
        return YES;
      }
      const bool on = _trim.toggle_preview();
      [self applyTrimPreview];
      if (on) {
        [self seekClipNs:_trim.keyframe_range().in_ns];
        if (!_lab.video_status_snapshot().playing) {
          ++_snap.anim_toggle_seq;  // Space's edge: play
          [self pokeSnapshot];
        }
      }
      [self bumpTrim];
      return YES;
    }
    case trim_keyframe:
    case trim_reencode:
    case trim_remove_middle: {
      if (!_trim.armed()) return NO;
      if (!_trim.has_marker()) {
        NSBeep();
        return YES;
      }
      const clip::op kind = command == trim_keyframe   ? clip::op::trim_keyframe
                            : command == trim_reencode ? clip::op::trim_reencode
                                                       : clip::op::remove_middle;
      return [self submitClipJob:_trim.request(kind)];
    }
    case keyframe_prev:
    case keyframe_next: {
      if (!_trim.armed() || !_trim.index_ready()) return NO;
      const std::int64_t at = [self clipPositionNs];
      const std::int64_t to = command == keyframe_prev ? _trim.prev_keyframe(at) : _trim.next_keyframe(at);
      if (to != at) [self seekClipNs:to];
      return YES;
    }
    case jobs_pane: [self setJobsVisible:!_jobsVisible]; return YES;
    case clip_tools:
      if (!clip_on) return NO;
      [self setClipToolsVisible:YES];
      return YES;
    case clip_split: {
      if (!clip_on) return NO;
      clip::request r;
      if (!mv::shell::clip_tool_request(mv::shell::pack_clip_choice(clip::op::split, 0), [self currentClipPath],
                                        [self clipPositionNs], &_trim, r)) {
        return NO;
      }
      return [self submitClipJob:r];
    }
    default: return NO;
  }
}

- (uint64_t)trimGeneration {
  return _trimGeneration;
}
- (const mv::shell::trim_state&)trim {
  return _trim;
}
- (mv::abi::clip_session*)clipJobs {
  return _clipJobs.get();
}
- (uint64_t)jobsGeneration {
  return _jobsGeneration;
}
- (BOOL)jobsVisible {
  return _jobsVisible;
}

- (void)setJobsVisible:(BOOL)visible {
  [self setJobsVisible:visible focus:visible];
}

- (void)setJobsVisible:(BOOL)visible focus:(BOOL)focus {
  if (visible == _jobsVisible) {
    if (visible && focus) [self.window makeFirstResponder:self.jobsHost];
    return;
  }
  // One right-edge pane at a time (the metadata and adjust panes' edge).
  if (visible && _metaPaneVisible) [self setMetaPaneVisible:NO];
  if (visible && _adjust.visible()) [self setAdjustVisible:NO];
  _jobsVisible = visible;
  self.jobsHost.hidden = !visible;
  [self layoutAIBadge];  // #345
  ++_jobsGeneration;
  if (!visible) [self workspacePaneClosed:mv::shell::edit_tab::jobs];
  if (visible && focus) [self.window makeFirstResponder:self.jobsHost];
  else if (!visible) [self.window makeFirstResponder:self.view];
}

- (void)jobsBlur {
  [self.window makeFirstResponder:self.view];
}

- (int32_t)clipToolFlags {
  std::int32_t flags = mv::shell::kClipFlagHasVideo | mv::shell::kClipFlagHasAudio;
  if (_trim.has_marker() && _trim.path() == [self currentClipPath]) flags |= mv::shell::kClipFlagHasRange;
  return flags;
}

- (void)setClipToolsVisible:(BOOL)visible {
  if (visible == _clipToolsVisible) return;
  _clipToolsVisible = visible;
  if (visible) {
    [self cancelKeyHolds];
    NSView* container = self.window.contentView;
    self.clipToolsHost = [MVChromeHost makeClipToolsView];
    self.clipToolsHost.translatesAutoresizingMaskIntoConstraints = NO;
    [container addSubview:self.clipToolsHost];
    [NSLayoutConstraint activateConstraints:@[
      [self.clipToolsHost.leadingAnchor constraintEqualToAnchor:container.leadingAnchor],
      [self.clipToolsHost.trailingAnchor constraintEqualToAnchor:container.trailingAnchor],
      [self.clipToolsHost.topAnchor constraintEqualToAnchor:container.topAnchor],
      [self.clipToolsHost.bottomAnchor constraintEqualToAnchor:container.bottomAnchor],
    ]];
    [self.window makeFirstResponder:self.clipToolsHost];
  } else {
    [self.clipToolsHost removeFromSuperview];
    self.clipToolsHost = nil;
    [self.window makeFirstResponder:self.view];
  }
}

- (void)confirmClipTool:(int32_t)packed {
  [self setClipToolsVisible:NO];
  mv::edit::clip::request r;
  if (![self currentItemIsVideo] ||
      !mv::shell::clip_tool_request(packed, [self currentClipPath], [self clipPositionNs], &_trim, r)) {
    NSBeep();
    return;
  }
  (void)[self submitClipJob:r];
}

// Cmd+S opens the sheet (ExportView.swift); its choice lands here as options:
// the stack baked into "<name>-edit.jpg" (or .png) beside the original, never
// over it and never over an earlier export.
- (void)exportCurrentItem:(const mv::edit::export_options&)options {
  if (_items.empty() || _index.current() >= _items.size()) return;
  const std::string path = _items[_index.current()].path_utf8;
  // A library item: its file, exported into our staging folder, then added to
  // the library as a new photo (owner 2026-11-04). Anything else protected is
  // still refused (it would save beside a library file).
  const bool library = mv::shell::photos::is_key(path);
  if (!library && [self refuseWriteTo:path]) return;
  // S0: adding needs Photos access (read-write or add-only); asked here, on
  // the click, when it was never asked.
  if (library && !mv::shell::photos::can_add()) {
    __weak MvLabApp* weakAsk = self;
    const mv::edit::export_options again = options;
    mv::shell::photos::request_add_access([weakAsk, again, path](bool granted) {
      MvLabApp* strong = weakAsk;
      if (!strong) return;
      if (granted) {
        // Only the photo the click was for: the prompt may have been
        // answered after a move to another item.
        const bool same = !strong->_items.empty() && strong->_index.current() < strong->_items.size() &&
                          strong->_items[strong->_index.current()].path_utf8 == path;
        if (same) [strong exportCurrentItem:again];
      } else {
        [strong noticeShow:std::string(mv::shell::photos::kAddRefusedNotice)];
      }
    });
    return;
  }
  const mv::edit::geometry g = _edits.export_geometry();
  const mv::edit::colour c = _edits.colour();
  const mv::edit::export_options opt = options;
  __weak MvLabApp* weakSelf = self;
  _jobs.submit_at(mv::background_generation, [path, library, g, c, opt,
                                              weakSelf](const mv::job_context& ctx) -> mv::status {
    mv::result<std::string> out = mv::err(mv::status::io);
    if (library) {
      // Read through the media hook (an iCloud original shows its progress),
      // written to the staging folder, added, and the staged file removed.
      out = mv::addon::media::save_copy_to_library(
          path,
          [&](const std::string& file, const std::string& dir) { return mv::shell::run_export(file, g, opt, c, dir); },
          &ctx);
    } else {
      // A cloud placeholder (iCloud Drive) comes down with this read: say so.
      const auto st = mv::io::stat_path(path);
      const bool fetching = st && st->cloud_placeholder;
      if (fetching) {
        dispatch_async(dispatch_get_main_queue(), ^{
          [weakSelf noticeShowUntilCleared:std::string(mv::shell::kCloudFetchNotice)];
        });
      }
      out = mv::shell::run_export(path, g, opt, c);
      if (fetching) {
        dispatch_async(dispatch_get_main_queue(), ^{
          MvLabApp* strong = weakSelf;
          if (strong && [strong noticeText] == mv::shell::kCloudFetchNotice) [strong noticeClear];
        });
      }
    }
    const bool ok = static_cast<bool>(out);
    const mv::status why = ok ? mv::status::ok : out.error();
    dispatch_async(dispatch_get_main_queue(), ^{
      if (!ok && library && why == mv::status::permission_denied) {
        [weakSelf noticeShow:std::string(mv::shell::photos::kAddRefusedNotice)];
      } else if (!ok) {
        NSBeep();
      }
      // Where it went (S0): -photosAdded:source: lists it beside this photo
      // and says so when this list holds it; otherwise this is the word. Its
      // describe job can land first: never overwrite the more exact notice.
      MvLabApp* strong = weakSelf;
      if (ok && library && strong && [strong noticeText] != mv::shell::photos::kAddedBesideNotice) {
        [strong noticeShow:std::string(mv::shell::photos::kAddedNotice)];
      }
    });
    return why;
  });
}

// ---- PR 11: macOS crash reporting, the verify's chrome crashes ----------------

// MV_CRASH_TEST=nsexception | swift_trap (crash_reporter_mac.h). Inert unless
// set. Two seconds after launch, from a run-loop timer — inside AppKit's own
// event handling, where an exception used to be swallowed — as a native call
// with its own correlation id, which the chrome report and the dump both carry.
- (void)scheduleChromeCrashTest {
  const std::string kind = mv::shell::crash::armed_chrome_test();
  if (kind.empty()) return;
  MV_LOG_WARN("crash: MV_CRASH_TEST=%s armed; the app will crash in 2 s", kind.c_str());
  const bool trap = kind == "swift_trap";
  [NSTimer scheduledTimerWithTimeInterval:2.0
                                  repeats:NO
                                    block:^(NSTimer* timer) {
                                      (void)timer;
                                      (void)mv::shell::crash::note_native_call();
                                      if (trap) [MVChromeHost crashTestSwiftTrap];
                                      else [MVChromeHost crashTestException];
                                    }];
}

// ---- PR 30: the Video Editor window (docs/design/21, owner 2026-09-26) ----------------
//
// Enter (or Edit video) on a clip opens a window of its own: the preview on
// top -- the viewer's canvas, moved in, so there is still one present path
// (rule 2) -- and the SwiftUI timeline under it (VideoEditorView). The cut
// list is shell::video_timeline; playback follows it by jumping the player
// over each cut; Export is clip::op::keep_ranges through the Jobs queue.

- (BOOL)editorOwnsCanvas {
  return _editorOpen;
}

- (uint64_t)editorGeneration {
  return _editorGeneration;
}

- (const mv::shell::video_timeline&)timeline {
  return _timeline;
}

- (const std::vector<mv::edit::clip::strip_frame>&)editorStrip {
  return _editorStrip;
}

- (const std::vector<float>&)editorPeaks {
  return _editorPeaks;
}

- (std::string)editorName {
  const std::size_t sep = _editorPath.find_last_of('/');
  return sep == std::string::npos ? _editorPath : _editorPath.substr(sep + 1);
}

- (std::int64_t)editorTimelinePosition {
  const auto st = _lab.video_status_snapshot();
  if (!st.active || !_timeline.loaded()) return 0;
  if (const auto t = _timeline.to_timeline(st.position_ns)) return *t;
  // In a cut (the jump has not landed yet): the start of the next piece.
  const std::int64_t next = _timeline.next_play_start(st.position_ns);
  if (next < 0) return _timeline.length();
  return _timeline.to_timeline(next).value_or(0);
}

- (void)editorViewInto:(mv_editor_view*)out {
  *out = mv_editor_view{};
  out->open = _editorOpen ? 1 : 0;
  out->ready = _timeline.loaded() ? 1 : 0;
  out->length_ns = _timeline.length();
  out->playhead_ns = [self editorTimelinePosition];
  const auto st = _lab.video_status_snapshot();
  out->playing = st.active && st.playing ? 1 : 0;
  out->piece_count = static_cast<int32_t>(_timeline.pieces().size());
  out->selected = _editorSelected;
  out->can_undo = _timeline.can_undo() ? 1 : 0;
  out->can_redo = _timeline.can_redo() ? 1 : 0;
  out->edited = _timeline.edited() ? 1 : 0;
  out->source_ns = _timeline.source_duration();
  out->strip_count = static_cast<int32_t>(_editorStrip.size());
  out->peak_count = static_cast<int32_t>(_editorPeaks.size());
  out->mark_in_ns = _timeline.marked_in();
  out->mark_out_ns = _timeline.marked_out();
  out->frame_rate = _editorFps;
  const mv::edit::clip::look& lk = _timeline.look();
  out->look_turns = lk.turns;
  out->look_mirror = (lk.flip_h ? 1 : 0) | (lk.flip_v ? 2 : 0);
  out->look_crop = static_cast<int32_t>(lk.crop);
  out->look_copyable = lk.copyable() ? 1 : 0;
  for (std::size_t i = 0; i < lk.light.v.size(); ++i) out->look_light[i] = lk.light.v[i];
  out->look_mute = lk.mute ? 1 : 0;
  out->look_volume = lk.volume;
  out->look_fade_in_ms = lk.fade_in_ms;
  out->look_fade_out_ms = lk.fade_out_ms;
  out->look_speed = lk.speed;
}

- (void)setEditorOpen:(BOOL)open {
  if (open == _editorOpen) {
    if (open) [self.editorWindow makeKeyAndOrderFront:nil];
    return;
  }
  if (open) {
    if ([self editSubject] != mv::shell::edit_subject::clip) {
      NSBeep();
      return;
    }
    const std::string path = [self currentClipPath];
    if (path.empty()) {
      NSBeep();
      return;
    }
    if (_ws.open) [self editClose];
    if (_trim.armed()) [self setTrimArmed:NO];
    _editorPath = path;
    _editorOpen = YES;
    _editorSelected = -1;
    _editorFps = 0;
    _editorExportedRevision = 0;
    _editorRate = 1.0;
    _shuttle.stop();
    _shuttleSkimmed = false;
    _editorStrip.clear();
    _editorPeaks.clear();
    _timeline.load(0);
    ++_editorToken;
    [self buildEditorWindow];
    [self moveCanvasToEditor:YES];
    [self editorLoadClip];
    [self editorTickResume];
    [self.editorWindow makeKeyAndOrderFront:nil];
    [self layoutAIBadge];  // #345
  } else {
    [self.editorWindow close];  // windowWillClose -> editorWindowClosed
  }
  [self editorPublishLook];
  ++_editorGeneration;
}

- (void)editorWindowClosed {
  if (!_editorOpen) return;
  [self editorSetRate:1.0];  // the viewer gets its clip back at the speed it had
  _timeline.end_trim();
  _editorOpen = NO;
  [self editorPublishLook];  // the viewer shows the clip as it is
  ++_editorToken;
  [self layoutAIBadge];  // #345
  [_editorTick invalidate];
  _editorTick = nil;
  [self moveCanvasToEditor:NO];
  self.editorWindow = nil;
  self.editorPreview = nil;
  self.editorChrome = nil;
  ++_editorGeneration;
  if (_closeAfterEditor) return;  // the viewer window is closing too (issue #181)
  [self.window makeKeyAndOrderFront:nil];
  [self.window makeFirstResponder:self.view];
}

- (void)buildEditorWindow {
  const NSRect frame = NSMakeRect(0, 0, 1180, 820);
  NSWindow* w = [[NSWindow alloc]
      initWithContentRect:frame
                styleMask:NSWindowStyleMaskTitled | NSWindowStyleMaskClosable | NSWindowStyleMaskResizable |
                          NSWindowStyleMaskMiniaturizable
                  backing:NSBackingStoreBuffered
                    defer:NO];
  w.title = [NSString stringWithFormat:@"Video Editor — %s", [self editorName].c_str()];
  w.releasedWhenClosed = NO;
  w.tabbingMode = NSWindowTabbingModeDisallowed;
  w.delegate = self;
  w.contentMinSize = NSMakeSize(720.0, 520.0);
  w.appearance = self.window.appearance;
  NSView* content = [[NSView alloc] initWithFrame:frame];
  w.contentView = content;
  NSView* preview = [[NSView alloc] initWithFrame:NSZeroRect];
  preview.translatesAutoresizingMaskIntoConstraints = NO;
  preview.wantsLayer = YES;
  preview.layer.backgroundColor = NSColor.blackColor.CGColor;
  [content addSubview:preview];
  NSView* chrome = [MVChromeHost makeVideoEditorView];
  [content addSubview:chrome];
  [NSLayoutConstraint activateConstraints:@[
    [preview.leadingAnchor constraintEqualToAnchor:content.leadingAnchor],
    [preview.trailingAnchor constraintEqualToAnchor:content.trailingAnchor],
    [preview.topAnchor constraintEqualToAnchor:content.topAnchor],
    [preview.bottomAnchor constraintEqualToAnchor:chrome.topAnchor],
    [chrome.leadingAnchor constraintEqualToAnchor:content.leadingAnchor],
    [chrome.trailingAnchor constraintEqualToAnchor:content.trailingAnchor],
    [chrome.bottomAnchor constraintEqualToAnchor:content.bottomAnchor],
    [chrome.heightAnchor constraintEqualToConstant:kEditorTimelinePoints],
  ]];
  // Beside the viewer, where there is room; the system keeps it on screen.
  NSRect main = self.window.frame;
  [w setFrameTopLeftPoint:NSMakePoint(NSMinX(main) + 40.0, NSMaxY(main) - 40.0)];
  self.editorWindow = w;
  self.editorPreview = preview;
  self.editorChrome = chrome;
  [w makeFirstResponder:chrome];
}

// The canvas is one NSView with one CAMetalLayer: it moves between the two
// windows, and the render thread keeps presenting into the same layer. syncSize
// republishes its size and insets for wherever it is now.
- (void)moveCanvasToEditor:(BOOL)toEditor {
  NSView* canvas = self.view;
  NSView* home = self.window.contentView;
  NSView* dest = toEditor ? self.editorPreview : home;
  if (dest == nil) return;
  [canvas removeFromSuperview];
  if (toEditor) {
    [dest addSubview:canvas];
  } else {
    // Back under every chrome view, where it started.
    [home addSubview:canvas positioned:NSWindowBelow relativeTo:nil];
  }
  canvas.translatesAutoresizingMaskIntoConstraints = NO;
  [NSLayoutConstraint activateConstraints:@[
    [canvas.leadingAnchor constraintEqualToAnchor:dest.leadingAnchor],
    [canvas.trailingAnchor constraintEqualToAnchor:dest.trailingAnchor],
    [canvas.topAnchor constraintEqualToAnchor:dest.topAnchor],
    [canvas.bottomAnchor constraintEqualToAnchor:dest.bottomAnchor],
  ]];
  // The viewer says where the picture went, and hides the clip's transport.
  if (toEditor) {
    if (self.canvasAwayLabel == nil) {
      NSTextField* label = [NSTextField labelWithString:@"Editing in the Video Editor window"];
      label.textColor = NSColor.secondaryLabelColor;
      label.font = [NSFont systemFontOfSize:15];
      label.translatesAutoresizingMaskIntoConstraints = NO;
      [home addSubview:label positioned:NSWindowBelow relativeTo:nil];
      [NSLayoutConstraint activateConstraints:@[
        [label.centerXAnchor constraintEqualToAnchor:home.centerXAnchor],
        [label.centerYAnchor constraintEqualToAnchor:home.centerYAnchor],
      ]];
      self.canvasAwayLabel = label;
    }
    self.canvasAwayLabel.hidden = NO;
  } else {
    self.canvasAwayLabel.hidden = YES;
  }
  self.transportHost.hidden = toEditor;
  [home layoutSubtreeIfNeeded];
  [dest layoutSubtreeIfNeeded];
  [self.view syncSize];
}

- (void)editorLoadClip {
  const std::string path = _editorPath;
  const std::uint64_t token = _editorToken;
  __weak MvLabApp* weakSelf = self;
  _jobs.submit_at(mv::background_generation, [path, token, weakSelf](const mv::job_context&) -> mv::status {
    auto info = mv::edit::clip::probe(path);
    std::int64_t duration = info ? info->duration_ns : 0;
    const double fps = info ? info->frame_rate : 0.0;
    std::vector<std::int64_t> times;
    for (int i = 0; i < kEditorThumbs && duration > 0; ++i) times.push_back(duration * i / kEditorThumbs);
    auto strip = times.empty() ? mv::result<std::vector<mv::edit::clip::strip_frame>>(
                                     mv::err(mv::status::unsupported_format))
                               : mv::edit::clip::thumbnails(path, times, kEditorThumbPx);
    auto peaks = mv::edit::clip::audio_peaks(path, kEditorPeaks);
    auto frames = std::make_shared<std::vector<mv::edit::clip::strip_frame>>(
        strip ? std::move(*strip) : std::vector<mv::edit::clip::strip_frame>{});
    auto env = std::make_shared<std::vector<float>>(peaks ? std::move(*peaks) : std::vector<float>{});
    dispatch_async(dispatch_get_main_queue(), ^{
      [weakSelf editorClipLoaded:token duration:duration fps:fps strip:frames peaks:env];
    });
    return info ? mv::status::ok : info.error();
  });
}

- (void)editorClipLoaded:(std::uint64_t)token
                duration:(std::int64_t)duration
                     fps:(double)fps
                   strip:(std::shared_ptr<std::vector<mv::edit::clip::strip_frame>>)strip
                   peaks:(std::shared_ptr<std::vector<float>>)peaks {
  if (token != _editorToken || !_editorOpen) return;  // another clip, or closed
  if (duration <= 0) {
    NSBeep();
    [self noticeShow:std::string("This clip could not be opened for editing")];
    [self setEditorOpen:NO];
    return;
  }
  _timeline.load(duration);
  _editorFps = fps > 0 && fps < 1000 ? fps : 0;
  _editorExportedRevision = _timeline.revision();
  _editorStrip = std::move(*strip);
  _editorPeaks = std::move(*peaks);
  ++_editorGeneration;
}

// 60 Hz while the editor's clip plays: playback skips what was cut, and stops
// at the end of the program. Issue #178: paused (or still opening) for
// kEditorIdleTicks in a row, the tick stops; a publish (a play key, a click,
// Now Playing) or the transport poll seeing it play starts it again.
static constexpr int kEditorIdleTicks = 30;  // half a second

- (void)editorTickResume {
  _editorIdleTicks = 0;
  if (!_editorOpen || _editorTick) return;
  __weak MvLabApp* weakSelf = self;
  _editorTick = [NSTimer scheduledTimerWithTimeInterval:1.0 / 60.0
                                                repeats:YES
                                                  block:^(NSTimer* timer) {
                                                    (void)timer;
                                                    [weakSelf editorFollowPlayback];
                                                  }];
}

- (void)editorFollowPlayback {
  const auto st = _lab.video_status_snapshot();
  if (!_editorOpen || !_timeline.loaded() || !st.active || !st.playing) {
    if (st.active && !st.playing) _editorLastSeek = -1;
    if (++_editorIdleTicks >= kEditorIdleTicks) {
      [_editorTick invalidate];
      _editorTick = nil;
    }
    return;
  }
  _editorIdleTicks = 0;
  if (!_timeline.to_timeline(st.position_ns)) ++_editorGlimpses;
  const std::int64_t lead = 20'000'000;  // a frame's worth, so a cut is not glimpsed
  const std::int64_t want = _timeline.next_play_start(st.position_ns, lead);
  if (want < 0) {
    mv_chrome_video_toggle();  // the end of the edit: pause there
    [self editorSeekSource:_timeline.pieces().back().out_ns - 1];
    return;
  }
  if (want != st.position_ns && want != _editorLastSeek) {
    _editorLastSeek = want;
    ++_editorJumps;
    [self editorSeekSource:want];
  }
}

- (void)editorSeekSource:(std::int64_t)source_ns {
  _snap.video_seek_ns = std::max<std::int64_t>(0, source_ns);
  _snap.video_seek_ms = _snap.video_seek_ns / 1'000'000;
  _snap.video_seek_exact = true;
  ++_snap.video_seek_seq;
  [self publish];
}

- (void)editorSeek:(int64_t)timeline_ns {
  if (!_timeline.loaded()) return;
  _editorLastSeek = -1;
  [self editorSeekSource:_timeline.to_source(std::clamp<std::int64_t>(timeline_ns, 0, _timeline.length()))];
  _editorSelected = static_cast<int32_t>(_timeline.piece_at(timeline_ns));
  ++_editorGeneration;
}

- (void)editorTogglePlay {
  if (!_timeline.loaded()) return;
  _shuttle.stop();
  [self editorPlayRate:1.0];
  const auto st = _lab.video_status_snapshot();
  // At the end, Play starts the program again.
  if (!st.playing && _timeline.next_play_start(st.position_ns, 20'000'000) < 0) {
    [self editorSeekSource:_timeline.pieces().front().in_ns];
  }
  mv_chrome_video_toggle();
}

- (void)editorStep:(int32_t)frames {
  mv_chrome_video_step(frames);
}

// The look's geometry on the canvas (docs/plans/video-editor-look.md); none
// once the editor closes.
- (void)editorPublishLook {
  const mv::edit::clip::look& l = _timeline.look();
  const bool on = _editorOpen && _timeline.loaded();
  _snap.video_look_turns = on ? l.turns : 0;
  _snap.video_look_mirror = on ? static_cast<std::uint8_t>((l.flip_h ? 1 : 0) | (l.flip_v ? 2 : 0)) : 0;
  _snap.video_look_crop = on ? static_cast<std::uint8_t>(l.crop) : 0;
  _snap.video_look_light = on ? l.light.v : decltype(l.light.v){};
  [self publish];
  // Its sound, in playback: the pieces place the fades (core/sound_envelope.h).
  mv::sound_envelope e;
  if (on && _timeline.sound_shaped()) {
    const std::vector<std::int64_t> flat = _timeline.flat_pieces();
    (void)e.set(flat, l.mute ? 0.0f : l.volume, static_cast<std::int64_t>(l.fade_in_ms) * 1'000'000,
                static_cast<std::int64_t>(l.fade_out_ms) * 1'000'000);
  }
  _lab.set_sound_envelope(e);
}

// A light and colour slider (param: edit::adjust_param); a drag is one undo step.
- (void)editorSetLight:(int32_t)param value:(float)value phase:(int32_t)phase {
  if (!_timeline.loaded() || param < 0 || param >= mv::edit::kAdjustParamCount) return;
  if (phase == 0) _timeline.begin_look_drag();
  mv::edit::clip::look l = _timeline.look();
  l.light.v[static_cast<std::size_t>(param)] = value;
  if (_timeline.set_look(l)) [self editorPublishLook];
  if (phase == 2) _timeline.end_look_drag();
  ++_editorGeneration;
}

// The sound: param 0 volume (0..2), 1 fade in, 2 fade out (seconds); a drag
// is one undo step.
- (void)editorSetSound:(int32_t)param value:(float)value phase:(int32_t)phase {
  if (!_timeline.loaded() || param < 0 || param > 2) return;
  if (phase == 0) _timeline.begin_look_drag();
  mv::edit::clip::look l = _timeline.look();
  if (param == 0) l.volume = value;
  if (param == 1) l.fade_in_ms = static_cast<std::int32_t>(std::lround(value * 1000.0f));
  if (param == 2) l.fade_out_ms = static_cast<std::int32_t>(std::lround(value * 1000.0f));
  if (_timeline.set_look(l)) [self editorPublishLook];
  if (phase == 2) _timeline.end_look_drag();
  ++_editorGeneration;
}

// Auto: auto tone (#289) on the frame at the playhead, read on a worker.
- (void)editorAutoLight {
  if (!_timeline.loaded() || _editorPath.empty()) return;
  const std::string path = _editorPath;
  const std::uint64_t token = _editorToken;
  const std::int64_t at_ms = _timeline.to_source([self editorTimelinePosition]) / 1'000'000;
  const mv::edit::colour current = _timeline.look().light;
  dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
    auto frame = mv::edit::clip::frame_rgb_at(path, at_ms, 512);
    bool changed = false;
    const mv::edit::colour light = frame ? mv::edit::clip::auto_light(frame->rgb, current, changed) : current;
    dispatch_async(dispatch_get_main_queue(), ^{
      if (token != self->_editorToken || !self->_editorOpen) return;  // another clip, or closed
      mv::edit::clip::look l = self->_timeline.look();
      l.light = light;
      if (!changed || !self->_timeline.set_look(l)) {
        NSBeep();  // a flat frame, or one that already fills the range
        return;
      }
      [self editorPublishLook];
      ++self->_editorGeneration;
    });
  });
}

// The frame at the playhead as a JPEG beside the clip, with the look's turn,
// mirror and crop (op::frame in the helper; the Jobs pane shows it).
- (void)editorSaveFrame {
  if (!_timeline.loaded() || _editorPath.empty()) return;
  mv::edit::clip::request r;
  r.kind = mv::edit::clip::op::frame;
  r.source = _editorPath;
  r.in_ns = _timeline.to_source([self editorTimelinePosition]);
  r.frame = mv::edit::clip::frame_format::jpeg;
  r.look = _timeline.look();
  (void)[self submitClipJob:r];
}

// what: 1 split at the playhead, 2 delete (the marked range, else the
// selected piece), 3 set in, 4 set out, 5 undo, 6 redo, 14 mark in, 15 mark
// out, 16 clear the marks; the look: 17 turn left, 18 turn right, 19 mirror
// left-right, 20 mirror upside down, 21-26 crop original / 16:9 / 9:16 / 1:1 /
// 4:3 / 4:5, 27 save the frame. The numbers are Windows' chrome_editor_action.
- (void)editorEdit:(int32_t)what {
  if (!_timeline.loaded()) return;
  const std::int64_t at = [self editorTimelinePosition];
  bool changed = false;
  switch (what) {
    case 1: changed = _timeline.split(at); if (changed) _editorSelected = static_cast<int32_t>(_timeline.piece_at(at)); break;
    case 2:
      if (_timeline.has_marks()) {  // a marked range first, as in every editor
        const std::int64_t from = std::max<std::int64_t>(0, _timeline.marked_in());
        changed = _timeline.remove_marked();
        if (changed) [self editorSeek:std::min(from, _timeline.length())];
        break;
      }
      if (_editorSelected < 0) _editorSelected = static_cast<int32_t>(_timeline.piece_at(at));
      changed = _timeline.remove(static_cast<std::size_t>(_editorSelected));
      if (changed) {
        _editorSelected = std::min<int32_t>(_editorSelected, static_cast<int32_t>(_timeline.pieces().size()) - 1);
        [self editorSeek:_timeline.piece_start(static_cast<std::size_t>(_editorSelected))];
      }
      break;
    case 3: changed = _timeline.set_in(at); if (changed) [self editorSeek:0]; break;
    case 4: changed = _timeline.set_out(at); break;
    case 5: changed = _timeline.undo(); break;
    case 6: changed = _timeline.redo(); break;
    // Marks change no piece: they never beep and never count as an edit.
    case 14: _timeline.mark_in(at); ++_editorGeneration; return;
    case 15: _timeline.mark_out(at); ++_editorGeneration; return;
    case 16:
      if (!_timeline.has_marks()) NSBeep();
      _timeline.clear_marks();
      ++_editorGeneration;
      return;
    case 17:
    case 18:
    case 19:
    case 20:
    case 21:
    case 22:
    case 23:
    case 24:
    case 25:
    case 26: {
      mv::edit::clip::look l = _timeline.look();
      if (what == 17) l.turns = static_cast<std::uint8_t>((l.turns + 3) & 3);
      if (what == 18) l.turns = static_cast<std::uint8_t>((l.turns + 1) & 3);
      if (what == 19) l.flip_h = !l.flip_h;
      if (what == 20) l.flip_v = !l.flip_v;
      if (what >= 21) l.crop = static_cast<mv::edit::clip::crop_ratio>(what - 21);
      changed = _timeline.set_look(l);
      break;
    }
    case 27: [self editorSaveFrame]; return;
    case 28: [self editorAutoLight]; return;
    case 30: {
      mv::edit::clip::look l = _timeline.look();
      l.mute = !l.mute;
      changed = _timeline.set_look(l);
      break;
    }
    case 31:
    case 32:
    case 33: {
      // The speed: 0.5x, 1x, 2x. Playback follows at once.
      mv::edit::clip::look l = _timeline.look();
      l.speed = what == 31 ? 0.5f : what == 32 ? 1.0f : 2.0f;
      changed = _timeline.set_look(l);
      if (changed) [self editorPlayRate:_shuttle.rate()];
      break;
    }
    case 29: {
      mv::edit::clip::look l = _timeline.look();
      l.light = {};
      changed = _timeline.set_look(l);
      break;
    }
    default: break;
  }
  [self editorPublishLook];
  if (!changed) NSBeep();
  if (_editorSelected >= static_cast<int32_t>(_timeline.pieces().size())) _editorSelected = -1;
  ++_editorGeneration;
}

- (void)editorSelect:(int32_t)index {
  _editorSelected = index >= 0 && index < static_cast<int32_t>(_timeline.pieces().size()) ? index : -1;
  ++_editorGeneration;
}

// A piece's edge dragged on the timeline (edge 0 in, 1 out). The preview shows
// the frame at the edge: a keyframe seek while it moves, the exact frame on
// release, as the viewer's scrubber does.
- (BOOL)editorTrimBegin:(int32_t)index edge:(int32_t)edge {
  if (!_timeline.loaded() || index < 0) return NO;
  const auto which = edge == 0 ? mv::shell::video_timeline::edge::in : mv::shell::video_timeline::edge::out;
  if (!_timeline.begin_trim(static_cast<std::size_t>(index), which)) return NO;
  _editorTrimEdge = edge;
  _editorTrimIndex = index;
  _editorSelected = index;
  const auto st = _lab.video_status_snapshot();
  if (st.playing) mv_chrome_video_toggle();
  ++_editorGeneration;
  return YES;
}

- (std::int64_t)editorEdgeFrame:(std::int64_t)at {
  // The out edge shows the last frame kept, not the first one cut.
  return _editorTrimEdge == 0 ? at : std::max<std::int64_t>(0, at - 1);
}

- (int64_t)editorTrimTo:(int64_t)source_ns {
  const std::int64_t at = _timeline.trim_to(source_ns);
  if (at < 0) return -1;
  _snap.video_seek_ns = [self editorEdgeFrame:at];
  _snap.video_seek_ms = _snap.video_seek_ns / 1'000'000;
  _snap.video_seek_exact = false;
  ++_snap.video_seek_seq;
  [self publish];
  ++_editorGeneration;
  return at;
}

- (void)editorTrimEnd {
  if (!_timeline.trimming()) return;
  _timeline.end_trim();
  const auto& pieces = _timeline.pieces();
  if (_editorTrimIndex >= 0 && static_cast<std::size_t>(_editorTrimIndex) < pieces.size()) {
    const auto& p = pieces[static_cast<std::size_t>(_editorTrimIndex)];
    [self editorSeekSource:[self editorEdgeFrame:_editorTrimEdge == 0 ? p.in_ns : p.out_ns]];
  }
  [self editorPublishLook];  // the fades follow the program's new ends
  ++_editorGeneration;
}

// The speed ladder is the viewer's (present_lab_mac.mm kLadder); the editor
// moves along it by rungs, as the viewer's speed keys do.
// The editor's playback at the edit's speed (the look, slice 4): Space and
// J K L ask for 1x, 2x, 4x of it. Leaving the editor uses editorSetRate.
- (void)editorPlayRate:(double)rate {
  [self editorSetRate:rate * static_cast<double>(_timeline.look().speed)];
}

- (void)editorSetRate:(double)rate {
  static constexpr int kRates[] = {25, 50, 100, 150, 200, 400};
  auto rung = [](int x100) {
    int best = 0;
    for (int i = 0; i < 6; ++i) {
      if (std::abs(kRates[i] - x100) < std::abs(kRates[best] - x100)) best = i;
    }
    return best;
  };
  const int want = rung(static_cast<int>(std::lround(rate * 100)));
  const int have = rung(_lab.video_status_snapshot().rate_x100);
  _editorRate = rate;
  if (want == have) return;
  _snap.video_speed_steps += want - have;
  [self publish];
}

// J K L (docs/design/16): key 0 J, 1 K, 2 L; phase 0 down, 1 auto-repeat, 2 up.
- (void)editorShuttle:(int32_t)key phase:(int32_t)phase {
  if (!_timeline.loaded()) return;
  const auto st = _lab.video_status_snapshot();
  switch (key) {
    case 0: {  // J: skim back, further on each quick press
      if (phase == 2) {
        // Let go: the keyframe skim settles on the exact frame.
        if (_shuttleSkimmed) [self editorSeekSource:_timeline.to_source(_shuttleTarget)];
        _shuttleSkimmed = false;
        return;
      }
      if (st.playing) mv_chrome_video_toggle();
      [self editorPlayRate:1.0];
      const auto now = std::chrono::duration_cast<std::chrono::nanoseconds>(
                           std::chrono::steady_clock::now().time_since_epoch()).count();
      const std::int64_t to = _shuttle.back([self editorTimelinePosition], now, phase == 1);
      _shuttleTarget = to;
      _editorLastSeek = -1;
      _snap.video_seek_ns = _timeline.to_source(to);
      _snap.video_seek_ms = _snap.video_seek_ns / 1'000'000;
      _snap.video_seek_exact = phase == 0;  // a held key skims keyframes; release settles
      _shuttleSkimmed = phase == 1;
      ++_snap.video_seek_seq;
      [self publish];
      _editorSelected = static_cast<int32_t>(_timeline.piece_at(to));
      ++_editorGeneration;
      return;
    }
    case 1:  // K: stop
      if (phase != 0) return;
      _shuttle.stop();
      if (st.playing) mv_chrome_video_toggle();
      [self editorPlayRate:1.0];
      return;
    case 2: {  // L: play, faster on each press
      if (phase != 0) return;
      const double rate = _shuttle.forward();
      [self editorPlayRate:rate];
      if (!st.playing) {
        if (_timeline.next_play_start(st.position_ns, 20'000'000) < 0) {
          [self editorSeekSource:_timeline.pieces().front().in_ns];
        }
        mv_chrome_video_toggle();
      }
      return;
    }
    default: return;
  }
}

// Done, Esc, the close button, ⌘W, Enter in the viewer: an edit that has not
// been exported since it last changed asks first. Closing it any other way
// (the self-test, another clip on the canvas) does not.
- (void)editorRequestClose {
  if (!_editorOpen) return;
  if (_editorClosePrompt) return;
  if (!_timeline.edited() || _timeline.revision() == _editorExportedRevision || self.editorWindow == nil) {
    [self setEditorOpen:NO];
    return;
  }
  NSAlert* alert = [[NSAlert alloc] init];
  alert.messageText = @"Discard this edit?";
  alert.informativeText =
      @"The edit has not been exported. Closing the Video Editor discards it; the clip itself is never changed.";
  [alert addButtonWithTitle:@"Keep editing"];
  NSButton* discard = [alert addButtonWithTitle:@"Discard"];
  discard.hasDestructiveAction = YES;
  _editorClosePrompt = YES;
  __weak MvLabApp* weakSelf = self;
  [alert beginSheetModalForWindow:self.editorWindow
                completionHandler:^(NSModalResponse response) {
                  MvLabApp* me = weakSelf;
                  if (me == nil) return;
                  me->_editorClosePrompt = NO;
                  const BOOL closeViewer = me->_closeAfterEditor;
                  if (response == NSAlertSecondButtonReturn) [me setEditorOpen:NO];
                  me->_closeAfterEditor = NO;
                  // performClose: so a kept process (#452) hides the viewer rather than closing it.
                  if (closeViewer && response == NSAlertSecondButtonReturn) [me.window performClose:nil];
                }];
}

- (BOOL)windowShouldClose:(NSWindow*)sender {
  // Issue #181: the viewer window closing clears the chrome bridge and the
  // folder, which the editor's chrome and canvas still use. The editor closes
  // first, through the discard prompt when its edit is not exported; Discard
  // then closes the viewer window, Keep editing leaves both open.
  if (sender == self.window && _editorOpen) {
    _closeAfterEditor = YES;
    [self editorRequestClose];
    if (_editorOpen) return NO;
    _closeAfterEditor = NO;
    return YES;
  }
  if (self.editorWindow != nil && sender == self.editorWindow && _editorOpen && _timeline.edited() &&
      _timeline.revision() != _editorExportedRevision) {
    [self editorRequestClose];
    return NO;
  }
  // #452: the viewer window closing while an add-on keeps the process hides
  // it instead; the process stays in the menu bar.
  if (sender == self.window && !_quitForReal && mv::addon::default_slots().keeping_alive()) {
    [self enterBackground];
    return NO;
  }
  return YES;
}

// ---- #452: in the background (docs/design/28 "In the background") ----------------------
// Off (the default) none of this runs: Quit terminates and the last window
// closing quits. On, the viewer drops what it showed (returnToWelcome: no
// clip plays, the folder and its watch close), its window is ordered out, and
// with no window left the app leaves the Dock (accessory). The add-on's own
// threads are all that run; the canvas presents nothing.

// ⌘Q (owner, 2026-10-29): Quit quits, background or not. Only closing the
// viewer window leaves the process receiving in the menu bar; a Quit that hid
// the app kept an old version running past updates and was not a quit.
- (void)quitFromMenu:(id)sender {
  (void)sender;
  _quitForReal = true;
  [NSApp terminate:nil];
}

- (void)enterBackground {
  if (_inBackground) return;
  _inBackground = true;
  if (_slideshowActive) [self leaveSlideshow];
  if ((self.window.styleMask & NSWindowStyleMaskFullScreen) != 0) [self.window toggleFullScreen:nil];
  [self returnToWelcome];
  [self.window orderOut:nil];
  [self backgroundSettle];
  [self watchBackgroundCloses];
  [self applyUpdateInBackground];
}

// After every window close while in the background: settle (the Dock icon goes
// once nothing is on screen).
- (void)watchBackgroundCloses {
  if (!_backgroundCloseWatch) {
    __weak MvLabApp* weakSelf = self;
    _backgroundCloseWatch = [NSNotificationCenter.defaultCenter
        addObserverForName:NSWindowWillCloseNotification
                    object:nil
                     queue:NSOperationQueue.mainQueue
                usingBlock:^(NSNotification*) {
                  // After the close: the window is still visible while it closes.
                  dispatch_async(dispatch_get_main_queue(), ^{
                    [weakSelf backgroundSettle];
                  });
                }];
  }
}

// No window left on screen: out of the Dock and the app switcher; the
// menu-bar item stays. A window still open (Driftwire's) keeps the Dock icon.
- (void)backgroundSettle {
  if (!_inBackground) return;
  for (NSWindow* w in NSApp.windows) {
    if (w.isVisible && w != self.window && ![w isKindOfClass:NSClassFromString(@"NSStatusBarWindow")]) return;
  }
  if (!mv::addon::default_slots().keeping_alive()) {
    // A login-item start whose add-ons are still loading: the grace decides.
    if (_backgroundStart) return;
    // Turned off while hidden: nothing keeps the process any more.
    [self quitFromBackground];
    return;
  }
  if (NSApp.activationPolicy != NSApplicationActivationPolicyAccessory) {
    [NSApp setActivationPolicy:NSApplicationActivationPolicyAccessory];
  }
}

- (void)leaveBackground {
  if (NSApp.activationPolicy != NSApplicationActivationPolicyRegular) {
    [NSApp setActivationPolicy:NSApplicationActivationPolicyRegular];
  }
  if (!_inBackground) return;
  _inBackground = false;
  // Shown: the login-item grace no longer applies, and turning the toggle off
  // after a later hide must quit (-backgroundSettle).
  _backgroundStart = false;
  [self.window makeKeyAndOrderFront:nil];
  [NSApp activateIgnoringOtherApps:YES];
}

- (void)quitFromBackground {
  _quitForReal = true;
  [NSApp terminate:nil];
}

- (void)noteUpdateAsked {
  _updateAsked = true;
}

// #532: another copy is installing an update. Quit the ordinary way once no
// add-on is busy (a Driftwire transfer finishes first).
- (void)quitForUpdateWhenIdle {
  if (_quitForReal) return;
  if (!mv::addon::default_slots().busy_what().empty()) {
    __weak MvLabApp* weakSelf = self;
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, NSEC_PER_SEC), dispatch_get_main_queue(), ^{
      [weakSelf quitForUpdateWhenIdle];
    });
    return;
  }
#if MV_WITH_SPARKLE
  if (_installUpdateNow) {
    // This copy has the update staged too. Sparkle installs it whenever this
    // copy quits, quitting every other copy (the one that asked included)
    // and relaunching none; installing it from here relaunches the app once.
    // Sparkle keeps one installer per app: when the asker staged after this
    // copy, this block does nothing, so quit the ordinary way after a moment
    // and the asker installs.
    MV_LOG_INFO("update: another MediaViewer asked; installing the staged update from here");
    void (^install)(void) = _installUpdateNow;
    _installUpdateNow = nil;
    _quitForReal = true;
    install();
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 5 * NSEC_PER_SEC), dispatch_get_main_queue(), ^{
      [NSApp terminate:nil];
    });
    return;
  }
#endif
  MV_LOG_INFO("update: another MediaViewer is installing an update; quitting");
  _quitForReal = true;
  [NSApp terminate:nil];
}

// #532: a hidden process is never quit, so "installs when you quit" never
// came. In the background with an update staged and no add-on busy (a
// Driftwire transfer waits for the next minute), install it now and come back
// in the background; the add-on takes its receiving back from the kept toggle.
- (void)applyUpdateInBackground {
#if MV_WITH_SPARKLE
  if (!_inBackground || !_installUpdateNow) return;
  bool shown = false;  // Driftwire's window, opened from the menu-bar item: the person is in it
  for (NSWindow* w in NSApp.windows) {
    if (w.isVisible && w != self.window && ![w isKindOfClass:NSClassFromString(@"NSStatusBarWindow")]) shown = true;
  }
  // Another copy still running would stay on the old version: the last one goes.
  if (shown || !mv::addon::default_slots().busy_what().empty() || MvOtherInstances().count > 0) {
    if (_backgroundUpdateRetry) return;  // one minute's retry at a time
    _backgroundUpdateRetry = true;
    __weak MvLabApp* weakSelf = self;
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 60 * NSEC_PER_SEC), dispatch_get_main_queue(), ^{
      MvLabApp* app = weakSelf;
      if (!app) return;
      app->_backgroundUpdateRetry = false;
      [app applyUpdateInBackground];
    });
    return;
  }
  MV_LOG_INFO("background: installing the staged update; starting again in the background");
  [NSUserDefaults.standardUserDefaults setBool:YES forKey:@"MVBackgroundAfterUpdate"];
  void (^install)(void) = _installUpdateNow;
  _installUpdateNow = nil;
  _quitForReal = true;
  install();  // Sparkle quits, installs, and relaunches
#endif
}

// The keep-alive list changed (the chrome's notice reader): off while hidden
// with nothing on screen quits; an add-on window opening from the menu-bar
// item or a notification brings the Dock icon back.
- (void)backgroundChanged {
  const bool kept = mv::addon::default_slots().keeping_alive();
  if (kept) _backgroundStart = false;
  [self syncLoginItem:kept];
  if (_inBackground) [self backgroundSettle];
}

// #452: the login-item start (or --background). The window was made but is
// never shown; the add-ons load as on any start, and Driftwire keeps the
// process (the menu-bar item) or, after the grace, it quits and takes its
// login item with it (the add-on is gone, or its toggle was turned off where
// this process could not see it).
- (void)startInBackground {
  _inBackground = true;
  _backgroundStart = true;
  if (NSApp.activationPolicy != NSApplicationActivationPolicyAccessory) {
    [NSApp setActivationPolicy:NSApplicationActivationPolicyAccessory];
  }
  [self watchBackgroundCloses];
  __weak MvLabApp* weakSelf = self;
  dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 60 * NSEC_PER_SEC), dispatch_get_main_queue(), ^{
    [weakSelf backgroundStartExpired];
  });
}

- (void)backgroundStartExpired {
  if (!_backgroundStart || !_inBackground) return;
  _backgroundStart = false;
  if (mv::addon::default_slots().keeping_alive()) return;
#if MV_APP_BUNDLE
  // An XPC call off the main thread; quit once it has answered.
  __weak MvLabApp* weakSelf = self;
  dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY, 0), ^{
    NSError* error = nil;
    SMAppService* app = SMAppService.mainAppService;
    if (app.status != SMAppServiceStatusNotRegistered) (void)[app unregisterAndReturnError:&error];
    dispatch_async(dispatch_get_main_queue(), ^{
      [weakSelf quitFromBackground];
    });
  });
#else
  [self quitFromBackground];
#endif
}

// #452: start at login follows the keep-alive list (SMAppService.mainApp; the
// Windows twin is shell/login_item_win.h). Only an edge counts: a window whose
// add-on never kept the process (another window, an add-on still loading)
// leaves the login item alone, and the list emptying while the app quits is
// not the person turning it off. The bundled app only: the lab binary is not
// an app LaunchServices can start at login.
- (void)syncLoginItem:(bool)kept {
  const int now = kept ? 1 : 0;
  const int was = _loginItemKept;
  _loginItemKept = now;
  if (was == now || (was == -1 && !kept)) return;
  if (_terminating || _quitForReal) return;
#if MV_APP_BUNDLE
  dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY, 0), ^{
    NSError* error = nil;
    SMAppService* app = SMAppService.mainAppService;
    if (kept) {
      if (app.status != SMAppServiceStatusEnabled) (void)[app registerAndReturnError:&error];
    } else if (app.status != SMAppServiceStatusNotRegistered) {
      (void)[app unregisterAndReturnError:&error];
    }
    if (error != nil) MV_LOG_WARN("login item: SMAppService refused (%ld)", static_cast<long>(error.code));
  });
#endif
}

- (BOOL)applicationShouldHandleReopen:(NSApplication*)sender hasVisibleWindows:(BOOL)flag {
  (void)sender;
  (void)flag;
  if (_inBackground) {
    [self leaveBackground];
    return NO;
  }
  return YES;
}

- (void)editorExport:(BOOL)exact {
  if (!_timeline.loaded() || _editorPath.empty()) return;
  if (!_timeline.edited()) {
    NSBeep();
    [self noticeShow:std::string("Nothing has been changed yet")];
    return;
  }
  if (!exact && !_timeline.look().copyable()) {
    // Packet copy carries a turn and mute only (docs/plans/video-editor-look.md).
    NSBeep();
    [self noticeShow:std::string("Crop, mirror, colour, sound and speed need Export exact")];
    return;
  }
  (void)[self submitClipJob:_timeline.export_request(_editorPath, exact)];
  _editorExportedRevision = _timeline.revision();
  [self noticeShow:exact ? std::string("Exporting the edit (exact) — see Jobs")
                         : std::string("Exporting the edit — see Jobs")];
  ++_editorGeneration;
}

// ---- docs/design/25: the open add-ons' verify rig ---------------------------------------

// MV_ADDON_SELFTEST=<folder>, launched with a .mvaddon as the path to open.
// Inert unless set. It walks what a person would: the sheet for the package,
// Install, each of its themes, Default again, a file of the installed add-on
// changed on disk (the chrome must fall back and say so), Remove; and writes
// the window as PNGs plus state.txt into <folder>, then quits. Nothing of the
// user's is touched: the add-ons install under <folder>/store and the theme
// choice is kept in memory (ThemeStore, Theme.swift).
- (void)scheduleAddonSelfTest {
  const char* dir = std::getenv("MV_ADDON_SELFTEST");
  if (dir == nullptr || *dir == '\0') return;
  NSString* out = [NSString stringWithUTF8String:dir];
  NSString* store = [out stringByAppendingPathComponent:@"store"];
  // PR 56's leg runs twice over one store (a restart in between), so its
  // second launch keeps what the first installed and chose.
  const char* pr56 = std::getenv("MV_ADDON_SELFTEST_PR56");
  const bool second = pr56 != nullptr && std::string_view(pr56) == "b";
  if (!second) {
    [[NSFileManager defaultManager] removeItemAtPath:store error:nil];
    [[NSFileManager defaultManager] removeItemAtPath:[out stringByAppendingPathComponent:@"settings"] error:nil];
    [[NSFileManager defaultManager] removeItemAtPath:[out stringByAppendingPathComponent:@"state.txt"] error:nil];
  }
  [[NSFileManager defaultManager] createDirectoryAtPath:out withIntermediateDirectories:YES attributes:nil error:nil];
  mv::io::set_open_addons_dir_override(store.UTF8String);
  mv::io::set_addon_settings_dir_override([out stringByAppendingPathComponent:@"settings"].UTF8String);
  MV_LOG_WARN("addons: MV_ADDON_SELFTEST armed; the app will quit when it is done");
  if (pr56 != nullptr) {
    [self addon56SelfTestStep:0 dir:out second:second];
    return;
  }
  [self addonSelfTestStep:0 dir:out];
}

// ---- PR 56: settings pages, keep-on-remove, key layouts (the same rig) -------------
// MV_ADDON_SELFTEST_PR56=a, launched with example.settings-demo: install, the
// page drawn and read, four values changed, read again; quit. Then =b, launched
// with example.vim-keys, over the same <folder>: the values after the restart,
// the Vim layout applied and Reset, settings-demo removed keeping its settings,
// installed again (MV_ADDON_SELFTEST_REINSTALL=<its .mvaddon>), removed without.
// Keys are never written to the person's defaults while the rig runs.

- (void)addon56Line:(NSString*)line dir:(NSString*)dir {
  [self editSelfTestLine:[line stringByAppendingString:@"\n"] dir:dir];
}

// "key=value ..." of a page as the core hands it to the hosts. [worker]
static std::string MvSelfTestPageSummary(const char* addon) {
  char buf[16384];
  const int32_t n = mv_addons_settings_page(addon, buf, sizeof buf);
  if (n <= 0) return "(no page)";
  const auto doc = mv::json::parse(std::string_view(buf, std::min<std::size_t>(n, sizeof buf - 1)));
  if (!doc) return "(unreadable)";
  std::string out;
  const mv::json::value* sections = doc->find("sections");
  for (const mv::json::value& s : sections ? sections->a : std::vector<mv::json::value>{}) {
    const mv::json::value* items = s.find("items");
    for (const mv::json::value& it : items ? items->a : std::vector<mv::json::value>{}) {
      const std::string* key = it.str("key");
      const std::string* type = it.str("type");
      const mv::json::value* v = it.find("value");
      if (!key || !type || !v) continue;
      std::string value = v->k == mv::json::kind::boolean ? (v->b ? "true" : "false")
                          : v->k == mv::json::kind::string ? "\"" + v->s + "\""
                          : v->is_integer ? std::to_string(v->i) : std::to_string(v->d);
      out += *key + "(" + *type + ")=" + value + " ";
    }
  }
  return out;
}

// The labels the live table (the one `?` and Settings read) gives a few
// commands a layout touches.
- (NSString*)addon56Keys {
  std::string table(1 << 17, '\0');
  const int32_t need = mv_chrome_command_table(table.data(), static_cast<int32_t>(table.size()));
  table.resize(std::min<std::size_t>(need > 0 ? static_cast<std::size_t>(need) : 0, table.size() - 1));
  std::string out;
  std::size_t at = 0;
  while (at < table.size()) {
    const std::size_t end = table.find('\n', at);
    const std::string line = table.substr(at, end == std::string::npos ? std::string::npos : end - at);
    at = end == std::string::npos ? table.size() : end + 1;
    std::vector<std::string> f;
    std::size_t p = 0;
    for (;;) {
      const std::size_t tab = line.find('\t', p);
      f.push_back(line.substr(p, tab == std::string::npos ? std::string::npos : tab - p));
      if (tab == std::string::npos) break;
      p = tab + 1;
    }
    if (f.size() < 4) continue;
    if (f[2] == "Previous" || f[2] == "Next" || f[2] == "Toggle mark" || f[2] == "Flip horizontal" ||
        f[2] == "Forward 10 s") {
      out += f[2] + "=" + (f[3].empty() ? std::string("(none)") : f[3]) + "; ";
    }
  }
  return [NSString stringWithUTF8String:out.c_str()];
}

- (void)addon56SelfTestStep:(int)step dir:(NSString*)dir second:(bool)second {
  BOOL done = NO;
  NSString* page = [dir stringByAppendingPathComponent:@"settings"];
  NSString* file = [page stringByAppendingPathComponent:@"example.settings-demo.json"];
  __weak MvLabApp* weakSelf = self;
  const auto pageLine = [weakSelf, dir](NSString* name) {
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
      const std::string summary = MvSelfTestPageSummary("example.settings-demo");
      dispatch_async(dispatch_get_main_queue(), ^{
        [weakSelf addon56Line:[NSString stringWithFormat:@"%@ page: %s", name, summary.c_str()] dir:dir];
      });
    });
  };
  if (!second) {
    switch (step) {
      case 0: break;
      case 1: [self addonSelfTestSnap:@"p1-sheet" dir:dir];
        (void)[MVChromeHost addonSelfTest:@"confirm" argument:@""];
        break;
      case 2: [self addonSelfTestSnap:@"p2-installed" dir:dir];
        [MVChromeHost addonSelfTestPage:@"example.settings-demo"
                                   path:[dir stringByAppendingPathComponent:@"p2-page.png"]];
        pageLine(@"p2-defaults");
        break;
      case 3: {
        dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
          std::string said;
          for (const auto& [key, value] : std::initializer_list<std::pair<const char*, const char*>>{
                   {"town_radius_km", "40"}, {"show_town", "false"}, {"label_names", "\"local\""},
                   {"home", "\"Porto\""}, {"town_radius_km", "400"}}) {
            char buf[1024];
            (void)mv_addons_setting_set("example.settings-demo", key, value, buf, sizeof buf);
            said += std::string(key) + "=" + value + " -> " + buf + " ";
          }
          dispatch_async(dispatch_get_main_queue(), ^{
            [weakSelf addon56Line:[NSString stringWithFormat:@"p3-set: %s", said.c_str()] dir:dir];
          });
        });
        break;
      }
      case 4:
        pageLine(@"p4-after-set");
        [MVChromeHost addonSelfTestPage:@"example.settings-demo"
                                   path:[dir stringByAppendingPathComponent:@"p4-page.png"]];
        break;
      default: done = YES; break;
    }
  } else {
    switch (step) {
      case 0: break;
      case 1: (void)[MVChromeHost addonSelfTest:@"confirm" argument:@""];
        break;
      case 2: {
        pageLine(@"q2-after-restart");
        [self addon56Line:[NSString stringWithFormat:@"q2-keys-before: %@", [self addon56Keys]] dir:dir];
        dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
          char pack[16384];
          const int32_t n = mv_open_addons_keymap("example.vim-keys", "vim", pack, sizeof pack);
          const std::string json(pack, n > 0 ? std::min<std::size_t>(n, sizeof pack - 1) : 0);
          dispatch_async(dispatch_get_main_queue(), ^{
            MvLabApp* strong = weakSelf;
            if (!strong) return;
            const std::string report = [strong applyKeymap:json.c_str()];
            [strong addon56Line:[NSString stringWithFormat:@"q2-apply: %s", report.c_str()] dir:dir];
          });
        });
        break;
      }
      case 3:
        [self addon56Line:[NSString stringWithFormat:@"q3-keys-after-apply: %@", [self addon56Keys]] dir:dir];
        [self resetKeys];
        break;
      case 4:
        [self addon56Line:[NSString stringWithFormat:@"q4-keys-after-reset: %@", [self addon56Keys]] dir:dir];
        [MVChromeHost addonSelfTestRemove:@"example.settings-demo" keepSettings:YES];
        break;
      case 5:
        pageLine(@"q5-removed-kept");
        [self addon56Line:[NSString stringWithFormat:@"q5-file-kept=%d",
                                                     [[NSFileManager defaultManager] fileExistsAtPath:file] ? 1 : 0]
                      dir:dir];
        if (const char* again = std::getenv("MV_ADDON_SELFTEST_REINSTALL")) {
          [MVChromeHost addonSelfTestOffer:[NSString stringWithUTF8String:again]];
        }
        break;
      case 6:
        [self addon56Line:[NSString stringWithFormat:@"q6 %@", [MVChromeHost addonSelfTest:@"confirm" argument:@""]]
                      dir:dir];
        break;
      case 7:
        [self addon56Line:[NSString stringWithFormat:@"q7 %@", [MVChromeHost addonSelfTest:@"state" argument:@""]]
                      dir:dir];
        pageLine(@"q7-installed-again");
        [MVChromeHost addonSelfTestRemove:@"example.settings-demo" keepSettings:NO];
        break;
      case 8:
        pageLine(@"q8-removed-forgotten");
        [self addon56Line:[NSString stringWithFormat:@"q8-file-kept=%d",
                                                     [[NSFileManager defaultManager] fileExistsAtPath:file] ? 1 : 0]
                      dir:dir];
        [MVChromeHost addonSelfTestRemove:@"example.vim-keys" keepSettings:NO];
        break;
      default: done = YES; break;
    }
  }
  if (done) {
    [NSApp terminate:nil];
    return;
  }
  dispatch_after(dispatch_time(DISPATCH_TIME_NOW, static_cast<int64_t>(1.5 * NSEC_PER_SEC)),
                 dispatch_get_main_queue(), ^{
                   [weakSelf addon56SelfTestStep:step + 1 dir:dir second:second];
                 });
}

- (void)addonSelfTestSnap:(NSString*)name dir:(NSString*)dir {
  NSView* v = self.window.contentView;
  [v layoutSubtreeIfNeeded];
  NSBitmapImageRep* rep = [v bitmapImageRepForCachingDisplayInRect:v.bounds];
  [v cacheDisplayInRect:v.bounds toBitmapImageRep:rep];
  NSData* png = [rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
  [png writeToFile:[dir stringByAppendingPathComponent:[name stringByAppendingString:@".png"]] atomically:YES];
  NSString* state = [MVChromeHost addonSelfTest:@"state" argument:@""];
  [self editSelfTestLine:[NSString stringWithFormat:@"%@ settings=%d home_rgb=%06x %@\n", name,
                                                    _settingsVisible ? 1 : 0, _snap.home.canvas >> 8, state]
                     dir:dir];
}

- (void)addonSelfTestStep:(int)step dir:(NSString*)dir {
  BOOL done = NO;
  NSString* addon = [MVChromeHost addonSelfTest:@"offered" argument:@""];  // its id, once inspected
  switch (step) {
    case 0: break;  // the package is inspected on a worker
    case 1: [self addonSelfTestSnap:@"a1-sheet" dir:dir];
      (void)[MVChromeHost addonSelfTest:@"confirm" argument:@""];
      break;
    case 2: [self addonSelfTestSnap:@"a2-installed" dir:dir];
      (void)[MVChromeHost addonSelfTest:@"choose-first" argument:@""];
      break;
    case 3: [self addonSelfTestSnap:@"a3-first-theme" dir:dir];
      [self setSettingsVisible:NO];
      break;
    case 4: [self addonSelfTestSnap:@"a4-first-theme-viewer" dir:dir];
      [self setSettingsVisible:YES];
      (void)[MVChromeHost addonSelfTest:@"choose-last" argument:@""];
      break;
    case 5: [self addonSelfTestSnap:@"a5-last-theme" dir:dir];
      (void)[MVChromeHost addonSelfTest:@"choose" argument:@""];
      break;
    case 6: [self addonSelfTestSnap:@"a6-default" dir:dir];
      (void)[MVChromeHost addonSelfTest:@"choose-first" argument:@""];
      break;
    case 7: {
      // One byte of an installed file changed behind the app's back.
      [self addonSelfTestSnap:@"a7-first-theme-again" dir:dir];
      NSString* root = [[dir stringByAppendingPathComponent:@"store"] stringByAppendingPathComponent:addon];
      NSDirectoryEnumerator<NSString*>* walk = [[NSFileManager defaultManager] enumeratorAtPath:root];
      for (NSString* rel in walk) {
        if (![rel.pathExtension isEqualToString:@"json"] || [rel.lastPathComponent hasPrefix:@"manifest"] ||
            [rel.lastPathComponent isEqualToString:@"publisher.json"]) {
          continue;
        }
        NSString* path = [root stringByAppendingPathComponent:rel];
        NSMutableData* bytes = [NSMutableData dataWithContentsOfFile:path];
        if (bytes.length > 0) {
          static_cast<unsigned char*>(bytes.mutableBytes)[bytes.length / 2] ^= 1;
          [bytes writeToFile:path atomically:NO];
        }
      }
      (void)[MVChromeHost addonSelfTest:@"changed" argument:@""];
      break;
    }
    case 8: [self addonSelfTestSnap:@"a8-tampered" dir:dir];
      (void)[MVChromeHost addonSelfTest:@"remove" argument:addon];
      break;
    case 9: [self addonSelfTestSnap:@"a9-removed" dir:dir];
      done = YES;
      break;
    default: done = YES; break;
  }
  if (done) {
    [NSApp terminate:nil];
    return;
  }
  __weak MvLabApp* weakSelf = self;
  dispatch_after(dispatch_time(DISPATCH_TIME_NOW, static_cast<int64_t>(1.2 * NSEC_PER_SEC)),
                 dispatch_get_main_queue(), ^{
                   [weakSelf addonSelfTestStep:step + 1 dir:dir];
                 });
}

// ---- docs/design/25 PR 57: the script add-ons' verify rig ----------------------------

// MV_SCRIPT_SELFTEST=<folder>. Inert unless set. The runner installs two add-ons
// into <folder>/store first (tools/addon-sdk, mv_addon_verify --open): the
// example Folder Count (Count files on Cmd+Shift+K, with folder.read) and a
// spinner whose Spin command (Cmd+Shift+J) never returns. The rig presses each
// key as a person would -- a key event through the app's own event queue, so
// the router, the command table and the script runtime all run -- and writes
// the notice the first one shows, the scripts' state after the second, and
// the window as PNGs into <folder>/state.txt, then quits.
- (void)scheduleScriptSelfTest {
  const char* dir = std::getenv("MV_SCRIPT_SELFTEST");
  if (dir == nullptr || *dir == '\0') return;
  NSString* out = [NSString stringWithUTF8String:dir];
  [[NSFileManager defaultManager] removeItemAtPath:[out stringByAppendingPathComponent:@"state.txt"] error:nil];
  MV_LOG_WARN("scripts: MV_SCRIPT_SELFTEST armed; the app will quit when it is done");
  [self scriptSelfTestStep:0 dir:out];
}

- (void)scriptSelfTestKey:(unsigned short)keyCode chars:(NSString*)chars {
  const NSEventModifierFlags mods = NSEventModifierFlagCommand | NSEventModifierFlagShift;
  for (NSEventType type : {NSEventTypeKeyDown, NSEventTypeKeyUp}) {
    NSEvent* e = [NSEvent keyEventWithType:type
                                  location:NSZeroPoint
                             modifierFlags:mods
                                 timestamp:[NSProcessInfo processInfo].systemUptime
                              windowNumber:self.window.windowNumber
                                   context:nil
                                characters:chars.uppercaseString
               charactersIgnoringModifiers:chars
                                 isARepeat:NO
                                   keyCode:keyCode];
    [NSApp postEvent:e atStart:NO];
  }
}

- (void)scriptSelfTestStep:(int)step dir:(NSString*)dir {
  BOOL done = NO;
  double next = 1.5;
  switch (step) {
    case 0: {
      // Wait for the scripts' rows to reach the live table (a worker lists and
      // verifies the store after launch).
      int rows = 0;
      for (int i = 0; i < mv::shell::kAddonCommandSlots; ++i) {
        const auto* row = mv::shell::addon_command(
            static_cast<mv::shell::command_id>(static_cast<int>(mv::shell::command_id::addon_cmd_0) + i));
        if (row && row->script) ++rows;
      }
      static int waited = 0;
      // ...and for the folder handed on the command line to list.
      if ((rows < 2 || _folder.item_count() == 0) && ++waited < 40) {
        [self performSelector:@selector(scriptSelfTestRetry:) withObject:dir afterDelay:0.25];
        return;
      }
      [self editSelfTestLine:[NSString stringWithFormat:@"s0 script_rows=%d folder_items=%zu\n", rows,
                                                    _folder.item_count()]
                     dir:dir];
      [self addonSelfTestSnap:@"s0-loaded" dir:dir];
      [self scriptSelfTestKey:40 chars:@"k"];  // Count files
      next = 1.0;
      break;
    }
    case 1: {
      [self editSelfTestLine:[NSString stringWithFormat:@"s1 notice=%s\n", _noticeText.c_str()] dir:dir];
      [self addonSelfTestSnap:@"s1-notice" dir:dir];
      [self scriptSelfTestKey:38 chars:@"j"];  // Spin: never returns
      next = 2.5;  // past the 1 s watchdog bound, and the viewer still answers
      break;
    }
    case 2: {
      char buf[16384] = {};
      (void)mv_open_addons_scripts(buf, static_cast<int32_t>(sizeof(buf)));
      [self editSelfTestLine:[NSString stringWithFormat:@"s2 scripts=%s\n", buf] dir:dir];
      [self setSettingsVisible:YES];
      [MVChromeHost revealOpenAddons];
      next = 2.0;
      break;
    }
    case 3: [self addonSelfTestSnap:@"s3-settings" dir:dir];
      done = YES;
      break;
    default: done = YES; break;
  }
  if (done) {
    [NSApp terminate:nil];
    return;
  }
  __weak MvLabApp* weakSelf = self;
  dispatch_after(dispatch_time(DISPATCH_TIME_NOW, static_cast<int64_t>(next * NSEC_PER_SEC)),
                 dispatch_get_main_queue(), ^{
                   [weakSelf scriptSelfTestStep:step + 1 dir:dir];
                 });
}

- (void)scriptSelfTestRetry:(NSString*)dir {
  [self scriptSelfTestStep:0 dir:dir];
}

// ---- PR 29: the Edit workspace's verify rig ------------------------------------

// MV_EDIT_SELFTEST=<folder> (docs/design/20 verify). Inert unless set. After launch it
// walks the workspace through the commands its buttons and keys run -- open,
// a 1:1 crop, apply, the Colour and Info tabs, Show original, Save copy, Esc
// -- or, on a clip, Trim and Jobs, and writes the window (the chrome; the
// Metal canvas is not in a cached display) as PNGs plus state.txt into
// <folder>, then quits. MV_EDIT_SELFTEST_DARK=1 / 0 forces Dark / Light Mode. The
// only file it writes beside the photo is Save copy's new file.
- (void)scheduleEditSelfTest {
  const char* dir = std::getenv("MV_EDIT_SELFTEST");
  if (dir == nullptr || *dir == '\0') return;
  NSString* out = [NSString stringWithUTF8String:dir];
  [[NSFileManager defaultManager] createDirectoryAtPath:out withIntermediateDirectories:YES attributes:nil error:nil];
  const char* dark = std::getenv("MV_EDIT_SELFTEST_DARK");
  if (dark != nullptr && (*dark == '0' || *dark == '1')) {
    self.window.appearance =
        [NSAppearance appearanceNamed:*dark == '1' ? NSAppearanceNameDarkAqua : NSAppearanceNameAqua];
  }
  MV_LOG_WARN("edit: MV_EDIT_SELFTEST armed; the app will quit when it is done");
  [self editSelfTestStep:0 dir:out];
}

// The colour sliders' values and the stack's length, one `adjust:` line.
- (void)editSelfTestAdjustLine:(NSString*)name dir:(NSString*)dir {
  const mv::edit::colour c = _edits.colour();
  NSMutableString* line = [NSMutableString stringWithFormat:@"    adjust %@: edits=%d auto=%d", name,
                                                            static_cast<int>(_edits.edit_count()),
                                                            _adjust.auto_running() ? 1 : 0];
  for (int i = 0; i < mv::edit::kAdjustParamCount; ++i) {
    const auto p = static_cast<mv::edit::adjust_param>(i);
    if (c.get(p) != 0.0f) [line appendFormat:@" %s=%g", mv::edit::range_of(p).name, c.get(p)];
  }
  for (int ch = 0; ch < mv::edit::kCurveChannels; ++ch) {
    if (c.curves[static_cast<std::size_t>(ch)].n > 0) [line appendFormat:@" curve%d=%d", ch, c.curves[static_cast<std::size_t>(ch)].n];
  }
  if (c.spot_count > 0) [line appendFormat:@" red_eye=%d", c.spot_count];
  [line appendString:@"\n"];
  [self editSelfTestLine:line dir:dir];
}

- (void)editSelfTestSnap:(NSString*)name dir:(NSString*)dir {
  NSView* v = self.window.contentView;
  [v layoutSubtreeIfNeeded];
  NSBitmapImageRep* rep = [v bitmapImageRepForCachingDisplayInRect:v.bounds];
  [v cacheDisplayInRect:v.bounds toBitmapImageRep:rep];
  NSData* png = [rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
  [png writeToFile:[dir stringByAppendingPathComponent:[name stringByAppendingString:@".png"]] atomically:YES];
  // The Metal canvas is not in a cached display. Where the OS still lets a
  // process read its own window (CGWindowListCreateImage, looked up at run
  // time: it is gone from newer SDKs), also write the composed window.
  using capture_fn = CGImageRef (*)(CGRect, CGWindowListOption, CGWindowID, CGWindowImageOption);
  static const auto capture = reinterpret_cast<capture_fn>(dlsym(RTLD_DEFAULT, "CGWindowListCreateImage"));
  if (capture != nullptr) {
    CGImageRef shot = capture(CGRectNull, kCGWindowListOptionIncludingWindow,
                              static_cast<CGWindowID>(self.window.windowNumber),
                              kCGWindowImageBoundsIgnoreFraming);
    if (shot != nullptr) {
      NSBitmapImageRep* full = [[NSBitmapImageRep alloc] initWithCGImage:shot];
      NSData* fpng = [full representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
      [fpng writeToFile:[dir stringByAppendingPathComponent:[name stringByAppendingString:@"-window.png"]]
             atomically:YES];
      CGImageRelease(shot);
    }
  }
  if (self.editorWindow != nil && capture != nullptr) {
    CGImageRef shot = capture(CGRectNull, kCGWindowListOptionIncludingWindow,
                              static_cast<CGWindowID>(self.editorWindow.windowNumber),
                              kCGWindowImageBoundsIgnoreFraming);
    if (shot != nullptr) {
      NSBitmapImageRep* full = [[NSBitmapImageRep alloc] initWithCGImage:shot];
      NSData* fpng = [full representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
      [fpng writeToFile:[dir stringByAppendingPathComponent:[name stringByAppendingString:@"-editor.png"]]
             atomically:YES];
      CGImageRelease(shot);
    }
  }
  mv_edit_view e;
  [self editViewInto:&e];
  __block NSString* line = [NSString
      stringWithFormat:@"%@ open=%d tab=%d subject=%d crop=%d aspect=%d portrait=%d crop_px=%dx%d edits=%d "
                       @"original=%d strip=%d pane=%d adjust=%d meta=%d jobs=%d trim=%d export=%d "
                       @"pane_pt=%d right_px=%u\n",
                       name, e.open, e.tab, e.subject, e.crop_active, e.aspect, e.portrait, e.crop_width,
                       e.crop_height, e.edit_count, e.show_original, self.editStripHost.hidden ? 0 : 1,
                       self.editPaneHost.hidden ? 0 : 1, _adjust.visible() ? 1 : 0, _metaPaneVisible ? 1 : 0,
                       _jobsVisible ? 1 : 0, _trim.armed() ? 1 : 0, self.exportHost != nil ? 1 : 0,
                       static_cast<int>(self.rightColumnWidth.constant), _snap.chrome_right_px];
  if (_editorOpen || _timeline.loaded()) {
    line = [line stringByAppendingFormat:@"    editor: open=%d pieces=%zu length_ms=%lld edited=%d strip=%zu peaks=%zu\n",
                                         _editorOpen ? 1 : 0, _timeline.pieces().size(),
                                         static_cast<long long>(_timeline.length() / 1'000'000),
                                         _timeline.edited() ? 1 : 0, _editorStrip.size(), _editorPeaks.size()];
  }
  if (const auto rec = _metaRecord) {
    std::string artist;
    for (const auto& p : rec->properties) {
      if (p.raw_tag == "Exif.Image.Artist") artist = p.value;
    }
    line = [line stringByAppendingFormat:@"    meta: date=%s artist=%s in_file=%d\n", rec->s.date_taken.c_str(),
                                         artist.c_str(), rec->writes_in_file ? 1 : 0];
  }
  NSString* log = [dir stringByAppendingPathComponent:@"state.txt"];
  NSFileHandle* fh = [NSFileHandle fileHandleForWritingAtPath:log];
  if (fh == nil) {
    [line writeToFile:log atomically:YES encoding:NSUTF8StringEncoding error:nil];
  } else {
    [fh seekToEndOfFile];
    [fh writeData:[line dataUsingEncoding:NSUTF8StringEncoding]];
    [fh closeFile];
  }
}

- (void)editSelfTestLine:(NSString*)line dir:(NSString*)dir {
  NSString* log = [dir stringByAppendingPathComponent:@"state.txt"];
  NSFileHandle* fh = [NSFileHandle fileHandleForWritingAtPath:log];
  if (fh == nil) {
    [line writeToFile:log atomically:YES encoding:NSUTF8StringEncoding error:nil];
    return;
  }
  [fh seekToEndOfFile];
  [fh writeData:[line dataUsingEncoding:NSUTF8StringEncoding]];
  [fh closeFile];
}

- (void)editSelfTestStep:(int)step dir:(NSString*)dir {
  using enum mv::shell::command_id;
  const auto kNoBack = mv::shell::back_target::none;
  const BOOL clip = [self currentItemIsVideo];
  BOOL done = NO;
  if (clip) {
    // PR 30: a clip opens the Video Editor window.
    const std::int64_t third = _timeline.length() / 3;
    switch (step) {
      case 0: break;  // let the clip load
      case 1: [self editSelfTestSnap:@"c0-viewer" dir:dir]; [self runCommand:edit_workspace back:kNoBack]; break;
      case 2: break;  // the strip is read on a worker
      case 3: [self editSelfTestSnap:@"c1-editor" dir:dir];
        if (std::getenv("MV_EDIT_SELFTEST_SOAK") != nullptr) {
          [self editorSoak:dir];
          return;
        }
        [self editorSeek:third];
        break;
      // Cut the middle third as a marked range (I, O, Delete), then drag the
      // join's incoming edge half a second later: one trim, one undo step.
      case 4: [self editorEdit:14]; [self editorSeek:2 * third]; break;
      case 5: {
        [self editorEdit:15];
        [self editorEdit:2];
        const std::int64_t cut_ms = _timeline.length() / 1'000'000;
        if (_timeline.pieces().size() == 2 && [self editorTrimBegin:1 edge:0]) {
          (void)[self editorTrimTo:_timeline.pieces()[1].in_ns + 500'000'000];
          [self editorTrimEnd];
        }
        [self editSelfTestLine:[NSString stringWithFormat:@"    polish: marked_cut_length_ms=%lld trimmed_length_ms=%lld pieces=%zu marks=%d\n",
                                                         static_cast<long long>(cut_ms),
                                                         static_cast<long long>(_timeline.length() / 1'000'000),
                                                         _timeline.pieces().size(), _timeline.has_marks() ? 1 : 0]
                          dir:dir];
        break;
      }
      case 6: [self editSelfTestSnap:@"c2-cut" dir:dir]; [self editorExport:NO]; [self editorExport:YES];
        [self editorShuttle:2 phase:0];  // L
        [self editorShuttle:2 phase:0];  // L again: 2x
        break;
      case 7:
        [self editSelfTestLine:[NSString stringWithFormat:@"    polish: shuttle_rate_x100=%d playing=%d\n",
                                                         _lab.video_status_snapshot().rate_x100,
                                                         _lab.video_status_snapshot().playing ? 1 : 0]
                          dir:dir];
        [self editorShuttle:1 phase:0];  // K
        break;
      case 8: case 9: break;  // the exports run (exact re-encodes on the GPU)
      case 10:
        // Exported: closing would not ask. An undo makes it unexported again.
        [self editSelfTestLine:[NSString stringWithFormat:@"    polish: after_k_rate_x100=%d playing=%d\n",
                                                         _lab.video_status_snapshot().rate_x100,
                                                         _lab.video_status_snapshot().playing ? 1 : 0]
                          dir:dir];
        (void)_timeline.undo();
        ++_editorGeneration;
        [self editorRequestClose];
        break;
      case 11:
        [self editSelfTestSnap:@"c3-exported" dir:dir];
        [self editSelfTestLine:[NSString stringWithFormat:@"    polish: close_asked=%d open=%d\n",
                                                         self.editorWindow.attachedSheet != nil ? 1 : 0,
                                                         _editorOpen ? 1 : 0]
                          dir:dir];
        // Discard, as the sheet's second button does.
        if (self.editorWindow.attachedSheet != nil) {
          [self.editorWindow endSheet:self.editorWindow.attachedSheet returnCode:NSAlertSecondButtonReturn];
        } else {
          [self setEditorOpen:NO];
        }
        break;
      case 12: [self editSelfTestSnap:@"c4-closed" dir:dir]; done = YES; break;
    }
  } else {
    switch (step) {
      case 0: break;  // let the photo decode
      case 1: [self editSelfTestSnap:@"s0-viewer" dir:dir]; [self runCommand:edit_workspace back:kNoBack]; break;
      case 2: [self editSelfTestSnap:@"s1-workspace" dir:dir]; [self editSetAspect:2 portrait:NO]; break;
      case 3: [self editSelfTestSnap:@"s2-crop-1x1" dir:dir]; [self runCommand:crop_commit back:kNoBack]; break;
      case 4:
        [self editSelfTestSnap:@"s3-applied" dir:dir];
        [self editSelectTab:1];
        // docs/plans/edit-refresh.md S1: the column's edge dragged to 600 through
        // the drag's own code (s4-colour shows pane_pt=600); never saved here.
        [self paneEdgeDown:nil];
        [self paneDragTo:[self paneClientPoints] - [self paneLimits].rail - 600.0];
        [self paneEdgeUp:nil];
        break;
      case 5: {
        // docs/plans/edit-adjust.md slice 1: the new sliders, then Colour's Auto.
        [self editSelfTestSnap:@"s4-colour" dir:dir];
        using mv::edit::adjust_param;
        [self adjustSet:static_cast<int32_t>(adjust_param::highlights) value:-40.0f];
        [self adjustSet:static_cast<int32_t>(adjust_param::shadows) value:40.0f];
        [self adjustSet:static_cast<int32_t>(adjust_param::vignette) value:60.0f];
        [self adjustSet:static_cast<int32_t>(adjust_param::mono) value:100.0f];
        [self adjustAuto:static_cast<int32_t>(mv::edit::adjust_section::colour)];
        break;
      }
      case 6:
        [self editSelfTestSnap:@"s4b-adjusted" dir:dir];
        [self editSelfTestAdjustLine:@"adjusted" dir:dir];
        [self adjustResetSection:static_cast<int32_t>(mv::edit::adjust_section::mono)];
        {
          // Slice 2: an S curve on the image, then Levels' Auto.
          mv::edit::curve s;
          s.n = 4;
          const float xs[] = {0.0f, 0.25f, 0.75f, 1.0f}, ys[] = {0.0f, 0.2f, 0.8f, 1.0f};
          for (int i = 0; i < 4; ++i) {
            s.x[i] = xs[i];
            s.y[i] = ys[i];
          }
          [self adjustCurve:0 curve:s];
          [self adjustAuto:static_cast<int32_t>(mv::edit::adjust_section::levels)];
        }
        break;
      case 7: {
        [self editSelfTestAdjustLine:@"mono-reset" dir:dir];
        // Slice 3: the white-balance picker and the red-eye tool clicked in
        // the middle of the view, and a selective colour band.
        const mv::shell::canvas_map map = _lab.still_map();
        [self adjustPick:1 size:0];
        [self adjustPickAtX:map.centre_x y:map.centre_y];
        [self adjustPick:2 size:0];
        [self adjustPickAtX:map.centre_x y:map.centre_y];
        [self adjustPick:0 size:0];
        [self adjustSet:static_cast<int32_t>(mv::edit::adjust_param::sel_blue_sat) value:-50.0f];
        [self adjustSet:static_cast<int32_t>(mv::edit::adjust_param::sharpen) value:40.0f];
        [self adjustSet:static_cast<int32_t>(mv::edit::adjust_param::noise) value:30.0f];
        // docs/plans/edit-refresh.md §7 S2: "a bit warmer" moves the
        // temperature one step (the prompt parser's small step).
        const float warm_before = _edits.colour().get(mv::edit::adjust_param::temperature);
        [self adjustPrompt:"a bit warmer and less noisy, more contrast"];
        const float warm_after = _edits.colour().get(mv::edit::adjust_param::temperature);
        [self editSelfTestLine:[NSString stringWithFormat:@"    prompt: %s\n", _adjust.view(_edits.colour()).prompt_note]
                          dir:dir];
        [self editSelfTestLine:[NSString stringWithFormat:@"    prompt_temperature: before=%g after=%g rose=%d\n",
                                                          warm_before, warm_after, warm_after > warm_before ? 1 : 0]
                          dir:dir];
        [self editSelfTestAdjustLine:@"picked" dir:dir];
        [self editSelfTestSnap:@"s4c-picked" dir:dir];
        [self adjustOpenEyes];  // slice 6: its note lands on the pool's answer
        break;
      }
      case 8:
        [self editSelfTestLine:[NSString stringWithFormat:@"    eyes: %s\n", _adjust.view(_edits.colour()).prompt_note]
                          dir:dir];
        // docs/plans/edit-refresh.md S2: the Enhance tab, and ✦ Auto (one op).
        [self editSelectTab:static_cast<int32_t>(mv::shell::edit_tab::enhance)];
        _selfTestEditsBeforeAuto = static_cast<int>(_edits.edit_count());
        [self autoEnhance];
        break;
      case 9: {
        [self editSelfTestSnap:@"s4d-enhance" dir:dir];
        const int after = static_cast<int>(_edits.edit_count());
        const BOOL on = _adjust.auto_enhance_on(_edits.edit_count(), _edits.colour());
        [self autoEnhance];  // a second press takes it back
        [self editSelfTestLine:[NSString stringWithFormat:@"    auto_enhance: edits_before=%d after=%d on=%d "
                                                          @"after_second_press=%d\n",
                                                          _selfTestEditsBeforeAuto, after, on ? 1 : 0,
                                                          static_cast<int>(_edits.edit_count())]
                          dir:dir];
        [self editSelectTab:2];
        // PR 29: any tag, and the date, from the Info tab.
        [self metaSetTag:"Exif.Image.Artist" value:"MV self-test"];
        [self metaSetDate:"2020-02-02 10:00:00"];
        break;
      }
      case 10: [self editSelfTestSnap:@"s5b-info-edited" dir:dir]; [self editSelectTab:0]; [self editShowOriginal:YES]; break;
      case 11: [self editSelfTestSnap:@"s6-original" dir:dir]; [self editShowOriginal:NO]; [self editSaveCopy]; break;
      case 12: [self editSelfTestSnap:@"s7-save-copy" dir:dir];
        [self confirmExport:mv::shell::pack_export(mv::edit::export_options{})];
        break;
      case 13: [self runCommand:back back:mv::shell::back_target::pane]; [self metaRevert]; break;
      case 14: [self editSelfTestSnap:@"s8-closed-reverted" dir:dir]; done = YES; break;
    }
  }
  if (done) {
    [NSApp terminate:nil];
    return;
  }
  __weak MvLabApp* weakSelf = self;
  dispatch_after(dispatch_time(DISPATCH_TIME_NOW, static_cast<int64_t>(1.2 * NSEC_PER_SEC)),
                 dispatch_get_main_queue(), ^{
                   [weakSelf editSelfTestStep:step + 1 dir:dir];
                 });
}

// MV_EDIT_SELFTEST_SOAK=<seconds> (clip only): the Video Editor's cost and seams.
// Cuts the program to three pieces with two joins, plays it through three
// times, then sits paused, then closes the editor and sits again, and writes
// the process's CPU for each phase, the ticks that saw a cut, and the jumps,
// to state.txt as one `soak:` line. Then quits.
static double mv_cpu_seconds() {
  rusage u{};
  getrusage(RUSAGE_SELF, &u);
  return static_cast<double>(u.ru_utime.tv_sec + u.ru_stime.tv_sec) +
         static_cast<double>(u.ru_utime.tv_usec + u.ru_stime.tv_usec) / 1e6;
}

// The main thread's own CPU: the chrome (SwiftUI) and the editor's ticks run
// there; decode and presents do not, so this is the UI cost on its own.
static double mv_main_cpu_seconds() {
  thread_basic_info_data_t info{};
  mach_msg_type_number_t count = THREAD_BASIC_INFO_COUNT;
  const mach_port_t self_thread = mach_thread_self();
  const kern_return_t kr =
      thread_info(self_thread, THREAD_BASIC_INFO, reinterpret_cast<thread_info_t>(&info), &count);
  mach_port_deallocate(mach_task_self(), self_thread);
  if (kr != KERN_SUCCESS) return 0;
  return static_cast<double>(info.user_time.seconds + info.system_time.seconds) +
         static_cast<double>(info.user_time.microseconds + info.system_time.microseconds) / 1e6;
}

static double mv_wall_seconds() {
  return std::chrono::duration<double>(std::chrono::steady_clock::now().time_since_epoch()).count();
}

- (void)editorSoak:(NSString*)dir {
  _soakHold = std::max(1.0, std::atof(std::getenv("MV_EDIT_SELFTEST_SOAK")));
  const std::int64_t sixth = _timeline.length() / 6;
  for (int k = 1; k <= 5; ++k) (void)_timeline.split(k * sixth);
  // Keep sixths 0, 2, 4 and 5: two cuts to jump, and the end of the program.
  for (int k : {3, 1}) (void)_timeline.remove(static_cast<std::size_t>(k));
  ++_editorGeneration;
  [self editorSoakPass:0 dir:dir];
}

- (void)editorSoakAfter:(double)seconds run:(dispatch_block_t)block {
  dispatch_after(dispatch_time(DISPATCH_TIME_NOW, static_cast<int64_t>(seconds * NSEC_PER_SEC)),
                 dispatch_get_main_queue(), block);
}

- (void)editorSoakPass:(int)pass dir:(NSString*)dir {
  const double program = static_cast<double>(_timeline.length()) / 1e9;
  __weak MvLabApp* weakSelf = self;
  // Paused at the start, whatever the viewer's autoplay left running.
  if (_lab.video_status_snapshot().playing) mv_chrome_video_toggle();
  [self editorSeek:0];
  [self editorSoakAfter:0.6 run:^{
    MvLabApp* me = weakSelf;
    if (me == nil) return;
    if (pass == 0) {
      me->_editorGlimpses = 0;
      me->_editorJumps = 0;
      me->_soakCpu0 = mv_cpu_seconds();
      me->_soakMain0 = mv_main_cpu_seconds();
      me->_soakWall0 = mv_wall_seconds();
    }
    if (!me->_lab.video_status_snapshot().playing) [me editorTogglePlay];
    [me editorSoakAfter:program + 0.8 run:^{
      MvLabApp* me2 = weakSelf;
      if (me2 == nil) return;
      if (pass + 1 < 3) {
        [me2 editorSoakPass:pass + 1 dir:dir];
        return;
      }
      me2->_soakPlayCpu = mv_cpu_seconds() - me2->_soakCpu0;
      me2->_soakPlayWall = mv_wall_seconds() - me2->_soakWall0;
      me2->_soakPlayMain = mv_main_cpu_seconds() - me2->_soakMain0;
      me2->_soakCpu0 = mv_cpu_seconds();
      me2->_soakMain0 = mv_main_cpu_seconds();
      [me2 editorSoakAfter:me2->_soakHold run:^{
        MvLabApp* me3 = weakSelf;
        if (me3 == nil) return;
        me3->_soakPausedCpu = mv_cpu_seconds() - me3->_soakCpu0;
        me3->_soakPausedMain = mv_main_cpu_seconds() - me3->_soakMain0;
        [me3 setEditorOpen:NO];
        [me3 editorSoakAfter:1.0 run:^{
          MvLabApp* me4 = weakSelf;
          if (me4 == nil) return;
          me4->_soakCpu0 = mv_cpu_seconds();
          me4->_soakMain0 = mv_main_cpu_seconds();
          [me4 editorSoakAfter:me4->_soakHold run:^{
            [weakSelf editorSoakFinish:dir program:program];
          }];
        }];
      }];
    }];
  }];
}

- (void)editorSoakFinish:(NSString*)dir program:(double)program {
  const double closed = mv_cpu_seconds() - _soakCpu0;
  const double closed_main = mv_main_cpu_seconds() - _soakMain0;
  NSString* line = [NSString
      stringWithFormat:@"soak: program_s=%.2f passes=3 hold_s=%.0f play_cpu_pct=%.1f paused_cpu_pct=%.1f "
                       @"closed_cpu_pct=%.1f main_play_pct=%.2f main_paused_pct=%.2f main_closed_pct=%.2f "
                       @"glimpse_ticks=%llu jumps=%llu\n",
                       program, _soakHold, 100.0 * _soakPlayCpu / std::max(0.001, _soakPlayWall),
                       100.0 * _soakPausedCpu / _soakHold, 100.0 * closed / _soakHold,
                       100.0 * _soakPlayMain / std::max(0.001, _soakPlayWall), 100.0 * _soakPausedMain / _soakHold,
                       100.0 * closed_main / _soakHold,
                       static_cast<unsigned long long>(_editorGlimpses),
                       static_cast<unsigned long long>(_editorJumps)];
  NSString* log = [dir stringByAppendingPathComponent:@"state.txt"];
  NSFileHandle* fh = [NSFileHandle fileHandleForWritingAtPath:log];
  if (fh == nil) {
    [line writeToFile:log atomically:YES encoding:NSUTF8StringEncoding error:nil];
  } else {
    [fh seekToEndOfFile];
    [fh writeData:[line dataUsingEncoding:NSUTF8StringEncoding]];
    [fh closeFile];
  }
  [NSApp terminate:nil];
}

// ---- PR 11: colour adjusts, the adjust pane, the FP16 working image -----------

- (BOOL)adjustStill {
  return !_items.empty() && _index.current() < _items.size() && ![self currentItemIsVideo] &&
         !_lab.anim_active() && _itemId != 0;
}

- (BOOL)adjustVisible { return _adjust.visible() ? YES : NO; }
- (uint64_t)adjustGeneration { return _adjustViewGeneration; }
- (mv::shell::adjust_view)adjustView {
  mv::shell::adjust_view v = _adjust.view(_edits.colour());
  // S3: the armed canvas tool is what a click on the photo does.
  v.picking = static_cast<std::int32_t>(mv::shell::pick_of_tool(_tool.tool));
  v.brush_strokes = static_cast<std::int32_t>(_brush.strokes());
  v.brush_full = _brush.full() ? 1 : 0;
  return v;
}
- (void)bumpAdjustView { ++_adjustViewGeneration; }

// Read, develop (a RAW: LibRaw's linear 16-bit develop — docs/design/07 waits for it,
// never the embedded preview), downscale to the preview edge, upload as an
// immutable RGBA16Float texture — all on the pool (rule 1). The same _jobs the
// lab's decode uses, so it is drained before the Metal device goes away.
- (void)startWorkingBuild:(std::uint64_t)token {
  _working.reset();
  _workingBase.reset();
  _detailShown = {};
  ++_detailToken;  // a pass for the item left is dropped when it lands
  _lab.drop_working();
  _adjustAwaitingOriginal = 0;
  if (_items.empty() || _index.current() >= _items.size()) return;
  std::string path = _items[_index.current()].path_utf8;
  if (mv::shell::photos::is_key(path)) {
    // docs/design/26 + S0: a library item's file. docs/design/07 waits for the
    // real data, as for a RAW: while only a preview is here the sliders say
    // Preparing, the original comes from iCloud (its progress in the notice),
    // and its arrival reopens the item, which builds again.
    const mv::io::dir_entry& entry = _items[_index.current()];
    path = [self fileForEntry:entry];
    if (path.empty()) {
      _adjustAwaitingOriginal = token;
      if (!_photosFetchTimer) [self fetchPhotosOriginal:entry.path_utf8];
      return;
    }
  }
  const std::uint64_t item = _itemId;
  const mv::generation gen = _adjustGen.load(std::memory_order_relaxed);
  std::atomic<mv::generation>* current = &_adjustGen;
  mv::shell::present_lab_mac* lab = &_lab;
  __weak MvLabApp* weakSelf = self;
  _jobs.submit_at(mv::background_generation, [path, item, gen, current, lab, token,
                                              weakSelf](const mv::job_context&) -> mv::status {
    const mv::job_context ctx(0, gen, current, 0);
    std::shared_ptr<const mv::image::linear_image> working;
    bool ok = false;
    bool from_raw = false;
    mv::status st = mv::status::ok;
    // S0: an evicted iCloud Drive file comes down with this read; say so.
    const auto stamp = mv::io::stat_path(path);
    const bool fetching = stamp && stamp->cloud_placeholder;
    if (fetching) {
      dispatch_async(dispatch_get_main_queue(), ^{
        [weakSelf noticeShowUntilCleared:std::string(mv::shell::kCloudFetchNotice)];
      });
    }
    auto bytes = mv::io::read_all(path);
    if (fetching) {
      dispatch_async(dispatch_get_main_queue(), ^{
        MvLabApp* strong = weakSelf;
        if (strong && [strong noticeText] == mv::shell::kCloudFetchNotice) [strong noticeClear];
      });
    }
    if (!bytes) {
      st = bytes.error();
    } else if (auto full = mv::image::decode_linear(*bytes, &ctx); !full) {
      st = full.error();
    } else if (auto preview = mv::image::downsample(*full, mv::image::kWorkingPreviewEdge, &ctx);
               !preview) {
      st = preview.error();
    } else if (ctx.cancelled()) {
      st = mv::status::cancelled;
    } else {
      from_raw = preview->from_raw;
      ok = lab->upload_working(*preview, item);
      if (ok) working = std::make_shared<const mv::image::linear_image>(std::move(preview).value());
      else st = mv::status::internal;
    }
    dispatch_async(dispatch_get_main_queue(), ^{
      [weakSelf workingLanded:token ok:ok fromRaw:from_raw working:working];
    });
    return st;
  });
}

- (void)workingLanded:(std::uint64_t)token
                   ok:(bool)ok
              fromRaw:(bool)fromRaw
              working:(std::shared_ptr<const mv::image::linear_image>)working {
  if (_adjust.working_landed(token, ok, fromRaw)) {
    _working = std::move(working);
    _workingBase = _working;
    _detailShown = {};
    [self scheduleHistogram];
    [self scheduleDetail];
  }
  [self autoEnhanceSettle];  // ✦ Auto clicked before the photo was ready
  [self bumpAdjustView];
}

// Slice 4 (edit/detail.h): when the detail sliders differ from the pass on
// the canvas, run it again on the pool once they settle, from the working
// image as built, and upload the result as the working texture. The canvas
// shows the last finished pass meanwhile.
- (void)scheduleDetail {
  if (!_workingBase) return;
  if (mv::edit::detail_of(_edits.colour()) == _detailShown) return;
  [_detailDebounce invalidate];
  __weak MvLabApp* weakSelf = self;
  _detailDebounce = [NSTimer scheduledTimerWithTimeInterval:0.15
                                                    repeats:NO
                                                      block:^(NSTimer* timer) {
                                                        (void)timer;
                                                        [weakSelf startDetail];
                                                      }];
}

- (void)startDetail {
  _detailDebounce = nil;
  if (!_workingBase) return;
  const mv::edit::detail_params d = mv::edit::detail_of(_edits.colour());
  if (d == _detailShown) return;
  const std::uint64_t token = ++_detailToken;
  const std::shared_ptr<const mv::image::linear_image> base = _workingBase;
  const std::uint64_t item = _itemId;
  const mv::generation gen = _adjustGen.load(std::memory_order_relaxed);
  std::atomic<mv::generation>* current = &_adjustGen;
  mv::shell::present_lab_mac* lab = &_lab;
  __weak MvLabApp* weakSelf = self;
  _jobs.submit_at(mv::background_generation, [base, d, item, gen, current, lab, token,
                                              weakSelf](const mv::job_context&) -> mv::status {
    const mv::job_context ctx(0, gen, current, 0);
    std::shared_ptr<const mv::image::linear_image> shown = base;
    if (!d.identity()) {
      auto out = mv::edit::apply_detail(*base, d, &ctx);
      if (!out) return out.error();
      shown = std::make_shared<const mv::image::linear_image>(std::move(out).value());
    }
    if (ctx.cancelled()) return mv::status::cancelled;
    if (!lab->upload_working(*shown, item)) return mv::status::internal;
    dispatch_async(dispatch_get_main_queue(), ^{
      [weakSelf detailLanded:token params:d working:shown];
    });
    return mv::status::ok;
  });
}

- (void)detailLanded:(std::uint64_t)token
              params:(mv::edit::detail_params)d
             working:(std::shared_ptr<const mv::image::linear_image>)working {
  if (token != _detailToken || !_workingBase) return;
  _working = std::move(working);
  _detailShown = d;
  [self pokeSnapshot];
  [self scheduleHistogram];
  [self scheduleDetail];  // a slider that moved while this ran
}

- (void)adjustBuildIf:(std::optional<std::uint64_t>)token {
  if (token) {
    _adjustGen.fetch_add(1, std::memory_order_relaxed);
    [self startWorkingBuild:*token];
  }
}

- (void)adjustItemChanged:(std::uint64_t)item {
  const bool has_colour = _edits.has_item() && !_edits.colour().identity();
  const auto before = _adjust.readiness();
  const std::optional<std::uint64_t> token = _adjust.set_item(item, has_colour);
  if (_adjust.readiness() == mv::shell::adjust_readiness::none &&
      before != mv::shell::adjust_readiness::none) {
    _adjustGen.fetch_add(1, std::memory_order_relaxed);
    _working.reset();
    _workingBase.reset();
    ++_detailToken;
    _lab.drop_working();
  }
  [self adjustBuildIf:token];
  [self autoEnhanceSettle];  // a ✦ Auto waiting for another photo ends
  [self bumpAdjustView];
}

- (void)adjustColourChanged {
  const bool has_colour = _edits.has_item() && !_edits.colour().identity();
  [self adjustBuildIf:_adjust.colour_changed(has_colour)];
  [self scheduleHistogram];
  [self scheduleDetail];
  [self bumpAdjustView];
}

- (void)scheduleHistogram {
  _adjust.histogram_dirty();
  [_histogramDebounce invalidate];
  __weak MvLabApp* weakSelf = self;
  _histogramDebounce = [NSTimer scheduledTimerWithTimeInterval:0.12
                                                       repeats:NO
                                                         block:^(NSTimer* timer) {
                                                           (void)timer;
                                                           [weakSelf startHistogram];
                                                         }];
}

- (void)startHistogram {
  _histogramDebounce = nil;
  if (!_working) return;
  const std::optional<std::uint64_t> token = _adjust.take_histogram_request();
  if (!token) return;
  const std::shared_ptr<const mv::image::linear_image> working = _working;
  const mv::edit::colour u = _edits.colour();
  const std::uint64_t t = *token;
  __weak MvLabApp* weakSelf = self;
  _jobs.submit_at(mv::background_generation, [working, u, t, weakSelf](const mv::job_context&) -> mv::status {
    auto h = mv::edit::compute_histogram(*working, u);
    if (!h) return h.error();
    const mv::edit::histogram hist = *h;
    dispatch_async(dispatch_get_main_queue(), ^{
      [weakSelf histogramLanded:t histogram:hist];
    });
    return mv::status::ok;
  });
}

- (void)histogramLanded:(std::uint64_t)token histogram:(const mv::edit::histogram&)h {
  if (_adjust.histogram_landed(token, h)) [self bumpAdjustView];
}

- (void)setAdjustVisible:(BOOL)visible {
  if (visible && ![self adjustStill]) {
    NSBeep();  // nothing to adjust: a clip, an animation, an empty window
    return;
  }
  if ((visible ? true : false) == _adjust.visible()) {
    if (visible) [self.window makeFirstResponder:self.adjustHost];
    return;
  }
  if (visible && _metaPaneVisible) [self setMetaPaneVisible:NO];
  if (visible && _jobsVisible) [self setJobsVisible:NO];
  const bool has_colour = _edits.has_item() && !_edits.colour().identity();
  [self adjustBuildIf:_adjust.show(visible, has_colour)];
  [self brushPublish];  // slice 7: the strokes show only with the pane's brush on
  if (!visible && !has_colour) {
    // Nothing on the canvas needs the working image now; a reopen rebuilds it.
    _adjustGen.fetch_add(1, std::memory_order_relaxed);
    _working.reset();
    _workingBase.reset();
    ++_detailToken;
    _lab.drop_working();
    _adjust.working_dropped();
    [self autoEnhanceSettle];  // its build went with it
  }
  self.adjustHost.hidden = !visible;
  [self layoutAIBadge];  // #345
  [self bumpAdjustView];
  if (!visible) [self workspacePaneClosed:mv::shell::edit_tab::colour];
  if (visible) {
    [self scheduleHistogram];
    [self.window makeFirstResponder:self.adjustHost];
  } else {
    [self.window makeFirstResponder:self.view];
  }
}

// A slider moved. Disabled until the working image is ready; a late one is ignored.
- (void)adjustSet:(int32_t)param value:(float)value {
  if (param < 0 || param >= mv::edit::kAdjustParamCount) return;
  if (!_adjust.working_ready() || ![self adjustStill]) return;
  if (_edits.set_adjust(static_cast<mv::edit::adjust_param>(param), value) !=
      mv::shell::edit_effect::redraw) {
    return;
  }
  [self publishEdit];
  [self pokeSnapshot];
  // No generation bump: the pane already shows the value it sent. The
  // histogram follows when the slider settles.
  const bool has_colour = !_edits.colour().identity();
  [self adjustBuildIf:_adjust.colour_changed(has_colour)];
  [self scheduleHistogram];
  [self scheduleDetail];
}

- (void)adjustReset {
  if (![self adjustStill]) return;
  if (_edits.reset_adjust() != mv::shell::edit_effect::redraw) return;
  [self publishEdit];
  [self pokeSnapshot];
  [self adjustColourChanged];
}

// Slice 2: a curve from the pane. A drag of a point is one op; no echo back
// (the pane already shows it), the histogram follows when it settles.
- (void)adjustCurve:(int32_t)channel curve:(const mv::edit::curve&)k {
  if (channel < 0 || channel >= mv::edit::kCurveChannels) return;
  if (!_adjust.working_ready() || ![self adjustStill]) return;
  if (_edits.set_curve(static_cast<mv::edit::curve_channel>(channel), k) != mv::shell::edit_effect::redraw) {
    return;
  }
  [self publishEdit];
  [self pokeSnapshot];
  const bool has_colour = !_edits.colour().identity();
  [self adjustBuildIf:_adjust.colour_changed(has_colour)];
  [self scheduleHistogram];
  [self scheduleDetail];
}

// Slice 5b (edit/prompt.h): a typed request. Its slider moves land as one
// op; the Autos it asked for run one after another (autoLanded starts the next).
// adjust_pane::prompt decides, as on Windows: a request it cannot run now
// (no still, the working image still building) is said in the note, never
// dropped without a word (owner 2026-11-05).
- (void)adjustPrompt:(const std::string&)text {
  const std::optional<mv::edit::prompt_result> r = _adjust.prompt(text, _edits.colour(), [self adjustStill]);
  if (!r) {
    [self bumpAdjustView];  // the note
    return;
  }
  if (r->changed(_edits.colour()) && _edits.set_colour(r->value) == mv::shell::edit_effect::redraw) {
    [self publishEdit];
    [self pokeSnapshot];
  }
  _pendingAutos.assign(r->autos.begin(), r->autos.end());
  [self adjustColourChanged];
  [self nextPendingAuto];
}

- (void)nextPendingAuto {
  if (_pendingAutos.empty() || _adjust.auto_running()) return;
  const mv::edit::adjust_section s = _pendingAutos.front();
  _pendingAutos.erase(_pendingAutos.begin());
  [self adjustAuto:static_cast<int32_t>(s)];
}

// Slice 6: Open closed eyes. On the pool: the frames of the same moment, the
// pack's faces and same-person donors (People data, owner 2026-11-02), then
// the transfer and a new file beside the photo. The note says what happened.
- (void)adjustOpenEyes { [self adjustFaces:0]; }

// The wand menu's faces: 0 Open closed eyes, 1 Improve faces from your photos.
// The same pack answer (the moment, then the person's other photos in People).
- (void)adjustFaces:(int32_t)mode {
  if (_eyesRunning || ![self adjustStill] || _items.empty() || _index.current() >= _items.size()) return;
  _eyesRunning = YES;
  ++_editGeneration;  // the wand menu: busy
  _adjust.set_prompt_note(mode == 1 ? "Looking through this person's photos for a better face…"
                                    : "Looking for open eyes in this person's photos…");
  [self bumpAdjustView];
  const std::string path = _items[_index.current()].path_utf8;
  __weak MvLabApp* weakSelf = self;
  _jobs.submit_at(mv::background_generation, [path, mode, weakSelf](const mv::job_context& ctx) -> mv::status {
    std::string candidates;
    for (const std::string& c : mv::addon::media::burst_neighbours(path)) candidates += c + "\n";
    auto pack = mv::addon::ai_eyes_json(path, candidates);
    mv::result<mv::addon::media::eyes_outcome> r = mv::err(pack ? mv::status::ok : pack.error());
    if (pack) {
      r = mode == 1 ? mv::addon::media::improve_faces(path, *pack, &ctx)
                    : mv::addon::media::open_closed_eyes(path, *pack, &ctx);
    }
    const mv::status ps = pack ? mv::status::ok : pack.error();
    const std::string note =
        mode == 1 ? mv::addon::media::faces_note(ps, r) : mv::addon::media::eyes_note(ps, r);
    dispatch_async(dispatch_get_main_queue(), ^{
      [weakSelf eyesLanded:note];
    });
    return mv::status::ok;
  });
}

- (void)eyesLanded:(const std::string&)note {
  _eyesRunning = NO;
  ++_editGeneration;
  _adjust.set_prompt_note(note);
  [self bumpAdjustView];
  [self noticeShow:note];  // seen on any tab (the wand menu ran it)
}

// Slice 3: what the next click on the photo does (shell::adjust_pick), from the
// Adjust pane and the wand. docs/plans/edit-refresh.md S3: the pick is a canvas
// tool now (shell/canvas_tool.h); the size travels apart (the bar, `[` `]`), so
// `size` is ignored. None puts the tool down.
- (void)adjustPick:(int32_t)mode size:(float)size {
  (void)size;
  if (mode < 0 || mode > static_cast<int32_t>(mv::shell::adjust_pick::remove)) return;
  const mv::shell::canvas_tool t = mv::shell::tool_of_pick(static_cast<mv::shell::adjust_pick>(mode));
  if (t == mv::shell::canvas_tool::none) [self toolDown];
  else [self armTool:t];
}

// ---- docs/plans/edit-refresh.md S3: canvas tools ---------------------------------

// The tool a press on the photo uses now: armed, on a still, not cropping.
- (mv::shell::canvas_tool)activeTool {
  if (_tool.tool == mv::shell::canvas_tool::none || ![self adjustStill] || _edits.crop_active()) {
    return mv::shell::canvas_tool::none;
  }
  return _tool.tool;
}
- (BOOL)toolArmed { return [self activeTool] != mv::shell::canvas_tool::none ? YES : NO; }
- (BOOL)toolPanHeld { return _tool.pan_held ? YES : NO; }
// Strokes not yet applied: A / D, Space and the walks are refused (owner call G).
- (BOOL)toolPending {
  const mv::shell::canvas_tool t = [self activeTool];
  if (t == mv::shell::canvas_tool::extend) return mv::shell::extend_empty(_extend) ? NO : YES;  // S6: a frame not filled
  return t == mv::shell::canvas_tool::remove_brush && !_brush.empty() ? YES : NO;
}

// Arms `t`: the workspace opens on its home tab (Remove on Enhance, red-eye on
// Adjust), a crop draft is applied first (a tool and crop are exclusive), the
// context bar takes the band below the photo, and the OS cursor gives way to
// the ring over the canvas.
- (void)armTool:(mv::shell::canvas_tool)t {
  if (t == mv::shell::canvas_tool::none) {
    [self toolDown];
    return;
  }
  if (![self adjustStill]) {
    NSBeep();
    return;
  }
  if (_edits.crop_active()) [self runEditCommand:mv::shell::command_id::crop_commit];
  const BOOL wasExtend = _tool.tool == mv::shell::canvas_tool::extend ? YES : NO;
  const BOOL changed = mv::shell::arm_tool(_tool, _ws, t) ? YES : NO;
  _toolHoverPlus1 = 0;
  _toolSnap[2] = 0.0f;
  if (changed) [self syncWorkspace];
  if (t == mv::shell::canvas_tool::red_eye) [self toolFetchEyes];
  if (t == mv::shell::canvas_tool::faces) [self facesFetch];
  // S6: a new frame, the camera framing room past the edges; another tool
  // taking over from Extend drops its frame and the room with it.
  if (t == mv::shell::canvas_tool::extend || wasExtend) [self extendReset];
  if (t == mv::shell::canvas_tool::extend) {
    // Zoomed in, the room past the edges would be off screen: Fit (0) at once.
    ++_snap.fit_seq;
    [self pokeSnapshot];
  }
  [self toolChanged];
}

// Esc, Done, a second click on the armed tool: the tool goes down; the
// brush's strokes stay, dimmed, for Remove later (or a walk away clears them).
- (void)toolDown {
  if (_tool.tool == mv::shell::canvas_tool::none) return;
  const BOOL extending = _tool.tool == mv::shell::canvas_tool::extend;
  (void)mv::shell::arm_tool(_tool, _ws, mv::shell::canvas_tool::none);
  // S6: Extend's Cancel (Esc, Done): the frame goes and the camera frames the photo again.
  if (extending) [self extendReset];
  _toolHoverPlus1 = 0;
  _toolSnap[2] = 0.0f;
  [self toolChanged];
}

// After any change of the armed tool: the pane's picker state, the bar, the
// band (a refit, never a swapchain resize), the overlay and the cursor.
- (void)toolChanged {
  _brushCursor[0] = -1.0f;
  [self syncToolBar];
  [self brushPublish];
  [self bumpAdjustView];
  ++_editGeneration;
  [self toolCursor];
  // The ring shows at once where the pointer already is.
  if ([self toolArmed]) [self brushHoverX:_snap.mouse_x y:_snap.mouse_y];
}

// The bar shows and the band is reserved while a tool is armed on a still.
- (BOOL)toolBandShown { return _toolBand; }
- (void)syncToolBar {
  // One-click Enhance: the bar also shows a run's line ("Enhancing… 40 %").
  const BOOL want = ([self toolArmed] || _enhanceRun.band) && !_galleryVisible && !_settingsVisible && !_editorOpen;
  if (self.toolBarHost) self.toolBarHost.hidden = !want;
  if (want == _toolBand) return;
  _toolBand = want;
  [self.view syncChrome];  // chrome_bottom_px gains the band: the picture refits above the bar
}

// The ring under the pointer replaces the OS cursor over the canvas; an open
// hand while Space is held.
- (void)toolCursor {
  if (![self toolArmed] || ![self pointerOverCanvas]) {
    [self toolCursorRestore];
    return;
  }
  _toolCursorSet = YES;
  if (_tool.pan_held) {
    [NSCursor.openHandCursor set];
    return;
  }
  if ([self activeTool] == mv::shell::canvas_tool::faces) {
    // S8: a hand over a face's box (a click chooses it), the arrow elsewhere.
    [(_faces.hover >= 0 ? NSCursor.pointingHandCursor : NSCursor.arrowCursor) set];
    return;
  }
  if ([self activeTool] == mv::shell::canvas_tool::extend) {
    // S6: the edge under the pointer says which way it drags.
    NSCursor* c = NSCursor.crosshairCursor;
    switch (mv::shell::extend_cursor_of(_extendGrab != 0 ? _extendGrab : _extendHover)) {
      case mv::shell::extend_cursor::left_right: c = NSCursor.resizeLeftRightCursor; break;
      case mv::shell::extend_cursor::up_down: c = NSCursor.resizeUpDownCursor; break;
      case mv::shell::extend_cursor::nw_se:
      case mv::shell::extend_cursor::ne_sw:
        // AppKit has no public diagonal resize cursor before macOS 15; the
        // open hand reads as "drag the corner".
        c = NSCursor.openHandCursor;
        break;
      case mv::shell::extend_cursor::move: c = NSCursor.openHandCursor; break;
      case mv::shell::extend_cursor::cross: break;
    }
    [c set];
    return;
  }
  if (!mv::shell::sized([self activeTool])) {
    [NSCursor.crosshairCursor set];
    return;
  }
  if (!_blankCursor) {
    NSImage* blank = [[NSImage alloc] initWithSize:NSMakeSize(1, 1)];
    _blankCursor = [[NSCursor alloc] initWithImage:blank hotSpot:NSZeroPoint];
  }
  [_blankCursor set];
}
// The pointer left the canvas (onto a pane, the bar, out of the window) or the
// tool went down: the arrow again, once (a pane's own cursors are its own),
// and the ring goes.
- (void)toolCursorRestore {
  if (_brushCursor[0] > -1.0f && _snap.edit[0].tool_ring_px > 0.0f) {
    _brushCursor[0] = -1.0f;
    [self brushPublish];
  }
  if (!_toolCursorSet) return;
  _toolCursorSet = NO;
  [NSCursor.arrowCursor set];
}
// The pointer is over the picture's rect: not the bar, the filmstrip, the
// tool bar's band, a docked pane or the page sidebar.
- (BOOL)pointerOverCanvas {
  const float x = _snap.mouse_x, y = _snap.mouse_y;
  return _snap.mouse_in_client && x >= static_cast<float>(_snap.chrome_left_px) &&
                 x < static_cast<float>(_snap.width) - static_cast<float>(_snap.chrome_right_px) &&
                 y >= static_cast<float>(_snap.chrome_height_px) &&
                 y < static_cast<float>(_snap.height) - static_cast<float>(_snap.chrome_bottom_px)
             ? YES
             : NO;
}

- (BOOL)brushActive {
  return [self activeTool] == mv::shell::canvas_tool::remove_brush ? YES : NO;
}
- (BOOL)redEyeRing {
  return [self activeTool] == mv::shell::canvas_tool::red_eye ? YES : NO;
}

// The ring's radius in physical pixels (half the size, at the backing scale).
- (float)toolRingPx {
  return mv::shell::ring_radius_px(mv::shell::tool_px(_tool), _snap.dpi_scale);
}

// Screen → the shown (edited) image's uv; false off the canvas.
- (BOOL)brushUV:(float)x y:(float)y u:(float*)u v:(float*)v {
  return _lab.still_map().to_uv(x, y, *u, *v) ? YES : NO;
}

// The strokes, the ring, the red-eye fixes and the pulse onto the canvas's
// edit view (a redraw, no decode).
- (void)brushPublish {
  if (_snap.edit[0].item != _itemId) return;
  ++_brushRev;
  const mv::shell::canvas_tool active = [self activeTool];
  [self brushMaskSync];
  mv::shell::apply_brush(_snap.edit[0], _brush, _brushMask, active == mv::shell::canvas_tool::remove_brush, _brushRev,
                         _brushCursor);
  [self toolApplyView];
  [self pokeSnapshot];
}

// S4a: the committed strokes onto the canvas's tint texture
// (shell/brush_mask.h). Nothing brushed drops it; otherwise the build the
// sync asks for starts on the pool (one at a time): the worker rasterises the
// dabs at 1024 on the long side and the lab creates one immutable texture
// from them, then -brushMaskLanded: shrinks the live tail to what it lacks.
- (void)brushMaskSync {
  if (_brush.empty()) {
    if (_brushMaskHeld) {
      _brushMaskHeld = NO;
      _lab.drop_brush_mask();
      _brushMask.dropped();
    }
    return;
  }
  const mv::edit::placement p = _edits.preview_placement();
  std::optional<mv::shell::brush_mask_job> job =
      _brushMask.next(_brush, _itemId, p.cropped.w, p.cropped.h, _snap.home.accent);
  if (!job) return;
  if (!_brushMaskBuilder) _brushMaskBuilder = std::make_shared<mv::shell::brush_mask_builder>();
  _brushMaskHeld = YES;
  const std::shared_ptr<mv::shell::brush_mask_builder> builder = _brushMaskBuilder;
  const auto shared_job = std::make_shared<const mv::shell::brush_mask_job>(std::move(*job));
  mv::shell::present_lab_mac* lab = &_lab;
  __weak MvLabApp* weakSelf = self;
  const mv::shell::brush_mask_tag started = shared_job->tag;
  const mv::job_id id = _jobs.submit_at(mv::background_generation, [builder, shared_job, lab,
                                                                     weakSelf](const mv::job_context&) -> mv::status {
    mv::shell::brush_mask_pixels px;
    bool ok = false;
    if (builder->build(*shared_job, px)) {
      ok = lab->upload_brush_mask(px.rgba.data(), px.width, px.height, shared_job->tag.item, shared_job->tag.epoch);
    }
    const mv::shell::brush_mask_tag tag = shared_job->tag;
    dispatch_async(dispatch_get_main_queue(), ^{
      MvLabApp* app = weakSelf;
      if (app) [app brushMaskLanded:tag ok:ok ? YES : NO];
    });
    return ok ? mv::status::ok : mv::status::internal;
  });
  if (id == mv::invalid_job) _brushMask.landed(started, false);  // the pool is not running
}

- (void)brushMaskLanded:(mv::shell::brush_mask_tag)tag ok:(BOOL)ok {
  _brushMask.landed(tag, ok == YES);
  if (ok) _brushMaskHeld = YES;  // even a stale one: the next empty sync drops it
  [self brushPublish];          // the live tail shrinks; the next build, if one is owed, starts
}

// The armed tool onto the canvas's edit view (shell/canvas_tool.h apply_tool):
// the ring in screen pixels, the red-eye fixes, the one under the pointer, the
// pulse and the size label's deadline.
- (void)toolApplyView {
  const mv::shell::canvas_tool active = [self activeTool];
  mv::shell::tool_view_in in;
  in.tool = active;
  in.erase = active == mv::shell::canvas_tool::remove_brush && mv::shell::erasing(_tool);
  in.dim = active != mv::shell::canvas_tool::remove_brush && !_brush.empty();
  if (_brushCursor[0] > -1.0f && mv::shell::sized(active) && !_tool.pan_held) {
    in.ring_px = [self toolRingPx];
    if (active == mv::shell::canvas_tool::red_eye && _toolSnap[2] > 0.0f) {
      in.ring_px = _toolSnap[2] * _lab.still_map().screen_long_px();
    }
  }
  in.label_px = mv::shell::tool_px(_tool);
  in.label_until_ms = _tool.hud_until_ms;
  in.hover_spot = _toolHoverPlus1 - 1;
  in.pulse = {_toolPulse[0], _toolPulse[1], _toolPulse[2]};
  in.pulse_until_ms = _toolPulseUntil;
  in.extend = _extend;
  in.extend_handle = _extendGrab != 0 ? _extendGrab : _extendHover;
  // One-click Enhance: the working glow, on the photo the run works on only.
  if (!_enhanceRunPath.empty() && !_items.empty() && _index.current() < _items.size() &&
      _items[_index.current()].path_utf8 == _enhanceRunPath) {
    in.work_glow_on_ms = _enhanceRun.glow_on_ms;
    in.work_glow_off_ms = _enhanceRun.glow_off_ms;
  }
  const mv::edit::placement p = _edits.preview_placement();
  mv::shell::apply_tool(_snap.edit[0], in, p, _edits.colour());
  // S8: the faces' boxes (only for the photo they were read from).
  if (_faces.item == _itemId) mv::shell::apply_faces(_snap.edit[0], _faces, p);
  else mv::shell::apply_faces(_snap.edit[0], mv::shell::faces_tool{}, p);
}

- (BOOL)brushPressX:(float)x y:(float)y {
  float u = 0, v = 0;
  if (![self brushUV:x y:y u:&u v:&v] || u < 0 || u > 1 || v < 0 || v > 1) return NO;
  const mv::edit::placement p = _edits.preview_placement();
  _brush.set_frame(p.cropped.w, p.cropped.h);
  const float r = mv::shell::radius_over_long([self toolRingPx], _lab.still_map());
  if (_brush.full()) {
    // Say why instead of beeping (docs/plans/edit-refresh.md §4.2).
    [self noticeShow:"Brush full: Remove, then brush more"];
    return NO;
  }
  if (!_brush.begin(u, v, r, mv::shell::erasing(_tool))) return NO;
  _brushCursor[0] = u;
  _brushCursor[1] = v;
  _brushCursor[2] = r;
  [self brushPublish];
  [self bumpAdjustView];
  return YES;
}

- (void)brushDragX:(float)x y:(float)y {
  if (_extendGrab != 0) {
    [self extendDragX:x y:y];
    return;
  }
  float u = 0, v = 0;
  if (![self brushUV:x y:y u:&u v:&v]) return;
  (void)_brush.drag(u, v);
  _brushCursor[0] = u;
  _brushCursor[1] = v;
  [self brushPublish];
}

// The ring follows the pointer over the canvas (it is the cursor there). The
// red-eye ring snaps to an eye the pack found, and a fix under it shows the
// cross a click acts on.
- (void)brushHoverX:(float)x y:(float)y {
  if ([self extendActive]) {
    [self extendHoverX:x y:y];
    return;
  }
  float u = 0, v = 0;
  const BOOL on = [self brushUV:x y:y u:&u v:&v] && [self pointerOverCanvas];
  if (!on && _brushCursor[0] <= -1.0f) return;
  _brushCursor[0] = on ? u : -1.0f;
  _brushCursor[1] = v;
  if ([self activeTool] == mv::shell::canvas_tool::faces) {
    // S8: the box under the pointer lights up (a redraw only when it changes).
    const int face = on && _faces.item == _itemId ? mv::shell::face_at(_faces, _edits.preview_placement(), u, v) : -1;
    if (_faces.set_hover(face)) [self brushPublish];
    return;
  }
  if ([self activeTool] == mv::shell::canvas_tool::red_eye && on) {
    const mv::edit::placement p = _edits.preview_placement();
    const float ring = mv::shell::radius_over_long([self toolRingPx], _lab.still_map());
    _toolHoverPlus1 = mv::shell::spot_at(p, _edits.colour(), u, v, ring * 0.5f) + 1;
    _toolSnap[2] = 0.0f;
    if (_toolHoverPlus1 == 0 && !_eyes.empty() && _eyesItem == _itemId) {
      std::vector<std::array<float, 3>> shown;
      shown.reserve(_eyes.size());
      for (const mv::shell::eye_point& e : _eyes) shown.push_back(mv::shell::spot_to_shown(p, {e.x, e.y, e.r}));
      const float aspect = p.cropped.h > 0 ? static_cast<float>(p.cropped.w) / static_cast<float>(p.cropped.h) : 1.0f;
      if (auto snapped = mv::shell::snap_eye(shown, u, v, ring, aspect)) {
        _brushCursor[0] = (*snapped)[0];
        _brushCursor[1] = (*snapped)[1];
        _toolSnap[0] = (*snapped)[0];
        _toolSnap[1] = (*snapped)[1];
        _toolSnap[2] = (*snapped)[2];
      }
    }
  }
  [self brushPublish];
}

- (void)brushRelease {
  if (_extendGrab != 0) {
    [self extendRelease];
    return;
  }
  _brush.end();
  [self brushPublish];  // S4a: the stroke goes to the tint texture's next build
  [self bumpAdjustView];
  ++_editGeneration;  // the bar's stroke count, Undo / Remove enabled
}

// 0 the last stroke off, 1 all of them, 2 Remove: Enhance's sheet takes it.
- (void)adjustBrush:(int32_t)action {
  if (action == 0) {
    (void)_brush.undo_stroke();
  } else if (action == 1) {
    _brush.clear();
  } else if (action == 2) {
    if (_brush.empty() || _items.empty() || _index.current() >= _items.size()) {
      [self noticeShow:"Brush over what to remove first"];
      return;
    }
    // S5: the docked panel runs it (the sheet when there is none).
    [self enhanceTool:"remove" run:YES];
  }
  [self brushPublish];
  [self bumpAdjustView];
  ++_editGeneration;  // the wand menu
}

- (BOOL)adjustPicking {
  return [self toolArmed] && [self activeTool] != mv::shell::canvas_tool::remove_brush ? YES : NO;
}

// A click on the photo with a tool that clicks: the white-balance picker (one
// click: screen → the shown image's uv → the source's uv through the edit's
// map → the working image), or red-eye: a click on a fix takes it off, else a
// fix lands there (at the ring, or snapped to the eye) with a short pulse.
// Each is one undo step.
- (void)adjustPickAtX:(float)x y:(float)y {
  float u = 0, v = 0;
  if (!_lab.still_map().to_uv(x, y, u, v) || u < 0 || u > 1 || v < 0 || v > 1) return;
  const mv::edit::placement p = _edits.preview_placement();
  mv::shell::edit_effect e = mv::shell::edit_effect::none;
  const mv::shell::canvas_tool tool = [self activeTool];
  if (tool == mv::shell::canvas_tool::wb_pick) {
    if (!_working) {
      [self noticeShow:"Preparing the photo — click again in a moment"];
      return;
    }
    const float* m = p.map.m;
    const float su = m[0] * u + m[1] * v + m[2], sv = m[3] * u + m[4] * v + m[5];
    const auto mean = mv::edit::sample_mean(*_working, su, sv);
    if (!mean) return;
    const std::array<float, 2> wb = mv::edit::neutral_balance(*mean);
    mv::edit::colour c = _edits.colour();
    c.v[static_cast<std::size_t>(mv::edit::adjust_param::temperature)] = wb[0];
    c.v[static_cast<std::size_t>(mv::edit::adjust_param::tint)] = wb[1];
    e = _edits.set_colour(c);
    [self toolDown];  // one click
  } else if (tool == mv::shell::canvas_tool::faces) {
    // S8: a click on a box chooses that face or leaves it out.
    if (_faces.item != _itemId) return;
    const int face = mv::shell::face_at(_faces, p, u, v);
    if (face < 0 || _faces.running) return;
    (void)_faces.toggle(face);
    [self brushPublish];
    ++_editGeneration;  // the bar's "2 chosen", the panel's checks
    return;
  } else if (tool == mv::shell::canvas_tool::red_eye) {
    const float ring = mv::shell::radius_over_long([self toolRingPx], _lab.still_map());
    const int hit = mv::shell::spot_at(p, _edits.colour(), u, v, ring * 0.5f);
    if (hit >= 0) {
      e = _edits.remove_red_eye(hit);
      _toolHoverPlus1 = 0;
    } else {
      float cu = u, cv = v, r = ring;
      if (_toolSnap[2] > 0.0f) {
        cu = _toolSnap[0];
        cv = _toolSnap[1];
        r = _toolSnap[2];
      }
      mv::edit::red_eye_spot spot;
      if (!mv::shell::shown_to_spot(p, cu, cv, r, spot)) return;
      e = _edits.add_red_eye(spot);
      if (e == mv::shell::edit_effect::refused) {
        [self noticeShow:"Eight fixes is the most a photo holds"];
        return;
      }
      _toolPulse[0] = cu;
      _toolPulse[1] = cv;
      _toolPulse[2] = r;
      _toolPulseUntil = mv::shell::steady_ms() + mv::shell::kToolPulseMs;
    }
  } else {
    return;
  }
  if (e == mv::shell::edit_effect::redraw) {
    [self publishEdit];
    [self pokeSnapshot];
  }
  [self adjustColourChanged];
  [self brushPublish];
}

// The eyes of the photo on screen, once per item, on the pool: the ring snaps
// to them and Find eyes reads them. Nothing without the AI pack or with
// People off (the pack says so; the ring then stays where the pointer is).
- (void)toolFetchEyes {
  if (_eyesItem == _itemId || _eyesFetching || _items.empty() || _index.current() >= _items.size()) return;
  _eyesFetching = YES;
  const std::string path = _items[_index.current()].path_utf8;
  const std::uint64_t item = _itemId;
  float w = 0, h = 0;
  if (_working) {
    w = static_cast<float>(_working->width);
    h = static_cast<float>(_working->height);
  } else {
    const mv::edit::placement p = _edits.preview_placement();
    w = static_cast<float>(p.oriented.w);
    h = static_cast<float>(p.oriented.h);
  }
  __weak MvLabApp* weakSelf = self;
  _jobs.submit_at(mv::background_generation, [path, item, w, h, weakSelf](const mv::job_context& ctx) -> mv::status {
    if (ctx.cancelled()) return mv::status::cancelled;
    const std::string readable = mv::addon::media::readable_path(path, &ctx).value_or(path);
    auto json = mv::addon::ai_eyes_json(readable, "");
    std::vector<mv::shell::eye_point> eyes;
    if (json) eyes = mv::shell::parse_eyes(*json, w, h);
    dispatch_async(dispatch_get_main_queue(), ^{
      MvLabApp* app = weakSelf;
      if (app) [app toolEyesLanded:item eyes:eyes];
    });
    return mv::status::ok;
  });
}

- (void)toolEyesLanded:(std::uint64_t)item eyes:(const std::vector<mv::shell::eye_point>&)eyes {
  _eyesFetching = NO;
  if (item != _itemId) {
    // The photo changed while these were read (its own fetch was skipped as one
    // was in flight): read the one on screen now.
    if (_tool.tool == mv::shell::canvas_tool::red_eye) [self toolFetchEyes];
    return;
  }
  _eyesItem = item;
  _eyes = eyes;
  ++_editGeneration;  // the bar: "2 eyes found", Find eyes enabled
}

// Find eyes: every detected eye red enough is fixed, as one undo step.
- (void)toolFindEyes {
  if ([self activeTool] != mv::shell::canvas_tool::red_eye || _findEyesBusy) return;
  if (_eyesItem != _itemId || _eyes.empty()) {
    [self noticeShow:_eyesFetching ? "Looking for eyes…"
                                   : "Find eyes needs People in Local search (Settings → Add-ons)"];
    return;
  }
  if (!_working) {
    [self noticeShow:"Preparing the photo — try again in a moment"];
    return;
  }
  _findEyesBusy = YES;
  ++_editGeneration;
  const std::shared_ptr<const mv::image::linear_image> working = _working;
  const std::vector<mv::shell::eye_point> eyes = _eyes;
  const std::uint64_t item = _itemId;
  __weak MvLabApp* weakSelf = self;
  _jobs.submit_at(mv::background_generation, [working, eyes, item, weakSelf](const mv::job_context& ctx) -> mv::status {
    if (ctx.cancelled()) return mv::status::cancelled;
    std::vector<mv::edit::red_eye_spot> spots = mv::shell::find_red_eyes(*working, eyes);
    dispatch_async(dispatch_get_main_queue(), ^{
      MvLabApp* app = weakSelf;
      if (app) [app toolFoundEyes:item spots:spots];
    });
    return mv::status::ok;
  });
}

- (void)toolFoundEyes:(std::uint64_t)item spots:(const std::vector<mv::edit::red_eye_spot>&)spots {
  _findEyesBusy = NO;
  ++_editGeneration;
  if (item != _itemId) return;
  if (spots.empty()) {
    [self noticeShow:"No red eyes found"];
    return;
  }
  const mv::edit::colour now = _edits.colour();
  const mv::edit::colour with = mv::shell::with_spots(now, spots);
  const int added = static_cast<int>(with.spot_count) - static_cast<int>(now.spot_count);
  if (added <= 0 || _edits.set_colour(with) != mv::shell::edit_effect::redraw) {
    [self noticeShow:"Those eyes are already fixed"];
    return;
  }
  [self publishEdit];
  [self pokeSnapshot];
  [self adjustColourChanged];
  [self brushPublish];
  [self noticeShow:added == 1 ? "Fixed 1 red eye" : "Fixed " + std::to_string(added) + " red eyes"];
}

// The tool keys (docs/design/16, shell/canvas_tool.h), routed in tool mode.
- (BOOL)runToolCommand:(mv::shell::command_id)command {
  using enum mv::shell::command_id;
  using mv::shell::canvas_tool;
  switch (command) {
    case tool_brush:
      if (![self adjustStill]) return NO;
      if (_tool.tool != canvas_tool::remove_brush) [self armTool:canvas_tool::remove_brush];
      return YES;
    case tool_red_eye:
      if (![self adjustStill]) return NO;
      if (_tool.tool == canvas_tool::red_eye) [self toolDown];
      else [self armTool:canvas_tool::red_eye];
      return YES;
    case tool_faces: [self editTool:2]; return YES;
    case tool_extend:
      if (![self adjustStill]) return NO;
      [self editTool:3];
      return YES;
    default: break;
  }
  const canvas_tool active = [self activeTool];
  if (active == canvas_tool::none) return NO;
  switch (command) {
    case tool_smaller: case tool_bigger:
      if (!mv::shell::sized(active)) return NO;
      (void)mv::shell::set_tool_px(_tool, mv::shell::step_tool_px(mv::shell::tool_px(_tool),
                                                                  command == tool_bigger ? 1 : -1),
                                   mv::shell::steady_ms());
      [self brushPublish];
      ++_editGeneration;  // the bar's slider
      return YES;
    case tool_undo:
      if (active == canvas_tool::remove_brush) {
        // No stroke left: ⌘Z is the edit's own undo again (the last Auto, a
        // slider), so an armed brush never makes it dead.
        if (!_brush.undo_stroke()) return [self runEditCommand:undo_edit];
        [self brushPublish];
        [self bumpAdjustView];
        ++_editGeneration;
        return YES;
      }
      // A red-eye fix (or its removal) is one op on the stack.
      return [self runEditCommand:undo_edit];
    case tool_redo:
      if (active != canvas_tool::remove_brush || !_brush.redo_stroke()) return NO;
      [self brushPublish];
      [self bumpAdjustView];
      ++_editGeneration;
      return YES;
    case tool_clear:
      if (active == canvas_tool::remove_brush) {
        if (_brush.empty()) return YES;
        _brush.clear();
        mv::addon::media::set_still_mask({}, {});
        [self brushPublish];
        [self bumpAdjustView];
        ++_editGeneration;
        return YES;
      }
      if (active == canvas_tool::red_eye && _edits.colour().spot_count > 0) {
        // Every fix off, one op (r 0 clears them all).
        if (_edits.add_red_eye({0.0f, 0.0f, 0.0f}) == mv::shell::edit_effect::redraw) {
          [self publishEdit];
          [self pokeSnapshot];
          [self adjustColourChanged];
          [self brushPublish];
        }
      }
      if (active == canvas_tool::extend) [self extendPreset:0];  // S6: back to the photo's own frame
      return YES;
    case tool_apply:
      if (active == canvas_tool::remove_brush) [self adjustBrush:2];
      else if (active == canvas_tool::extend) [self extendFill];  // S6: Fill ↵
      else [self toolDown];
      return YES;
    case tool_pan: case tool_pan_release:
      _tool.pan_held = command == tool_pan;
      [self brushPublish];  // the ring hides while panning
      [self toolCursor];
      return YES;
    default: return NO;
  }
}

// The bar's buttons (ToolBarView, mv_chrome_tool_action).
- (void)toolBarAction:(int32_t)action {
  using mv::shell::tool_bar_action;
  using enum mv::shell::command_id;
  if (const int preset = mv::shell::extend_preset_of_action(action); preset >= 0) {
    [self extendPreset:preset];  // S6: a chip on Extend's bar
    return;
  }
  switch (static_cast<tool_bar_action>(action)) {
    case tool_bar_action::done: [self toolDown]; break;
    case tool_bar_action::undo: (void)[self runToolCommand:tool_undo]; break;
    case tool_bar_action::redo: (void)[self runToolCommand:tool_redo]; break;
    case tool_bar_action::clear: (void)[self runToolCommand:tool_clear]; break;
    case tool_bar_action::apply: (void)[self runToolCommand:tool_apply]; break;
    case tool_bar_action::find_eyes: [self toolFindEyes]; break;
    case tool_bar_action::faces_open_eyes:
      [self facesRun:-1 action:static_cast<int>(mv::shell::face_action::open_eyes)];
      break;
    case tool_bar_action::faces_improve:
      [self facesRun:-1 action:static_cast<int>(mv::shell::face_action::improve)];
      break;
    case tool_bar_action::faces_do_all: [self facesRun:-1 action:mv::shell::kFaceDoAll]; break;
    case tool_bar_action::extend_preset: break;  // handled above
  }
}
- (void)toolSetSize:(float)px {
  if (!mv::shell::set_tool_px(_tool, px, mv::shell::steady_ms())) return;
  [self brushPublish];
  ++_editGeneration;
}
- (void)toolSetErase:(BOOL)on {
  _tool.erase = on;
  [self brushPublish];
  ++_editGeneration;
}
// ⌥ + wheel: the ring ×1.2 per wheel notch (ten points of a trackpad's
// scroll), with the size label. False when no sized tool is armed.
- (BOOL)toolWheel:(CGFloat)dy precise:(BOOL)precise {
  if (![self toolArmed] || !mv::shell::sized([self activeTool])) return NO;
  const float units = static_cast<float>(precise ? dy / 10.0 : dy);
  if (units == 0.0f) return YES;
  const float px = mv::shell::tool_px(_tool) * std::pow(mv::shell::kToolStep, units);
  if (mv::shell::set_tool_px(_tool, px, mv::shell::steady_ms())) ++_editGeneration;
  [self brushPublish];
  return YES;
}
// Option held: the brush erases while it is down (the ring dashes).
- (void)toolModifiers:(BOOL)option {
  if (_tool.erase_held == static_cast<bool>(option)) return;
  _tool.erase_held = option;
  if ([self brushActive]) [self brushPublish];
}

- (mv::shell::tool_bar)toolBar {
  mv::shell::tool_bar b;
  const mv::shell::canvas_tool active = [self activeTool];
  b.visible = active != mv::shell::canvas_tool::none ? 1 : 0;
  b.tool = static_cast<std::int32_t>(active);
  b.size_px = mv::shell::tool_px(_tool);
  b.erase = _tool.erase ? 1 : 0;
  b.strokes = static_cast<std::int32_t>(_brush.strokes());
  b.spots = _edits.has_item() ? _edits.colour().spot_count : 0;
  b.full = _brush.full() ? 1 : 0;
  b.can_redo = _brush.can_redo() ? 1 : 0;
  b.can_undo = _brush.can_undo() ? 1 : 0;
  b.busy = _findEyesBusy ? 1 : 0;
  b.eyes = _eyesItem == _itemId ? static_cast<std::int32_t>(_eyes.size()) : 0;
  b.can_apply = active == mv::shell::canvas_tool::remove_brush
                    ? (!_brush.empty() && mv::shell::find_addon_command("enhance", "open") != mv::shell::command_id::none)
                    : active == mv::shell::canvas_tool::red_eye ? b.eyes > 0 && !_findEyesBusy : 0;
  if (active == mv::shell::canvas_tool::faces) {
    // S8: `eyes` the faces found, `spots` the chosen, `busy` a read or a fix
    // on the pool (shell/canvas_tool.h tool_bar).
    const bool mine = _faces.item == _itemId;
    b.eyes = mine ? _faces.count() : 0;
    b.spots = mine ? _faces.chosen_count() : 0;
    b.busy = mine && (_faces.running_here() || _faces.status == mv::shell::faces_status::looking) ? 1 : 0;
    b.can_apply = mine && _faces.status == mv::shell::faces_status::ready && b.spots > 0 && !_faces.running &&
                          !_eyesRunning
                      ? 1
                      : 0;
  }
  if (active == mv::shell::canvas_tool::extend) {
    // S6: the readout, the chip, and Fill: any frame; past the edges only with Enhance.
    mv::shell::apply_extend_bar(b, _extend, _edits.preview_placement());
    b.can_apply = !mv::shell::extend_empty(_extend) &&
                  (!mv::shell::extend_overhangs(_extend) ||
                   mv::shell::find_addon_command("enhance", "open") != mv::shell::command_id::none);
  }
  return b;
}

// ---- docs/plans/edit-refresh.md S8: the Faces tool ----------------------------------

- (const mv::shell::faces_tool&)facesTool {
  static const mv::shell::faces_tool none;
  return _faces.item == _itemId ? _faces : none;
}
- (BOOL)facesArmed { return [self activeTool] == mv::shell::canvas_tool::faces ? YES : NO; }

// The faces of the photo on screen, once per item, on the pool: the pack's
// answer (People's names and counts with it), then the still for each face's
// thumbnail and whether its eyes look shut. Without the pack, or with People
// off, the panel says so (and offers to turn People on).
- (void)facesFetch {
  if (_items.empty() || _index.current() >= _items.size()) return;
  // Read (or reading) already; a failure or a refusal (People off) reads again.
  if (!_faces.needs_read(_itemId)) return;
  const std::uint64_t item = _itemId;
  _faces.looking(item);
  ++_editGeneration;
  const std::string path = _items[_index.current()].path_utf8;
  __weak MvLabApp* weakSelf = self;
  _jobs.submit_at(mv::background_generation, [path, item, weakSelf](const mv::job_context& ctx) -> mv::status {
    // Always lands (a cancelled read as failed, so "Try again" can read it
    // again): the panel never waits on a read that is not coming.
    auto scan = std::make_shared<mv::shell::faces_scan>();
    if (!ctx.cancelled()) {
      try {
        const std::string readable = mv::addon::media::readable_path(path, &ctx).value_or(path);
        auto json = mv::addon::ai_eyes_json(readable, "");
        std::optional<mv::image::linear_image> still;
        if (json && json->find("\"lm\"") != std::string::npos && !ctx.cancelled()) {
          if (auto bytes = mv::io::read_all(readable)) {
            if (auto img = mv::image::decode_linear(*bytes, &ctx)) still = std::move(*img);
          }
        }
        *scan = mv::shell::read_faces(json ? mv::status::ok : json.error(),
                                      json ? std::string_view(*json) : std::string_view(), still ? &*still : nullptr);
      } catch (...) {
        *scan = {};  // out of memory: failed
      }
    }
    dispatch_async(dispatch_get_main_queue(), ^{
      MvLabApp* app = weakSelf;
      if (app) [app facesLanded:item scan:scan];
    });
    return mv::status::ok;
  });
}

- (void)facesLanded:(std::uint64_t)item scan:(std::shared_ptr<mv::shell::faces_scan>)scan {
  if (!_faces.landed(item, std::move(*scan))) return;  // another photo's
  [self brushPublish];
  ++_editGeneration;  // the panel, the bar
}

// A fix from the panel or the bar: `action` (shell::face_action, or
// kFaceDoAll) on `face`, or on the chosen faces for -1. On the pool: the same
// moment's frames and the pack's donors (People), matched to the boxes the
// canvas chose (media::faces_mask_of), then a new file beside the photo.
- (void)facesRun:(int)face action:(int)action {
  if (_eyesRunning || _faces.running || _faces.item != _itemId || ![self adjustStill] || _items.empty() ||
      _index.current() >= _items.size()) {
    return;
  }
  if (action < mv::shell::kFaceDoAll || action >= mv::shell::kFaceActionCount) return;
  std::vector<float> boxes = _faces.run_boxes(face);
  if (boxes.empty()) {
    [self noticeShow:"Choose a face first: click its box on the photo"];
    return;
  }
  if (action == static_cast<int>(mv::shell::face_action::restore)) {
    // S10's model through Enhance's docked panel (its progress and result
    // row), on these faces only; the host's own fixes stay free meanwhile.
    [self enhanceTool:"faces" run:YES faces:boxes];
    return;
  }
  _faces.start_run(face, action);
  _eyesRunning = YES;
  ++_editGeneration;
  [self brushPublish];
  const std::string path = _items[_index.current()].path_utf8;
  const auto fix = static_cast<mv::addon::media::face_fix>(action);
  __weak MvLabApp* weakSelf = self;
  _jobs.submit_at(mv::background_generation, [path, fix, boxes, weakSelf](const mv::job_context& ctx) -> mv::status {
    std::string candidates;
    for (const std::string& c : mv::addon::media::burst_neighbours(path)) candidates += c + "\n";
    auto pack = mv::addon::ai_eyes_json(path, candidates);
    mv::result<mv::addon::media::eyes_outcome> r = mv::err(pack ? mv::status::ok : pack.error());
    if (pack) r = mv::addon::media::fix_faces(path, *pack, fix, mv::addon::media::faces_mask_of(*pack, boxes), &ctx);
    const std::string note = mv::addon::media::fix_note(fix, pack ? mv::status::ok : pack.error(), r);
    dispatch_async(dispatch_get_main_queue(), ^{
      [weakSelf facesRunLanded:note];
    });
    return mv::status::ok;
  });
}

- (void)facesRunLanded:(const std::string&)note {
  _faces.run_done();
  [self brushPublish];
  [self eyesLanded:note];  // the wand's busy flag, the note, the notice
}

// The panel's and the bar's controls (mv_chrome_faces_op, shell::pack_faces_op).
- (void)facesOp:(int32_t)packed {
  const std::optional<mv::shell::faces_op_args> a = mv::shell::unpack_faces_op(packed);
  if (!a) return;
  switch (a->op) {
    case mv::shell::faces_op::run: [self facesRun:a->face action:a->action]; return;
    case mv::shell::faces_op::toggle:
      if (_faces.running || !_faces.toggle(a->face)) return;
      break;
    case mv::shell::faces_op::choose_all:
      if (_faces.running) return;
      _faces.choose_all();
      break;
    case mv::shell::faces_op::choose_none:
      if (_faces.running) return;
      _faces.choose_none();
      break;
    case mv::shell::faces_op::people:
      // The chrome opens People's settings (AddonNav). The panel keeps
      // saying People is off until a read says otherwise: the next arm, a
      // walk, or Check again (retry) reads again.
      return;
    case mv::shell::faces_op::retry:
      if ([self facesArmed] && [self adjustStill]) [self facesFetch];
      return;
    case mv::shell::faces_op::hover:
      // The panel's row under the pointer lights its box on the photo.
      if (_faces.item != _itemId || !_faces.set_hover(a->face)) return;
      [self brushPublish];
      return;
  }
  [self brushPublish];
  ++_editGeneration;
}

// What tool mode refused: say why (docs/plans/edit-refresh.md §4.1).
- (void)toolBlocked {
  if ([self activeTool] == mv::shell::canvas_tool::extend && [self toolPending]) {
    [self noticeShow:"Fill or cancel the new frame first"];  // S6
    return;
  }
  [self noticeShow:[self toolPending] ? "Remove or clear the strokes first"
                                      : "Put the tool down first (Esc)"];
}

// ---- docs/plans/edit-refresh.md S6: Extend on the canvas --------------------------
//
// The frame is shell state (shell/edit_workspace.h extend_draft), never an
// edit: dragged past the photo's edges it is new picture Enhance fills,
// inside them a crop. The camera frames the photo and the frame with room
// around them (input_snapshot::fit_rect_uv, refit_seq) once a drag ends, so
// the edge under the pointer does not run away while it is held.

- (BOOL)extendActive {
  return [self activeTool] == mv::shell::canvas_tool::extend ? YES : NO;
}

// A new frame (none), nothing held, and the camera framing it.
- (void)extendReset {
  _extend = {};
  _extend.on = _tool.tool == mv::shell::canvas_tool::extend;
  _extendGrab = 0;
  _extendHover = 0;
  mv::addon::media::set_still_extend({}, {});  // a frame not filled is not Enhance's
  [self extendRefit];
  ++_editGeneration;  // the bar's readout
}

// The camera frames the photo and the frame (a refit, never a resize).
- (void)extendRefit {
  // Only while Extend is active on a still: a clip under an armed tool fits as itself.
  std::array<float, 4> f{0.0f, 0.0f, 1.0f, 1.0f};
  if ([self extendActive]) f = mv::shell::extend_fit(_extend);
  if (std::equal(f.begin(), f.end(), _snap.fit_rect_uv)) return;
  std::copy(f.begin(), f.end(), _snap.fit_rect_uv);
  ++_snap.refit_seq;
  [self pokeSnapshot];
}

// The grab distance in the shown picture's uv, from screen pixels.
- (void)extendReachU:(float*)ru v:(float*)rv {
  const auto map = _lab.still_map();
  const float px = mv::shell::kExtendGrabPx * (_snap.dpi_scale > 0.0f ? _snap.dpi_scale : 1.0f);
  *ru = map.zoom > 0.0f && map.width > 0.0f ? px / (map.width * map.zoom) : 0.0f;
  *rv = map.zoom > 0.0f && map.height > 0.0f ? px / (map.height * map.zoom) : 0.0f;
}

- (BOOL)extendPressX:(float)x y:(float)y {
  float u = 0, v = 0, ru = 0, rv = 0;
  if (![self brushUV:x y:y u:&u v:&v]) return NO;
  [self extendReachU:&ru v:&rv];
  const std::uint8_t grab = mv::shell::extend_hit(_extend, u, v, ru, rv);
  if (grab == mv::shell::extend_none) return NO;
  _extendGrab = grab;
  _extendStart = _extend;
  _extendPress[0] = u;
  _extendPress[1] = v;
  [self brushPublish];
  [self toolCursor];
  return YES;
}

- (void)extendDragX:(float)x y:(float)y {
  float u = 0, v = 0;
  if (![self brushUV:x y:y u:&u v:&v]) return;
  const mv::shell::extend_draft d =
      mv::shell::extend_drag(_extendStart, _extendGrab, u - _extendPress[0], v - _extendPress[1]);
  if (d.l == _extend.l && d.t == _extend.t && d.r == _extend.r && d.b == _extend.b) return;
  _extend = d;
  _extend.on = YES;
  [self brushPublish];
  ++_editGeneration;  // the bar's readout follows the drag
}

- (void)extendRelease {
  _extendGrab = 0;
  [self extendRefit];
  [self brushPublish];
  [self toolCursor];
  ++_editGeneration;
}

- (void)extendHoverX:(float)x y:(float)y {
  float u = 0, v = 0, ru = 0, rv = 0;
  std::uint8_t hover = 0;
  if ([self brushUV:x y:y u:&u v:&v] && [self pointerOverCanvas]) {
    [self extendReachU:&ru v:&rv];
    hover = mv::shell::extend_hit(_extend, u, v, ru, rv);
  }
  if (hover == _extendHover) return;
  _extendHover = hover;
  [self brushPublish];  // the edge lights under the pointer
}

// ---- docs/design/20 Behaviour 4: crop mode's handles on the canvas ---------------
//
// A press on the draft's edge or corner (shell/crop_drag.h crop_hit, Extend's
// grab distance) resizes it, one inside moves it; edit_session::drag_crop keeps
// a locked ratio and the straightened source's covered area. Crop mode shows
// the whole frame, so the shown picture's uv is the draft's. The Windows twin
// is main.cpp crop_press / crop_drag_to / crop_hover_at / crop_release.

// Crop mode on a still on screen: the handles take presses.
- (BOOL)cropHandles {
  return _edits.crop_active() && !_showOriginal && [self editSubject] == mv::shell::edit_subject::still ? YES : NO;
}

// The edges a press grabs: resize arrows for one edge, the open hand for a
// corner (AppKit has no public diagonal resize cursor before macOS 15) or a move.
- (void)cropCursor:(std::uint8_t)handle {
  NSCursor* c = nil;
  switch (mv::shell::extend_cursor_of(handle)) {
    case mv::shell::extend_cursor::left_right: c = NSCursor.resizeLeftRightCursor; break;
    case mv::shell::extend_cursor::up_down: c = NSCursor.resizeUpDownCursor; break;
    case mv::shell::extend_cursor::nw_se:
    case mv::shell::extend_cursor::ne_sw:
    case mv::shell::extend_cursor::move: c = NSCursor.openHandCursor; break;
    case mv::shell::extend_cursor::cross: break;
  }
  if (c) {
    [c set];
    _cropCursorSet = YES;
  } else if (_cropCursorSet) {
    _cropCursorSet = NO;
    [NSCursor.arrowCursor set];
  }
}

- (std::uint8_t)cropHitX:(float)x y:(float)y {
  float u = 0, v = 0, ru = 0, rv = 0;
  if (![self cropHandles] || ![self pointerOverCanvas] || ![self brushUV:x y:y u:&u v:&v]) return 0;
  [self extendReachU:&ru v:&rv];
  return mv::shell::crop_hit(_edits.crop_overlay(), u, v, ru, rv);
}

- (BOOL)cropPressX:(float)x y:(float)y {
  const std::uint8_t grab = [self cropHitX:x y:y];
  if (grab == mv::shell::extend_none) return NO;
  float u = 0, v = 0;
  (void)[self brushUV:x y:y u:&u v:&v];
  std::uint32_t w = 0, h = 0;
  if (_lab.still_size(_itemId, &w, &h)) _edits.set_size(w, h);
  _cropGrab = grab;
  _cropStart = _edits.crop_overlay();
  _cropPress[0] = u;
  _cropPress[1] = v;
  [self cropCursor:grab];
  return YES;
}

- (void)cropDragX:(float)x y:(float)y {
  float u = 0, v = 0;
  if (_cropGrab == 0 || ![self brushUV:x y:y u:&u v:&v]) return;
  // Only the draft moves: the overlay redraws, the Crop pane's size follows.
  if (_edits.drag_crop(_cropStart, _cropGrab, u - _cropPress[0], v - _cropPress[1]) ==
      mv::shell::edit_effect::redraw) {
    [self publishEdit];
    [self pokeSnapshot];
  }
}

- (void)cropRelease {
  _cropGrab = 0;
  _cropHover = 0xff;  // the next move picks the cursor again
  [self cropHoverX:_snap.mouse_x y:_snap.mouse_y];
}

- (void)cropHoverX:(float)x y:(float)y {
  const std::uint8_t hover = [self cropHitX:x y:y];
  if (hover == _cropHover && (hover == 0 || _cropCursorSet)) return;
  _cropHover = hover;
  [self cropCursor:hover];
}

// A chip on the bar: the add-on's preset as a frame (0 Original: none).
- (void)extendPreset:(int)i {
  if ([self activeTool] != mv::shell::canvas_tool::extend) return;
  const mv::edit::placement p = _edits.preview_placement();
  _extend = mv::shell::extend_preset_draft(i, p.cropped.w, p.cropped.h);
  _extendGrab = 0;
  [self extendRefit];
  [self brushPublish];
  ++_editGeneration;
}

// Fill ↵: the part of the frame over the photo lands as an ordinary crop (one
// undo step); the rest is margins Enhance fills, from the edited picture
// (still_extend), in its docked panel on the Enhance tab (S5), or in its
// sheet, which opens on Extend, with an Enhance that has no panel.
- (void)extendFill {
  if ([self activeTool] != mv::shell::canvas_tool::extend) return;
  if (mv::shell::extend_empty(_extend)) {
    [self noticeShow:"Drag the frame's edges past the photo first"];
    return;
  }
  const BOOL over = mv::shell::extend_overhangs(_extend) ? YES : NO;
  const mv::shell::command_id enhance = mv::shell::find_addon_command("enhance", "open");
  if (over && enhance == mv::shell::command_id::none) {
    [self noticeShow:"Extending past the edges needs the Enhance add-on (Settings → Add-ons)."];
    return;
  }
  if (_items.empty() || _index.current() >= _items.size()) return;
  const std::string path = _items[_index.current()].path_utf8;
  const mv::shell::extend_draft d = _extend;
  if (mv::shell::extend_crops(d)) {
    const std::array<float, 4> c = mv::shell::extend_crop(d);
    std::uint32_t w = 0, h = 0;
    if (_lab.still_size(_itemId, &w, &h)) _edits.set_size(w, h);
    // One crop op; publishEdit hands Enhance's copy the crop (set_still_edit).
    [self applyEditEffect:_edits.crop_inside({c[0], c[1], c[2], c[3]})];
  }
  [self toolDown];  // the frame goes; the camera frames the picture again
  if (!over) return;
  mv::addon::media::set_still_extend(path, mv::shell::extend_overhang(d));
  // Enhance's docked panel under the Extend card runs it on the frame (S5's
  // enhance/tool); an Enhance without the panel opens its sheet on Extend.
  [self enhanceTool:"extend" run:YES];
}

// A section's Reset: its sliders back to 0, one undo step.
- (void)adjustResetSection:(int32_t)section {
  if (section < 0 || section >= mv::edit::kAdjustSectionCount) return;
  if (!_adjust.working_ready() || ![self adjustStill]) return;
  const mv::edit::colour c =
      mv::edit::without_section(_edits.colour(), static_cast<mv::edit::adjust_section>(section));
  if (_edits.set_colour(c) != mv::shell::edit_effect::redraw) return;
  [self publishEdit];
  [self pokeSnapshot];
  [self adjustColourChanged];
}

// A section's Auto (edit/auto_adjust.h): read on the pool from the working
// image, landed on the main thread as one op if nothing moved meanwhile.
- (void)adjustAuto:(int32_t)section {
  if (section < 0 || section >= mv::edit::kAdjustSectionCount ||
      !mv::edit::has_auto(static_cast<mv::edit::adjust_section>(section))) {
    return;
  }
  if (!_working || ![self adjustStill]) return;
  const auto sec = static_cast<mv::edit::adjust_section>(section);
  const std::optional<std::uint64_t> token = _adjust.request_auto_tone(sec);
  if (!token) return;
  [self bumpAdjustView];
  const std::shared_ptr<const mv::image::linear_image> working = _working;
  const mv::edit::colour current = _edits.colour();
  const std::uint64_t t = *token;
  __weak MvLabApp* weakSelf = self;
  _jobs.submit_at(mv::background_generation,
                  [working, current, sec, t, weakSelf](const mv::job_context& ctx) -> mv::status {
                    auto r = mv::edit::compute_auto(*working, current, sec, &ctx);
                    const bool ok = r.has_value();
                    const mv::edit::colour value = ok ? r->value : current;
                    dispatch_async(dispatch_get_main_queue(), ^{
                      [weakSelf autoLanded:t ok:ok value:value];
                    });
                    return ok ? mv::status::ok : r.error();
                  });
}

- (void)autoLanded:(std::uint64_t)token ok:(bool)ok value:(const mv::edit::colour&)value {
  const BOOL enhance = token != 0 && token == _autoEnhanceToken;
  if (enhance) {
    _autoEnhanceToken = 0;
    ++_editGeneration;  // the header's ✦ stops
  }
  if (!_adjust.auto_tone_landed(token)) {
    _pendingAutos.clear();  // the colour moved meanwhile: the rest of a typed request's Autos too
    return;
  }
  if (ok && [self adjustStill] && _edits.set_colour(value) == mv::shell::edit_effect::redraw) {
    [self publishEdit];
    [self pokeSnapshot];
    [self adjustColourChanged];
    // ✦ Auto is one undo step; a second click right after takes it back.
    if (enhance) _adjust.auto_enhance_landed(_edits.edit_count(), _edits.colour());
  } else if (enhance && ok) {
    [self noticeShow:std::string("Auto found nothing to change in this photo")];
    [self bumpAdjustView];
  } else {
    [self bumpAdjustView];  // the spinner stops; nothing changed
  }
  [self nextPendingAuto];
}

- (void)adjustBlur {
  [self.window makeFirstResponder:self.view];
}

// ---- PR 9: metadata, folder tree, sort ------------------------------------------

- (BOOL)metadataWanted {
  return _metaPaneVisible || _snap.info_overlay || _snap.af_points || _afFocusPending;
}

// Issue #209 (Shift+Z): the record is adopted, so the quads in _snap.meta are
// this item's. Bump the edge, or say why there is nothing to zoom to.
- (void)afFocusFire {
  _afFocusPending = NO;
  if (_snap.meta.af_count == 0) {
    [self noticeShow:std::string("No AF point recorded in this file")];
    return;
  }
  _zoomIntentAt = CACurrentMediaTime();
  ++_snap.af_focus_seq;
  [self pokeSnapshot];
}

// Selection moved: the old record is no longer the item on screen. The new one is
// asked for only if something is showing metadata, and only after a pause, so
// holding an arrow key queues no read for the images that flash past.
- (void)metadataSelectionChanged {
  [_metaDebounce invalidate];
  _metaDebounce = nil;
  _afFocusPending = NO;  // Shift+Z was for the item just left
  if (_metaRecord) _metaRecord.reset();
  ++_metaGeneration;
  _snap.meta = mv::shell::meta_overlay{};
  if (_items.empty() || ![self metadataWanted]) return;
  _metaDebounce = [NSTimer scheduledTimerWithTimeInterval:0.09
                                                   target:self
                                                 selector:@selector(requestMetadataNow)
                                                 userInfo:nil
                                                  repeats:NO];
}

// Asks for the current item's record: a cache hit is adopted at once; a miss
// submits one read on the pool and the completion hops back to the main thread.
- (void)requestMetadataNow {
  [_metaDebounce invalidate];
  _metaDebounce = nil;
  if (_metaRecord || _items.empty() || _index.current() >= _items.size()) return;
  mv::io::dir_entry entry = _items[_index.current()];
  // docs/design/26: a Photos item's record is its file's (in place, or the preview /
  // the fetched original); nothing to read until it has resolved.
  if (mv::shell::photos::is_key(entry.path_utf8)) {
    const auto hit = _photosResolved.find(entry.path_utf8);
    if (hit == _photosResolved.end()) return;
    entry.path_utf8 = hit->second.path;
  }
  MvLabApp* app = self;
  auto record = _meta.get(entry, _jobs, [app](std::string path) {
    dispatch_async(dispatch_get_main_queue(), ^{
      [app metadataArrived:path];
    });
  });
  if (record) [self adoptMetadata:record];
}

- (void)metadataArrived:(const std::string&)path {
  if (_items.empty() || _index.current() >= _items.size()) return;
  mv::io::dir_entry entry = _items[_index.current()];
  if (mv::shell::photos::is_key(entry.path_utf8)) {
    const auto hit = _photosResolved.find(entry.path_utf8);
    if (hit == _photosResolved.end()) return;
    entry.path_utf8 = hit->second.path;
  }
  if (entry.path_utf8 != path || _metaRecord) return;  // navigated on, or already adopted
  if (auto record = _meta.peek(entry)) [self adoptMetadata:record];
}

- (void)adoptMetadata:(std::shared_ptr<const mv::meta::metadata>)record {
  _metaRecord = record;
  ++_metaGeneration;
  // Pre-format everything the render thread will draw, once, here.
  mv::shell::meta_overlay o;
  const auto copy = [](char* dst, std::size_t cap, const std::string& src) {
    const std::size_t n = std::min(src.size(), cap - 1);
    std::memcpy(dst, src.data(), n);
    dst[n] = '\0';
  };
  copy(o.camera_line, sizeof(o.camera_line), mv::meta::overlay_camera_line(*record));
  copy(o.exposure_line, sizeof(o.exposure_line), mv::meta::overlay_exposure_line(*record));
  copy(o.date_line, sizeof(o.date_line), mv::meta::overlay_date_line(*record));
  const auto af = mv::meta::displayed_af_points(*record);
  for (std::size_t i = 0; i < af.size() && i < mv::shell::meta_overlay::kMaxAf; ++i) {
    o.af[i][0] = af[i].x;
    o.af[i][1] = af[i].y;
    o.af[i][2] = af[i].w;
    o.af[i][3] = af[i].h;
    o.af[i][4] = af[i].in_focus ? 1.0f : 0.0f;
    o.af_count = static_cast<std::uint8_t>(i + 1);
  }
  _snap.meta = o;
  [self pokeSnapshot];
  // #345: the full record is the badge's best answer (it reads what the probe
  // leaves out: a clip's software tag, a HEIF's XMP).
  [self aiBadgeRefresh];
  if (_afFocusPending) [self afFocusFire];
}

- (BOOL)metaPaneVisible { return _metaPaneVisible; }
- (BOOL)metaLoading {
  return [self metadataWanted] && !_metaRecord && !_items.empty();
}
- (uint64_t)metaGeneration { return _metaGeneration; }
- (std::shared_ptr<const mv::meta::metadata>)metaRecord { return _metaRecord; }

// ---- #345: the AI-generated badge --------------------------------------------------
//
// shell/ai_badge.h decides the text; meta_store::provenance supplies the answer
// (a held record, an earlier probe, or one bounded probe on the pool). A cached
// answer shows at once; a miss waits the metadata pause first, so holding an
// arrow probes none of the items flashing past. Nothing here touches `_snap`:
// the badge is an NSHostingView over the canvas, never a present.

- (BOOL)aiBadgeEnabled {
  return mv::shell::view_settings::from_flags(_viewFlags).ai_badge ? YES : NO;
}

// The current item as the store keys it; a Photos item through its resolved file.
- (BOOL)aiBadgeEntry:(mv::io::dir_entry&)entry {
  if (_items.empty() || _index.current() >= _items.size()) return NO;
  entry = _items[_index.current()];
  if (mv::shell::photos::is_key(entry.path_utf8)) {
    const auto hit = _photosResolved.find(entry.path_utf8);
    if (hit == _photosResolved.end()) return NO;
    entry.path_utf8 = hit->second.path;
  }
  return YES;
}

static std::string MvBadgeKey(const mv::io::dir_entry& e) {
  return e.path_utf8 + '\0' + std::to_string(e.mtime_unix) + '\0' + std::to_string(e.size);
}

- (void)setAIBadgeTo:(const mv::shell::ai_badge&)badge {
  if (badge == _aiBadge) return;
  _aiBadge = badge;
  // Hidden, the text is cleared too: that closes a popover a hover or focus
  // left open, so it never floats over the next item with the last one's text.
  [MVChromeHost setAIBadgeWithTitle:[NSString stringWithUTF8String:badge.title.c_str()] ?: @""
                           evidence:[NSString stringWithUTF8String:badge.evidence.c_str()] ?: @""];
  [self layoutAIBadge];
}

- (void)aiBadgeSelectionChanged {
  mv::io::dir_entry entry;
  const BOOL have = [self aiBadgeEntry:entry];
  const std::string key = have ? MvBadgeKey(entry) : std::string();
  if (key == _aiBadgeKey) return;  // a relist, the same file: keep what is shown
  _aiBadgeKey = key;
  [_aiBadgeDebounce invalidate];
  _aiBadgeDebounce = nil;
  if (!have || ![self aiBadgeEnabled]) {
    [self setAIBadgeTo:mv::shell::ai_badge{}];
    return;
  }
  if (auto hit = _meta.peek_provenance(entry)) {
    [self setAIBadgeTo:mv::shell::make_ai_badge(*hit, true)];
    return;
  }
  [self setAIBadgeTo:mv::shell::ai_badge{}];
  _aiBadgeDebounce = [NSTimer scheduledTimerWithTimeInterval:0.09
                                                      target:self
                                                    selector:@selector(aiBadgeRequestNow)
                                                    userInfo:nil
                                                     repeats:NO];
}

- (void)aiBadgeRequestNow {
  [_aiBadgeDebounce invalidate];
  _aiBadgeDebounce = nil;
  mv::io::dir_entry entry;
  if (![self aiBadgeEnabled] || ![self aiBadgeEntry:entry]) return;
  MvLabApp* app = self;
  const auto answer = _meta.provenance(entry, _jobs, [app](std::string) {
    dispatch_async(dispatch_get_main_queue(), ^{
      [app aiBadgeRefresh];
    });
  });
  if (answer) [self setAIBadgeTo:mv::shell::make_ai_badge(*answer, true)];
}

// An answer landed (a probe, or a full record): show it if it is still the
// item on screen. Never submits.
- (void)aiBadgeRefresh {
  mv::io::dir_entry entry;
  if (![self aiBadgeEntry:entry] || MvBadgeKey(entry) != _aiBadgeKey) return;
  if (auto hit = _meta.peek_provenance(entry)) {
    [self setAIBadgeTo:mv::shell::make_ai_badge(*hit, [self aiBadgeEnabled] == YES)];
  }
}

// Settings -> Viewer: off hides it at once; on asks again for what is on screen.
- (void)aiBadgeSettingChanged {
  _aiBadgeKey.clear();
  [self aiBadgeSelectionChanged];
}

// Bottom-right of the canvas: above the filmstrip, above a clip's transport,
// left of a right-hand pane; gone under the gallery, Settings or the Video Editor.
- (void)layoutAIBadge {
  // Every right pane's show and hide comes through here (#345), and so does
  // the gallery, Settings and the Video Editor: the column's edge follows.
  [self syncPaneEdge];
  NSView* host = self.aiBadgeHost;
  if (!host) return;
  const BOOL covered = _galleryVisible || _settingsVisible || _editorOpen;
  const BOOL want = _aiBadge.shown && !covered && !_items.empty();
  if (want) {
    const BOOL rightPane = !self.metaHost.hidden || !self.adjustHost.hidden || !self.jobsHost.hidden ||
                           !self.editPaneHost.hidden || !self.editStripHost.hidden;
    const CGFloat rail = self.railHost.hidden ? 0.0 : [self paneLimits].rail;
    const CGFloat trailing = -(16.0 + rail + (rightPane ? self.rightColumnWidth.constant : 0.0));
    CGFloat bottom = -(([self filmstripVisible] ? kFilmstripHeightPoints : 0.0) + 10.0);
    if (_transportClip) bottom -= 44.0 + 8.0;  // the strip's height and a gap
    if (self.aiBadgeTrailing.constant != trailing) self.aiBadgeTrailing.constant = trailing;
    if (self.aiBadgeBottom.constant != bottom) self.aiBadgeBottom.constant = bottom;
  }
  if (host.hidden == !want) return;
  host.hidden = !want;
  if (!want && self.window.firstResponder &&
      [self.window.firstResponder isKindOfClass:[NSView class]] &&
      [(NSView*)self.window.firstResponder isDescendantOf:host]) {
    [self.window makeFirstResponder:self.view];  // focus never stays on a hidden badge
  }
}

// ---- PR 12: rating, comment, revert ----------------------------------------------
//
// Keys 0-5 and the pane's controls queue a write; nothing here touches a file on
// the main thread. The queue coalesces (3 then 4 writes 4), runs one job at a
// time on the pool, and never overlaps a lossless rotation of the same JPEG.

- (const mv::io::dir_entry*)currentEntry {
  if (_items.empty() || _index.current() >= _items.size()) return nullptr;
  return &_items[_index.current()];
}

- (BOOL)rateCurrentItem:(int)stars {
  const mv::io::dir_entry* entry = [self currentEntry];
  if (!entry || stars < 0 || stars > mv::meta::kMaxRating) return NO;
  if ([self refuseWriteTo:entry->path_utf8]) return YES;  // the key was ours; the answer is no
  _metaWriter.submit(entry->path_utf8, mv::shell::rating_fields(stars));
  // The keystroke shows at once; the file catches up a moment later.
  [self noticeShow:stars == 0 ? std::string("Rating cleared") : mv::meta::format_rating(stars)];
  [self scheduleMetaWrite:0.25];
  return YES;
}

// Issue #207: `X` toggles reject (rating -1), through the same queue as a rating.
- (BOOL)rejectCurrentItem {
  const mv::io::dir_entry* entry = [self currentEntry];
  if (!entry) return NO;
  if ([self refuseWriteTo:entry->path_utf8]) return YES;
  const int next = mv::shell::reject_toggled([self metaRating]);
  _metaWriter.submit(entry->path_utf8, mv::shell::rating_fields(next));
  [self noticeShow:next == 0 ? std::string("Rating cleared") : mv::meta::format_rating(next)];
  [self scheduleMetaWrite:0.25];
  return YES;
}

// Issue #207: keypad / ⌘⇧ 6-9 set a colour label (the same one again clears
// it), `U` clears it: XMP xmp:Label, in place on a plain JPEG, else the sidecar.
- (BOOL)labelCurrentItem:(mv::shell::colour_label)pressed {
  const mv::io::dir_entry* entry = [self currentEntry];
  if (!entry) return NO;
  if ([self refuseWriteTo:entry->path_utf8]) return YES;
  std::string now;
  if (auto pending = _metaWriter.pending_label(entry->path_utf8)) now = std::move(*pending);
  else if (_metaRecord) now = _metaRecord->s.label;
  const std::string next = mv::shell::label_toggled(pressed, now);
  if (next.empty() && now.empty()) {
    [self noticeShow:"No label"];
    return YES;
  }
  _metaWriter.submit(entry->path_utf8, mv::shell::label_fields(next));
  [self noticeShow:next.empty() ? std::string("Label cleared") : "Label: " + next];
  [self scheduleMetaWrite:0.25];
  return YES;
}

- (BOOL)focusCommentField {
  if (![self currentEntry]) return NO;
  if (_adjust.visible()) [self setAdjustVisible:NO];
  if (!_metaPaneVisible) [self setMetaPaneVisible:YES focus:NO];
  // Swift opens All tags and focuses its search once per ask (issue #185).
  _metaFocusTags = YES;
  ++_metaFocusSeq;
  [self.window makeFirstResponder:self.metaHost];
  return YES;
}

- (int32_t)metaRating {
  const mv::io::dir_entry* entry = [self currentEntry];
  if (!entry) return 0;
  if (const auto pending = _metaWriter.pending_rating(entry->path_utf8)) return *pending;
  return _metaRecord ? _metaRecord->s.rating : 0;
}

- (std::string)metaComment {
  const mv::io::dir_entry* entry = [self currentEntry];
  if (!entry) return {};
  if (auto pending = _metaWriter.pending_comment(entry->path_utf8)) return std::move(*pending);
  return _metaRecord ? _metaRecord->s.comment : std::string{};
}

- (BOOL)metaCanEdit {
  const mv::io::dir_entry* entry = [self currentEntry];
  return entry != nullptr && !mv::shell::write_protected(entry->path_utf8);
}

- (BOOL)metaCanRevert {
  const mv::io::dir_entry* entry = [self currentEntry];
  return entry && _metaWritten.count(entry->path_utf8) != 0 && !mv::shell::write_protected(entry->path_utf8);
}

- (void)metaSetRating:(int32_t)stars {
  (void)[self rateCurrentItem:std::clamp<int32_t>(stars, 0, mv::meta::kMaxRating)];
}

- (void)metaSetComment:(const char*)utf8 {
  const mv::io::dir_entry* entry = [self currentEntry];
  if (!entry || [self refuseWriteTo:entry->path_utf8]) return;
  const std::string text(utf8);
  if (text.size() > mv::meta::kMaxCommentBytes) {
    NSBeep();
    [self noticeShow:std::string("Comment is too long")];
    return;
  }
  if (text == [self metaComment]) return;  // unchanged: no write
  _metaWriter.submit(entry->path_utf8, mv::shell::comment_fields(text));
  [self scheduleMetaWrite:0.05];
}

// PR 29: one tag, by its raw key; the queue merges edits to the same file.
- (void)metaSetTag:(const char*)key value:(const char*)value {
  const mv::io::dir_entry* entry = [self currentEntry];
  const auto rec = [self metaRecord];
  if (!entry || !rec || [self refuseWriteTo:entry->path_utf8]) return;
  const std::string k(key);
  const mv::meta::tag_access a = mv::meta::access_of(
      k, rec->writes_in_file ? mv::meta::write_target::in_file : mv::meta::write_target::sidecar);
  if (a == mv::meta::tag_access::read_only || (a == mv::meta::tag_access::via_sidecar && value == nullptr)) {
    NSBeep();
    [self noticeShow:a == mv::meta::tag_access::read_only
                         ? std::string("That tag describes the file itself and cannot be changed")
                         : std::string("That tag is in the original, which is never rewritten")];
    return;
  }
  mv::meta::write_fields f;
  f.tags.push_back({k, value ? mv::meta::change<std::string>::to(value) : mv::meta::change<std::string>::remove()});
  _metaWriter.submit(entry->path_utf8, f);
  [self scheduleMetaWrite:0.05];
}

- (void)metaSetDate:(const char*)value {
  const mv::io::dir_entry* entry = [self currentEntry];
  if (!entry || [self refuseWriteTo:entry->path_utf8]) return;
  mv::meta::write_fields f;
  if (value != nullptr) {
    std::string exif_form, xmp_form;
    if (!mv::meta::exif_date_of(value, exif_form, xmp_form)) {
      NSBeep();
      [self noticeShow:std::string("Not a date: use YYYY-MM-DD HH:MM:SS")];
      return;
    }
    f.date_taken = mv::meta::change<std::string>::to(value);
  } else {
    f.date_taken = mv::meta::change<std::string>::remove();
  }
  _metaWriter.submit(entry->path_utf8, f);
  [self scheduleMetaWrite:0.05];
}

// #352: the Summary's Location editor. The text is read again here (the
// field's preview is only a preview); blank removes every GPS row, which the
// pane asks to confirm first. Windows' twin is main.cpp location_change.
- (void)metaSetLocation:(const char*)text {
  const mv::io::dir_entry* entry = [self currentEntry];
  const auto rec = [self metaRecord];
  if (!entry || !rec || [self refuseWriteTo:entry->path_utf8]) return;
  const mv::meta::location_input in = mv::meta::parse_location(text);
  mv::meta::write_fields f;
  if (in.k == mv::meta::location_input::kind::invalid) {
    NSBeep();
    [self noticeShow:std::string(in.error)];
    return;
  }
  if (in.k == mv::meta::location_input::kind::point) {
    f.location = mv::meta::change<mv::meta::geo_point>::to(in.point);
  } else {
    const mv::meta::location_rights rights = mv::meta::location_rights_of(*rec);
    if (!rights.can_clear) {
      NSBeep();
      [self noticeShow:rights.in_original
                           ? std::string("This file's own location is in the original, which is never rewritten")
                           : std::string("There is no location to remove")];
      return;
    }
    f.location = mv::meta::change<mv::meta::geo_point>::remove();
  }
  _metaWriter.submit(entry->path_utf8, f);
  [self scheduleMetaWrite:0.05];
}

- (void)metaRevert {
  const mv::io::dir_entry* entry = [self currentEntry];
  if (!entry || _metaWritten.count(entry->path_utf8) == 0 || [self refuseWriteTo:entry->path_utf8]) return;
  _metaWriter.submit_revert(entry->path_utf8);
  [self noticeShow:std::string("Reverting metadata…")];
  [self scheduleMetaWrite:0.05];
}

- (uint64_t)metaFocusSeq { return _metaFocusSeq; }
- (BOOL)metaFocusTags { return _metaFocusTags; }
- (void)metaBlur { [self.window makeFirstResponder:self.view]; }
- (void)galleryBlur { [self.window makeFirstResponder:self.view]; }

- (void)scheduleMetaWrite:(NSTimeInterval)delay {
  [_metaWriteDebounce invalidate];
  __weak MvLabApp* weakSelf = self;
  _metaWriteDebounce = [NSTimer scheduledTimerWithTimeInterval:delay
                                                       repeats:NO
                                                         block:^(NSTimer* timer) {
                                                           (void)timer;
                                                           [weakSelf startMetaWrite];
                                                         }];
}

- (void)startMetaWrite {
  _metaWriteDebounce = nil;
  if (_metaWriter.in_flight()) return;  // its completion starts the next
  // A lossless rotation of a JPEG owns the file until it lands.
  if (_edits.write_in_flight()) {
    [self scheduleMetaWrite:0.2];
    return;
  }
  const std::optional<mv::shell::meta_job> next = _metaWriter.take_next();
  if (!next) return;
  const mv::shell::meta_job job = *next;
  // The identity the item's edits are filed under; a rewrite changes it.
  std::uint64_t old_size = 0;
  std::int64_t old_mtime = 0;
  for (const auto& entry : _items) {
    if (entry.path_utf8 != job.path) continue;
    old_size = entry.size;
    old_mtime = entry.mtime_unix;
    break;
  }
  __weak MvLabApp* weakSelf = self;
  _jobs.submit_at(mv::background_generation,
                  [job, old_size, old_mtime, weakSelf](const mv::job_context&) -> mv::status {
                    const mv::shell::meta_outcome out = mv::shell::run_meta_job(job);
                    dispatch_async(dispatch_get_main_queue(), ^{
                      [weakSelf metaWriteFinished:out job:job oldSize:old_size oldMtime:old_mtime];
                    });
                    return out.ok ? mv::status::ok : out.error;
                  });
}

- (void)metaWriteFinished:(const mv::shell::meta_outcome&)out
                      job:(const mv::shell::meta_job&)job
                  oldSize:(std::uint64_t)old_size
                 oldMtime:(std::int64_t)old_mtime {
  _metaWriter.finished(out);
  if (!out.ok) {
    (void)_metaWriter.take_failure();
    NSBeep();
    MV_LOG_WARN("metadata write failed: %s", mv::status_name(out.error));  // never the path (rule 6)
    [self noticeShow:job.revert                  ? std::string("Could not revert the metadata")
                     : job.fields.rating.touches() ? std::string("Could not save the rating")
                     : job.fields.comment.touches() ? std::string("Could not save the comment")
                     : job.fields.location.touches() ? std::string("Could not save the location; nothing was changed")
                     : out.error == mv::status::invalid_arg
                         ? std::string("That value does not fit the tag; nothing was changed")
                         : std::string("Could not save the metadata; nothing was changed")];
    if (_metaWriter.has_pending()) [self scheduleMetaWrite:0.0];
    return;
  }

  // What the store cached for this file is out of date: a JPEG's stamp moved,
  // a sidecar's did not, so drop it by path either way.
  _meta.invalidate(out.path);
  if (_tags) {
    _tags->invalidate(out.path);
    [self armTagScan];  // read it again shortly
  }
  struct stat st{};
  if (::stat(out.path.c_str(), &st) == 0) {
    const auto new_size = static_cast<std::uint64_t>(st.st_size);
    const auto new_mtime = static_cast<std::int64_t>(st.st_mtimespec.tv_sec);
    for (auto& entry : _items) {
      if (entry.path_utf8 != out.path) continue;
      entry.size = new_size;
      entry.mtime_unix = new_mtime;
    }
    ++_thumbGeneration;
    // The bytes changed, the pixels did not: keep the item's edits.
    _edits.metadata_rewritten(out.path, old_size, old_mtime, new_size, new_mtime);
  }
  if (job.revert) _metaWritten.erase(out.path);
  else _metaWritten.insert(out.path);

  const mv::io::dir_entry* current = [self currentEntry];
  if (current && current->path_utf8 == out.path) {
    _metaRecord.reset();
    ++_metaGeneration;
    if ([self metadataWanted]) [self requestMetadataNow];
  }

  // Say where it went, unless another change to the same file is already queued
  // (its message is the one that matters).
  if (!_metaWriter.busy_for(out.path)) {
    std::string text = job.revert ? std::string("Metadata reverted") : mv::shell::describe_write(job.fields);
    if (out.target == mv::meta::write_target::sidecar && out.sidecar_touched) {
      const std::size_t sep = out.sidecar_path.find_last_of('/');
      text += "  \xE2\x80\x94 " + out.sidecar_path.substr(sep == std::string::npos ? 0 : sep + 1);  // — IMG_1234.xmp
    }
    if (!text.empty()) [self noticeShow:text];
  }
  if (_metaWriter.has_pending()) [self scheduleMetaWrite:0.0];
}

- (void)noticeShow:(const std::string&)text {
  _noticeText = text;
  ++_noticeGeneration;
  [_noticeTimer invalidate];
  __weak MvLabApp* weakSelf = self;
  _noticeTimer = [NSTimer scheduledTimerWithTimeInterval:3.0
                                                 repeats:NO
                                                   block:^(NSTimer* timer) {
                                                     (void)timer;
                                                     [weakSelf noticeClear];
                                                   }];
}

// A notice for work in flight: no timer, it stays until its owner clears it
// (noticeClear) or another notice replaces it. Opening the Photos library (#420).
- (void)noticeShowUntilCleared:(const std::string&)text {
  [_noticeTimer invalidate];
  _noticeTimer = nil;
  _noticeText = text;
  ++_noticeGeneration;
}

- (void)noticeClear {
  [_noticeTimer invalidate];
  _noticeTimer = nil;
  _noticeText.clear();
  ++_noticeGeneration;
}

- (uint64_t)noticeGeneration { return _noticeGeneration; }
- (std::string)noticeText { return _noticeText; }

- (void)setMetaPaneVisible:(BOOL)visible {
  [self setMetaPaneVisible:visible focus:visible];
}

// docs/design/16 `I`: showing the pane focuses it (← → tabs, ↓ tag search, Esc
// back to the canvas, issue #185). The Edit workspace's Info tab shows it
// without the keyboard, as its Jobs tab does.
- (void)setMetaPaneVisible:(BOOL)visible focus:(BOOL)focus {
  if (visible == _metaPaneVisible) return;
  _metaPaneVisible = visible;
  self.metaHost.hidden = !visible;
  [self layoutAIBadge];  // #345
  ++_metaGeneration;
  if (!visible) [self workspacePaneClosed:mv::shell::edit_tab::info];
  if (visible) [self requestMetadataNow];
  if (visible && focus) {
    _metaFocusTags = NO;
    ++_metaFocusSeq;
    [self.window makeFirstResponder:self.metaHost];
  } else {
    [self.window makeFirstResponder:self.view];
  }
}

- (BOOL)treeVisible { return _treeVisible; }
// docs/design/16 "Folder tree": ⌘⇧E shows and focuses it (issue #185).
- (void)setTreeVisible:(BOOL)visible {
  if (visible == _treeVisible) return;
  _treeVisible = visible;
  self.treeHost.hidden = !visible;
  [self.window makeFirstResponder:visible ? self.treeHost : self.view];
}
- (void)treeBlur { [self.window makeFirstResponder:self.view]; }
- (NSString*)currentFolder {
  return [NSString stringWithUTF8String:_currentDir.c_str()];
}
- (void)openFolderPath:(const char*)utf8_path {
  // A tree click stays on the trail (visit), so the root the user started from
  // remains the root. Open Folder from the menu still resets it.
  if (!utf8_path || ![self openPath:utf8_path navigation:YES]) NSBeep();
}

// Sort. `sortItems` orders `_items` for a fresh listing; `resortKeepingSelection`
// re-orders the same listing when the order (or the date keys) change, keeping the
// current item current without reloading its image.
- (void)sortItems {
  const mv::meta::tag_index* tags = _tags.get();
  mv::io::sort_entries(_items, _sort, [tags](const mv::io::dir_entry& e) {
    return tags ? tags->date_key(e) : std::optional<std::int64_t>{};
  });
  // Sorting never starts the tag pass: resortKeepingSelection runs when the
  // pass ends, and restarting it there would re-read the cache and re-list
  // the folder on every tick. A fresh listing and a change to date-taken
  // order start it (refreshFolderIfChanged, setSortOrder:).
}

// #291: the folder's tag pass starts once the item on screen has its first
// pixel (or after a second, for a clip or a slow file), so it never runs ahead
// of the view or the +-2 prefetch (CLAUDE.md "The view comes first"). No timer
// polls the folder any more (issue #178), so a fresh listing arms a short one
// (-armTagScan) that checks every 0.2 s and stops as soon as the pass starts:
// within about a second, then nothing ticks.
- (void)armTagScan {
  _tagScanPending = YES;
  if (_tagScanTimer) return;
  __weak MvLabApp* weakSelf = self;
  _tagScanTimer = [NSTimer scheduledTimerWithTimeInterval:0.2
                                                  repeats:YES
                                                    block:^(NSTimer* timer) {
                                                      (void)timer;
                                                      [weakSelf tagScanTick];
                                                    }];
  _tagScanTimer.tolerance = 0.04;
}

- (void)tagScanTick {
  [self startTagScanIfDue];
  if (_tagScanPending && !_listOpen && !_items.empty()) return;
  [_tagScanTimer invalidate];
  _tagScanTimer = nil;
}

// #612 (docs/design/04 "Thumbnail cache upkeep"): the cache's sweep, once a
// launch, when a still is on screen: never ahead of the view (CLAUDE.md). A
// background job that waits while the viewer pans or plays.
- (void)startThumbSweepIfDue {
  if (_thumbSweepStarted || !_lab.showing_still()) return;
  _thumbSweepStarted = YES;
  [self startThumbSweep];
}

- (void)startThumbSweep {
  _folder.start_thumb_sweep(_jobs, g_thumb_cache_cap.load(std::memory_order_relaxed),
                            [] { return mv::shell::g_present_busy.load(std::memory_order_relaxed); });
}

- (void)startTagScanIfDue {
  if (!_tagScanPending || _listOpen || _items.empty()) return;
  if (!_lab.showing_still() && CFAbsoluteTimeGetCurrent() - _tagScanListedAt < 1.0) return;
  [self startTagScan];
}

- (void)startTagScan {
  _tagScanPending = NO;
  if (!_tags || _listOpen || _items.empty() || _currentDir.empty()) return;
  std::vector<mv::io::dir_entry> files;
  files.reserve(_items.size());
  for (const auto& e : _items) files.push_back(e);  // Photos keys too (PHAsset.location)
  // Each chunk and the end post one refresh (coalesced): it bumps the tag
  // generation for an open file search and re-sorts by date once the pass
  // ends. Issue #178: nothing polls for it.
  _tags->scan(
      _currentDir, std::move(files), _jobs,
      [] {
        if (g_tag_refresh_posted.exchange(true, std::memory_order_acq_rel)) return;
        dispatch_async(dispatch_get_main_queue(), ^{
          g_tag_refresh_posted.store(false, std::memory_order_release);
          [g_chrome_app refreshFolderIfChanged];
        });
      },
      [] { return mv::shell::g_present_busy.load(std::memory_order_relaxed); });
}

- (uint64_t)tagGeneration {
  return _tagGeneration;
}

// {"done":n,"total":m,"reading":b,"hits":[[index,"why"],...]}: the files of
// the listing whose tags hold every word, in listing order (names are the
// chrome's own half).
- (std::string)tagSearchJSON:(const char*)query {
  mv::json::writer w;
  w.begin_object();
  const auto p = _tags ? _tags->progress() : mv::meta::tag_index::progress_info{};
  w.key("done").integer(p.done);
  w.key("total").integer(p.total);
  w.key("reading").boolean(p.reading || _tagScanPending);
  w.key("hits").begin_array();
  if (_tags && !_listOpen) {
    if (_tagMapGeneration != _listingGeneration) {
      _tagIndexOf.clear();
      _tagIndexOf.reserve(_items.size());
      for (std::size_t i = 0; i < _items.size(); ++i) _tagIndexOf.emplace(_items[i].path_utf8, i);
      _tagMapGeneration = _listingGeneration;
    }
    for (const auto& h : _tags->match(query)) {
      const auto it = _tagIndexOf.find(h.path);
      if (it == _tagIndexOf.end()) continue;
      w.begin_array();
      w.integer(static_cast<std::int64_t>(it->second));
      w.string(h.why);
      w.end_array();
    }
  }
  w.end_array();
  w.end_object();
  return w.take();
}

- (void)resortKeepingSelection {
  // A result list is ranked, not sorted (docs/design/17 "best match first").
  if (_items.empty() || _listOpen) return;
  const std::size_t at = std::min(_index.current(), _items.size() - 1);
  const std::string current = _items[at].path_utf8;
  [self sortItems];
  std::size_t now = 0;
  for (std::size_t i = 0; i < _items.size(); ++i) {
    if (_items[i].path_utf8 == current) {
      now = i;
      break;
    }
  }
  _index.reset(_items.size(), now);
  _wantSelectedPath = current;
  _snap.item_index = static_cast<std::uint32_t>(now);
  ++_listingGeneration;
  [self updateMarkSnapshot];
  [self publish];
}

// ---- Milestone H: result listings (docs/design/17; mv_folder_open_list's twin) -------
- (const std::string&)displayNameAt:(std::size_t)index {
  if (_listOpen && index < _listNames.size()) return _listNames[index];
  return _items[index].name_utf8;
}

// Two results can share a file name (every camera writes IMG_0001.JPG). The
// tile captions and the gallery's marks go by name, so a repeated name gets
// its folder added.
- (void)makeListNames {
  _listNames.clear();
  _listNames.reserve(_items.size());
  std::vector<std::string> sorted;
  sorted.reserve(_items.size());
  for (const auto& e : _items) sorted.push_back(e.name_utf8);
  std::sort(sorted.begin(), sorted.end());
  for (const auto& e : _items) {
    const auto range = std::equal_range(sorted.begin(), sorted.end(), e.name_utf8);
    if (range.second - range.first < 2) {
      _listNames.push_back(e.name_utf8);
      continue;
    }
    if (mv::shell::photos::is_key(e.path_utf8)) {
      // docs/design/26: a library item has no folder; its date tells two IMG_0001s apart.
      char date[32] = {};
      const time_t t = static_cast<time_t>(e.mtime_unix);
      struct tm tmv {};
      localtime_r(&t, &tmv);
      std::strftime(date, sizeof(date), "%Y-%m-%d %H:%M", &tmv);
      _listNames.push_back(e.name_utf8 + " \u2014 " + date);
      continue;
    }
    const std::string parent = mv::shell::browse_path::parent_of(e.path_utf8);
    _listNames.push_back(e.name_utf8 + " \u2014 " + mv::shell::browse_path::leaf(parent));
  }
  // Still equal (same name in two folders of the same name): the full path is
  // unique, so every file's name falls back to it. A library item's path is
  // its photos: key, which is no name to show: two shots in the same minute
  // are numbered instead (a 23 k-asset library always has a pair, so every
  // caption was a key, #420).
  std::vector<std::string> check = _listNames;
  std::sort(check.begin(), check.end());
  if (std::adjacent_find(check.begin(), check.end()) != check.end()) {
    std::unordered_map<std::string, int> count;
    for (const auto& n : _listNames) ++count[n];
    std::unordered_map<std::string, int> seen;
    bool files_collide = false;
    for (std::size_t i = 0; i < _items.size(); ++i) {
      std::string& n = _listNames[i];
      if (count[n] < 2) continue;
      if (!mv::shell::photos::is_key(_items[i].path_utf8)) {
        files_collide = true;
        continue;
      }
      if (const int k = ++seen[n]; k > 1) n += " (" + std::to_string(k) + ")";
    }
    if (files_collide) {
      for (std::size_t i = 0; i < _items.size(); ++i) {
        if (!mv::shell::photos::is_key(_items[i].path_utf8)) _listNames[i] = _items[i].path_utf8;
      }
    }
  }
}

- (BOOL)openListTitled:(const std::string&)title
                 paths:(std::vector<std::string>)paths
               moments:(std::vector<std::int64_t>)moments
                select:(std::size_t)select
               gallery:(BOOL)gallery {
  if (paths.empty()) return NO;
  moments.resize(paths.size(), -1);
  std::vector<mv::shell::folder_model::list_entry> entries;
  entries.reserve(paths.size());
  for (std::size_t i = 0; i < paths.size(); ++i) {
    mv::shell::folder_model::list_entry e;
    e.path_utf8 = std::move(paths[i]);
    e.moment_ms = moments[i];
    entries.push_back(std::move(e));
  }
  return [self openListTitled:title entries:std::move(entries) select:select gallery:gallery];
}

- (BOOL)openListTitled:(const std::string&)title
               entries:(std::vector<mv::shell::folder_model::list_entry>)entries
                select:(std::size_t)select
               gallery:(BOOL)gallery {
  if (entries.empty()) return NO;
  [self photosListEnding];
  if (!_listOpen) _listReturnDir = _currentDir;
  _listOpen = YES;
  _listTitle = title;
  _listNames.clear();
  _moments.clear();
  _folderFind = NO;
  _folderQuery.clear();
  _browsePath.reset("");
  _folderCursor = -1;
  _subdirs.clear();
  _siblings.clear();
  _siblingIndex = -1;
  _revealChild.clear();
  _galleryIfEmptyDir.clear();
  _wantSelectedPath = select < entries.size() ? entries[select].path_utf8 : std::string();
  // A new search lands its chosen clip on its moment again, even when that
  // result is already on screen (and has since played on).
  if (_shownMoment >= 0) _shownMoment = kShownMomentStale;
  // mv_folder_directory reports "" while a list is open; so does this host.
  _currentDir.clear();
  _items.clear();
  _index.reset(0);
  _metaRecord.reset();
  ++_metaGeneration;
  ++_listingGeneration;

  // A stat per result and the thumbnail cache: never on the main thread
  // (rule 1). Superseded like -openPath:'s own open.
  mv::shell::folder_model* folder = &_folder;
  mv::job_system* jobs = &_jobs;
  const std::uint64_t my_generation = _openGeneration.fetch_add(1, std::memory_order_acq_rel) + 1;
  std::atomic<std::uint64_t>* open_generation = &_openGeneration;
  std::mutex* open_mutex = &_folderOpenMutex;
  _jobs.submit_at(mv::background_generation,
                  [folder, jobs, title, entries = std::move(entries), my_generation,
                   open_generation, open_mutex](const mv::job_context&) mutable -> mv::status {
                    std::lock_guard<std::mutex> lock(*open_mutex);
                    if (open_generation->load(std::memory_order_acquire) != my_generation) {
                      return mv::status::cancelled;
                    }
                    // docs/design/26: a Photos key given as a plain path (a search
                    // result) becomes a virtual entry: one PhotoKit fetch for
                    // the lot gives names and stamps; a deleted asset drops out.
                    std::vector<std::string> keys;
                    for (const auto& e : entries) {
                      if (!e.is_virtual && mv::shell::photos::is_key(e.path_utf8)) keys.push_back(e.path_utf8);
                    }
                    if (!keys.empty()) {
                      auto described = mv::shell::photos::describe(keys);
                      std::unordered_map<std::string, const mv::shell::photos::item*> by_key;
                      if (described) {
                        for (std::size_t i = 0; i < keys.size(); ++i) {
                          if (described.value()[i]) by_key[keys[i]] = &*described.value()[i];
                        }
                      }
                      std::vector<mv::shell::folder_model::list_entry> kept;
                      kept.reserve(entries.size());
                      for (auto& e : entries) {
                        if (e.is_virtual || !mv::shell::photos::is_key(e.path_utf8)) {
                          kept.push_back(std::move(e));
                          continue;
                        }
                        const auto hit = by_key.find(e.path_utf8);
                        if (hit == by_key.end()) continue;
                        e.is_virtual = true;
                        e.name_utf8 = hit->second->name;
                        e.mtime_unix = hit->second->mtime;
                        e.size = hit->second->size;
                        kept.push_back(std::move(e));
                      }
                      entries.swap(kept);
                      if (entries.empty()) {
                        dispatch_async(dispatch_get_main_queue(), ^{
                          NSBeep();
                        });
                        return mv::status::not_found;
                      }
                    }
                    auto opened = folder->open_list(title, std::move(entries), *jobs);
                    if (!opened) {
                      dispatch_async(dispatch_get_main_queue(), ^{
                        NSBeep();
                      });
                      return opened.error();
                    }
                    return mv::status::ok;
                  });
  // Enter shows the chosen result on the canvas; Cmd+Enter the whole list as
  // the gallery grid (the chrome brief, docs/design/17 "Results are the gallery").
  // A list opened from Settings (a person's photos) is what the person asked
  // to see: Settings steps aside (owner report, 2026-09-27).
  [self setSettingsVisible:NO];
  [self setGalleryVisible:gallery];
  [self updateChromeBarHeight];
  return YES;
}

- (void)closeList {
  if (!_listOpen) return;
  [self photosListEnding];
  NSString* back = _listReturnDir.empty() ? nil : [NSString stringWithUTF8String:_listReturnDir.c_str()];
  if (!back) return [self returnToWelcome];
  __weak MvLabApp* weakSelf = self;
  [self openEntryPaths:@[ back ]
                failed:^{
                  [weakSelf returnToWelcome];
                }];
}

// Nothing to return to (the list was opened from the empty window, a search
// from the welcome): the window as it was before anything was opened. The
// canvas drops the result it showed, the folder model drops the list, and the
// welcome card lists the recent folders again.
- (void)returnToWelcome {
  _listOpen = NO;
  _listTitle.clear();
  _listReturnDir.clear();
  _moments.clear();
  _listNames.clear();
  _items.clear();
  _subdirs.clear();
  _siblings.clear();
  _siblingIndex = -1;
  _folderCursor = -1;
  _revealChild.clear();
  _galleryIfEmptyDir.clear();
  _currentDir.clear();
  _browsePath.reset("");
  _wantSelectedPath.clear();
  if (!_marks.empty()) {
    _marks.clear();
    ++_marksGeneration;
  }
  [self clearGalleryRange];
  _metaRecord.reset();
  ++_metaGeneration;
  ++_listingGeneration;
  mv::shell::set_read_only_paths({});  // the list's Photos files (write_guard.h)

  // The list may still be opening on a worker: a newer generation supersedes
  // it, and the model closes there too (it joins its watch thread, rule 1).
  mv::shell::folder_model* folder = &_folder;
  const std::uint64_t my_generation = _openGeneration.fetch_add(1, std::memory_order_acq_rel) + 1;
  std::atomic<std::uint64_t>* open_generation = &_openGeneration;
  std::mutex* open_mutex = &_folderOpenMutex;
  _jobs.submit_at(mv::background_generation,
                  [folder, my_generation, open_generation, open_mutex](const mv::job_context&) -> mv::status {
                    std::lock_guard<std::mutex> lock(*open_mutex);
                    if (open_generation->load(std::memory_order_acquire) != my_generation) {
                      return mv::status::cancelled;
                    }
                    folder->close();
                    return mv::status::ok;
                  });

  _lab.close_item();
  _shownItem = 0;
  _shownMoment = -1;
  [self setGalleryVisible:NO];
  [self selectIndex:0];
  [self updateChromeBarHeight];
  [self refreshWelcomeRecents];
  // No folder is open now: Local search's People shows everyone again, not
  // the last folder's people (its scope follows the open folder).
  MvAddonsFolderOpened("");
}

- (BOOL)listOpen { return _listOpen; }

// ---- docs/design/26: the Photos library as a folder -----------------------------------

- (BOOL)photosListOpen {
  return _listOpen && _listTitle == mv::shell::photos::kListTitle;
}

// Settings' flag and PhotoKit access, both: the row, the menu item, the backup.
- (BOOL)photosLibraryAvailable {
  return mv::shell::photos::available() ? YES : NO;
}

// The whole library, oldest first, as a list of virtual items; the newest
// selected, in the gallery (what Photos lands on). Enumeration is PhotoKit on
// a worker, names from the fetched assets (no per-asset resource lookup: that
// took minutes, #420); "photos: listed N assets in M ms" in the unified log.
// A notice says it is opening and stays until the listing ends; one listing
// at a time.
- (void)openPhotosLibrary {
  if (![self photosLibraryAvailable]) {
    NSBeep();
    return;
  }
  if (_photosListing) return;  // the listing in flight opens the list
  _photosListing = YES;
  static const std::string kOpening = "Opening the Photos library…";
  [self noticeShowUntilCleared:kOpening];
  MvLabApp* __weak weakSelf = self;
  _jobs.submit_at(mv::background_generation, [weakSelf](const mv::job_context&) -> mv::status {
    auto listed = mv::shell::photos::enumerate();
    if (!listed) {
      dispatch_async(dispatch_get_main_queue(), ^{
        MvLabApp* strongSelf = weakSelf;
        if (strongSelf) {
          strongSelf->_photosListing = NO;
          if ([strongSelf noticeText] == kOpening) [strongSelf noticeClear];
        }
        NSBeep();
      });
      return listed.error();
    }
    auto entries = std::make_shared<std::vector<mv::shell::folder_model::list_entry>>();
    entries->reserve(listed->size());
    for (auto& it : listed.value()) {
      mv::shell::folder_model::list_entry e;
      e.path_utf8 = std::move(it.key);
      e.is_virtual = true;
      e.name_utf8 = std::move(it.name);
      e.mtime_unix = it.mtime;
      e.size = it.size;
      entries->push_back(std::move(e));
    }
    dispatch_async(dispatch_get_main_queue(), ^{
      MvLabApp* strongSelf = weakSelf;
      if (!strongSelf) return;
      strongSelf->_photosListing = NO;
      if ([strongSelf noticeText] == kOpening) [strongSelf noticeClear];
      if (entries->empty()) {
        [strongSelf noticeShow:"Your Photos library has no photos or videos MediaViewer can show."];
        return;
      }
      const std::size_t newest = entries->size() - 1;
      [strongSelf openListTitled:std::string(mv::shell::photos::kListTitle)
                         entries:std::move(*entries)
                          select:newest
                         gallery:YES];
    });
    return mv::status::ok;
  });
}

// A list is ending (another opens, a folder opens, Back): the on-view iCloud
// downloads go ("cleared after", owner 2026-09-28) and so does what the keys
// resolved to. Previews stay until the next launch; they are tiny.
- (void)photosListEnding {
  [_photosFetchTimer invalidate];
  _photosFetchTimer = nil;
  if (_photosFetchCancel) _photosFetchCancel->store(true, std::memory_order_release);
  _photosFetchCancel.reset();
  ++_photosResolveSeq;
  if (_photosResolved.empty()) return;
  _photosResolved.clear();
  _jobs.submit_at(mv::background_generation, [](const mv::job_context&) -> mv::status {
    mv::shell::photos::clear_downloads();
    return mv::status::ok;
  });
}

- (std::string)fileForEntry:(const mv::io::dir_entry&)entry {
  if (!mv::shell::photos::is_key(entry.path_utf8)) return entry.path_utf8;
  const auto hit = _photosResolved.find(entry.path_utf8);
  if (hit == _photosResolved.end() || hit->second.preview) return {};
  return hit->second.path;
}

// Opens a Photos item through its file. Memoised, the second visit is as
// direct as a file's; otherwise PhotoKit resolves it on a worker (milliseconds
// in place; a preview JPEG written once for an iCloud-only original) and the
// open follows on the main thread if the user is still on it. The neighbours
// resolve in a job of their own after it, so the next arrow does not wait.
- (void)openPhotosEntry:(const mv::io::dir_entry&)entry moment:(std::int64_t)moment {
  const auto hit = _photosResolved.find(entry.path_utf8);
  if (hit != _photosResolved.end()) {
    [self showResolvedPhotos:hit->second entry:entry moment:moment];
    return;
  }
  const std::uint64_t seq = ++_photosResolveSeq;
  const std::string key = entry.path_utf8;
  std::vector<std::string> near;
  const std::size_t cur = _index.current();
  for (const int off : {1, -1, 2, -2}) {
    const auto i = static_cast<std::ptrdiff_t>(cur) + off;
    if (i < 0 || static_cast<std::size_t>(i) >= _items.size()) continue;
    const std::string& p = _items[static_cast<std::size_t>(i)].path_utf8;
    if (mv::shell::photos::is_key(p) && !_photosResolved.count(p)) near.push_back(p);
  }
  MvLabApp* __weak weakSelf = self;
  mv::job_system* jobs = &_jobs;
  // The item first, on its own: it goes up as soon as it resolves. The
  // neighbours followed it in the same job, so a click waited for up to four
  // more PhotoKit reads (iCloud-only ones the slowest) before anything showed
  // (2026-10-05). They resolve after, in the background, for the next arrow.
  _jobs.submit([weakSelf, key, near, seq, jobs](const mv::job_context&) -> mv::status {
    auto got = mv::shell::photos::resolve(key, false);
    const mv::status st = got ? mv::status::ok : got.error();
    auto resolved = std::make_shared<std::optional<mv::shell::photos::resolved>>();
    if (got) *resolved = std::move(got).value();
    dispatch_async(dispatch_get_main_queue(), ^{
      MvLabApp* strongSelf = weakSelf;
      if (!strongSelf) return;
      if (*resolved) strongSelf->_photosResolved[key] = **resolved;
      if (seq != strongSelf->_photosResolveSeq) return;  // the user has moved on
      if (strongSelf->_items.empty() || strongSelf->_index.current() >= strongSelf->_items.size()) return;
      const mv::io::dir_entry& now = strongSelf->_items[strongSelf->_index.current()];
      if (now.path_utf8 != key) return;
      if (!*resolved) {
        [strongSelf noticeShow:st == mv::status::not_found
                                   ? "This item is no longer in your Photos library."
                                   : "This item could not be read from Photos."];
        return;
      }
      const std::int64_t at = strongSelf->_listOpen && strongSelf->_index.current() < strongSelf->_moments.size()
                                  ? strongSelf->_moments[strongSelf->_index.current()]
                                  : -1;
      [strongSelf showResolvedPhotos:**resolved entry:now moment:at];
    });
    if (!got || near.empty()) return st;
    jobs->submit_at(mv::background_generation, [weakSelf, near, seq](const mv::job_context&) -> mv::status {
      auto extra = std::make_shared<std::vector<std::pair<std::string, mv::shell::photos::resolved>>>();
      for (const std::string& n : near) {
        if (auto r = mv::shell::photos::resolve(n, false)) extra->emplace_back(n, std::move(r).value());
      }
      dispatch_async(dispatch_get_main_queue(), ^{
        MvLabApp* strongSelf = weakSelf;
        if (!strongSelf) return;
        std::vector<std::string> prefetch;
        for (auto& [k, r] : *extra) {
          if (!r.preview || !strongSelf->_photosResolved.count(k)) strongSelf->_photosResolved[k] = r;
          if (!mv::shell::is_video_name(r.path)) prefetch.push_back(r.path);
        }
        // Still on the item they are the neighbours of: decode them ahead.
        if (seq == strongSelf->_photosResolveSeq && !prefetch.empty()) strongSelf->_lab.prefetch(prefetch);
      });
      return mv::status::ok;
    });
    return st;
  });
}

- (void)showResolvedPhotos:(const mv::shell::photos::resolved&)resolved
                     entry:(const mv::io::dir_entry&)entry
                    moment:(std::int64_t)moment {
  // With the file's stamp: a revisit is a still-cache hit, as for any file.
  _shownItem = _lab.open_item(resolved.path,
                              resolved.mtime_unix != 0 ? resolved.mtime_unix : mv::shell::present_lab_mac::kNoStamp,
                              resolved.size, moment);
  [self editItemOpened:entry item:_shownItem];
  [self metadataSelectionChanged];
  [self aiBadgeSelectionChanged];
  [_photosFetchTimer invalidate];
  _photosFetchTimer = nil;
  if (!resolved.preview) return;
  // A preview: after a short stay (arrowing past fetches nothing), the
  // original comes from iCloud and replaces it in place -- the viewer's usual
  // first-picture-then-full-resolution refinement, over the network.
  const std::string key = entry.path_utf8;
  MvLabApp* __weak weakSelf = self;
  _photosFetchTimer = [NSTimer scheduledTimerWithTimeInterval:0.4
                                                      repeats:NO
                                                        block:^(NSTimer*) {
                                                          [weakSelf fetchPhotosOriginal:key];
                                                        }];
}

- (void)fetchPhotosOriginal:(const std::string&)key {
  _photosFetchTimer = nil;
  if (_items.empty() || _index.current() >= _items.size() || _items[_index.current()].path_utf8 != key) return;
  // Already coming (the Edit pane asked too), and not stopped by a navigation.
  if (_photosFetchingKey == key && _photosFetchCancel && !_photosFetchCancel->load(std::memory_order_acquire)) return;
  if (_photosFetchCancel) _photosFetchCancel->store(true, std::memory_order_release);
  auto cancel = std::make_shared<std::atomic<bool>>(false);
  _photosFetchCancel = cancel;
  _photosFetchingKey = key;
  MvLabApp* __weak weakSelf = self;
  // Background generation: the download outlives a navigation; the cancel
  // flag, not the generation, is what stops it (and removes the part file).
  // S0: its progress shows in the notice ("Downloading from iCloud… 40 %").
  _jobs.submit_at(mv::background_generation, [weakSelf, key, cancel](const mv::job_context&) -> mv::status {
    auto reported = std::make_shared<std::atomic<bool>>(false);
    const mv::shell::photos::fetch_progress progress = [weakSelf, cancel, reported](double fraction) {
      reported->store(true, std::memory_order_release);
      dispatch_async(dispatch_get_main_queue(), ^{
        if (!cancel->load(std::memory_order_acquire)) [weakSelf photosFetchProgress:fraction];
      });
      return true;  // `cancel` stops it
    };
    auto got = mv::shell::photos::resolve(key, true, cancel.get(), progress);
    const mv::status st = got ? mv::status::ok : got.error();
    auto resolved = std::make_shared<std::optional<mv::shell::photos::resolved>>();
    if (got) *resolved = std::move(got).value();
    const bool fetched = reported->load(std::memory_order_acquire);
    dispatch_async(dispatch_get_main_queue(), ^{
      MvLabApp* strongSelf = weakSelf;
      if (!strongSelf) return;
      // Only this fetch's own mark: a cancelled fetch of the same key landing
      // after a new one started must not make the new one look idle.
      if (strongSelf->_photosFetchCancel == cancel) strongSelf->_photosFetchingKey.clear();
      if (fetched) [strongSelf photosFetchEnded];
      if (cancel->load(std::memory_order_acquire)) return;
      const bool here = !strongSelf->_items.empty() && strongSelf->_index.current() < strongSelf->_items.size() &&
                        strongSelf->_items[strongSelf->_index.current()].path_utf8 == key;
      if (!*resolved) {
        // Offline, or iCloud refused: the preview stays; the sliders, which
        // wait for the original, say they could not get it.
        if (!here) return;
        [strongSelf noticeShow:"The original could not be downloaded from iCloud. The picture shown is a preview."];
        if (const std::uint64_t token = strongSelf->_adjustAwaitingOriginal; token != 0) {
          strongSelf->_adjustAwaitingOriginal = 0;
          [strongSelf workingLanded:token ok:false fromRaw:false working:nullptr];
        }
        return;
      }
      strongSelf->_photosResolved[key] = **resolved;
      if (!here) return;
      strongSelf->_shownItem = 0;  // the bytes changed: reopen on the original
      [strongSelf selectIndex:strongSelf->_index.current()];
    });
    return st;
  });
}

- (void)photosFetchProgress:(double)fraction {
  const int pct = static_cast<int>(std::clamp(fraction, 0.0, 1.0) * 100.0);
  const bool showing = [self noticeText].rfind(mv::shell::photos::kFetchNoticePrefix, 0) == 0;
  if (showing && pct == _photosFetchPercent) return;
  _photosFetchPercent = pct;
  [self noticeShowUntilCleared:mv::shell::photos::fetch_notice(fraction)];
}

- (void)photosFetchEnded {
  _photosFetchPercent = -1;
  if ([self noticeText].rfind(mv::shell::photos::kFetchNoticePrefix, 0) == 0) [self noticeClear];
}

// S0: a saved edit of a library item is a new photo (the media hook's add).
// When the list on screen holds the photo it was made from, it is listed
// right after it, so the arrow (or Show) reaches it, and the notice says so.
// Its name and stamp come from PhotoKit on a worker.
- (void)photosAdded:(const std::string&)key source:(const std::string&)source {
  if (!_listOpen || key.empty()) return;
  if (std::none_of(_items.begin(), _items.end(), [&](const mv::io::dir_entry& e) { return e.path_utf8 == source; })) {
    return;
  }
  mv::shell::folder_model* folder = &_folder;
  MvLabApp* __weak weakSelf = self;
  _jobs.submit_at(mv::background_generation, [weakSelf, folder, key, source](const mv::job_context&) -> mv::status {
    const std::string one[] = {key};
    auto described = mv::shell::photos::describe(std::span<const std::string>(one));
    if (!described) return described.error();
    if (described->empty() || !(*described)[0]) return mv::status::not_found;
    mv::shell::folder_model::list_entry e;
    e.path_utf8 = key;
    e.is_virtual = true;
    e.name_utf8 = (*described)[0]->name;
    e.mtime_unix = (*described)[0]->mtime;
    e.size = (*described)[0]->size;
    auto entry = std::make_shared<mv::shell::folder_model::list_entry>(std::move(e));
    dispatch_async(dispatch_get_main_queue(), ^{
      MvLabApp* strongSelf = weakSelf;
      if (!strongSelf || !strongSelf->_listOpen) return;
      if (folder->insert_virtual(source, std::move(*entry))) {
        [strongSelf noticeShow:std::string(mv::shell::photos::kAddedBesideNotice)];
      }
    });
    return mv::status::ok;
  });
}

// ---- docs/design/26 "Backup": the Photos library's originals to a folder ------------

static NSString* const kPhotosBackupDestinationDefault = @"mv.photosBackup.destination";
static NSString* const kPhotosBackupLastDefault = @"mv.photosBackup.last";
static NSString* const kPhotosBackupLayoutDefault = @"mv.photosBackup.layout";  // backup::layout

static void MvFillBackup(mv_chrome_photos_backup* out, const mv::shell::backup::progress& p) {
  *out = {};
  out->state = static_cast<uint32_t>(p.state);
  out->total = p.total;
  out->done = p.done;
  out->skipped = p.skipped;
  out->failed = p.failed;
  out->fetched = p.fetched;
  out->bytes = p.bytes;
  out->started_unix = p.started_unix;
  out->finished_unix = p.finished_unix;
  std::snprintf(out->current, sizeof(out->current), "%s", p.current.c_str());
  std::snprintf(out->error, sizeof(out->error), "%s", p.error.c_str());
}

- (BOOL)startPhotosBackupTo:(const std::string&)destination {
  if (destination.empty() || ![self photosLibraryAvailable]) return NO;
  if (_photosBackup && _photosBackup->running()) return NO;
  if (!_photosBackup) _photosBackup = std::make_unique<mv::shell::backup::engine>();
  mv::shell::backup::options opts;
  opts.destination = destination;
  opts.folders = static_cast<mv::shell::backup::layout>([self photosBackupLayout]);
  // Fetched originals wait here for their verified copy; emptied at the end.
  NSArray<NSString*>* caches = NSSearchPathForDirectoriesInDomains(NSCachesDirectory, NSUserDomainMask, YES);
  NSString* base = caches.firstObject ?: [NSHomeDirectory() stringByAppendingPathComponent:@"Library/Caches"];
  opts.scratch = std::string([[[base stringByAppendingPathComponent:@"MediaViewer"]
      stringByAppendingPathComponent:@"Photos Backup"] UTF8String]);
  if (!_photosBackup->start(mv::shell::backup::make_photos_source(), std::move(opts))) return NO;
  _photosBackupRecorded = NO;
  [[NSUserDefaults standardUserDefaults] setObject:[NSString stringWithUTF8String:destination.c_str()]
                                            forKey:kPhotosBackupDestinationDefault];
  return YES;
}

- (void)cancelPhotosBackup {
  if (_photosBackup) _photosBackup->cancel();
}

- (void)photosBackupProgress:(mv_chrome_photos_backup*)out {
  if (!out) return;
  if (!_photosBackup) {
    *out = {};
    return;
  }
  const mv::shell::backup::progress p = _photosBackup->snapshot();
  MvFillBackup(out, p);
  // A run that has ended is remembered once, for the "last backup" line.
  const bool ended = p.state == mv::shell::backup::run_state::done ||
                     p.state == mv::shell::backup::run_state::cancelled ||
                     p.state == mv::shell::backup::run_state::failed;
  if (ended && !_photosBackupRecorded && !_photosBackup->running()) {
    _photosBackupRecorded = YES;
    [[NSUserDefaults standardUserDefaults] setObject:@{
      @"finished" : @(p.finished_unix),
      @"done" : @(p.done),
      @"skipped" : @(p.skipped),
      @"failed" : @(p.failed),
      @"state" : @(static_cast<int>(p.state)),
    }
                                              forKey:kPhotosBackupLastDefault];
  }
}

- (std::string)photosBackupDestination {
  NSString* dest = [[NSUserDefaults standardUserDefaults] stringForKey:kPhotosBackupDestinationDefault];
  return dest.UTF8String ? std::string(dest.UTF8String) : std::string();
}

// Absent (every backup before issue #414) is 0, year/day: an existing backup
// keeps writing the tree it has.
- (int32_t)photosBackupLayout {
  const NSInteger v = [[NSUserDefaults standardUserDefaults] integerForKey:kPhotosBackupLayoutDefault];
  return v >= 0 && v < mv::shell::backup::kLayoutCount ? static_cast<int32_t>(v) : 0;
}

- (void)setPhotosBackupLayout:(int32_t)layout {
  if (layout < 0 || layout >= mv::shell::backup::kLayoutCount) return;
  [[NSUserDefaults standardUserDefaults] setInteger:layout forKey:kPhotosBackupLayoutDefault];
}

- (BOOL)photosBackupLast:(mv_chrome_photos_backup*)out {
  if (!out) return NO;
  NSDictionary* last = [[NSUserDefaults standardUserDefaults] dictionaryForKey:kPhotosBackupLastDefault];
  if (!last) return NO;
  *out = {};
  out->finished_unix = [last[@"finished"] longLongValue];
  out->done = static_cast<uint64_t>([last[@"done"] unsignedLongLongValue]);
  out->skipped = static_cast<uint64_t>([last[@"skipped"] unsignedLongLongValue]);
  out->failed = static_cast<uint64_t>([last[@"failed"] unsignedLongLongValue]);
  out->state = static_cast<uint32_t>([last[@"state"] intValue]);
  return out->finished_unix != 0;
}
// The clip the render thread has adopted is the item on screen, not the one
// before it while the new one is still opening.
- (BOOL)liveClipIsShown {
  const auto st = _lab.video_status_snapshot();
  return st.active && _shownItem != 0 && st.item == _shownItem ? YES : NO;
}
- (std::string)listTitle { return _listOpen ? _listTitle : std::string(); }
- (std::string)currentItemPath {
  if (_items.empty() || _index.current() >= _items.size()) return {};
  return _items[_index.current()].path_utf8;
}
- (std::string)itemPathAtIndex:(NSInteger)index {
  if (index < 0 || static_cast<std::size_t>(index) >= _items.size()) return {};
  return [self fileForEntry:_items[static_cast<std::size_t>(index)]];
}
// The gallery / filmstrip thumbnail key (mv_chrome_item_thumb_key): the
// content identity the thumb cache already uses (path + size + mtime), plus a
// result list's moment, so a same-named file in another folder or a rewritten
// file never matches an old thumbnail (issue #177).
- (std::string)thumbKeyAtIndex:(NSInteger)index {
  if (index < 0 || static_cast<std::size_t>(index) >= _items.size()) return {};
  const auto at = static_cast<std::size_t>(index);
  const mv::io::dir_entry& entry = _items[at];
  std::string key = entry.path_utf8;
  key += '\n';
  key += std::to_string(entry.size);
  key += '\n';
  key += std::to_string(entry.mtime_unix);
  if (_listOpen && at < _moments.size() && _moments[at] >= 0) {
    key += '\n';
    key += std::to_string(_moments[at]);
  }
  return key;
}
// mv_chrome_listing (issue #226): per item, name NUL clip ('0'/'1') NUL thumb
// key NUL -- what itemNameAtIndex, itemIsVideoAtIndex and thumbKeyAtIndex
// give one at a time, for the whole listing in one bridge call.
- (std::string)listingSnapshot {
  std::string out;
  out.reserve(_items.size() * 128);
  for (std::size_t i = 0; i < _items.size(); ++i) {
    out += [self displayNameAt:i];
    out += '\0';
    out += mv::shell::is_video_name(_items[i].name_utf8) ? '1' : '0';
    out += '\0';
    out += [self thumbKeyAtIndex:static_cast<NSInteger>(i)];
    out += '\0';
  }
  return out;
}

- (void)setScrubMarkers:(std::vector<std::int64_t>)ms
                current:(int32_t)current
                forPath:(const std::string&)path {
  _scrubMs = std::move(ms);
  _scrubPath = _scrubMs.empty() ? std::string() : path;
  _scrubCurrent = current;
  ++_scrubGeneration;
}
- (uint64_t)scrubGeneration { return _scrubGeneration; }
- (int32_t)scrubMarkersInto:(int64_t*)out cap:(int32_t)cap current:(int32_t*)current {
  // Only the clip on screen: markers for a clip the user has left are stale.
  if (_scrubMs.empty() || _scrubPath != [self currentItemPath]) return 0;
  if (current) *current = _scrubCurrent;
  const auto n = static_cast<int32_t>(_scrubMs.size());
  if (out && cap > 0) {
    std::memcpy(out, _scrubMs.data(), sizeof(int64_t) * static_cast<std::size_t>(std::min(n, cap)));
  }
  return n;
}

// Issue #206: View > Show. A view of the folder for this run only: the same
// relist path as Settings' kinds (-refreshFolderIfChanged), no rescan.
- (int32_t)kindFilter { return static_cast<int32_t>(_kindFilter); }
- (BOOL)setKindFilter:(mv::io::kind_filter)f {
  std::set<std::string> kept;
  if (f == mv::io::kind_filter::marked) {
    if (_marks.empty()) {
      [self noticeShow:"Nothing is marked"];
      NSBeep();
      return NO;
    }
    kept = _marks;
  }
  // Choosing a cull filter again re-applies it: ratings and labels set since
  // (the stop on screen stays under a relist) are what it shows now.
  const bool cull = mv::io::needs_cull_marks(mv::io::kind_filter_mask(f));
  if (f == _kindFilter && kept == _kindKept && !cull) return YES;
  _kindFilter = f;
  _kindKept = std::move(kept);
  _kindFilterChanged = YES;
  _refilterListing = YES;  // picked up by the 0.2 s folder timer, like any relist
  [self noticeShow:mv::io::kind_filter_notice(f)];
  return YES;
}

- (int32_t)sortOrder { return mv::io::pack_sort(_sort); }
- (void)setSortOrder:(int32_t)packed {
  const mv::io::sort_order next = mv::io::unpack_sort(packed);
  if (next.key == _sort.key && next.descending == _sort.descending) return;
  _sort = next;
  [[NSUserDefaults standardUserDefaults] setInteger:packed forKey:@"mv.sort"];
  [self resortKeepingSelection];
  // The tag pass gives the date keys; it reads nothing it already has.
  if (_sort.key == mv::io::sort_key::date_taken && !_listOpen) [self startTagScan];
}

// ---- PR 15: OS integration (docs/design/10 "OS integration", docs/design/16 View) ------------

// The Dock menu's recent folders, the twin of the Windows jump list. A folder
// opened from Finder, the Dock, Open, a drop or argv counts; walking siblings
// or the tree does not (-openPath:navigation: passes those as navigation).
- (void)noteRecentFolder:(const std::string&)dir {
  [self refreshWelcomeRecents];  // something is opening: the card's rows go
  if (_options.soak_seconds > 0.0) return;  // a soak's fixture is not a folder the user opened
  if (!g_boot_report.empty()) return;        // nor a --boot-report's (issue #486)
  std::vector<std::string> next = mv::shell::push_recent_folder(_recentFolders, dir);
  if (next == _recentFolders) return;
  _recentFolders = std::move(next);
  [self persistRecentFolders];
}

// Issue #617: what the card, the Dock menu and File > Open Recent list: the
// pins first, then the recents that are not pinned (os_integration.h). Every
// row index is into this list.
- (std::vector<std::string>)shownFolders {
  return mv::shell::pinned_then_recent(_pinnedFolders, _recentFolders);
}

- (void)persistPinnedFolders {
  NSMutableArray<NSString*>* list = [NSMutableArray array];
  for (const auto& p : _pinnedFolders) {
    if (NSString* s = [NSString stringWithUTF8String:p.c_str()]) [list addObject:s];
  }
  [NSUserDefaults.standardUserDefaults setObject:list forKey:kDefaultsPinnedFolders];
}

// Pin / Unpin from a card row's menu. A soak or a --boot-report records nothing
// (the PR 15 rule), and a full list beeps.
- (void)setFolder:(const std::string&)dir pinned:(BOOL)pin {
  if (_options.soak_seconds > 0.0 || !g_boot_report.empty() || dir.empty()) return;
  std::vector<std::string> next = pin ? mv::shell::pin_folder(_pinnedFolders, dir)
                                      : mv::shell::remove_folder(_pinnedFolders, dir);
  if (next == _pinnedFolders) {
    if (pin) NSBeep();
    return;
  }
  _pinnedFolders = std::move(next);
  [self persistPinnedFolders];
  [self refreshWelcomeRecents];
}

// A folder leaves every list: the recents and, if it was pinned, the pins.
- (void)forgetFolder:(const std::string&)dir {
  _recentFolders = mv::shell::remove_folder(std::move(_recentFolders), dir);
  [self persistRecentFolders];
  if (mv::shell::is_pinned_folder(_pinnedFolders, dir)) {
    _pinnedFolders = mv::shell::remove_folder(std::move(_pinnedFolders), dir);
    [self persistPinnedFolders];
  }
  [self refreshWelcomeRecents];
}

// The shown folder a card row stands for ("" for the iCloud row or none).
- (std::string)welcomeRowFolder:(int)row {
  if (_snap.recents.icloud) {
    if (row == 0) return {};
    --row;
  }
  const std::vector<std::string> shown = [self shownFolders];
  if (row < 0 || static_cast<std::size_t>(row) >= shown.size()) return {};
  return shown[static_cast<std::size_t>(row)];
}

- (NSMenu*)welcomeRowMenu:(int)row {
  const std::string dir = [self welcomeRowFolder:row];
  NSString* path = dir.empty() ? nil : [NSString stringWithUTF8String:dir.c_str()];
  if (!path) return nil;
  const bool pinned = mv::shell::is_pinned_folder(_pinnedFolders, dir);
  NSMenu* menu = [[NSMenu alloc] initWithTitle:@""];
  menu.autoenablesItems = NO;
  NSMenuItem* open = [menu addItemWithTitle:@"Open" action:@selector(openRecentFolder:) keyEquivalent:@""];
  open.target = self;
  open.representedObject = path;
  NSMenuItem* pin = [menu addItemWithTitle:pinned ? @"Unpin" : @"Pin to Top"
                                    action:@selector(togglePinnedFolder:)
                             keyEquivalent:@""];
  pin.target = self;
  pin.representedObject = path;
  pin.enabled = pinned || _pinnedFolders.size() < mv::shell::kMaxPinnedFolders;
  [menu addItem:[NSMenuItem separatorItem]];
  NSMenuItem* remove = [menu addItemWithTitle:@"Remove from List" action:@selector(forgetFolderFromMenu:)
                                keyEquivalent:@""];
  remove.target = self;
  remove.representedObject = path;
  return menu;
}

- (void)togglePinnedFolder:(NSMenuItem*)item {
  NSString* path = item.representedObject;
  if (![path isKindOfClass:[NSString class]]) return;
  const std::string dir = path.UTF8String;
  [self setFolder:dir pinned:mv::shell::is_pinned_folder(_pinnedFolders, dir) ? NO : YES];
}

- (void)forgetFolderFromMenu:(NSMenuItem*)item {
  NSString* path = item.representedObject;
  if (![path isKindOfClass:[NSString class]]) return;
  [self forgetFolder:path.UTF8String];
}

// The welcome card lists recent folders only while nothing has been opened:
// once a folder or file is chosen the card is a hint again, not a menu.
- (BOOL)welcomeListsRecents {
  return _currentDir.empty() && _items.empty() && _wantSelectedPath.empty() && _shownPath.empty() &&
         !_listOpen && !_gameOn && _options.soak_seconds <= 0.0;
}

- (void)refreshWelcomeRecents {
  mv::shell::welcome_recents next;
  if ([self welcomeListsRecents]) {
    const char* home = NSHomeDirectory().fileSystemRepresentation;
    mv::shell::fill_welcome_recents([self shownFolders], home ? home : "", next,
                                    [self photosLibraryAvailable] == YES, _pinnedFolders.size());
  }
  // A row index survives the refresh only if the rows did not move.
  if (next.count == _snap.recents.count && next.icloud == _snap.recents.icloud &&
      next.pinned == _snap.recents.pinned) {
    next.hover = _snap.recents.hover;
    next.hover_remove = _snap.recents.hover_remove;
  }
  if (std::memcmp(&next, &_snap.recents, sizeof(next)) == 0) return;
  _snap.recents = next;
  [self publish];  // one redraw
}

- (int)welcomeRowAtPointer {
  return [self welcomeRowAtPointerOnRemove:nullptr];
}

- (int)welcomeRowAtPointerOnRemove:(BOOL*)onRemove {
  if (onRemove) *onRemove = NO;
  if (_snap.recents.count == 0 || !_snap.mouse_in_client || ![self welcomeListsRecents]) return -1;
  const float scale = _snap.dpi_scale > 0.0f ? _snap.dpi_scale : 1.0f;
  const mv::shell::welcome_geometry g =
      mv::shell::layout_welcome(static_cast<float>(_snap.width), static_cast<float>(_snap.height),
                                static_cast<float>(_snap.chrome_height_px), scale, _snap.recents.count, 0.0f,
                                _snap.recents.icloud);
  const int row = mv::shell::welcome_row_at(g, _snap.mouse_x, _snap.mouse_y);
  // The iCloud row has no remove button.
  if (row >= 0 && onRemove && !(_snap.recents.icloud && row == 0)) {
    *onRemove = mv::shell::welcome_on_remove(g, _snap.mouse_x);
  }
  return row;
}

- (BOOL)welcomePointerMoved {
  BOOL onRemove = NO;
  const int row = [self welcomeRowAtPointerOnRemove:&onRemove];
  const bool remove = onRemove == YES;
  if (row != _snap.recents.hover || remove != _snap.recents.hover_remove) {
    _snap.recents.hover = static_cast<std::int8_t>(row);
    _snap.recents.hover_remove = remove;
    [self publish];
  }
  return row >= 0;
}

// The x on a welcome card row: the folder leaves the card, the Dock menu and
// File > Open Recent. The folder itself is not touched.
- (void)removeWelcomeRow:(int)row {
  // The library leaves from Settings, not the card (its row has no folder).
  const std::string dir = [self welcomeRowFolder:row];
  if (dir.empty()) return;
  [self forgetFolder:dir];  // a pinned folder's x unpins it too
}

- (void)openWelcomeRow:(int)row {
  if (_snap.recents.icloud && row == 0) {
    // The library's settings (its backup), not the library itself: listing
    // every asset is File > Open Photos Library and the folder tree's row.
    [NSCursor.arrowCursor set];
    [self setSettingsVisible:YES];
    [MVChromeHost revealPhotosSettings];
    return;
  }
  const std::string dir = [self welcomeRowFolder:row];
  NSString* path = dir.empty() ? nil : [NSString stringWithUTF8String:dir.c_str()];
  if (!path) return;
  [NSCursor.arrowCursor set];
  NSMenuItem* item = [[NSMenuItem alloc] init];
  item.representedObject = path;
  [self openRecentFolder:item];
}

- (void)persistRecentFolders {
  NSMutableArray<NSString*>* list = [NSMutableArray array];
  for (const auto& p : _recentFolders) {
    if (NSString* s = [NSString stringWithUTF8String:p.c_str()]) [list addObject:s];
  }
  [NSUserDefaults.standardUserDefaults setObject:list forKey:kDefaultsRecentFolders];
}

- (NSMenu*)applicationDockMenu:(NSApplication*)sender {
  (void)sender;
  NSMenu* menu = [[NSMenu alloc] initWithTitle:@""];
  NSMenuItem* newWindow = [menu addItemWithTitle:@"New Window" action:@selector(menuAction:) keyEquivalent:@""];
  newWindow.target = self;
  newWindow.tag = kMenuNewWindow;
  if (_recentFolders.empty() && _pinnedFolders.empty() && ![self photosLibraryAvailable]) return menu;
  [menu addItem:[NSMenuItem separatorItem]];
  [self addRecentFolderItemsTo:menu headers:YES];
  return menu;
}

// File > Open Recent: the Dock menu's list, so the keyboard reaches it too
// (the menu bar, or Help's search).
- (void)menuNeedsUpdate:(NSMenu*)menu {
  if (menu != _openRecentMenu) return;
  [menu removeAllItems];
  [self addRecentFolderItemsTo:menu headers:NO];
  if (menu.numberOfItems == 0) [menu addItemWithTitle:@"No Recent Folders" action:nil keyEquivalent:@""];
}

// Issue #617: the pins first (a pin glyph on each; under a "Pinned Folders"
// header in the Dock menu), a separator, then the recents (under "Recent
// Folders" there). Open Recent has no headers, as the system's own.
- (void)addRecentFolderItemsTo:(NSMenu*)menu headers:(BOOL)headers {
  const std::vector<std::string> shown = [self shownFolders];
  const std::size_t pinned = std::min(_pinnedFolders.size(), shown.size());
  // docs/design/26: the iCloud Photos library first, while it is added in Settings.
  if ([self photosLibraryAvailable]) {
    NSMenuItem* icloud = [menu addItemWithTitle:@"iCloud Photos" action:@selector(openPhotosLibraryFromMenu:)
                                  keyEquivalent:@""];
    icloud.target = self;
    icloud.image = [NSImage imageWithSystemSymbolName:@"icloud" accessibilityDescription:@"iCloud"];
    if (!shown.empty()) [menu addItem:[NSMenuItem separatorItem]];
  }
  const std::vector<std::string> labels = mv::shell::recent_folder_labels(shown);
  for (std::size_t i = 0; i < shown.size(); ++i) {
    if (headers && i == 0 && pinned > 0) [menu addItem:[NSMenuItem sectionHeaderWithTitle:@"Pinned Folders"]];
    if (i == pinned && pinned > 0) [menu addItem:[NSMenuItem separatorItem]];
    if (headers && i == pinned) [menu addItem:[NSMenuItem sectionHeaderWithTitle:@"Recent Folders"]];
    NSString* path = [NSString stringWithUTF8String:shown[i].c_str()];
    NSString* title = [NSString stringWithUTF8String:labels[i].c_str()];
    if (!path || !title) continue;
    NSMenuItem* item = [menu addItemWithTitle:title action:@selector(openRecentFolder:) keyEquivalent:@""];
    item.target = self;
    item.representedObject = path;
    if (i < pinned) item.image = [NSImage imageWithSystemSymbolName:@"pin" accessibilityDescription:@"Pinned"];
  }
}

- (void)openPhotosLibraryFromMenu:(NSMenuItem*)item {
  (void)item;
  [NSApp activate];
  [self.window makeKeyAndOrderFront:nil];
  [self openPhotosLibrary];
}

- (void)openRecentFolder:(NSMenuItem*)item {
  NSString* path = item.representedObject;
  if (![path isKindOfClass:[NSString class]]) return;
  [NSApp activate];
  [self.window makeKeyAndOrderFront:nil];
  const std::string gone = path.UTF8String;
  __weak MvLabApp* weakSelf = self;
  [self openEntryPaths:@[ path ]
                failed:^{
                  // The card was ejected or the folder deleted: it is no longer a place to go.
                  MvLabApp* app = weakSelf;
                  NSBeep();
                  if (!app) return;
                  [app forgetFolder:gone];  // and its pin, if it had one
                }];
}

// ⌘⌥C: the still as the canvas shows it, edits baked, as a PNG. The bake is
// a full-resolution export, so it runs on the pool; the pasteboard is written
// on the main thread when it lands. Both a file (Finder, Mail, Messages) and
// the PNG itself (Preview's New from Clipboard, Keynote) are offered.
- (BOOL)copyFlattened {
  if (_items.empty() || _index.current() >= _items.size() || [self currentItemIsVideo] ||
      _lab.anim_active()) {
    return NO;
  }
  const std::string path = _items[_index.current()].path_utf8;
  const mv::edit::geometry g = _edits.export_geometry();
  const mv::edit::colour c = _edits.colour();
  _jobs.submit_at(mv::background_generation, [path, g, c](const mv::job_context&) -> mv::status {
    mv::result<mv::shell::flattened_copy> out = mv::shell::run_flatten(path, g, c);
    if (!out) {
      dispatch_async(dispatch_get_main_queue(), ^{ NSBeep(); });
      return out.error();
    }
    NSURL* file = [NSURL fileURLWithPath:[NSString stringWithUTF8String:out->path.c_str()]];
    NSData* png = [NSData dataWithBytes:out->png.data() length:out->png.size()];
    dispatch_async(dispatch_get_main_queue(), ^{
      NSPasteboardItem* item = [[NSPasteboardItem alloc] init];
      [item setString:file.absoluteString forType:NSPasteboardTypeFileURL];
      [item setData:png forType:NSPasteboardTypePNG];
      NSPasteboard* board = NSPasteboard.generalPasteboard;
      [board clearContents];
      if (![board writeObjects:@[ item ]]) NSBeep();
    });
    return mv::status::ok;
  });
  return YES;
}

// ---- Issue #614: Print (⌘P; docs/design/16 "Print") --------------------------------

// ⌘P / File ▸ Print…: two or more marks (or a gallery range) as a contact
// sheet, else the still on screen with its edits baked. The bake runs on the
// pool; the panel opens when it lands. NO beeps (nothing here prints).
- (BOOL)printRequest {
  if (_printBusy) {
    [self noticeShow:"Still preparing the last print"];
    return YES;
  }
  const std::vector<mv::io::dir_entry> entries = [self markedOrCurrentEntries];
  const bool sheet = mv::shell::print_as_sheet(entries.size());
  std::vector<mv::shell::print_source> sources;
  const std::string current =
      !_items.empty() && _index.current() < _items.size() ? _items[_index.current()].path_utf8 : std::string();
  if (sheet) {
    // The file on screen keeps its session edits; the other marks print as
    // they are on disk.
    for (const auto& entry : entries) {
      mv::shell::print_source s{entry.path_utf8, {}, {}};
      if (entry.path_utf8 == current) {
        s.g = _edits.export_geometry();
        s.c = _edits.colour();
      }
      sources.push_back(std::move(s));
    }
  } else {
    // As ⌘⌥C: a clip or a playing animation has no still to bake.
    if (current.empty() || [self currentItemIsVideo] || _lab.anim_active()) return NO;
    sources.push_back(mv::shell::print_source{current, _edits.export_geometry(), _edits.colour()});
  }

  // Sized for the paper Page Setup holds, at kPrintDpi. Fit or fill is chosen
  // in the panel, so a photo is baked to cover the page (fill's need, which
  // also serves fit); a sheet's cells for the grid its marks ask for.
  const mv::shell::print_rect area = mv::shell::print_area(MvPrintPage(NSPrintInfo.sharedPrintInfo));
  const mv::shell::print_pixels px =
      sheet ? mv::shell::pixels_for(mv::shell::contact_frame(
                  area, mv::shell::contact_grid(sources.size(), _printOptions.grid), false))
            : mv::shell::pixels_for(area);
  const mv::edit::size2 box{px.w, px.h};
  const bool cover = !sheet;

  _printBusy = YES;
  [self noticeShow:"Preparing to print…"];
  MvLabApp* __weak weakSelf = self;
  _jobs.submit_at(mv::background_generation,
                  [sources, box, cover, sheet, weakSelf](const mv::job_context& ctx) -> mv::status {
                    // A pool thread has no autorelease pool of its own.
                    @autoreleasepool {
                      NSMutableArray* images = [[NSMutableArray alloc] init];
                      std::vector<std::string> names;
                      mv::status st = mv::status::ok;
                      auto keep = [&](const mv::codec::raster& pixels, const std::string& path) {
                        CGImageRef cg = MvPrintImage(pixels);
                        if (!cg) return;
                        [images addObject:(__bridge_transfer id)cg];
                        names.push_back(path);
                      };
                      if (sheet) {
                        auto pics = mv::shell::render_contact_pictures(sources, box, &ctx);
                        if (pics) {
                          for (const auto& p : *pics) keep(p.pixels, p.path);
                        } else {
                          st = pics.error();
                        }
                      } else {
                        const mv::shell::print_source& s = sources.front();
                        auto pic = mv::shell::render_print_picture(s.path, s.g, s.c, box, cover, &ctx);
                        if (pic) {
                          keep(*pic, s.path);
                        } else {
                          st = pic.error();
                        }
                      }
                      dispatch_async(dispatch_get_main_queue(), ^{
                        MvLabApp* strongSelf = weakSelf;
                        if (strongSelf) [strongSelf printPrepared:images names:names sheet:sheet];
                      });
                      return st;
                    }
                  });
  return YES;
}

- (void)printPrepared:(NSArray*)images names:(const std::vector<std::string>&)names sheet:(bool)sheet {
  _printBusy = NO;
  if (images.count == 0 || !self.window) {
    NSBeep();
    [self noticeShow:"Could not prepare the print"];
    return;
  }
  [self noticeClear];
  MvPrintOptions* options = [[MvPrintOptions alloc] init];
  options.sheet = sheet;
  options.fill = _printOptions.fit == mv::shell::print_fit::fill;
  options.captions = _printOptions.captions;
  options.grid = _printOptions.grid;
  MvPrintView* view = [[MvPrintView alloc] initWithImages:images names:names sheet:sheet options:options];
  NSPrintInfo* info = [NSPrintInfo.sharedPrintInfo copy];
  // print_layout keeps its own margins inside the device's imageable area.
  info.topMargin = 0;
  info.bottomMargin = 0;
  info.leftMargin = 0;
  info.rightMargin = 0;
  info.horizontallyCentered = NO;
  info.verticallyCentered = NO;
  NSPrintOperation* op = [NSPrintOperation printOperationWithView:view printInfo:info];
  op.jobTitle = sheet ? @"Contact sheet" : @(std::string(mv::shell::print_caption(names.front())).c_str());
  op.showsPrintPanel = YES;
  op.showsProgressPanel = YES;
  op.canSpawnSeparateThread = YES;  // pages spool off the main thread
  op.printPanel.options |= NSPrintPanelShowsPaperSize | NSPrintPanelShowsOrientation | NSPrintPanelShowsPreview;
  [op.printPanel addAccessoryController:options];
  _printOptionsPanel = options;
  [op runOperationModalForWindow:self.window
                        delegate:self
                  didRunSelector:@selector(printOperationDidRun:success:contextInfo:)
                     contextInfo:nullptr];
}

// Print kept the panel's choices for the next ⌘P (this run only); Cancel drops
// them, and nothing was written.
- (void)printOperationDidRun:(NSPrintOperation*)op success:(BOOL)success contextInfo:(void*)contextInfo {
  (void)op;
  (void)contextInfo;
  if (success && _printOptionsPanel) _printOptions = [_printOptionsPanel chosenOptions];
  _printOptionsPanel = nil;
}

// ---- Text in images (Live Text, docs/design/16 "Text in images") -------------------

// What the words on screen would be read from: the still and its geometry, or
// nothing when there is no still to select in (a clip, audio, a document, an
// animation, the gallery, the Edit workspace). A change drops the old words.
- (mv::shell::text_select::source)textSource {
  mv::shell::text_select::source src;
  if ([self editSubject] != mv::shell::edit_subject::still || _galleryVisible || _ws.open ||
      _edits.crop_active() || _showOriginal || _compareOn) {
    return src;
  }
  src.item = _itemId;
  src.geometry = _edits.export_geometry();
  return src;
}

- (void)textSync {
  if (_text.show([self textSource])) [self textPublish];
}

- (void)textPublish {
  _text.fill(_snap.text);
  [self pokeSnapshot];
}

// The pointer in 0..1 of the still as the render thread last drew it.
- (BOOL)textPointX:(float)x y:(float)y u:(float*)u v:(float*)v aspect:(float*)aspect {
  const mv::shell::canvas_map map = _lab.still_map();
  if (!map.to_uv(x, y, *u, *v)) return NO;
  *aspect = map.aspect();
  return YES;
}

- (BOOL)textPressX:(float)x y:(float)y clicks:(NSInteger)clicks {
  [self textSync];
  if (!_text.has_words()) return NO;
  if (_snap.eyedropper || _snap.loupe) return NO;
  float u = 0, v = 0, aspect = 1;
  if (![self textPointX:x y:y u:&u v:&v aspect:&aspect]) return NO;
  const bool had = _text.has_selection();
  const bool on_text = _text.press(u, v, aspect, static_cast<int>(clicks));
  if (on_text || had) [self textPublish];
  return on_text ? YES : NO;
}

- (void)textDragX:(float)x y:(float)y {
  float u = 0, v = 0, aspect = 1;
  if (![self textPointX:x y:y u:&u v:&v aspect:&aspect]) return;
  _text.drag(u, v);
  [self textPublish];
}

- (void)textRelease {
  const bool had = _text.has_selection();
  _text.release();
  if (had != _text.has_selection()) [self textPublish];
}

// The pointer moved over the canvas. Reading a still costs a decode and the
// recogniser, so it waits until the pointer has rested on a still for half a
// second (arrowing through a folder never reads anything), runs on the pool
// (rule 1) and on device (rule 6), and is read once per still and geometry.
- (BOOL)textHoverX:(float)x y:(float)y {
  [self textSync];
  float u = 0, v = 0, aspect = 1;
  const BOOL placed = [self textPointX:x y:y u:&u v:&v aspect:&aspect];
  if (placed && _text.wants_read() && !_textDwell) {
    MvLabApp* __weak weakSelf = self;
    _textDwell = [NSTimer scheduledTimerWithTimeInterval:0.5
                                                 repeats:NO
                                                   block:^(NSTimer*) {
                                                     MvLabApp* strongSelf = weakSelf;
                                                     if (!strongSelf) return;
                                                     strongSelf->_textDwell = nil;
                                                     [strongSelf textRead];
                                                   }];
  }
  return placed && !_snap.eyedropper && !_snap.loupe && _text.over_text(u, v, aspect) ? YES : NO;
}

- (void)textRead {
  [self textSync];
  if (!_text.wants_read() || _items.empty() || _index.current() >= _items.size()) return;
  if (!_lab.still_map().valid) return;
  const mv::shell::text_select::source src = _text.current();
  // A Photos item (issue #451) is read from the file the canvas shows (its
  // rendition, or the preview standing in for an iCloud-only original), never
  // its "photos:" key, which no decoder opens. Not resolved yet: no read, and
  // the next rest on it asks again.
  std::string path = _items[_index.current()].path_utf8;
  if (mv::shell::photos::is_key(path)) {
    const auto hit = _photosResolved.find(path);
    if (hit == _photosResolved.end() || hit->second.path.empty()) return;
    path = hit->second.path;
  }
  _text.reading();
  MvLabApp* __weak weakSelf = self;
  _jobs.submit_at(mv::background_generation, [path, src, weakSelf](const mv::job_context&) -> mv::status {
    mv::shell::vision_text_recognizer recognizer;
    auto out = std::make_shared<mv::shell::read_text>(mv::shell::run_text_recognition(path, src.geometry, recognizer));
    dispatch_async(dispatch_get_main_queue(), ^{
      MvLabApp* strongSelf = weakSelf;
      if (!strongSelf) return;
      (void)strongSelf->_text.set_words(src, std::move(out->layout));
      // Nothing to say on the Mac: Vision is always there.
    });
    return mv::status::ok;
  });
}

// Issue #444 (docs/design/16 "Share"): the one share command. ⌘⇧S, the
// gallery's share icon, the bar's share button and the right-click Share
// submenu all run it. The files are the range, else the marks, else the
// current one (markedOrCurrentEntries), or the right-clicked file when it is
// not one of them. The Mac lists both halves of a pair as items and keeps no
// pairing, so this is a walk of the in-memory listing with no syscall: no
// stat, no read (a Photos item without a file yet is left out). The chrome
// (ShareMenu.swift) shows the menu: Driftwire, then the system's picker.
- (std::vector<std::string>)shareFilesForClicked:(NSInteger)clicked {
  std::vector<std::string> selection;
  for (const auto& entry : [self markedOrCurrentEntries]) {
    std::string file = [self fileForEntry:entry];
    if (!file.empty()) selection.push_back(std::move(file));
  }
  std::string picked;
  if (clicked >= 0 && static_cast<std::size_t>(clicked) < _items.size()) {
    picked = [self fileForEntry:_items[static_cast<std::size_t>(clicked)]];
    if (picked.empty()) return {};  // a Photos item still without its file
  }
  return mv::shell::share_stops(std::move(selection), picked);
}

// {"files": [...], "media": [...]}: Driftwire's, and the system picker's
// (media only, no sidecars).
- (std::string)shareFilesJSONForClicked:(NSInteger)clicked {
  const std::vector<std::string> files = [self shareFilesForClicked:clicked];
  if (files.empty()) return {};
  mv::json::writer w;
  w.begin_object();
  w.key("files").begin_array();
  for (const std::string& f : files) w.string(f);
  w.end_array();
  w.key("media").begin_array();
  for (const std::string& f : mv::shell::share_system_files(files)) w.string(f);
  w.end_array();
  w.end_object();
  return w.str();
}

- (BOOL)shareRequest:(mv::shell::share_request)request {
  const std::string json = [self shareFilesJSONForClicked:request.clicked];
  if (json.empty()) {
    NSBeep();
    return NO;
  }
  [MVChromeHost presentShare:[NSString stringWithUTF8String:json.c_str()]
                      target:static_cast<NSInteger>(request.target)
                        from:static_cast<NSInteger>(request.from)];
  return YES;
}

// Now Playing (the taskbar transport buttons' and SMTC's twin): Control
// Centre, the menu-bar widget, the keyboard's media keys and AirPods drive the
// clip. The info is republished only when the system could not extrapolate it
// (play / pause, rate, a new clip, a seek); a 0.5 s poll of the render
// thread's status runs only while a clip is the current item.
- (void)nowPlayingItemChanged {
  if (![self currentItemIsVideo] && !_nowPlayingTimer) return;
  [self wireRemoteCommands];
  _nowPlayingShown = {};
  if (!_nowPlayingTimer) {
    _nowPlayingTimer = [NSTimer scheduledTimerWithTimeInterval:0.5
                                                        target:self
                                                      selector:@selector(nowPlayingTick:)
                                                      userInfo:nil
                                                       repeats:YES];
    _nowPlayingTimer.tolerance = 0.2;
  }
  [self nowPlayingTick:nil];
}

- (void)nowPlayingTick:(NSTimer*)timer {
  (void)timer;
  MPNowPlayingInfoCenter* center = MPNowPlayingInfoCenter.defaultCenter;
  const BOOL video = [self currentItemIsVideo];
  const auto st = _lab.video_status_snapshot();
  [self syncKeepAwake];  // issue #228: this poll is where play / pause / end is seen
  if (!video) {
    center.nowPlayingInfo = nil;
    center.playbackState = MPNowPlayingPlaybackStateStopped;
    [_nowPlayingTimer invalidate];
    _nowPlayingTimer = nil;
    _nowPlayingShown = {};
    return;
  }
  if (!st.active) return;  // the clip is still opening
  const auto& was = _nowPlayingShown;
  // Where the last published state says the playhead is now: 0.5 s on at its rate.
  const std::int64_t expected = was.position_ms + (was.playing ? 500 * was.rate_x100 / 100 : 0);
  const bool changed = !was.active || was.playing != st.playing || was.rate_x100 != st.rate_x100 ||
                       was.duration_ms != st.duration_ms || std::llabs(st.position_ms - expected) > 750;
  _nowPlayingShown = st;
  if (!changed) return;
  NSString* title = @"";
  if (_index.current() < _items.size()) {
    title = [NSString stringWithUTF8String:_items[_index.current()].name_utf8.c_str()] ?: @"";
  }
  center.nowPlayingInfo = @{
    MPMediaItemPropertyTitle : title,
    MPNowPlayingInfoPropertyMediaType : @(MPNowPlayingInfoMediaTypeVideo),
    MPMediaItemPropertyPlaybackDuration : @(static_cast<double>(st.duration_ms) / 1000.0),
    MPNowPlayingInfoPropertyElapsedPlaybackTime : @(static_cast<double>(st.position_ms) / 1000.0),
    MPNowPlayingInfoPropertyPlaybackRate : @(st.playing ? st.rate_x100 / 100.0 : 0.0),
    MPNowPlayingInfoPropertyDefaultPlaybackRate : @1.0,
  };
  center.playbackState = st.playing ? MPNowPlayingPlaybackStatePlaying : MPNowPlayingPlaybackStatePaused;
}

// Issue #228: media is being presented -- a clip plays, or a slideshow runs --
// so hold an activity that keeps the display (and the Mac) awake; pause, the
// end of the clip, leaving it or the slideshow lets it go. Driven from the
// slideshow transitions and the Now Playing poll; quitting ends it with the process.
- (void)syncKeepAwake {
  const auto st = _lab.video_status_snapshot();
  const BOOL clipPlaying = [self currentItemIsVideo] && st.active && st.playing;
  const BOOL want = clipPlaying || (_slideshowActive && !_slideshowPaused);
  if (want == (_keepAwakeActivity != nil)) return;
  if (want) {
    _keepAwakeActivity = [NSProcessInfo.processInfo
        beginActivityWithOptions:NSActivityIdleDisplaySleepDisabled | NSActivityIdleSystemSleepDisabled
                          reason:@"Presenting media"];
  } else {
    [NSProcessInfo.processInfo endActivity:_keepAwakeActivity];
    _keepAwakeActivity = nil;
  }
}

- (void)wireRemoteCommands {
  if (_remoteCommandsWired) return;
  _remoteCommandsWired = YES;
  MPRemoteCommandCenter* rc = MPRemoteCommandCenter.sharedCommandCenter;
  MvLabApp* __weak weak = self;
  [rc.togglePlayPauseCommand addTargetWithHandler:^MPRemoteCommandHandlerStatus(MPRemoteCommandEvent* e) {
    (void)e;
    return [weak remoteSetPlaying:-1];
  }];
  [rc.playCommand addTargetWithHandler:^MPRemoteCommandHandlerStatus(MPRemoteCommandEvent* e) {
    (void)e;
    return [weak remoteSetPlaying:1];
  }];
  [rc.pauseCommand addTargetWithHandler:^MPRemoteCommandHandlerStatus(MPRemoteCommandEvent* e) {
    (void)e;
    return [weak remoteSetPlaying:0];
  }];
  // Next / previous walk the folder, as SMTC's do on Windows.
  [rc.nextTrackCommand addTargetWithHandler:^MPRemoteCommandHandlerStatus(MPRemoteCommandEvent* e) {
    (void)e;
    return [weak runCommand:mv::shell::command_id::next back:mv::shell::back_target::none]
               ? MPRemoteCommandHandlerStatusSuccess
               : MPRemoteCommandHandlerStatusCommandFailed;
  }];
  [rc.previousTrackCommand addTargetWithHandler:^MPRemoteCommandHandlerStatus(MPRemoteCommandEvent* e) {
    (void)e;
    return [weak runCommand:mv::shell::command_id::prev back:mv::shell::back_target::none]
               ? MPRemoteCommandHandlerStatusSuccess
               : MPRemoteCommandHandlerStatusCommandFailed;
  }];
  [rc.changePlaybackPositionCommand addTargetWithHandler:^MPRemoteCommandHandlerStatus(MPRemoteCommandEvent* e) {
    MvLabApp* app = weak;
    if (!app || ![e isKindOfClass:[MPChangePlaybackPositionCommandEvent class]]) {
      return MPRemoteCommandHandlerStatusCommandFailed;
    }
    return [app remoteSeekTo:static_cast<MPChangePlaybackPositionCommandEvent*>(e).positionTime];
  }];
}

- (MPRemoteCommandHandlerStatus)remoteSetPlaying:(int)want {
  const auto st = _lab.video_status_snapshot();
  if (![self currentItemIsVideo] || !st.active) return MPRemoteCommandHandlerStatusNoActionableNowPlayingItem;
  if (want < 0 || (want == 1) != st.playing) mv_chrome_video_toggle();
  _nowPlayingShown = {};  // republish on the next tick, with the new state
  return MPRemoteCommandHandlerStatusSuccess;
}

- (MPRemoteCommandHandlerStatus)remoteSeekTo:(NSTimeInterval)seconds {
  const auto st = _lab.video_status_snapshot();
  if (![self currentItemIsVideo] || !st.active) return MPRemoteCommandHandlerStatusNoActionableNowPlayingItem;
  mv_chrome_video_seek(std::llround(std::clamp(seconds, 0.0, st.duration_ms / 1000.0) * 1000.0), true);
  _nowPlayingShown = {};
  return MPRemoteCommandHandlerStatusSuccess;
}

// ---- Settings -----------------------------------------------------------------
static NSString* const kDefaultsViewFlags = @"mv.viewFlags";
static NSString* const kDefaultsKeys = @"mv.keys";
static NSString* const kDefaultsAddonKeys = @"mv.addonKeys";
static NSString* const kDefaultsRecentFolders = @"mv.recentFolders";
static NSString* const kDefaultsPinnedFolders = @"mv.pinnedFolders";  // issue #617

- (BOOL)settingsVisible { return _settingsVisible; }
- (void)setSettingsVisible:(BOOL)visible {
  if (visible == _settingsVisible) return;
  if (!visible) [self cancelKeyCapture];
  _settingsVisible = visible;
  self.settingsHost.hidden = !visible;
  [self layoutAIBadge];  // #345
  [self syncToolBar];  // S3
  if (visible) [self cancelKeyHolds];
  if (!visible) [self.window makeFirstResponder:self.view];
}
- (int32_t)viewFlags { return _viewFlags; }

// The view settings that reach native state: wrap (browse_index) and sticky
// zoom (input_snapshot, read by the render thread). The two filmstrip
// preferences are applied when something is opened.
- (void)applyViewFlags {
  const auto s = mv::shell::view_settings::from_flags(_viewFlags);
  _index.set_wrap(s.wrap);
  _snap.sticky_zoom = s.sticky_zoom;
  [self pokeSnapshot];
}
- (void)setViewFlags:(int32_t)flags {
  const auto before = mv::shell::view_settings::from_flags(_viewFlags).hidden_kinds();
  const int32_t changed = flags ^ _viewFlags;
  _viewFlags = flags;
  // #355: Local search indexes audio files only while they are shown.
  if (changed & mv::shell::kSettingShowAudio) MvAddonsShowAudioChanged((flags & mv::shell::kSettingShowAudio) != 0);
  // #354: and documents only while they are shown.
  if (changed & mv::shell::kSettingShowDocuments) {
    MvAddonsShowDocumentsChanged((flags & mv::shell::kSettingShowDocuments) != 0);
  }
  // Picked up on the main queue, like any relist.
  if (mv::shell::view_settings::from_flags(flags).hidden_kinds() != before) {
    _refilterListing = YES;
    dispatch_async(dispatch_get_main_queue(), ^{ [g_chrome_app refreshFolderIfChanged]; });
  }
  [[NSUserDefaults standardUserDefaults] setInteger:flags forKey:kDefaultsViewFlags];
  // #345: the AI badge is chrome only; switching it pokes nothing the render
  // thread reads, so it never costs a present.
  if (changed & ~mv::shell::kSettingHideAiBadge) [self applyViewFlags];
  if (changed & mv::shell::kSettingHideAiBadge) [self aiBadgeSettingChanged];
  ++_keysGeneration;  // the Settings screen re-reads flags and keys on this
}

- (void)persistKeys {
  // The verify rig changes keys (PR 56's key layout leg); the person's stay theirs.
  if (std::getenv("MV_ADDON_SELFTEST") != nullptr) return;
  // commands.h live_key_remaps: the same list Windows keeps in settings.ini, a
  // row a swap left unbound included as key 0 (issue #153).
  NSMutableArray<NSString*>* rows = [NSMutableArray array];
  for (const mv::shell::key_remap& r : mv::shell::live_key_remaps()) {
    [rows addObject:[NSString stringWithFormat:@"%d,%d,%d", r.row, static_cast<int>(r.k),
                                                static_cast<int>(r.mods)]];
  }
  [[NSUserDefaults standardUserDefaults] setObject:rows forKey:kDefaultsKeys];
  // Contributed add-on rows, by name: "k,mods,<add-on id>/<command id>".
  NSMutableArray<NSString*>* addonRows = [NSMutableArray array];
  for (const mv::shell::addon_key_remap& r : mv::shell::live_addon_key_remaps()) {
    [addonRows addObject:[NSString stringWithFormat:@"%d,%d,%s", static_cast<int>(r.k), static_cast<int>(r.mods),
                                                     r.command.c_str()]];
  }
  [[NSUserDefaults standardUserDefaults] setObject:addonRows forKey:kDefaultsAddonKeys];
}

- (void)loadSettings {
  NSUserDefaults* d = [NSUserDefaults standardUserDefaults];
  _viewFlags = [d objectForKey:kDefaultsViewFlags] != nil
                   ? static_cast<int32_t>([d integerForKey:kDefaultsViewFlags])
                   : mv::shell::view_settings{}.flags();
  // #355: before the AI pack attaches, which reads it.
  MvAddonsShowAudioChanged((_viewFlags & mv::shell::kSettingShowAudio) != 0);
  MvAddonsShowDocumentsChanged((_viewFlags & mv::shell::kSettingShowDocuments) != 0);  // #354
  _stripHintLearned = [d boolForKey:@"mv.hint.filmstripT"];
  _pageSidebarWanted = [d objectForKey:@"mv.pageSidebar"] == nil || [d boolForKey:@"mv.pageSidebar"];
  std::vector<mv::shell::key_remap> remaps;
  for (NSString* row in [d arrayForKey:kDefaultsKeys]) {
    int idx = 0, k = 0, m = 0;
    if ([row isKindOfClass:[NSString class]] && sscanf(row.UTF8String, "%d,%d,%d", &idx, &k, &m) == 3 &&
        k >= 0 && k < mv::shell::kKeyCount && m >= 0 && m < mv::shell::kModCombos) {
      remaps.push_back(mv::shell::key_remap{idx, static_cast<mv::shell::key>(k), static_cast<std::uint8_t>(m)});
    }
  }
  mv::shell::apply_key_remaps(remaps);  // resets the live table first
  std::vector<mv::shell::addon_key_remap> addonRemaps;
  for (NSString* row in [d arrayForKey:kDefaultsAddonKeys]) {
    int k = 0, m = 0, used = 0;
    if ([row isKindOfClass:[NSString class]] && sscanf(row.UTF8String, "%d,%d,%n", &k, &m, &used) == 2 &&
        used > 0 && k >= 0 && k < mv::shell::kKeyCount && m >= 0 && m < mv::shell::kModCombos) {
      std::string name(row.UTF8String + used);
      if (!name.empty()) {
        addonRemaps.push_back(
            mv::shell::addon_key_remap{std::move(name), static_cast<mv::shell::key>(k), static_cast<std::uint8_t>(m)});
      }
    }
  }
  mv::shell::apply_addon_key_remaps(addonRemaps);
  [self rebuildKeys];
  _sort = mv::io::unpack_sort(static_cast<std::int32_t>([d integerForKey:@"mv.sort"]));
  _recentFolders.clear();
  for (id entry in [d arrayForKey:kDefaultsRecentFolders]) {
    if ([entry isKindOfClass:[NSString class]] && [entry length] > 0 &&
        _recentFolders.size() < mv::shell::kMaxRecentFolders) {
      _recentFolders.emplace_back([entry UTF8String]);
    }
  }
  _pinnedFolders.clear();
  for (id entry in [d arrayForKey:kDefaultsPinnedFolders]) {
    if ([entry isKindOfClass:[NSString class]] && [entry length] > 0) {
      _pinnedFolders = mv::shell::pin_folder(std::move(_pinnedFolders), [entry UTF8String]);  // capped, no repeats
    }
  }
  // A launch with a path to open never shows the rows, not even for a frame.
  if (_options.open_path.empty() && [self welcomeListsRecents]) {
    const char* home = NSHomeDirectory().fileSystemRepresentation;
    mv::shell::fill_welcome_recents([self shownFolders], home ? home : "", _snap.recents,
                                    [self photosLibraryAvailable] == YES, _pinnedFolders.size());
  }
  // Straight into the state (no publish: the render thread is not up yet at
  // launch, and the next input publishes the snapshot anyway).
  const auto prefs = mv::shell::view_settings::from_flags(_viewFlags);
  _index.set_wrap(prefs.wrap);
  _snap.sticky_zoom = prefs.sticky_zoom;
  _snap.compare = g_start_compare;
}

- (void)resetKeys {
  [self cancelKeyCapture];
  mv::shell::reset_live_bindings();
  [self rebuildKeys];
  [self persistKeys];
  ++_keysGeneration;
}

// docs/design/16 "Keymap packs": once, from Settings. The defaults with the pack's
// keys written in; from then on the person's table, persisted like a remap.
- (std::string)applyKeymap:(const char*)packJson {
  std::vector<mv::addon::keymap_binding> bindings;
  if (!mv::shell::keymap_bindings_from_json(packJson, bindings)) {
    mv::shell::keymap_result refused;
    refused.skipped.push_back("not a key layout");
    return mv::shell::keymap_report_json(refused);
  }
  [self cancelKeyCapture];
  [self cancelKeyHolds];  // rebuild forgets held keys (issue #186)
  // ⌘H, ⌘Q, ⌘M, ⌘⌫ are the fixed menu items', which see them first: a pack
  // row given one would never run, as Settings' capture refuses (issue #182).
  const mv::shell::keymap_result r = mv::shell::apply_keymap(
      bindings, [](mv::shell::key k, std::uint8_t mods, void*) -> bool {
        return MvMenuOwnsChord(NSApp.mainMenu, k, mods);
      });
  [self rebuildKeys];
  [self persistKeys];
  ++_keysGeneration;
  return mv::shell::keymap_report_json(r);
}

- (int)captureRow { return _captureRow; }
- (uint64_t)keysGeneration { return _keysGeneration; }
// docs/design/25: an add-on's rows came or went (addons_mac.mm).
- (void)commandsChanged {
  // rebuild forgets held keys; release them first (issue #186).
  [self cancelKeyHolds];
  [self rebuildKeys];
  ++_keysGeneration;
}

- (void)cancelKeyCapture {
  if (_captureMonitor) [NSEvent removeMonitor:_captureMonitor];
  _captureMonitor = nil;
  if (_captureRow >= 0) ++_keysGeneration;
  _captureRow = -1;
}

// ⌘A / ⌘C / ⌘X / ⌘V / ⌘Z / ⇧⌘Z in a text field (owner, 2026-09-27: "Cmd+A in
// the search bar"). A field editor gets these only as Edit menu items, and
// this app has none on purpose: on the canvas those keys are the viewer's own
// commands (⌘A marks all, ⌘C copies the image, ⌘Z undoes an edit), routed by
// keyDown:. So when a text editor is first responder in the key window (every
// SwiftUI TextField: file search, the ⌘F panel, Settings, People,
// Import, the metadata pane), the chord is handed to it here and goes no
// further; anywhere else the event is left alone and routes exactly as before.
// ⌃A stays the field's own "start of line"; Esc is never taken here.
- (void)installTextEditKeys {
  if (_textEditMonitor) return;
  __weak MvLabApp* weakSelf = self;
  _textEditMonitor = [NSEvent
      addLocalMonitorForEventsMatchingMask:NSEventMaskKeyDown
                                   handler:^NSEvent*(NSEvent* event) {
                                     MvLabApp* strong = weakSelf;
                                     if (!strong || strong->_captureRow >= 0) return event;
                                     return [strong handleTextEditKey:event] ? nil : event;
                                   }];
}

- (BOOL)handleTextEditKey:(NSEvent*)event {
  const NSEventModifierFlags flags = event.modifierFlags & NSEventModifierFlagDeviceIndependentFlagsMask;
  if ((flags & NSEventModifierFlagCommand) == 0 || (flags & NSEventModifierFlagControl) != 0) return NO;
  NSResponder* first = NSApp.keyWindow.firstResponder;
  if (![first isKindOfClass:[NSText class]]) return NO;
  NSText* editor = (NSText*)first;
  // An input method composing owns its keys until it commits.
  if ([editor isKindOfClass:[NSTextView class]] && [(NSTextView*)editor hasMarkedText]) return NO;
  mv::shell::key_event e;
  e.k = MvKeyFromEvent(event, &e.mods);
  e.repeat = event.isARepeat;
  NSUndoManager* undo = editor.undoManager;
  switch (mv::shell::text_edit_for(e)) {
    case mv::shell::text_edit::none: return NO;
    case mv::shell::text_edit::select_all: [editor selectAll:nil]; return YES;
    case mv::shell::text_edit::copy: [editor copy:nil]; return YES;
    case mv::shell::text_edit::cut:
      if (editor.isEditable) [editor cut:nil];
      return YES;
    case mv::shell::text_edit::paste:
      if (editor.isEditable) [editor paste:nil];
      return YES;
    case mv::shell::text_edit::undo:
      if (editor.isEditable && undo.canUndo) [undo undo];
      return YES;
    case mv::shell::text_edit::redo:
      if (editor.isEditable && undo.canRedo) [undo redo];
      return YES;
  }
  return NO;
}

// "Choose a shortcut, then press its replacement. Esc cancels." A local monitor
// sees the key before anything else, so it can take chords the menu bar would
// otherwise claim (Cmd+something) and never lets the key reach a command. A
// chord a fixed menu item owns is refused; the table's own items follow the
// remap (syncMenuKeyEquivalents).
- (void)beginKeyCaptureForRow:(int)row {
  [self cancelKeyCapture];
  _captureRow = row;
  ++_keysGeneration;
  __weak MvLabApp* weakSelf = self;
  _captureMonitor = [NSEvent
      addLocalMonitorForEventsMatchingMask:NSEventMaskKeyDown
                                   handler:^NSEvent*(NSEvent* event) {
                                     MvLabApp* strong = weakSelf;
                                     if (!strong || strong->_captureRow < 0) return event;
                                     std::uint8_t mods = 0;
                                     const mv::shell::key k = MvKeyFromEvent(event, &mods);
                                     if (k == mv::shell::key::escape && mods == mv::shell::mod_none) {
                                       [strong cancelKeyCapture];
                                       return nil;
                                     }
                                     if (k == mv::shell::key::none) return nil;
                                     // Issue #182: ⌘H, ⌘Q, ⌘M, ⌘⌫ are the menu's, which sees
                                     // them first; the row would never run. Pick another.
                                     if (MvMenuOwnsChord(NSApp.mainMenu, k, mods)) {
                                       NSBeep();
                                       return nil;
                                     }
                                     const int row = strong->_captureRow;
                                     [strong cancelKeyCapture];
                                     if (mv::shell::rebind_live(row, k, mods)) {
                                       [strong rebuildKeys];
                                       [strong persistKeys];
                                       ++strong->_keysGeneration;
                                     }
                                     return nil;
                                   }];
}

- (void)navigateNext {
  if (_items.empty()) return;
  [self selectIndex:_index.next()];
}
- (void)navigatePrev {
  if (_items.empty()) return;
  [self selectIndex:_index.prev()];
}
- (void)swipeStep:(int)delta {
  if (delta == 0 || _galleryVisible || _edits.crop_active()) return;
  if (delta > 0) [self navigateNext];
  else [self navigatePrev];
}
- (void)navigateFirst {
  if (_items.empty()) return;
  [self selectIndex:_index.first()];
}
- (void)navigateLast {
  if (_items.empty()) return;
  [self selectIndex:_index.last()];
}
// Ctrl/Cmd+PageDown / PageUp: the next or previous page of the multi-page
// still on screen (docs/plans/audio-and-documents.md §2.3). The lab learns
// the page count when the file decodes; until then, and on a single-page
// file or a clip, the keys do nothing.
- (void)turnPage:(int)delta {
  (void)[self turnPage:delta land:NO];
}
// `land`: a scroll turned it, so the page keeps the zoom and lands at its top
// (forward) or bottom (back) instead of fitting. NO when nothing turned.
- (BOOL)turnPage:(int)delta land:(BOOL)land {
  if (_shownItem == 0 || _shownPath.empty() || [self currentItemIsVideo]) return NO;
  // A Photos library item (docs/design/26) is a key, not a file, and never paged.
  if (mv::shell::photos::is_key(_shownPath)) return NO;
  // The page just asked for may still be decoding: keep the count it reported.
  if (const std::uint32_t known = _lab.page_count(_shownItem)) _shownPageCount = known;
  const std::uint32_t count = _shownPageCount;
  if (count <= 1) return NO;
  const std::int64_t want = std::clamp<std::int64_t>(static_cast<std::int64_t>(_shownPage) + delta, 0,
                                                     static_cast<std::int64_t>(count) - 1);
  if (want == static_cast<std::int64_t>(_shownPage)) return NO;
  _shownPage = static_cast<std::uint32_t>(want);
  ++_snap.page_land_seq;
  _snap.page_land = land ? (delta > 0 ? 1 : -1) : 0;
  const std::int64_t mtime =
      _shownMtime == kShownStampUnknown ? mv::shell::present_lab_mac::kNoStamp : _shownMtime;
  _shownItem = _lab.open_item(_shownPath, mtime, _shownSize, -1, _shownPage);
  if (!_items.empty() && _index.current() < _items.size()) {
    [self editItemOpened:_items[_index.current()] item:_shownItem];
  }
  [self noticeShow:mv::shell::page_notice(_shownPage, count)];
  [self stripHintShow];
  [self pokeSnapshot];
  return YES;
}

// Issue #429 (docs/design/04 "Page sidebar"): a strip of page thumbnails down
// the left of a PDF, DOCX or PPTX with more than one page, when the filmstrip
// is hidden. It takes the filmstrip's role for a document, so the two never
// show at once; Shift+T turns it off and on (remembered, on by default).
- (void)pageCount:(std::uint32_t)count knownForItem:(std::uint64_t)item {
  if (item != _shownItem || count == 0) return;
  if (count == _shownPageCount && _pageSidebarShown) return;
  _shownPageCount = count;
  [self applyPageSidebarLayout];
}
- (BOOL)pageSidebarShown {
  return _pageSidebarShown;
}
// The count the strip lists: the stop's own once the lab knows it. Until then,
// while the last document's strip is up, that one's: arrowing from one
// document to the next keeps the strip rather than taking it down and putting
// it back, which would refit the canvas twice.
- (std::uint32_t)pageSidebarCount {
  if (_shownPageCount > 0) return _shownPageCount;
  return _pageSidebarShown ? _pageSidebarListed : 0;
}
- (BOOL)pageSidebarVisible {
  if (!_pageSidebarWanted || [self pageSidebarCount] <= 1) return NO;
  if (_items.empty() || _shownItem == 0 || _shownPath.empty()) return NO;
  if (_galleryVisible || [self filmstripVisible] || _editorOpen) return NO;
  if (mv::shell::photos::is_key(_shownPath)) return NO;
  return mv::io::is_document_name(_shownPath) ? YES : NO;
}
// Re-run whenever what decides it changes (a stop, a page, the count, the
// filmstrip, the gallery). Tells the sidebar the page on screen every time,
// so its highlight follows a scroll or a key.
- (void)applyPageSidebarLayout {
  if (!self.pageSidebarHost) return;
  const BOOL shown = [self pageSidebarVisible];
  if (!_pageThumbs) _pageThumbs = std::make_shared<mv::image::page_thumb_book>();
  // The serial names the stop: a new one (or none) starts a new serial, so a
  // thumbnail of the last document still in flight is never shown on this one.
  std::uint32_t serial = 0;
  if (shown) {
    serial = _pageThumbs->want(_shownPath, 0, 0).serial;
  } else {
    _pageThumbs->clear();
    serial = _pageThumbs->serial();
  }
  _pageSidebarListed = shown ? [self pageSidebarCount] : 0;
  [MVChromeHost setPageSidebarWithCount:static_cast<int32_t>(_pageSidebarListed)
                                current:static_cast<int32_t>(_shownPage)
                                 serial:serial];
  if (shown == _pageSidebarShown) return;
  _pageSidebarShown = shown;
  self.pageSidebarHost.hidden = !shown;
  [self layoutHintNotice];
  [self syncCanvasGuide];
  [self.view syncChrome];  // chrome_left_px: the canvas frames right of it
}
- (void)togglePageSidebar {
  _pageSidebarWanted = !_pageSidebarWanted;
  [NSUserDefaults.standardUserDefaults setBool:_pageSidebarWanted forKey:@"mv.pageSidebar"];
  [self applyPageSidebarLayout];
  // Asked for over a document that cannot show it: say why rather than nothing.
  if (_pageSidebarWanted && !_pageSidebarShown && mv::io::is_document_name(_shownPath) &&
      [self filmstripVisible]) {
    [self noticeShow:"Press T to hide the filmstrip and show the page sidebar"];
  }
}
// The sidebar's visible window of pages (from the SwiftUI strip). Thumbnails
// render on a background job from one open of the file; each lands on the
// main thread with the serial it was made for.
- (void)requestPageThumbsFrom:(int32_t)first count:(int32_t)count {
  if (!_pageSidebarShown || first < 0 || count <= 0 || !_pageThumbs) return;
  auto want = _pageThumbs->want(_shownPath, static_cast<std::uint32_t>(first),
                                static_cast<std::uint32_t>(count));
  if (want.pages.empty()) return;
  const std::int64_t mtime = _shownMtime == kShownStampUnknown ? 0 : _shownMtime;
  std::shared_ptr<mv::image::page_thumb_book> book = _pageThumbs;
  const std::uint32_t serial = want.serial;
  _folder.request_page_thumbs(
      _shownPath, mtime, _shownSize, std::move(want.pages),
      [book, serial](std::vector<std::uint32_t> pages) { return book->still_wanted(serial, pages); },
      [book, serial](std::uint32_t page, std::string path) {
        if (!book->landed(serial, page, path)) return false;
        NSString* ns = [NSString stringWithUTF8String:path.c_str()] ?: @"";
        dispatch_async(dispatch_get_main_queue(), ^{
          [MVChromeHost pageThumbReadyWithSerial:serial page:static_cast<int32_t>(page) path:ns];
        });
        return true;
      },
      [book, serial](std::vector<std::uint32_t> pages) { book->finished(serial, pages); });
}
// A sidebar click: that page, fitted, as Ctrl+PageDown would show it.
- (void)selectPage:(int32_t)page {
  if (page < 0 || !_pageSidebarShown) return;
  (void)[self turnPage:page - static_cast<int>(_shownPage) land:NO];
}

- (BOOL)documentScrolls {
  if (_items.empty() || _shownItem == 0 || _shownPath.empty()) return NO;
  if (_galleryVisible || [self filmstripVisible] || _editorOpen) return NO;
  if (mv::shell::photos::is_key(_shownPath)) return NO;
  return mv::io::is_document_name(_shownPath) ? YES : NO;
}
// A wheel notch is a tenth of the canvas and glides there on the canvas spring;
// a trackpad's deltas (and its momentum) move the view directly. Pushing past
// the top or bottom edge turns the page at once, landing at its top or bottom
// at the same zoom (canvas/document_scroll.h, shared with Windows).
- (void)scrollDocument:(NSEvent*)event {
  const double scale = self.window.backingScaleFactor > 0 ? self.window.backingScaleFactor : 1.0;
  const BOOL precise = event.hasPreciseScrollingDeltas;
  const double step = precise ? scale : std::max(1.0, 0.1 * static_cast<double>(_snap.height));
  // Read the ack before the edges: the lab stores them the other way round.
  const std::uint32_t ack = _lab.page_land_ack();
  mv::canvas::document_scroll_input in;
  in.dx = -event.scrollingDeltaX * step;
  in.dy = -event.scrollingDeltaY * step;
  in.precise = precise == YES;
  in.now = CACurrentMediaTime();
  in.edges = _lab.scroll_edges();
  in.canvas_h = static_cast<float>(_snap.height);
  in.land_ack = ack;
  const auto out = _docScroll.feed(in);
  if (out.turn != 0 && [self turnPage:out.turn land:YES]) {
    _docScroll.turned(_snap.page_land_seq, in.now);
  }
  if (out.px_x == 0 && out.px_y == 0) return;
  if (out.direct) {
    _snap.scroll_direct_px_x += out.px_x;
    _snap.scroll_direct_px_y += out.px_y;
  } else {
    _snap.scroll_px_x += out.px_x;
    _snap.scroll_px_y += out.px_y;
  }
  [self pokeSnapshot];
}

// The "Press T" filmstrip hint (shell/filmstrip_hint.h, docs/design/16), the
// Windows host's strip_hint_* twins.
- (mv::shell::strip_hint_subject)stripHintSubjectNow {
  if (_items.empty() || _shownItem == 0 || _shownPath.empty()) return mv::shell::strip_hint_subject::none;
  if (_galleryVisible || _editorOpen || mv::shell::photos::is_key(_shownPath)) {
    return mv::shell::strip_hint_subject::none;
  }
  if (mv::io::is_document_name(_shownPath)) return mv::shell::strip_hint_subject::document;
  if (mv::shell::is_video_name(_shownPath)) return mv::shell::strip_hint_subject::clip;  // issue #416
  return mv::shell::strip_hint_subject::none;
}
- (std::string_view)stripHintDueText {
  const auto subject = [self stripHintSubjectNow];
  if (!mv::shell::strip_hint_due(subject, [self filmstripVisible] == YES, _stripHintLearned == YES)) return {};
  return mv::shell::strip_hint_text(subject);
}
// Shows the card (it fades by itself) when the hint is due, and takes it down
// when what is on screen no longer has it due. The wheel re-shows it at most
// once a second.
- (void)stripHintShow {
  const auto text = [self stripHintDueText];
  if (text.empty()) {
    [self stripHintHide];
    return;
  }
  const CFTimeInterval now = CACurrentMediaTime();
  if (_stripHintCard && now - _stripHintShownAt < 1.0) return;
  _stripHintCard = YES;
  _stripHintShownAt = now;
  [self layoutHintNotice];
  [MVChromeHost showHint:[[NSString alloc] initWithBytes:text.data()
                                                  length:text.size()
                                                encoding:NSUTF8StringEncoding] ?: @""];
}
- (void)stripHintHide {
  if (!_stripHintCard) return;
  _stripHintCard = NO;
  [MVChromeHost showHint:@""];
}
- (void)stripHintLearn {
  if (_stripHintLearned) return;
  _stripHintLearned = YES;
  [NSUserDefaults.standardUserDefaults setBool:YES forKey:@"mv.hint.filmstripT"];
  [self stripHintHide];
}
- (void)stripHintToggled {
  if (_stripHintLearned) return;
  const auto subject = [self stripHintSubjectNow];
  if (!mv::shell::strip_hint_learned_by_toggle(subject, [self filmstripVisible] == YES)) return;
  [self stripHintLearn];
}
// Above the filmstrip when it is up, and above the resume notice and the
// restart card (#510, the same hosting view) while either shows.
- (void)layoutHintNotice {
  CGFloat bottom = -([self filmstripVisible] ? kFilmstripHeightPoints : 0.0) - 8.0;
  if (self.resumeHost != nil && !self.resumeHost.hidden) bottom -= self.resumeHost.fittingSize.height;
  self.hintBottom.constant = bottom;
}

- (void)navigateSkip:(std::ptrdiff_t)delta {
  if (_items.empty()) return;
  [self selectIndex:_index.skip(delta)];
}
- (BOOL)applicationShouldTerminateAfterLastWindowClosed:(NSApplication*)sender {
  (void)sender;
  // #452: in the background the viewer window is only ordered out, so AppKit's
  // check can find nothing on screen after an add-on window closes;
  // -backgroundSettle decides whether the process goes.
  return !_inBackground;
}
- (void)windowWillClose:(NSNotification*)notification {
  // PR 30: the Video Editor closing hands the canvas back; the app goes on.
  if (self.editorWindow != nil && notification.object == self.editorWindow) {
    [self editorWindowClosed];
    return;
  }
  // Command-bar buttons stop reaching the lab first: they only poke _snap
  // through the g_chrome_* globals, so clearing those before teardown means
  // a button click racing window close can never touch a torn-down lab.
  // This is the only work windowWillClose does -- it runs on the main
  // thread and must not block it (CLAUDE.md rule 1). The actual teardown
  // (job_system::shutdown() joining workers, _lab.stop() joining the render
  // thread) can take as long as an in-flight decode+upload job does, so it
  // runs off the main thread in -applicationShouldTerminate: instead, which
  // fires only after the window has already closed.
  g_chrome_snap = nullptr;
  g_chrome_lab = nullptr;
  g_chrome_app = nullptr;
  [_transportPollTimer invalidate];
  _transportPollTimer = nil;
  [_editorTick invalidate];
  _editorTick = nil;
  // _slideshowTimer's target is self, retained by NSTimer until invalidated
  // -- nulling g_chrome_app above does not stop it, since it calls
  // -slideshowAdvance directly rather than through the bridge globals. Left
  // running, it would keep firing -slideshowAdvance/-selectIndex: on a
  // half-torn-down MvLabApp after the window (and _folder) are gone, racing
  // -applicationShouldTerminate:'s own off-main-thread teardown. Not
  // routed through -leaveSlideshow: that also un-fullscreens the window,
  // which is unnecessary work on a window that is already closing.
  [_slideshowTimer invalidate];
  _slideshowTimer = nil;
  _slideshowActive = NO;
  _slideshowPaused = NO;
  // Stops and joins the FSEvents watch thread; safe on the main thread per
  // io/dir.h's contract, and cheap -- in-flight relist/thumb jobs keep their
  // own shared_ptr<shared_state> and finish safely regardless (folder_model_mac.h).
  _folder.close();
}
- (NSApplicationTerminateReply)applicationShouldTerminate:(NSApplication*)sender {
  (void)sender;
  // #532: this copy asked the others to quit for its update, and something
  // quits it first: another copy's install (Sparkle quits every copy and may
  // relaunch none). It comes back once the new version is in place.
  if (_updateAsked && !_quitForReal && !_terminating) {
    _quitForReal = true;
    [self relaunchAfterUpdateInstalls];
  }
#if MV_WITH_SPARKLE
  // #532: Sparkle's installer quits this copy for an install started elsewhere
  // (another copy's restart, or its quit). It is not the person's Quit: it
  // quits, in the background too, but never under a transfer. Busy, it waits
  // and quits once the transfer ends; Sparkle's installer waits for it.
  if (!_terminating && !_quitForReal && MvQuitFromSparkle(NSAppleEventManager.sharedAppleEventManager.currentAppleEvent)) {
    if (!mv::addon::default_slots().busy_what().empty()) {
      MV_LOG_INFO("update: Sparkle's quit waits for a transfer to finish");
      [self quitForUpdateWhenIdle];
      return NSTerminateCancel;
    }
    _quitForReal = true;
  }
#endif
  // #452 hid the app for a Quit (⌘Q, the Dock's, another app's quit event)
  // while an add-on kept the process; since 2026-10-29 every Quit quits, and
  // only closing the viewer window leaves it in the menu bar.
  if (_terminating) return NSTerminateLater;
  _terminating = true;
  // PR 12: writes the user asked for and has not seen land -- a rating inside
  // its 0.25 s debounce, a comment queued behind another write, a rotation
  // inside its 0.4 s debounce. Taken here, on the main thread that owns the
  // queues, and written below once the pool has finished the write it is
  // running (a second write to one file must not overlap it). The rotation
  // goes first: it refuses bytes a metadata write has changed, while a
  // metadata write applies to whatever orientation it finds. A rotation
  // already in flight is not repeated (a turn is relative; a rating is not).
  [_rotateDebounce invalidate];
  _rotateDebounce = nil;
  [_metaWriteDebounce invalidate];
  _metaWriteDebounce = nil;
  // docs/design/26: a Photos original being fetched stops; the downloads go (below).
  [_photosFetchTimer invalidate];
  _photosFetchTimer = nil;
  if (_photosFetchCancel) _photosFetchCancel->store(true, std::memory_order_release);
  std::optional<mv::shell::rotation_write> exitTurn = _edits.take_pending_write();
  std::vector<mv::shell::meta_job> exitMeta = _metaWriter.drain_for_exit();
  // Add-on chromes shut down here, before their packs stop (below, off the
  // main thread): nothing may call a table whose add-on is gone. Nothing
  // here waits on a pack.
  MvAddonsQuit();
  // Jobs first: submit_image_load()'s job holds a raw (non-retaining)
  // id<MTLDevice> pointer, so it must finish before _lab.stop() reaches
  // device_.destroy() on the render thread -- shutdown() drains queued jobs
  // and joins running ones, so this ordering guarantees that. Both block,
  // so both run on a background queue; the window is already closed by the
  // time this method runs, so nothing user-visible waits on it.
  // #612: a sweep waiting out a busy viewer would hold a worker the join
  // below waits for; Clear no longer reaches the folder model.
  g_storage_folder.store(nullptr, std::memory_order_release);
  _folder.stop_thumb_sweep();
  dispatch_async(dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_DEFAULT, 0), ^{
    // PR 13 / 14: running clip jobs are cancelled and their temporaries
    // removed (no partial output); joins the queue's workers.
    _clipJobs.reset();
    _jobs.shutdown();
    mv::shell::photos::clear_downloads();  // "cleared after" (owner, 2026-09-28)
    // docs/design/26: a backup run stops between buffers and leaves no part file.
    if (_photosBackup) {
      _photosBackup->cancel();
      _photosBackup->join();
    }
    if (exitTurn && !mv::shell::run_rotation_write(*exitTurn)) MV_LOG_WARN("exit: rotation write failed");
    for (const mv::shell::meta_job& job : exitMeta) {
      const mv::shell::meta_outcome out = mv::shell::run_meta_job(job);
      if (!out.ok) MV_LOG_WARN("exit: metadata write failed: %s", mv::status_name(out.error));  // never the path
    }
    // Half a second from Quit for the add-ons to stop (an idle pack takes
    // ~0.06 s). One still in a model load or a Core ML compile (seconds to a
    // minute, not cancellable) is left to the exit (addons_mac.h).
    MvAddonsWaitStopped(0.5);
    _lab.stop();
    // Not dispatch_async(main queue): while NSTerminateLater is pending,
    // -[NSApplication terminate:] spins a nested run loop in a mode that does
    // not service the main dispatch queue, so that block never ran and the
    // process never exited (found on real hardware, 2026-09-19: every
    // --soak run, and so frametime, timed out after writing its report).
    // Performing the block in the common modes runs in whichever mode the
    // wait is in.
    CFRunLoopPerformBlock(CFRunLoopGetMain(), kCFRunLoopCommonModes, ^{
      [NSApp replyToApplicationShouldTerminate:YES];
    });
    CFRunLoopWakeUp(CFRunLoopGetMain());
  });
  return NSTerminateLater;
}
- (void)windowDidChangeOcclusionState:(NSNotification*)notification {
  (void)notification;
  _snap.window_visible = (self.window.occlusionState & NSWindowOcclusionStateVisible) != 0;
  [self.view publish];
  _lab.wake();
}
// Issue #38: a fullscreen / windowed transition shows the controls, like any
// other activity, so the change of frame is never also a missing transport.
- (void)windowDidEnterFullScreen:(NSNotification*)notification {
  (void)notification;
  [self transportActivity];
}
- (void)windowDidExitFullScreen:(NSNotification*)notification {
  (void)notification;
  [self transportActivity];
}

// --- Issue #38: auto-hide the clip transport ----------------------------------
// The rule is shell/transport_autohide.h, shared with Windows. This host feeds
// it facts and applies the answer: a fade of the floating strip, and in
// fullscreen the pointer. Hiding is visual only -- the strip keeps its layout,
// decode and audio carry on, and every key still routes.

static std::uint64_t MvNowMs() {
  return static_cast<std::uint64_t>(CACurrentMediaTime() * 1000.0);
}

- (mv::shell::transport_view)transportView {
  mv::shell::transport_view v;
  v.clip = _transportClip;
  v.playing = _transportPlaying;
  NSView* host = self.transportHost;
  bool over = false;
  if (host && !host.hidden && self.window) {
    const NSPoint p = [host convertPoint:[self.window mouseLocationOutsideOfEventStream] fromView:nil];
    over = NSPointInRect(p, host.bounds);
    NSResponder* first = self.window.firstResponder;
    const bool focused = [first isKindOfClass:[NSView class]] && [(NSView*)first isDescendantOf:host];
    v.held = over || focused;
  }
  v.screen_reader = NSWorkspace.sharedWorkspace.voiceOverEnabled;
  v.fullscreen = (self.window.styleMask & NSWindowStyleMaskFullScreen) != 0;
  v.pointer_on_canvas = _snap.mouse_in_client && !over;
  return v;
}

- (void)transportActivity {
  if (!_transportClip) return;
  _autohide.activity(MvNowMs());
  // Already up with a timer running (or paused, when nothing is timed): the
  // timer re-reads the clock when it fires, so a stream of mouse-moves costs a
  // compare, not a timer each.
  if (_transportShown && (_autohideTimer || !_transportPlaying)) return;
  [self applyTransportAutohide];
}

- (void)menuDidEndTracking:(NSNotification*)notification {
  (void)notification;
  [self transportActivity];
}

- (void)autohideTimerFired:(NSTimer*)timer {
  (void)timer;
  _autohideTimer = nil;
  [self applyTransportAutohide];
}

- (void)applyTransportAutohide {
  NSView* host = self.transportHost;
  if (!host) return;
  const std::uint64_t now = MvNowMs();
  const mv::shell::transport_view v = [self transportView];
  const bool changed = _autohide.update(v, now);
  const bool want = _transportClip && _autohide.shown();

  if (!_transportClip) {
    // No clip (or covered): gone at once, nothing to fade.
    [host.layer removeAllAnimations];
    host.alphaValue = 1.0;
    host.hidden = YES;
  } else if (want && (host.hidden || !_transportShown)) {
    host.hidden = NO;
    [NSAnimationContext runAnimationGroup:^(NSAnimationContext* ctx) {
      ctx.duration = 0.12;
      host.animator.alphaValue = 1.0;
    }];
  } else if (!want && _transportShown) {
    // Fade, then hide, so a click where it was reaches the video instead of a
    // button nobody can see (waking must never also press something).
    [NSAnimationContext runAnimationGroup:^(NSAnimationContext* ctx) {
      ctx.duration = 0.25;
      host.animator.alphaValue = 0.0;
    } completionHandler:^{
      if (!self->_autohide.shown()) host.hidden = YES;
    }];
  }
  _transportShown = want;

  if (changed && _autohide.pointer_hidden()) [NSCursor setHiddenUntilMouseMoves:YES];

  const std::uint64_t due = _autohide.due_in(v, now);
  [_autohideTimer invalidate];
  _autohideTimer = nil;
  if (due > 0) {
    _autohideTimer = [NSTimer scheduledTimerWithTimeInterval:static_cast<double>(due) / 1000.0
                                                      target:self
                                                    selector:@selector(autohideTimerFired:)
                                                    userInfo:nil
                                                     repeats:NO];
    _autohideTimer.tolerance = 0.05;
  }
}

- (void)windowDidBecomeKey:(NSNotification*)notification {
  (void)notification;
  _snap.window_active = true;
  // Back from Settings, where the Photos library may have been added or
  // removed: the welcome card's iCloud row follows (a memcmp when unchanged).
  [self refreshWelcomeRecents];
  [self.view publish];
  // The render thread presents only while the window is key (present_policy).
  // What landed while another window was (the search panel: a clip opened on
  // its moment, a still) is owed a frame now, not at the next key press.
  _lab.wake();
}
- (void)windowDidResignKey:(NSNotification*)notification {
  (void)notification;
  _snap.window_active = false;
  [self.view publish];
  // No key-up is coming for a key held as the window lost focus.
  [self cancelKeyHolds];
}
- (int)exitCode {
  return _lab.exit_code();
}
@end

namespace {

void usage() {
  std::fprintf(stderr,
               "mediaviewer_lab — Metal present lab (PR 16), still decode + pan/zoom (PR 17),\n"
               "                  folder browse + drag-drop (PR 18)\n"
               "  --soak N --json PATH [--gate] [--static] [--no-overlay]\n"
               "  --browse-soak --json PATH FOLDER   time arrows and jumps (tools/perf)\n"
               "  --edit-tab N                       with --browse-soak: Edit open on tab N (5 = Enhance)\n"
               "  --pane-drag-soak --json PATH STILL drag the right column 280<->720 for 20 s\n"
               "  --page-soak PATH DOCUMENT          fling the page sidebar, time page jumps\n"
               "  --compare     start with the two-up compare on (`|`)\n"
               "  --boot-report PATH   write the launch's boot timeline as JSON once ready, then quit\n"
               "  --open PATH   or a bare PATH: a folder opens that folder; a file opens its\n"
               "                folder with that file selected (docs/design/16-commands.md). Wheel to\n"
               "                zoom toward the cursor, drag to pan, 0 fit, 1 one-to-one.\n"
               "                Left/Right or A/D previous/next, Home/End first/last,\n"
               "                PageUp/PageDown skip ~10, Space next once a folder is open.\n");
}

}  // namespace

int main(int argc, char** argv) {
  // Issue #486: the boot timeline counts from process creation, so dyld, the
  // static initialisers and the frameworks' load before this line are in it too.
  {
    kinfo_proc info{};
    std::size_t size = sizeof info;
    int mib[4] = {CTL_KERN, KERN_PROC, KERN_PROC_PID, getpid()};
    timespec now{};
    if (::sysctl(mib, 4, &info, &size, nullptr, 0) == 0 && size == sizeof info &&
        ::clock_gettime(CLOCK_REALTIME, &now) == 0) {
      const timeval started = info.kp_proc.p_starttime;
      const std::int64_t age_ns =
          (static_cast<std::int64_t>(now.tv_sec) - started.tv_sec) * 1'000'000'000LL +
          static_cast<std::int64_t>(now.tv_nsec) - static_cast<std::int64_t>(started.tv_usec) * 1000LL;
      if (age_ns > 0) mv::boot::set_process_age(static_cast<std::uint64_t>(age_ns));
    }
    mv::boot::mark(mv::boot::stage::host_entry);
  }
#if defined(MV_WITH_SEARCH_AGENT)
  // docs/design/23: launchd runs this executable as Final Cut Pro's search agent
  // (Contents/Library/LaunchAgents). Before anything of the viewer: no window,
  // no crash reporter, no add-ons.
  if (argc == 2 && std::strcmp(argv[1], "--search-agent") == 0) return MvSearchAgentMain();
#endif
  mv::trace::provider_register();
  mv::shell::mac_lab_options options;
  for (int i = 1; i < argc; ++i) {
    const char* arg = argv[i];
    auto next = [&]() -> const char* { return i + 1 < argc ? argv[++i] : ""; };
    if (std::strcmp(arg, "--soak") == 0) {
      options.soak_seconds = std::strtod(next(), nullptr);
    } else if (std::strcmp(arg, "--json") == 0) {
      options.json_report_path = next();
    } else if (std::strcmp(arg, "--gate") == 0) {
      options.gate_exit_code = true;
    } else if (std::strcmp(arg, "--static") == 0) {
      options.start_animating = false;
    } else if (std::strcmp(arg, "--no-overlay") == 0) {
      options.overlay_visible = false;
    } else if (std::strcmp(arg, "--open") == 0) {
      options.open_path = next();
    } else if (std::strcmp(arg, "--new-window") == 0) {
      // Cmd+N in another MediaViewer window: "--new-window X Y", its top-left.
      g_new_window = true;
      const double x = std::strtod(next(), nullptr);
      const double y = std::strtod(next(), nullptr);
      g_new_window_from = NSMakePoint(x, y);
    } else if (std::strcmp(arg, "--browse-soak") == 0) {
      g_mac_browse.enabled = true;
    } else if (std::strcmp(arg, "--pane-drag-soak") == 0) {
      g_pane_drag.enabled = true;
    } else if (std::strcmp(arg, "--page-soak") == 0) {
      g_mac_pages.enabled = true;
      g_mac_pages.json_path = next();
    } else if (std::strcmp(arg, "--edit-tab") == 0) {
      g_browse_edit_tab = std::atoi(next());
    } else if (std::strcmp(arg, "--compare") == 0) {
      g_start_compare = true;
    } else if (std::strcmp(arg, "--background") == 0) {
      g_start_background = true;  // #452: as a login item starts it
    } else if (std::strcmp(arg, "--boot-report") == 0) {
      g_boot_report = next();
    } else if (std::strcmp(arg, "--help") == 0 || std::strcmp(arg, "-h") == 0) {
      usage();
      return 0;
    } else if (std::strncmp(arg, "-psn_", 5) == 0) {
      // A Finder/LaunchServices launch of an older-style process serial
      // number: not ours, and not an error (PR 20: MediaViewer.app starts
      // from Finder).
    } else if (arg[0] != '-') {
      // A bare positional path: "the first entry that exists wins"
      // (docs/design/16-commands.md) -- MvLabApp resolves it (folder, or a file's
      // containing folder with that file selected) after the lab starts.
      // The first one given wins if more than one is passed; later ones are
      // ignored rather than erroring, matching a drop of several files.
      if (options.open_path.empty()) options.open_path = arg;
    } else {
      std::fprintf(stderr, "mediaviewer_lab: unrecognised argument %s\n", arg);
      usage();
      return 2;
    }
  }
  if (g_mac_pages.enabled) {
    if (g_mac_pages.json_path.empty() || options.open_path.empty()) {
      std::fprintf(stderr, "mediaviewer_lab: --page-soak needs a report PATH and a PDF, DOCX or PPTX\n");
      return 2;
    }
    options.harness = true;
  }
  if (!g_boot_report.empty()) options.harness = true;
  if (g_pane_drag.enabled) {
    if (g_mac_browse.enabled || options.soak_seconds > 0.0 || options.json_report_path.empty() ||
        options.open_path.empty()) {
      std::fprintf(stderr, "mediaviewer_lab: --pane-drag-soak needs --json PATH and a still, not --soak\n");
      return 2;
    }
    g_pane_drag.json_path = std::move(options.json_report_path);
    options.json_report_path.clear();
    options.harness = true;
    options.pane_drag_soak = true;
  }
  if (g_mac_browse.enabled) {
    if (options.soak_seconds > 0.0 || options.json_report_path.empty() || options.open_path.empty()) {
      std::fprintf(stderr, "mediaviewer_lab: --browse-soak needs --json PATH and a folder, not --soak\n");
      return 2;
    }
    // The browse report is the host's; the lab's own soak report is not written.
    g_mac_browse.json_path = std::move(options.json_report_path);
    options.json_report_path.clear();
    options.harness = true;
  }
  // The F3 overlay is an instrument: off until asked, so a launch shows the
  // welcome rather than a stats panel. A soak keeps it (Windows does the same).
  if (options.soak_seconds <= 0.0) options.overlay_visible = false;
  if (options.soak_seconds > 0.0) {
    bool saw_static = false;
    for (int i = 1; i < argc; ++i) {
      if (std::strcmp(argv[i], "--static") == 0) saw_static = true;
    }
    options.start_animating = !saw_static;
  }

  // PR 11 (docs/design/13): Crashpad out of process, and the NSException capture,
  // before anything else can crash. Never waits on the handler's report scan.
  (void)mv::shell::crash::start();
  mv::boot::mark(mv::boot::stage::crash_armed);

  @autoreleasepool {
    [NSApplication sharedApplication];
    [NSApp setActivationPolicy:NSApplicationActivationPolicyRegular];
#if MV_APP_BUNDLE
    // First launch from the DMG: offer to move to /Applications and eject it.
    if (mv::shell::offer_install_from_disk_image()) return 0;
#endif
    MvLabApp* app = [[MvLabApp alloc] initWithOptions:options];
    NSApp.delegate = app;
    [NSApp run];
    const int code = [app exitCode];
    mv::trace::provider_unregister();
    return code;
  }
}
